const SHUOSHUO_BANGKOK_MORNING_V6SRJHDISDS_TRANSLATIONS = [
  `N\u1ebfu ph\u1ea3i n\u00f3i v\u1ec1 th\u00f3i quen bu\u1ed5i s\u00e1ng c\u1ee7a t\u00f4i,`,
  `Th\u00ec t\u00f4i ph\u1ea3i n\u00f3i v\u1ec1 th\u00f3i quen bu\u1ed5i chi\u1ec1u c\u1ee7a t\u00f4i tr\u01b0\u1edbc.`,
  `\u00c0i. Th\u00f3i quen bu\u1ed5i chi\u1ec1u c\u1ee7a t\u00f4i r\u1ea5t \u0111\u01a1n gi\u1ea3n:`,
  `Ng\u1ee7, ch\u01a1i \u0111i\u1ec7n tho\u1ea1i,`,
  `Xem TV. B\u1ea1n \u0111\u1ebfn mu\u1ed9n kh\u00f4ng \u1edf \u0111\u00f3.`,
  `T\u00f4i bi\u1ebft nhi\u1ec1u ng\u01b0\u1eddi th\u00e0nh c\u00f4ng th\u00edch d\u1eady r\u1ea5t s\u1edbm,`,
  `Nh\u01b0ng, \u1eebm \u1eebm, \u0111\u00e2y kh\u00f4ng ph\u1ea3i l\u00fd do t\u00f4i d\u1eady s\u1edbm.`,
  `L\u00fd do t\u00f4i d\u1eady l\u00fac 5 r\u01b0\u1ee1i s\u00e1ng m\u1ed7i ng\u00e0y r\u1ea5t \u0111\u01a1n gi\u1ea3n,`,
  `\u0110\u00f3 l\u00e0 \u2014 sau khi \u0103n tr\u01b0a t\u00f4i kh\u00f4ng th\u1ec3 l\u00e0m vi\u1ec7c,`,
  `Kh\u00f4ng th\u1ec3 h\u1ecdc, kh\u00f4ng th\u1ec3 \u0111\u1ecdc s\u00e1ch,`,
  `Kh\u00f4ng th\u1ec3 l\u00e0m b\u1ea5t c\u1ee9 \u0111i\u1ec1u g\u00ec.`,
  `T\u00f4i \u0111\u00e1nh r\u0103ng trong nh\u00e0 v\u1ec7 sinh.`,
  `T\u00f4i r\u1eeda m\u1eb7t trong nh\u00e0 v\u1ec7 sinh.`,
  `T\u00f4i \u0111i v\u1ec7 sinh trong nh\u00e0 v\u1ec7 sinh.`,
  `B\u00e2y gi\u1edd t\u00f4i s\u1ebd \u0111un n\u01b0\u1edbc,`,
  `pha c\u00e0 ph\u00ea. T\u00f4i kh\u00f4ng d\u00f9ng m\u00e1y pha c\u00e0 ph\u00ea,`,
  `v\u00ec t\u00f4i th\u1ea5y n\u00f3 kh\u00e1 phi\u1ec1n ph\u1ee9c,`,
  `n\u00ean t\u00f4i d\u00f9ng n\u01b0\u1edbc n\u00f3ng pha tr\u1ef1c ti\u1ebfp.`,
  `T\u00f4i r\u1ea5t th\u00edch c\u1ee5m t\u1eeb "n\u01b0\u1edbc s\u00f4i r\u1ed3i",`,
  `th\u1eadt th\u00fa v\u1ecb. N\u01b0\u1edbc s\u00f4i l\u00e0 n\u01b0\u1edbc n\u00f3ng,`,
  `r\u1ea5t n\u00f3ng r\u1ed3i,`,
  `100 \u0111\u1ed9 r\u1ed3i.`,
  `B\u1ea1n nh\u00ecn h\u00ecnh d\u00e1ng n\u01b0\u1edbc s\u00f4i xem,`,
  `c\u00f3 gi\u1ed1ng nh\u01b0 r\u1ea5t nhi\u1ec1u b\u00f4ng hoa \u0111ang n\u1edf kh\u00f4ng?`,
  `V\u00ec v\u1eady, t\u00f4i th\u1ea5y c\u1ee5m t\u1eeb n\u00e0y \u0111\u1eb7c bi\u1ec7t th\u00fa v\u1ecb.`,
  `Ch\u00e0o bu\u1ed5i s\u00e1ng nha, \u0111\u00e2y l\u00e0 kho\u1ea3ng th\u1eddi gian t\u00f4i y\u00eau th\u00edch nh\u1ea5t trong ng\u00e0y.`,
  `Ng\u1ed3i tr\u00ean ban c\u00f4ng,`,
  `v\u1eeba u\u1ed1ng c\u00e0 ph\u00ea v\u1eeba \u0111\u1ecdc s\u00e1ch.`,
  `B\u00ean ngo\u00e0i nh\u00e0 t\u00f4i b\u00e2y gi\u1edd c\u00f3 r\u1ea5t nhi\u1ec1u t\u00f2a nh\u00e0 cao t\u1ea7ng,`,
  `t\u00f2a nh\u00e0 r\u1ea5t cao. Tr\u01b0\u1edbc \u0111\u00e2y t\u00f4i s\u1ed1ng \u1edf n\u01a1i kh\u00e1c,`,
  `B\u00ean ngo\u00e0i nh\u00e0 t\u00f4i l\u00e0 m\u1ed9t ng\u1ecdn n\u00fai.`,
  `T\u00f4i r\u1ea5t th\u00edch n\u01a1i \u0111\u00f3.`,
  `C\u00f2n b\u1ea1n? N\u1ebfu b\u1ea1n ng\u1ed3i tr\u00ean ban c\u00f4ng,`,
  `B\u1ea1n mu\u1ed1n nh\u00ecn th\u1ea5y nh\u1eefng t\u00f2a nh\u00e0 cao t\u1ea7ng hay nh\u1eefng ng\u1ecdn n\u00fai?`,
  `Ph\u00f2ng n\u00e0y l\u00e0 studio l\u00e0m vi\u1ec7c c\u1ee7a t\u00f4i.`,
  `Tr\u01b0\u1edbc \u0111\u00e2y \u0111\u00e2y l\u00e0 m\u1ed9t ph\u00f2ng ng\u1ee7.`,
  `B\u1ea1n th\u1ea5y \u0111\u1ea5y, \u1edf \u0111\u00e2y v\u1eabn c\u00f2n m\u1ed9t c\u00e1i t\u1ee7 qu\u1ea7n \u00e1o,`,
  `l\u00e0 c\u00e1i t\u1ee7 \u0111\u1ec3 qu\u1ea7n \u00e1o.`,
  `Nh\u01b0ng b\u00e2y gi\u1edd,`,
  `n\u00f3 l\u00e0 studio l\u00e0m vi\u1ec7c c\u1ee7a t\u00f4i.`,
  `H\u00e0ng ng\u00e0y t\u00f4i l\u00e0m vi\u1ec7c \u1edf \u0111\u00e2y,`,
  `d\u1ea1y h\u1ecdc, quay video,`,
  `d\u1ef1ng video. M\u1ed7i s\u00e1ng,`,
  `l\u00e0 l\u00fac \u0111\u1ea7u \u00f3c t\u00f4i minh m\u1eabn nh\u1ea5t.`,
  `V\u00ec v\u1eady, bu\u1ed5i s\u00e1ng t\u00f4i s\u1ebd l\u00e0m nh\u1eefng vi\u1ec7c c\u1ea7n suy ngh\u0129,`,
  `c\u00f4ng vi\u1ec7c c\u1ea7n \u0111\u01b0\u1ee3c t\u1ea1o ra.`,
  `V\u00ed d\u1ee5, ngh\u0129 xem video c\u1ee7a t\u00f4i s\u1ebd quay v\u1ec1 c\u00e1i g\u00ec,`,
  `v\u00ed d\u1ee5, thi\u1ebft k\u1ebf kh\u00f3a h\u1ecdc c\u1ee7a m\u00ecnh,`,
  `l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 kh\u00f3a h\u1ecdc c\u1ee7a t\u00f4i v\u1eeba h\u1eefu \u00edch v\u1eeba th\u00fa v\u1ecb.`,
  `\u1eeam \u1eebm, \u0111\u00e3 thay m\u1ed9t b\u1ed9 \u0111\u1ed3 kh\u00e1c.`,
  `Thay m\u1ed9t b\u1ed9 \u0111\u1ed3 kh\u00e1c.`,
  `B\u00e2y gi\u1edd l\u00e0 bu\u1ed5i s\u00e1ng,`,
  `Xem n\u00e0o, 7 gi\u1edd 07 ph\u00fat.`,
  `8 gi\u1edd r\u01b0\u1ee1i s\u00e1ng t\u00f4i c\u00f3 m\u1ed9t ti\u1ebft h\u1ecdc,`,
  `v\u00ec v\u1eady t\u1eeb b\u00e2y gi\u1edd \u0111\u1ebfn 8 r\u01b0\u1ee1i l\u00e0 th\u1eddi gian l\u00e0m vi\u1ec7c c\u1ee7a t\u00f4i.`,
  `S\u00e1ng nay t\u00f4i ph\u1ea3i ho\u00e0n th\u00e0nh nh\u1eefng c\u00f4ng vi\u1ec7c n\u00e0y.`,
  `B\u00e2y gi\u1edd t\u00f4i \u0111ang d\u00f9ng ph\u01b0\u01a1ng ph\u00e1p Pomodoro n\u00e0y.`,
  `T\u1ee9c l\u00e0 t\u00f4i s\u1ebd l\u00e0m vi\u1ec7c 35 ph\u00fat,`,
  `sau \u0111\u00f3 t\u00f4i s\u1ebd ngh\u1ec9 5 ph\u00fat.`,
  `C\u00f3 th\u1ec3 \u0111\u1ee9ng d\u1eady \u0111i l\u1ea1i m\u1ed9t ch\u00fat,`,
  `C\u00f3 th\u1ec3 t\u1eadp th\u1ec3 d\u1ee5c, ho\u1eb7c nh\u00ecn ra ngo\u00e0i v\u00e0 m\u01a1 m\u1ed9ng.`,
  `B\u00e2y gi\u1edd l\u00e0 8 gi\u1edd 25 ph\u00fat,`,
  `5 ph\u00fat n\u1eefa t\u00f4i s\u1ebd b\u1eaft \u0111\u1ea7u ti\u1ebft h\u1ecdc.`,
  `\u0110\u00e2y l\u00e0 m\u1ed9t l\u1edbp h\u1ecdc tr\u00ecnh \u0111\u1ed9 trung c\u1ea5p v\u00e0 cao c\u1ea5p.`,
  `H\u1ecdc sinh c\u1ee7a t\u00f4i c\u00f3 tr\u00ecnh \u0111\u1ed9 HSK5,`,
  `6. \u00d4ng ch\u1ee7 n\u00e0y, b\u1ea1n mu\u1ed1n nh\u00e2n vi\u00ean c\u1ee7a m\u00ecnh l\u00e0m vi\u1ec7c ch\u0103m ch\u1ec9 h\u01a1n,`,
  `V\u00ec v\u1eady b\u1ea1n s\u1ebd n\u00f3i m\u1ed9t s\u1ed1 \u0111i\u1ec1u b\u1ea1n c\u00f3 th\u1ec3 nh\u1eadn \u0111\u01b0\u1ee3c,`,
  `V\u00ed d\u1ee5, sau khi b\u1ea1n th\u00e0nh c\u00f4ng, b\u1ea1n c\u00f3 th\u1ec3 nh\u1eadn \u0111\u01b0\u1ee3c n\u00f3.`,
  `V\u1ebd th\u00f4i. \u00c0, anh \u1ea5y v\u1ebd m\u1ed9t c\u00e1i b\u00e1nh hay m\u1ed9t t\u1ea3ng b\u0103ng?`,
  `B\u0103ng. Hahaha.`,
  `B\u00e1nh. N\u00e0y, b\u00e1nh. B\u00e1nh quy.`,
  `B\u00e1nh quy. V\u1ebd b\u00e1nh (ve\u0303 vo\u0300ng).`,
  `K\u1ebft th\u00fac gi\u1edd h\u1ecdc r\u1ed3i. B\u00e2y gi\u1edd t\u00f4i ph\u1ea3i \u0111\u1ebfn qu\u00e1n c\u00e0 ph\u00ea l\u00e0m vi\u1ec7c ngay,`,
  `B\u1edfi v\u00ec n\u1ebfu t\u00f4i l\u00e0m vi\u1ec7c \u1edf nh\u00e0,`,
  `T\u00f4i s\u1ebd mu\u1ed1n ngh\u1ec9 ng\u01a1i.`,
  `N\u1ebfu t\u00f4i ngh\u1ec9 ng\u01a1i,`,
  `H\u00f4m nay t\u00f4i s\u1ebd kh\u00f4ng l\u00e0m vi\u1ec7c \u0111\u01b0\u1ee3c,`,
  `V\u00ec v\u1eady t\u00f4i s\u1ebd thu d\u1ecdn \u0111\u1ed3 \u0111\u1ea1c ngay,`,
  `V\u00e0 \u0111i \u0111\u1ebfn qu\u00e1n c\u00e0 ph\u00ea \u0111\u1ec3 l\u00e0m vi\u1ec7c.`,
  `B\u00e2y gi\u1edd l\u00e0 10 gi\u1edd 27 ph\u00fat s\u00e1ng.`,
  `T\u00f4i s\u1ebd l\u00e0m vi\u1ec7c \u1edf \u0111\u00e2y cho \u0111\u1ebfn 12 gi\u1edd r\u01b0\u1ee1i,`,
  `Sau \u0111\u00f3 t\u00f4i c\u00f3 th\u1ec3 ngh\u1ec9 ng\u01a1i.`,
  `V\u1eady \u0111\u00f3 l\u00e0 th\u00f3i quen c\u1ee7a t\u00f4i t\u1eeb 5 gi\u1edd s\u00e1ng \u0111\u1ebfn 12 gi\u1edd tr\u01b0a.`,
  `C\u00f2n b\u1ea1n? Th\u00f3i quen c\u1ee7a b\u1ea1n c\u00f3 gi\u1ed1ng t\u00f4i kh\u00f4ng?`,
  `B\u1ea1n th\u00edch ho\u00e0n th\u00e0nh m\u1ecdi vi\u1ec7c v\u00e0o bu\u1ed5i s\u00e1ng,`,
  `Hay th\u00edch l\u00e0m t\u1eeb t\u1eeb m\u1ed9t ch\u00fat v\u00e0o bu\u1ed5i s\u00e1ng,`,
  `M\u1ed9t ch\u00fat v\u00e0o bu\u1ed5i chi\u1ec1u,`,
  `V\u00e0 m\u1ed9t ch\u00fat n\u1eefa v\u00e0o bu\u1ed5i t\u1ed1i?`,
  `Ch\u00e0o m\u1eebng b\u1ea1n chia s\u1ebb v\u1edbi ch\u00fang t\u00f4i trong ph\u1ea7n b\u00ecnh lu\u1eadn.`,
  `V\u1eady th\u00ec ch\u00fang ta g\u1eb7p nhau \u1edf video ti\u1ebfp theo nh\u00e9.`,
  `T\u1ea1m bi\u1ec7t.`,
];

