const TEDED_ANIMAL_VISION_EMW_DRGFOA8_TRANSLATIONS = [
  `Trong v\u01b0\u01a1ng qu\u1ed1c \u0111\u1ed9ng v\u1eadt t\u1ed3n t\u1ea1i h\u00e0ng ngh\u00ecn lo\u1ea1i m\u1eaft phi th\u01b0\u1eddng.`,
  `C\u00f3 con c\u00f3 th\u1ec3 \u0111i\u1ec1u khi\u1ec3n m\u1ed9t m\u1eaft xoay chuy\u1ec3n,`,
  `c\u00f3 con l\u1ea1i c\u00f3 \u0111\u1ed3ng t\u1eed h\u00ecnh l\u01b0\u1ee3n s\u00f3ng.`,
  `C\u00f3 con \u0111\u01b0\u1ee3c b\u1ea3o v\u1ec7 b\u1eb1ng m\u00ed m\u1eaft,`,
  `l\u1ea1i c\u00f3 con phun m\u00e1u t\u1ef1 v\u1ec7.`,
  `Nh\u01b0ng lo\u00e0i n\u00e0o c\u00f3 th\u1ec3 nh\u00ecn xa h\u00e0ng d\u1eb7m?`,
  `Ai c\u00f3 th\u1ec3 nh\u00ecn xuy\u00ean b\u00f3ng t\u1ed1i,`,
  `ai nh\u00ecn th\u1ea5u m\u1ecdi chi ti\u1ebft?`,
  `Ai c\u00f3 th\u1ec3 c\u1ea3m nh\u1eadn \u0111\u01b0\u1ee3c d\u1ea3i m\u00e0u r\u1ed9ng nh\u1ea5t?`,
  `V\u00e0 ai c\u00f3 th\u1ec3 n\u1eafm b\u1eaft chuy\u1ec3n \u0111\u1ed9ng nhanh nh\u1eb9n nh\u1ea5t?`,
  `S\u00f3ng \u00e1nh s\u00e1ng t\u1ea1o ra c\u1ea3m gi\u00e1c trong m\u1eaft,`,
  `m\u1eaft t\u1eadp trung \u00e1nh s\u00e1ng n\u00e0y v\u00e0o c\u00e1c th\u1ee5 th\u1ec3 \u00e1nh s\u00e1ng,`,
  `chuy\u1ec3n \u0111\u1ed5i th\u00e0nh m\u1ecdi th\u1ee9 ch\u00fang ta th\u1ea5y.`,
  `Nh\u1eefng t\u1ebf b\u00e0o n\u00e0y bi\u1ebfn \u00e1nh s\u00e1ng th\u00e0nh t\u00edn hi\u1ec7u th\u1ea7n kinh,`,
  `v\u00e0 g\u1eedi ch\u00fang \u0111\u1ebfn n\u00e3o b\u1ed9 \u0111\u1ec3 x\u1eed l\u00fd.`,
  `\u0110\u00f4i m\u1eaft nh\u00ecn r\u00f5 nh\u1ea5t trong b\u00f3ng t\u1ed1i`,
  `c\u00f3 kh\u1ea3 n\u0103ng thu nh\u1eadn nhi\u1ec1u \u00e1nh s\u00e1ng nh\u1ea5t c\u00f3 th\u1ec3.`,
  `Nh\u00e3n c\u1ea7u c\u1ee7a m\u1ef1c colossal to b\u1eb1ng s\u00e2n b\u00f3ng \u0111\u00e1,`,
  `l\u00e0 lo\u1ea1i l\u1edbn nh\u1ea5t t\u1eebng \u0111\u01b0\u1ee3c bi\u1ebft \u0111\u1ebfn tr\u00ean th\u1ebf gi\u1edbi.`,
  `\u0110i\u1ec1u n\u00e0y c\u00f3 l\u1ebd gi\u00fap ch\u00fang \u0111\u1ecbnh v\u1ecb c\u00e1 nh\u00e0 t\u00e1ng ph\u00e1t ra \u00e1nh s\u00e1ng l\u1edd m\u1edd \u0111\u1ec3 g\u00e2y nhi\u1ec5u c\u00e1c lo\u00e0i v\u1eadt ph\u00e1t quang kh\u00e1c.`,
  `M\u1ed9t s\u1ed1 lo\u00e0i c\u00e1 c\u00f2n c\u00f3 g\u01b0\u01a1ng trong m\u1eaft, \u0111\u00e2y l\u00e0 \u0111i\u1ec1u \u0111\u1ed9c \u0111\u00e1o trong s\u1ed1 c\u00e1c lo\u00e0i \u0111\u1ed9ng v\u1eadt c\u00f3 x\u01b0\u01a1ng s\u1ed1ng.`,
  `C\u00e1 m\u0169i nh\u1ecdn (telescopefish),`,
  `s\u1eed d\u1ee5ng c\u00e1c t\u1ea5m tinh th\u1ec3 nh\u1ecf t\u1eadp trung \u00e1nh s\u00e1ng hi\u1ec7u qu\u1ea3,`,
  `t\u1ea1o th\u00e0nh m\u1ed9t c\u1eb7p g\u01b0\u01a1ng tr\u00ean v\u00e0 d\u01b0\u1edbi trong m\u1eaft.`,
  `Ch\u00fang c\u00f3 th\u1ec3 quan s\u00e1t \u0111\u1ed3ng th\u1eddi c\u1ea3 ph\u00eda tr\u00ean v\u00e0 ph\u00eda d\u01b0\u1edbi,`,
  `v\u00e0 ngay c\u1ea3 \u1edf d\u01b0\u1edbi bi\u1ec3n s\u00e2u,`,
  `c\u0169ng c\u00f3 th\u1ec3 nh\u00ecn r\u00f5 h\u00ecnh d\u1ea1ng \u1edf xa.`,
  `Tu\u1ea7n l\u1ed9c tr\u00ean c\u1ea1n \u1edf B\u1eafc C\u1ef1c,`,
  `c\u00f3 th\u1ec3 th\u00edch nghi v\u1edbi b\u00f3ng t\u1ed1i k\u00e9o d\u00e0i h\u00e0ng th\u00e1ng tr\u1eddi.`,
  `N\u00f3 c\u00f3 th\u1ec3 thay \u0111\u1ed5i m\u00e0u s\u1eafc \u1edf ph\u00eda sau m\u1eaft,`,
  `M\u00f9a h\u00e8 chuy\u1ec3n sang m\u00e0u v\u00e0ng kim, m\u00f9a \u0111\u00f4ng chuy\u1ec3n sang m\u00e0u xanh lam.`,
  `M\u1eaft xanh nh\u1ea1y c\u1ea3m v\u1edbi \u00e1nh s\u00e1ng ng\u01b0\u1ee3c g\u1ea5p 1000 l\u1ea7n,`,
  `gi\u00fap nai s\u1eebng t\u1ea5m c\u00f3 th\u1ec3 nh\u1eadn bi\u1ebft nh\u1eefng v\u1eadt quan tr\u1ecdng tr\u00ean tuy\u1ebft,`,
  `ch\u1eb3ng h\u1ea1n nh\u01b0 n\u01b0\u1edbc ti\u1ec3u c\u1ee7a \u0111\u1ed9ng v\u1eadt v\u00e0 DE.`,
  `Khi n\u00f3i \u0111\u1ebfn th\u1ecb l\u1ef1c tinh t\u01b0\u1eddng nh\u1ea5t,`,
  `lo\u00e0i chim \u0111\u1ee9ng h\u00e0ng \u0111\u1ea7u.`,
  `C\u00e0ng nhi\u1ec1u th\u1ee5 th\u1ec3 \u00e1nh s\u00e1ng trong m\u1eaft,`,
  `c\u00e0ng c\u00f3 th\u1ec3 n\u1eafm b\u1eaft nhi\u1ec1u chi ti\u1ebft h\u01a1n,`,
  `kh\u1ea3 n\u0103ng x\u1eed l\u00fd th\u1ecb gi\u00e1c c\u0169ng t\u1eeb \u0111\u00f3 m\u00e0 t\u0103ng l\u00ean.`,
  `Chim s\u0103n m\u1ed3i c\u00f3 h\u1ed1 trung t\u00e2m r\u1ea5t s\u00e2u,`,
  `h\u1ed1 n\u00e0y c\u00e0ng s\u00e2u th\u00ec c\u00e0ng ch\u1ee9a \u0111\u01b0\u1ee3c nhi\u1ec1u th\u1ee5 th\u1ec3 \u00e1nh s\u00e1ng.`,
  `V\u00ec v\u1eady, th\u1ecb l\u1ef1c c\u1ee7a ch\u00fang s\u1eafc n\u00e9t g\u1ea5p \u0111\u00f4i so v\u1edbi con ng\u01b0\u1eddi.`,
  `Ch\u00fang c\u00f3 th\u1ec3 kh\u00f3a m\u1ee5c ti\u00eau m\u1ed9t con th\u1ecf t\u1eeb kho\u1ea3ng c\u00e1ch 3 km.`,
  `Sinh v\u1eadt n\u00e0o c\u00f3 kh\u1ea3 n\u0103ng c\u1ea3m nh\u1eadn m\u00e0u s\u1eafc t\u1ed1t nh\u1ea5t?`,
  `C\u00e2u h\u1ecfi n\u00e0y h\u01a1i kh\u00f3.`,
  `Nh\u1eefng t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng kh\u00e1c nhau s\u1ebd nh\u1ea1y c\u1ea3m v\u1edbi c\u00e1c b\u01b0\u1edbc s\u00f3ng \u00e1nh s\u00e1ng c\u1ee5 th\u1ec3,`,
  `ngh\u0129a l\u00e0 m\u00e0u s\u1eafc ch\u00fang ta nh\u00ecn th\u1ea5y ph\u1ee5 thu\u1ed9c ph\u1ea7n l\u1edbn v\u00e0o lo\u1ea1i t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng m\u00e0 ch\u00fang ta c\u00f3.`,
  `Theo l\u1ebd th\u01b0\u1eddng, c\u00e0ng c\u00f3 nhi\u1ec1u t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng x\u1eed l\u00fd c\u00e1c lo\u1ea1i m\u00e0u kh\u00e1c nhau,`,
  `th\u00ec kh\u1ea3 n\u0103ng nh\u1eadn bi\u1ebft m\u00e0u s\u1eafc c\u00e0ng t\u1ed1t.`,
  `Ch\u00f3 ch\u1ec9 c\u00f3 hai lo\u1ea1i t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn,`,
  `trong khi con ng\u01b0\u1eddi c\u00f3 ba lo\u1ea1i. V\u1ec1 m\u1eb7t n\u00e0y,`,
  `chim, c\u00e1 v\u00e0 c\u00f4n tr\u00f9ng b\u1ecf xa ch\u00fang ta.`,
  `B\u01b0\u1edbm xanh c\u00f3 \u00edt nh\u1ea5t 15 lo\u1ea1i t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng.`,
  `ch\u1ec9 ri\u00eang vi\u1ec7c ph\u00e2n bi\u1ec7t m\u00e0u xanh lam v\u00e0 xanh l\u1ee5c`,
  `\u0111\u00e3 c\u00f3 7 lo\u1ea1i. C\u00e1c nh\u00e0 nghi\u00ean c\u1ee9u cho r\u1eb1ng \u0111i\u1ec1u n\u00e0y c\u00f3 th\u1ec3 gi\u00fap ch\u00fang \u0111\u1ecbnh v\u1ecb l\u1eabn nhau trong c\u00e1c cu\u1ed9c r\u01b0\u1ee3t \u0111u\u1ed5i t\u1ed1c \u0111\u1ed9 cao.`,
  `T\u00f4m t\u00edt c\u00f3 t\u1edbi 16 lo\u1ea1i th\u1ee5 th\u1ec3 c\u1ea3m quang,`,
  `trong \u0111\u00f3 c\u00f3 5 lo\u1ea1i d\u00f9ng \u0111\u1ec3 nh\u1eadn bi\u1ebft quang ph\u1ed5 tia c\u1ef1c t\u00edm m\u00e0 m\u1eaft ng\u01b0\u1eddi kh\u00f4ng nh\u00ecn th\u1ea5y \u0111\u01b0\u1ee3c.`,
  `Tuy nhi\u00ean, c\u00e1c th\u00ed nghi\u1ec7m cho th\u1ea5y`,
  `kh\u1ea3 n\u0103ng \u0111\u1ed5i m\u00e0u c\u1ee7a t\u00f4m t\u00edt h\u1ea1n ch\u1ebf h\u01a1n nhi\u1ec1u so v\u1edbi nh\u1eefng g\u00ec b\u1ea1n t\u01b0\u1edfng.`,
  `C\u00e1ch ch\u00fang s\u1eed d\u1ee5ng \u0111\u00f4i m\u1eaft k\u00e9p v\u1eabn c\u00f2n l\u00e0 m\u1ed9t b\u00ed \u1ea9n.`,
  `Trong khi \u0111\u00f3, c\u00e1 v\u00e0ng`,
  `d\u00f9 ch\u1ec9 c\u00f3 4 lo\u1ea1i t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng,`,
  `nh\u01b0ng l\u1ea1i c\u1ef1c gi\u1ecfi ph\u00e2n bi\u1ec7t nh\u1eefng kh\u00e1c bi\u1ec7t nh\u1ecf trong s\u1eafc \u0111\u1ed9.`,
  `Cu\u1ed1i c\u00f9ng, c\u00f4n tr\u00f9ng l\u00e0 nh\u1eefng b\u1eadc th\u1ea7y v\u1ec1 th\u1ecb gi\u00e1c khi bay.`,
  `Chuy\u1ec3n \u0111\u1ed9ng nhanh \u0111\u00f2i h\u1ecfi c\u00e1c t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng ph\u1ea3i nhanh ch\u00f3ng nh\u1eadn bi\u1ebft s\u1ef1 thay \u0111\u1ed5i c\u1ee7a \u00e1nh s\u00e1ng,`,
  `v\u00e0 n\u00e3o b\u1ed9 c\u0169ng c\u1ea7n x\u1eed l\u00fd th\u00f4ng tin n\u00e0y c\u1ef1c nhanh.`,
  `M\u1ed9t b\u1ed9 phim t\u1ed1c \u0111\u1ed9 24 khung h\u00ecnh m\u1ed7i gi\u00e2y \u0111\u1ed1i v\u1edbi ch\u00fang ta g\u1ea7n nh\u01b0 li\u1ec1n m\u1ea1ch.`,
  `Nh\u01b0ng n\u1ebfu cho c\u00f4n tr\u00f9ng xem th\u00ec \u0111\u00f3 l\u1ea1i l\u00e0 m\u1ed9t lo\u1ea1t \u1ea3nh t\u0129nh.`,
  `C\u00e1c t\u1ebf b\u00e0o c\u1ea3m nh\u1eadn \u00e1nh s\u00e1ng c\u1ee7a ru\u1ed3i ghi nh\u1eadn s\u1ef1 thay \u0111\u1ed5i nhanh g\u1ea5p 10 l\u1ea7n c\u1ee7a ch\u00fang ta,`,
  `\u0111\u00f3 l\u00e0 l\u00fd do t\u1ea1i sao ch\u00fang r\u1ea5t kh\u00f3 b\u1eaft.`,
  `Nh\u1eefng lo\u00e0i \u0111\u1ed9ng v\u1eadt n\u00e0y \u0111\u1ec1u c\u00f3 th\u1ecb gi\u00e1c c\u1ef1c t\u1ed1t,`,
  `nh\u01b0ng kh\u00f4ng c\u00f3 ng\u01b0\u1eddi chi\u1ebfn th\u1eafng ho\u00e0n h\u1ea3o.`,
  `B\u1edfi v\u00ec c\u00f3 s\u1ef1 \u0111\u00e1nh \u0111\u1ed5i gi\u1eefa c\u00e1c kh\u1ea3 n\u0103ng kh\u00e1c nhau,`,
  `m\u1ed7i lo\u00e0i ch\u1ec9 v\u01b0\u1ee3t tr\u1ed9i \u1edf m\u1ed9t s\u1ed1 l\u0129nh v\u1ef1c c\u1ee5 th\u1ec3.`,
  `Do \u0111\u00f3, m\u1ed9t s\u1ed1 \u0111\u00f4i m\u1eaft c\u00f3 n\u0103ng l\u1ef1c chuy\u00ean bi\u1ec7t,`,
  `Ng\u01b0\u1eddi nh\u01b0 ch\u00fang ta,`,
  `l\u1ea1i l\u00e0 chuy\u00ean gia t\u1ed5ng h\u1ee3p nhi\u1ec1u l\u0129nh v\u1ef1c.`,
  `Cho d\u00f9 l\u00e0 qu\u1ea3 b\u00f3ng \u0111\u00e1 l\u1edbn,`,
  `hay l\u00e0 \u0111\u00f4i m\u1eaft c\u00f3 th\u1ec3 nh\u00ecn th\u1ea5y tia c\u1ef1c t\u00edm,`,
  `c\u00e1ch nh\u00ecn th\u1ebf gi\u1edbi c\u0169ng mu\u00f4n h\u00ecnh v\u1ea1n tr\u1ea1ng nh\u01b0 sinh m\u1ec7nh.`,
  `Ch\u00fang t\u00f4i cam k\u1ebft cung c\u1ea5p n\u1ed9i dung gi\u00e1o d\u1ee5c ch\u1ea5t l\u01b0\u1ee3ng cao mi\u1ec5n ph\u00ed cho c\u00e0ng nhi\u1ec1u ng\u01b0\u1eddi s\u1eed d\u1ee5ng nhi\u1ec1u ng\u00f4n ng\u1eef c\u00e0ng t\u1ed1t.`,
  `H\u00e3y gi\u00fap h\u1ed7 tr\u1ee3 s\u1ee9 m\u1ec7nh phi l\u1ee3i nhu\u1eadn c\u1ee7a ch\u00fang t\u00f4i b\u1eb1ng c\u00e1ch \u0111\u00f3ng g\u00f3p cho Patreon c\u1ee7a ch\u00fang t\u00f4i,`,
  `v\u00e0 \u0111\u1eebng qu\u00ean \u0111\u0103ng k\u00fd k\u00eanh n\u00e0y.`,
];

