const TEDED_TOILET_HISTORY_UPY3BQ8TZOQ_TRANSLATIONS = [
  `V\u00e0o nh\u1eefng ng\u00e0y n\u1eafng r\u00e1o, c\u00e1c c\u00f4ng d\u00e2n La M\u00e3 c\u1ed5 \u0111\u1ea1i c\u1ee7a Ostia s\u1ebd t\u1eadp trung t\u1ea1i m\u1ed9t b\u0103ng gh\u1ebf d\u00e0i b\u1eb1ng \u0111\u00e1 ch\u1ea1y d\u1ecdc theo n\u01a1i h\u1ed9i h\u1ecdp c\u00f4ng c\u1ed9ng.`,
  `Trong l\u00fac b\u1ea1n b\u00e8 v\u00e0 h\u00e0ng x\u00f3m trao \u0111\u1ed5i tin t\u1ee9c v\u00e0 chuy\u1ec7n phi\u1ebfm,`,
  `h\u1ecd c\u0169ng tham gia v\u00e0o m\u1ed9t vi\u1ec7c c\u1ea5p b\u00e1ch h\u01a1n nhi\u1ec1u.`,
  `Nh\u1eefng nh\u00e0 v\u1ec7 sinh c\u00f4ng c\u1ed9ng n\u00e0y c\u00f3 th\u1ec3 ch\u1ee9a t\u1edbi 20 c\u00f4ng d\u00e2n La M\u00e3 m\u1ed9t l\u00fac,`,
  `v\u00e0 s\u1eed d\u1ee5ng n\u01b0\u1edbc ch\u1ea3y b\u00ean d\u01b0\u1edbi \u0111\u1ec3 lo\u1ea1i b\u1ecf ch\u1ea5t th\u1ea3i.`,
  `Ng\u00e0y nay, h\u1ea7u h\u1ebft c\u00e1c n\u1ec1n v\u0103n h\u00f3a coi vi\u1ec7c \u0111i v\u1ec7 sinh l\u00e0 m\u1ed9t chuy\u1ec7n ri\u00eang t\u01b0 h\u01a1n.`,
  `Th\u1ebf nh\u01b0ng ngay c\u1ea3 khi \u0111i v\u1ec7 sinh m\u1ed9t m\u00ecnh,`,
  `c\u01a1 s\u1edf h\u1ea1 t\u1ea7ng n\u01b0\u1edbc th\u1ea3i c\u00f4ng c\u1ed9ng v\u1eabn l\u00e0 m\u1ed9t trong nh\u1eefng ph\u00e1t minh quan tr\u1ecdng nh\u1ea5t trong l\u1ecbch s\u1eed nh\u00e2n lo\u1ea1i.`,
  `Nhi\u1ec1u v\u0103n b\u1ea3n t\u00f4n gi\u00e1o c\u1ed5 \u0111\u1ea1i m\u00f4 t\u1ea3 c\u00e1c ph\u01b0\u01a1ng ph\u00e1p t\u00e1ch n\u01b0\u1edbc th\u1ea3i kh\u1ecfi n\u01b0\u1edbc u\u1ed1ng v\u00e0 khu c\u1eafm tr\u1ea1i.`,
  `Vi\u1ec7c qu\u1ea3n l\u00fd n\u01b0\u1edbc th\u1ea3i t\u01b0\u01a1ng t\u1ef1 nh\u01b0 hi\u1ec7n \u0111\u1ea1i \u0111\u00e3 c\u00f3 t\u1eeb n\u0103m 3000 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean.`,
  `C\u00e1c khu \u0111\u1ecbnh c\u01b0 c\u1ed5 \u0111\u1ea1i c\u1ee7a L\u01b0\u1ee1ng H\u00e0 c\u00f3 m\u1ed9t c\u1ea5u tr\u00fac b\u1eb1ng \u0111\u1ea5t s\u00e9t \u1edf v\u1ecb tr\u00ed ri\u00eang t\u01b0 nh\u1ea5t trong nh\u00e0,`,
  `th\u01b0\u1eddng \u0111\u01b0\u1ee3c d\u00f9ng \u0111\u1ec3 ng\u1ed3i x\u1ed5m.`,
  `Ch\u00fang \u0111\u01b0\u1ee3c n\u1ed1i v\u1edbi c\u00e1c \u0111\u01b0\u1eddng \u1ed1ng d\u1eabn n\u01b0\u1edbc th\u1ea3i ra r\u00e3nh v\u00e0 h\u1ed1 ga tr\u00ean \u0111\u01b0\u1eddng ph\u1ed1.`,
  `V\u00ed d\u1ee5 tr\u00ean ph\u00e1t tri\u1ec3n m\u1ea1nh m\u1ebd v\u00e0o th\u1eddi k\u1ef3 \u0111\u1ed3 \u0111\u1ed3ng,`,
  `cho ph\u00e9p c\u00e1c gia \u0111\u00ecnh kh\u00f4ng ch\u1ec9 x\u1eed l\u00fd ch\u1ea5t th\u1ea3i c\u1ee7a con ng\u01b0\u1eddi m\u00e0 c\u00f2n t\u1eafm r\u1eeda v\u00e0 gi\u1eb7t gi\u0169.`,
  `c\u0169ng nh\u01b0 \u1edf m\u1ed9t s\u1ed1 khu v\u1ef1c thu\u1ed9c l\u01b0u v\u1ef1c s\u00f4ng \u1ea4n,`,
  `h\u1ea7u h\u1ebft m\u1ecdi nh\u00e0 v\u1ec7 sinh \u0111\u1ec1u \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i v\u1edbi h\u1ec7 th\u1ed1ng tho\u00e1t n\u01b0\u1edbc th\u00e0nh ph\u1ed1.`,
  `Nh\u00e0 v\u1ec7 sinh trong c\u00e1c cung \u0111i\u1ec7n c\u1ed5 \u1edf Crete th\u1eadm ch\u00ed c\u00f2n c\u00f3 th\u1ec3 x\u1ea3 n\u01b0\u1edbc th\u1ee7 c\u00f4ng.`,
  `C\u00e1c nh\u00e0 nghi\u00ean c\u1ee9u kh\u00f4ng ch\u1eafc ch\u1eafn v\u1ec1 c\u00e1ch nh\u1eefng h\u1ec7 th\u1ed1ng tho\u00e1t n\u01b0\u1edbc ban \u0111\u1ea7u n\u00e0y \u0111\u01b0\u1ee3c ph\u00e1t minh,`,
  `nh\u01b0ng c\u00f3 th\u1ec3 kh\u1eb3ng \u0111\u1ecbnh r\u1eb1ng vi\u1ec7c qu\u1ea3n l\u00fd n\u01b0\u1edbc th\u1ea3i l\u00e0 y\u1ebfu t\u1ed1 then ch\u1ed1t \u0111\u1ed1i v\u1edbi s\u1ee9c kh\u1ecfe c\u1ed9ng \u0111\u1ed3ng.`,
  `N\u01b0\u1edbc th\u1ea3i ch\u01b0a \u0111\u01b0\u1ee3c x\u1eed l\u00fd c\u00f3 th\u1ec3 nu\u00f4i d\u01b0\u1ee1ng vi sinh v\u1eadt c\u00f3 h\u1ea1i,`,
  `g\u00e2y ra c\u00e1c b\u1ec7nh nh\u01b0 t\u1ea3,`,
  `ki\u1ebft l\u1ef5 v\u00e0 s\u1ed1t th\u01b0\u01a1ng h\u00e0n.`,
  `Tuy nhi\u00ean, ph\u1ea3i m\u1ea5t h\u00e0ng ngh\u00ecn n\u0103m sau c\u00e1c nh\u00e0 khoa h\u1ecdc m\u1edbi c\u00f3 th\u1ec3 hi\u1ec3u r\u00f5 m\u1ed1i quan h\u1ec7 gi\u1eefa n\u01b0\u1edbc th\u1ea3i v\u00e0 b\u1ec7nh t\u1eadt.`,
  `D\u00f9 v\u1eady, m\u1ed1i li\u00ean h\u1ec7 gi\u1eefa m\u00f9i n\u01b0\u1edbc th\u1ea3i h\u00f4i th\u1ed1i v\u00e0 b\u1ec7nh t\u1eadt \u0111\u00e3 \u0111\u01b0\u1ee3c ghi nh\u1eadn t\u1eeb n\u0103m 100 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean.`,
  `\u0110\u1ebfn n\u0103m 100 sau C\u00f4ng nguy\u00ean, c\u00e1c gi\u1ea3i ph\u00e1p v\u1ec7 sinh ph\u1ee9c t\u1ea1p h\u01a1n \u0111\u00e3 xu\u1ea5t hi\u1ec7n.`,
  `\u0110\u1ebf ch\u1ebf La M\u00e3 s\u1eed d\u1ee5ng h\u1ec7 th\u1ed1ng d\u1eabn n\u01b0\u1edbc ch\u1ea3y li\u00ean t\u1ee5c,`,
  `\u0111\u01b0a n\u01b0\u1edbc th\u1ea3i ra ngo\u1ea1i \u00f4 th\u00e0nh ph\u1ed1.`,
  `C\u00f9ng th\u1eddi k\u1ef3, Trung Qu\u1ed1c c\u0169ng c\u00f3 nh\u00e0 v\u1ec7 sinh ri\u00eang v\u00e0 c\u00f4ng c\u1ed9ng.`,
  `Tuy nhi\u00ean, \u1edf Trung Qu\u1ed1c, ch\u1ea5t th\u1ea3i n\u00e0y \u0111\u01b0\u1ee3c t\u00e1i s\u1eed d\u1ee5ng ngay l\u1eadp t\u1ee9c,`,
  `Ph\u00e2n ng\u01b0\u1eddi t\u1eeb nh\u00e0 v\u1ec7 sinh gia \u0111\u00ecnh ch\u1ee7 y\u1ebfu \u0111\u01b0\u1ee3c d\u00f9ng \u0111\u1ec3 nu\u00f4i l\u1ee3n,`,
  `c\u00f2n ch\u1ea5t th\u1ea3i t\u1eeb nh\u00e0 v\u1ec7 sinh c\u00f4ng c\u1ed9ng s\u1ebd \u0111\u01b0\u1ee3c ng\u01b0\u1eddi chuy\u00ean tr\u00e1ch thu gom,`,
  `sau \u0111\u00f3 ch\u1ebf bi\u1ebfn th\u00e0nh ph\u00e2n b\u00f3n \u0111\u1ec3 b\u00e1n.`,
  `Ph\u01b0\u01a1ng ph\u00e1p x\u1eed l\u00fd ch\u1ea5t th\u1ea3i truy\u1ec1n th\u1ed1ng c\u1ee7a Trung Qu\u1ed1c \u0111\u00e3 duy tr\u00ec trong nhi\u1ec1u th\u1ebf k\u1ef7.`,
  `Nh\u01b0ng \u1edf ch\u00e2u \u00c2u,`,
  `s\u1ef1 suy t\u00e0n c\u1ee7a \u0110\u1ebf ch\u1ebf La M\u00e3 \u0111\u00e3 \u0111\u1ea9y v\u1ec7 sinh c\u00f4ng c\u1ed9ng v\u00e0o th\u1eddi k\u1ef3 t\u0103m t\u1ed1i.`,
  `H\u1ed1 x\u00ed, c\u00f2n \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 "gong", r\u1ea5t ph\u1ed5 bi\u1ebfn.`,
  `B\u00f4 th\u01b0\u1eddng xuy\u00ean \u0111\u01b0\u1ee3c \u0111\u1ed5 th\u1eb3ng ra \u0111\u01b0\u1eddng,`,
  `c\u00f2n c\u00e1c c\u1eeda s\u1ed5 cao c\u1ee7a l\u00e2u \u0111\u00e0i th\u00ec x\u1ea3 ch\u1ea5t th\u1ea3i xu\u1ed1ng h\u1ed1 ph\u00e2n c\u00f4ng c\u1ed9ng b\u00ean ngo\u00e0i.`,
  `\u0110\u1ebfn \u0111\u00eam, nh\u1eefng ng\u01b0\u1eddi h\u00f3t ph\u00e2n s\u1ebd ch\u1ea5t \u0111\u1ea7y xe c\u00fat k\u00edt ch\u1ea5t th\u1ea3i,`,
  `ch\u1edf ch\u00fang ra ngo\u00e0i th\u00e0nh ph\u1ed1 v\u00e0 v\u1ee9t b\u1ecf.`,
  `Trong nhi\u1ec1u th\u1ebf k\u1ef7, ch\u00e2u \u00c2u kh\u00f4ng x\u1eed l\u00fd v\u1ec7 sinh ch\u1ea5t th\u1ea3i,`,
  `nh\u01b0ng b\u1ea3n th\u00e2n nh\u00e0 v\u1ec7 sinh \u0111\u00e3 tr\u1ea3i qua m\u1ed9t s\u1ed1 thay \u0111\u1ed5i l\u1edbn.`,
  `\u0110\u1ebfn cu\u1ed1i th\u1eddi Trung c\u1ed5,`,
  `h\u1ea7u h\u1ebft c\u00e1c gia \u0111\u00ecnh gi\u00e0u c\u00f3 \u0111\u1ec1u \u0111\u01b0\u1ee3c trang b\u1ecb b\u1ed3n c\u1ea7u,`,
  `H\u00f2m g\u1ed7 c\u00f3 n\u1eafp v\u00e0 gh\u1ebf ng\u1ed3i.`,
  `Trong c\u00e1c tri\u1ec1u \u0111\u00ecnh ho\u00e0ng gia \u1edf Anh,`,
  `nh\u1eefng chi\u1ebfc b\u00f4 n\u00e0y \u0111\u01b0\u1ee3c c\u00e1c th\u1ecb th\u1ea7n chuy\u00ean qu\u1ea3n l\u00fd ch\u1ea5t th\u1ea3i ph\u1ee5 tr\u00e1ch.`,
  `Ngo\u00e0i ra, \u0111\u1ec3 theo d\u00f5i s\u1ee9c kh\u1ecfe \u0111\u01b0\u1eddng ru\u1ed9t c\u1ee7a nh\u00e0 vua,`,
  `m\u1ed1i quan h\u1ec7 v\u00f4 c\u00f9ng th\u00e2n thi\u1ebft gi\u1eefa v\u1ecb th\u1ecb th\u1ea7n n\u00e0y v\u00e0 nh\u00e0 vua,`,
  `\u0111\u00e3 khi\u1ebfn ch\u1ee9c danh n\u00e0y tr\u1edf n\u00ean c\u1ef1c k\u1ef3 c\u00f3 \u1ea3nh h\u01b0\u1edfng.`,
  `B\u01b0\u1edbc nh\u1ea3y v\u1ecdt l\u1edbn ti\u1ebfp theo trong l\u1ecbch s\u1eed ph\u00e1t tri\u1ec3n c\u00f4ng ngh\u1ec7 nh\u00e0 v\u1ec7 sinh xu\u1ea5t hi\u1ec7n v\u00e0o n\u0103m 1596.`,
  `Ng\u00e0i John Harington \u0111\u00e3 thi\u1ebft k\u1ebf chi\u1ebfc b\u1ed3n c\u1ea7u x\u1ea3 n\u01b0\u1edbc hi\u1ec7n \u0111\u1ea1i \u0111\u1ea7u ti\u00ean cho N\u1eef ho\u00e0ng Elizabeth.`,
  `\u00d4ng s\u1eed d\u1ee5ng c\u1ea7n g\u1ea1t \u0111\u1ec3 x\u1ea3 n\u01b0\u1edbc v\u00e0 van \u0111\u1ec3 h\u00fat n\u01b0\u1edbc t\u1eeb th\u00f9ng,`,
  `t\u1ea1o ti\u1ec1n \u0111\u1ec1 cho thi\u1ebft k\u1ebf b\u1ed3n c\u1ea7u hi\u1ec7n \u0111\u1ea1i.`,
  `Tuy nhi\u00ean, ph\u00e1t minh c\u1ee7a Harington kh\u00f4ng gi\u1ea3i quy\u1ebft \u0111\u01b0\u1ee3c v\u1ea5n \u0111\u1ec1 ng\u0103n k\u00e9o ch\u1ea5t th\u1ea3i.`,
  `May m\u1eafn thay, \u0111\u1ebfn n\u0103m 1775,`,
  `nh\u00e0 ph\u00e1t minh ng\u01b0\u1eddi Scotland Alexander Cumming \u0111\u00e3 th\u00eam m\u1ed9t thi\u1ebft k\u1ebf u\u1ed1n cong v\u00e0o \u0111\u01b0\u1eddng \u1ed1ng tho\u00e1t n\u01b0\u1edbc \u0111\u1ec3 gi\u1eef n\u01b0\u1edbc v\u00e0 ng\u0103n m\u00f9i h\u00f4i.`,
  `Thi\u1ebft k\u1ebf h\u00ecnh ch\u1eef S n\u00e0y,`,
  `\u0111\u00e3 \u0111\u01b0\u1ee3c Thomas Crapper c\u1ea3i ti\u1ebfn th\u00e0nh thi\u1ebft k\u1ebf h\u00ecnh ch\u1eef U hi\u1ec7n \u0111\u1ea1i.`,
  `M\u1eb7c d\u00f9 thu\u1eadt ng\u1eef`,
  `\u0110\u1ebfn cu\u1ed1i th\u1ebf k\u1ef7 19,`,
  `nhi\u1ec1u th\u00e0nh ph\u1ed1 \u0111\u00e3 c\u00f3 c\u01a1 s\u1edf h\u1ea1 t\u1ea7ng tho\u00e1t n\u01b0\u1edbc hi\u1ec7n \u0111\u1ea1i v\u00e0 nh\u00e0 m\u00e1y x\u1eed l\u00fd n\u01b0\u1edbc th\u1ea3i.`,
  `Ng\u00e0y nay, nh\u00e0 v\u1ec7 sinh c\u0169ng \u0111\u00e3 ph\u00e1t tri\u1ec3n nhi\u1ec1u t\u00ednh n\u0103ng \u0111a d\u1ea1ng,`,
  `t\u1eeb sang tr\u1ecdng \u0111\u1ebfn b\u1ec1n v\u1eefng.`,
  `Tuy nhi\u00ean, v\u1eabn c\u00f2n kho\u1ea3ng 2 t\u1ef7 ng\u01b0\u1eddi kh\u00f4ng c\u00f3 nh\u00e0 v\u1ec7 sinh ri\u00eang t\u1ea1i nh\u00e0,`,
  `v\u00e0 2,2 t\u1ef7 ng\u01b0\u1eddi kh\u00e1c kh\u00f4ng c\u00f3 c\u01a1 s\u1edf x\u1eed l\u00fd n\u01b0\u1edbc th\u1ea3i ph\u00f9 h\u1ee3p,`,
  `khi\u1ebfn h\u1ecd ti\u1ebfp x\u00fac v\u1edbi v\u00f4 s\u1ed1 b\u1ec7nh t\u1eadt.`,
  `\u0110\u1ec3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 n\u00e0y,`,
  `ch\u00fang ta c\u1ea7n ph\u00e1t minh ra c\u00e1c c\u00f4ng ngh\u1ec7 v\u1ec7 sinh m\u1edbi,`,
  `v\u00e0 th\u00f4ng qua c\u00e1c y\u1ebfu t\u1ed1 h\u00e0nh vi,`,
  `kinh t\u1ebf v\u00e0 ch\u00ednh tr\u1ecb \u0111\u1ec3 gi\u1ea3i quy\u1ebft s\u1ef1 b\u1ea5t b\u00ecnh \u0111\u1eb3ng trong h\u1ec7 th\u1ed1ng \u0111\u01b0\u1eddng \u1ed1ng v\u1ec7 sinh.`,
  `\u0110\u1ec3 t\u00ecm hi\u1ec3u l\u1ecbch s\u1eed h\u1ea5p d\u1eabn, tri\u1ebft l\u00fd kh\u00f3 hi\u1ec3u v\u1ec1 cu\u1ed9c phi\u00eau l\u01b0u ngo\u00e0i kh\u00f4ng gian,`,
  `c\u00e2u tr\u1ea3 l\u1eddi cho nh\u1eefng c\u00e2u h\u1ecfi ng\u1eabu nhi\u00ean nh\u1ea5t v\u1ec1 c\u01a1 th\u1ec3 b\u1ea1n, v.v.`,
  `H\u00e3y \u0111\u0103ng k\u00fd k\u00eanh n\u00e0y,`,
  `H\u00e3y ti\u1ebfp t\u1ee5c theo d\u00f5i,`,
  `v\u00e0 gi\u1eef s\u1ef1 t\u00f2 m\u00f2.`,
];

