const TMP_CHINA_HISTORY_FULL_C9QIE0RFSLQ_TRANSLATIONS = [
  `Tr\u01b0\u1edbc th\u1eddi nh\u00e0 H\u1ea1, Trung Qu\u1ed1c v\u1eabn \u1edf trong x\u00e3 h\u1ed9i nguy\u00ean th\u1ee7y.`,
  `Vi\u1ec7c ch\u1ecdn v\u1ecb vua ti\u1ebfp theo \u0111\u1ec1u th\u1ef1c hi\u1ec7n ch\u1ebf \u0111\u1ed9 thi\u1ec7n nh\u01b0\u1ee3ng,`,
  `T\u1ee9c l\u00e0, anh h\u00f9ng kh\u00f4ng k\u1ec3 xu\u1ea5t th\u00e2n,`,
  `Ai c\u00f3 n\u0103ng l\u1ef1c th\u00ec ng\u01b0\u1eddi \u0111\u00f3 s\u1ebd cai tr\u1ecb.`,
  `\u0110\u1ebfn \u0111\u1eddi vua khai qu\u1ed1c nh\u00e0 H\u1ea1 l\u00e0 V\u0169,`,
  `\u0110\u00fang v\u1eady, ch\u00ednh l\u00e0 V\u0169 \u0111\u00e3 tr\u1ecb th\u1ee7y \u0111\u00f3,`,
  `M\u1ecdi vi\u1ec7c \u0111\u00e3 kh\u00f4ng c\u00f2n nh\u01b0 tr\u01b0\u1edbc n\u1eefa.`,
  `V\u0169 qu\u1ea3 th\u1eadt l\u00e0 m\u1ed9t nh\u00e2n t\u00e0i.`,
  `Sau khi l\u00e0m vua,`,
  `C\u00f4ng tr\u1ea1ng ng\u00e0y c\u00e0ng l\u1eaby l\u1eebng,`,
  `Quy\u1ec1n l\u1ef1c c\u0169ng ng\u00e0y c\u00e0ng l\u1edbn m\u1ea1nh.`,
  `\u00d4ng ta kh\u00f4ng cam t\u00e2m truy\u1ec1n ng\u00f4i v\u1ecb cho ng\u01b0\u1eddi kh\u00e1c n\u1eefa,`,
  `Th\u1ebf l\u00e0 ng\u1ea5m ng\u1ea7m b\u1ed3i d\u01b0\u1ee1ng con trai m\u00ecnh l\u00e0 Kh\u1ea3i,`,
  `Nh\u01b0ng b\u1ec1 ngo\u00e0i v\u1eabn ch\u1ecdn m\u1ed9t ng\u01b0\u1eddi k\u1ebf v\u1ecb t\u00ean l\u00e0 B\u00e1 \u00cdch theo \u0111\u00fang quy t\u1eafc.`,
  `Cha con V\u0169 v\u00e0 Kh\u1ea3i sau v\u00e0i n\u0103m s\u1eafp \u0111\u1eb7t k\u1ef9 l\u01b0\u1ee1ng,`,
  `\u1ea2nh h\u01b0\u1edfng c\u1ee7a Kh\u1ea3i d\u1ea7n v\u01b0\u1ee3t qua B\u00e1 \u00cdch.`,
  `Sau khi V\u0169 qua \u0111\u1eddi,`,
  `\u0111\u00e1ng l\u1ebd B\u00e1 \u00cdch k\u1ebf v\u1ecb, nh\u01b0ng l\u00fac n\u00e0y kh\u00f4ng c\u00f3 m\u1ea5y ai \u0111\u1ec3 \u00fd \u0111\u1ebfn \u00f4ng ta n\u1eefa,`,
  `\u0111\u1ec1u \u0111i \u1ee7ng h\u1ed9 Kh\u1ea3i.`,
  `B\u00e1 \u00cdch c\u0169ng kh\u00f4ng ng\u1ed1c, \u0111\u1ecbnh ch\u1ed1ng tr\u1ea3 m\u1ed9t ch\u00fat,`,
  `l\u00fac n\u00e0y m\u1edbi ph\u00e1t hi\u1ec7n s\u1ee9c l\u1ef1c c\u1ee7a m\u00ecnh c\u0103n b\u1ea3n kh\u00f4ng th\u1ec3 so s\u00e1nh v\u1edbi Kh\u1ea3i.`,
  `V\u00ec \u0111\u00e3 kh\u00f4ng th\u1ec3 xoay chuy\u1ec3n t\u00ecnh th\u1ebf,`,
  `B\u00e1 \u00cdch r\u1ea5t bi\u1ebft \u0111i\u1ec1u m\u00e0 r\u00fat kh\u1ecfi cu\u1ed9c tranh gi\u00e0nh, t\u00f4i kh\u00f4ng c\u00f3 kh\u1ea3 n\u0103ng \u0111\u1ec3 Kh\u1ea3i l\u00e0m vua.`,
  `C\u1ee9 nh\u01b0 v\u1eady, Kh\u1ea3i thay th\u1ebf B\u00e1 \u00cdch thu\u1eadn l\u1ee3i k\u1ebf th\u1eeba v\u01b0\u01a1ng v\u1ecb.`,
  `Kh\u1ea3i c\u0169ng l\u00e0 m\u1ed9t ng\u01b0\u1eddi c\u00f3 d\u00e3 t\u00e2m, gi\u1ed1ng nh\u01b0 cha c\u1ee7a \u00f4ng ta,`,
  `th\u1ee9c \u0103n \u0111\u00e3 \u0111\u1ebfn tay sao c\u00f3 th\u1ec3 \u0111\u1ec3 ng\u01b0\u1eddi kh\u00e1c c\u01b0\u1edbp m\u1ea5t.`,
  `V\u00ec v\u1eady \u00f4ng ta c\u0169ng truy\u1ec1n ng\u00f4i v\u1ecb c\u1ee7a m\u00ecnh cho con trai.`,
  `Ch\u1ebf \u0111\u1ed9 thi\u1ec7n nh\u01b0\u1ee3ng t\u1eeb \u0111\u00f3 bi\u1ebfn th\u00e0nh ch\u1ebf \u0111\u1ed9 th\u1ebf t\u1eadp,`,
  `ch\u1ebf \u0111\u1ed9 th\u1ebf t\u1eadp t\u1eeb nh\u00e0 H\u1ea1 \u0111\u1ebfn nh\u00e0 Thanh t\u1ed5ng c\u1ed9ng \u0111\u01b0\u1ee3c \u00e1p d\u1ee5ng h\u01a1n b\u1ed1n ngh\u00ecn n\u0103m,`,
  `cho \u0111\u1ebfn khi ho\u00e0ng \u0111\u1ebf Thanh Tuy\u00ean Th\u1ed1ng Ph\u1ed5 Nghi tho\u00e1i v\u1ecb m\u1edbi k\u1ebft th\u00fac.`,
  `H\u1ec7 th\u1ed1ng th\u1ebf t\u1eadp ra \u0111\u1eddi \u0111\u00e3 l\u00e0m thay \u0111\u1ed5i h\u00ecnh th\u00e1i x\u00e3 h\u1ed9i ban \u0111\u1ea7u,`,
  `\u0110\u00e1nh d\u1ea5u s\u1ef1 th\u00e0nh l\u1eadp tri\u1ec1u \u0111\u1ea1i \u0111\u1ea7u ti\u00ean trong l\u1ecbch s\u1eed Trung Qu\u1ed1c l\u00e0 nh\u00e0 H\u1ea1.`,
  `Nh\u00e0 H\u1ea1 k\u00e9o d\u00e0i h\u01a1n 400 n\u0103m,`,
  `Tr\u1ea3i qua 17 \u0111\u1eddi vua,`,
  `V\u1ecb vua cu\u1ed1i c\u00f9ng t\u00ean l\u00e0 H\u1ea1 Ki\u1ec7t,`,
  `M\u1ed9t b\u1ea1o ch\u00faa n\u1ed5i ti\u1ebfng,`,
  `V\u00ec qu\u00e1 hoang d\u00e2m b\u1ea1o ng\u01b0\u1ee3c, khi\u1ebfn d\u00e2n ch\u00fang s\u1ed1ng kh\u00f4ng b\u1eb1ng ch\u1ebft.`,
  `C\u00f3 \u00e1p b\u1ee9c \u1eaft c\u00f3 \u0111\u1ea5u tranh,`,
  `Th\u1ebf l\u00e0 c\u00f3 m\u1ed9t ng\u01b0\u1eddi t\u00ean Th\u00e0nh Thang \u0111\u1ee9ng l\u00ean kh\u1edfi ngh\u0129a,`,
  `\u0110\u00e3 di\u1ec7t nh\u00e0 H\u1ea1 th\u00e0nh c\u00f4ng.`,
  `Nh\u00e0 Th\u01b0\u01a1ng sau \u0111\u00f3 \u0111\u01b0\u1ee3c th\u00e0nh l\u1eadp,`,
  `Khai qu\u1ed1c qu\u00e2n ch\u1ee7 ch\u00ednh l\u00e0 Th\u00e0nh Thang.`,
  `Nh\u00e0 Th\u01b0\u01a1ng c\u00f3 m\u1ed9t \u0111\u1eb7c \u0111i\u1ec3m,`,
  `R\u1ea5t th\u00edch d\u1eddi \u0111\u00f4,`,
  `B\u00ecnh th\u01b0\u1eddng ch\u00fang ta chuy\u1ec3n nh\u00e0 \u0111\u00e3 r\u1ea5t phi\u1ec1n ph\u1ee9c r\u1ed3i.`,
  `M\u1ed9t qu\u1ed1c gia r\u1ed9ng l\u1edbn c\u1ee9 di chuy\u1ec3n h\u1ebft l\u1ea7n n\u00e0y \u0111\u1ebfn l\u1ea7n kh\u00e1c,`,
  `Kh\u00f4ng ph\u1ea3i v\u00ec vui \u0111\u00e2u nh\u1ec9?`,
  `C\u00f3 hai c\u00e1ch gi\u1ea3i th\u00edch,`,
  `M\u1ed9t l\u00e0 v\u1ecb tr\u00ed \u0111\u1ecba l\u00fd c\u1ee7a nh\u00e0 H\u1ea1 \u1edf khu v\u1ef1c Trung Nguy\u00ean,`,
  `T\u1ee9c l\u00e0 H\u00e0 B\u1eafc,`,
  `H\u00e0 Nam v\u00e0 S\u01a1n \u0110\u00f4ng,`,
  `G\u1ea7n s\u00f4ng Ho\u00e0ng H\u00e0,`,
  `Ho\u00e0ng H\u00e0 th\u01b0\u1eddng xuy\u00ean l\u0169 l\u1ee5t,`,
  `Kinh \u0111\u00f4 nh\u00e0 Th\u01b0\u01a1ng th\u01b0\u1eddng b\u1ecb ng\u1eadp \u00fang,`,
  `Kh\u00f4ng c\u00f2n c\u00e1ch n\u00e0o kh\u00e1c, ch\u1ec9 c\u00f3 th\u1ec3 di chuy\u1ec3n h\u1ebft l\u1ea7n n\u00e0y \u0111\u1ebfn l\u1ea7n kh\u00e1c.`,
  `Tuy nhi\u00ean, c\u00e1ch gi\u1ea3i th\u00edch n\u00e0y kh\u00e1 g\u01b0\u1ee3ng \u00e9p.`,
  `M\u1ed9t c\u00e1ch gi\u1ea3i th\u00edch \u0111\u00e1ng tin c\u1eady h\u01a1n l\u00e0,`,
  `Vi\u1ec7c d\u1eddi \u0111\u00f4 l\u00e0 do cu\u1ed9c \u0111\u1ea5u tranh gi\u00e0nh ngai v\u00e0ng c\u1ee7a nh\u00e0 Th\u01b0\u01a1ng r\u1ea5t kh\u1ed1c li\u1ec7t,`,
  `H\u00f4m nay con gi\u1ebft b\u1ed1,`,
  `Ng\u00e0y mai ch\u00fa l\u1ea1i \u0111\u1ea7u \u0111\u1ed9c ch\u00e1u,`,
  `M\u1ed7i l\u1ea7n c\u00f3 t\u00e2n v\u01b0\u01a1ng l\u00ean ng\u00f4i l\u1ea1i ph\u1ea3i \u0111\u1ed5i \u0111\u00f4.`,
  `V\u00ec v\u1eady, nguy\u00ean nh\u00e2n th\u1ef1c s\u1ef1 c\u1ee7a vi\u1ec7c d\u1eddi \u0111\u00f4 li\u00ean t\u1ee5c l\u00e0 do n\u1ed9i chi\u1ebfn trong ho\u00e0ng t\u1ed9c.`,
  `Nh\u00e0 Th\u01b0\u01a1ng \u0111\u00e3 d\u1eddi \u0111\u00f4 n\u0103m l\u1ea7n,`,
  `cu\u1ed1i c\u00f9ng ch\u1ecdn An D\u01b0\u01a1ng, H\u00e0 Nam l\u00e0m n\u01a1i \u0111\u1ecbnh c\u01b0 v\u0129nh vi\u1ec5n.`,
  `Sau g\u1ea7n 600 n\u0103m th\u1ed1ng tr\u1ecb,`,
  `x\u00e3 h\u1ed9i nh\u00e0 Th\u01b0\u01a1ng th\u1eddi k\u1ef3 cu\u1ed1i d\u1ea7n suy t\u00e0n,`,
  `v\u1ecb qu\u00e2n ch\u1ee7 cu\u1ed1i c\u00f9ng l\u00e0 Tr\u1ee5 V\u01b0\u01a1ng \u0111\u1ea1i danh l\u1eebng l\u1eaby.`,
  `N\u00f3i v\u1ec1 s\u1ef1 t\u00e0n b\u1ea1o, \u00f4ng ta ch\u01b0a bao gi\u1edd thua k\u00e9m ai.`,
  `M\u1eb7c d\u00f9 ti\u1ebfng t\u0103m kh\u00f4ng t\u1ed1t,`,
  `nh\u01b0ng Tr\u1ee5 V\u01b0\u01a1ng trong l\u1ecbch s\u1eed kh\u00f4ng ph\u1ea3i l\u00e0 m\u1ed9t h\u00f4n qu\u00e2n.`,
  `Nguy\u00ean nh\u00e2n di\u1ec7t vong c\u1ee7a nh\u00e0 Th\u01b0\u01a1ng ch\u1ee7 y\u1ebfu l\u00e0 do s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a n\u1ed9i b\u1ed9 t\u1eadp \u0111o\u00e0n th\u1ed1ng tr\u1ecb,`,
  `n\u1ed9i chi\u1ebfn trong ho\u00e0ng t\u1ed9c, qu\u00fd t\u1ed9c chia r\u1ebd,`,
  `c\u1ed9ng th\u00eam giai c\u1ea5p th\u1ed1ng tr\u1ecb xa hoa th\u1ed1i n\u00e1t,`,
  `trong cung \u0111\u00ecnh r\u1ed1i ren,`,
  `th\u00ec l\u00e0m sao \u0111\u1ea5t n\u01b0\u1edbc c\u00f3 th\u1ec3 \u0111\u01b0\u1ee3c cai tr\u1ecb t\u1ed1t.`,
  `X\u00e3 h\u1ed9i b\u1ea5t \u1ed5n, d\u00e2n ch\u00fang l\u1ea7m than.`,
  `Th\u1ebf l\u00e0, Chu V\u0169 V\u01b0\u01a1ng, m\u1ed9t ch\u01b0 h\u1ea7u c\u1ee7a nh\u00e0 Th\u01b0\u01a1ng, \u0111\u00e3 th\u00e0nh c\u00f4ng trong vi\u1ec7c \u0111\u00e1nh b\u1ea1i Tr\u1ee5 V\u01b0\u01a1ng,`,
  `L\u1eadp n\u00ean nh\u00e0 Chu, s\u1eed g\u1ecdi l\u00e0 T\u00e2y Chu.`,
  `N\u01b0\u1edbc \u0111\u00e3 \u0111\u01b0\u1ee3c th\u00e0nh l\u1eadp, nh\u01b0ng khi \u0111\u00f3 nh\u00e0 Chu kh\u00f4ng ti\u1ebfp qu\u1ea3n to\u00e0n b\u1ed9 l\u00e3nh th\u1ed5 c\u1ee7a nh\u00e0 Th\u01b0\u01a1ng,`,
  `V\u00ec giao th\u00f4ng th\u1eddi \u0111\u00f3 th\u1ef1c s\u1ef1 kh\u00f4ng ph\u00e1t tri\u1ec3n.`,
  `Ph\u00e1 v\u1ee1 ho\u00e0ng th\u00e0nh th\u00ec d\u1ec5,`,
  `Mu\u1ed1n thu ph\u1ee5c c\u00e1c v\u00f9ng \u0111\u1ea5t kh\u00e1c th\u00ec r\u1ea5t kh\u00f3,`,
  `Th\u00eam v\u00e0o \u0111\u00f3, nh\u00e0 Chu m\u1edbi th\u00e0nh l\u1eadp kh\u00f4ng l\u00e2u,`,
  `N\u1ec1n m\u00f3ng ch\u01b0a v\u1eefng ch\u1eafc. Th\u1ebf l\u00e0 Chu V\u0169 V\u01b0\u01a1ng ngh\u0129 ra m\u1ed9t c\u00e1ch,`,
  `Phong nhi\u1ec1u ch\u01b0 h\u1ea7u h\u01a1n,`,
  `Chia \u0111\u1ea5t \u0111ai ch\u01b0a thu ph\u1ee5c \u0111\u01b0\u1ee3c cho h\u1ecd,`,
  `R\u1ed3i c\u1ea5p cho h\u1ecd m\u1ed9t s\u1ed1 binh l\u00ednh v\u00e0 ng\u1ef1a,`,
  `Vi\u1ec7c c\u00f3 nh\u1eadm ch\u1ee9c su\u00f4n s\u1ebb hay kh\u00f4ng l\u00e0 t\u00f9y v\u00e0o kh\u1ea3 n\u0103ng c\u1ee7a t\u1eebng ch\u01b0 h\u1ea7u.`,
  `C\u00f2n Thi\u00ean t\u1eed nh\u00e0 Chu ch\u1ec9 c\u1ea7n qu\u1ea3n l\u00fd c\u00e1c v\u00f9ng l\u00e2n c\u1eadn kinh \u0111\u00f4 v\u00e0 ki\u1ec3m so\u00e1t c\u00e1c ch\u01b0 h\u1ea7u n\u00e0y l\u00e0 \u0111\u01b0\u1ee3c.`,
  `Th\u1ebf l\u00e0 Chu V\u0169 V\u01b0\u01a1ng \u0111\u00e3 phong t\u1ed5ng c\u1ed9ng b\u1ea3y m\u01b0\u01a1i m\u1ed1t n\u01b0\u1edbc ch\u01b0 h\u1ea7u.`,
  `\u0110\u1eebng n\u00f3i ph\u01b0\u01a1ng ph\u00e1p n\u00e0y th\u1ef1c s\u1ef1 hi\u1ec7u qu\u1ea3.`,
  `C\u00e1c ch\u01b0 h\u1ea7u kh\u00f4ng ng\u1eebng n\u1ed7 l\u1ef1c hu\u1ea5n luy\u1ec7n qu\u00e2n \u0111\u1ed9i v\u00ec l\u00e3nh th\u1ed5 c\u1ee7a m\u00ecnh.`,
  `V\u00ec v\u1eady, l\u00e3nh th\u1ed5 nh\u00e0 Chu sau n\u00e0y kh\u00f4ng ng\u1eebng m\u1edf r\u1ed9ng.`,
  `T\u01b0\u01a1ng truy\u1ec1n, l\u00e3nh th\u1ed5 nh\u00e0 Chu b\u1ea5y gi\u1edd r\u1ed9ng t\u1edbi m\u1ed9t tri\u1ec7u n\u0103m tr\u0103m ng\u00e0n kilomet vu\u00f4ng,`,
  `D\u00e2n s\u1ed1 h\u01a1n ch\u1ee5c tri\u1ec7u ng\u01b0\u1eddi.`,
  `Ng\u00e0y nay, con s\u1ed1 n\u00e0y nghe c\u00f3 v\u1ebb kh\u00f4ng nhi\u1ec1u,`,
  `Nh\u01b0ng \u0111\u1eebng qu\u00ean, khi \u0111\u00f3 n\u0103ng su\u1ea5t to\u00e0n c\u1ea7u c\u00f2n th\u1ea5p,`,
  `C\u00e1c n\u01b0\u1edbc ch\u00e2u \u00c2u \u0111\u1ec1u l\u00e0 nh\u1eefng th\u00e0nh bang nh\u1ecf b\u00e9,`,
  `M\u1ed9t qu\u1ed1c gia c\u00f2n kh\u00f4ng l\u1edbn b\u1eb1ng m\u1ed9t th\u00e0nh ph\u1ed1 c\u1ee7a nh\u00e0 Chu.`,
  `T\u00e2y Chu b\u1ea5y gi\u1edd \u0111\u00e3 l\u00e0 m\u1ed9t si\u00eau c\u01b0\u1eddng tr\u00ean th\u1ebf gi\u1edbi,`,
  `M\u1ed9t th\u1eddi h\u01b0ng th\u1ecbnh. Vua nh\u00e0 Chu n\u00f3i ri\u00eang v\u1ec1 hai ng\u01b0\u1eddi,`,
  `Chu L\u1ec7 V\u01b0\u01a1ng v\u00e0 Chu U V\u01b0\u01a1ng.`,
  `L\u1ec7 V\u01b0\u01a1ng l\u00e0 m\u1ed9t ng\u01b0\u1eddi k\u1ef3 l\u1ea1, \u00f4ng ta cho r\u1eb1ng thi\u00ean h\u1ea1 l\u00e0 c\u1ee7a m\u00ecnh,`,
  `Kh\u00f4ng cho ph\u00e9p d\u00e2n ch\u00fang s\u0103n b\u1eafn,`,
  `\u0110\u1ed9ng v\u1eadt tr\u00ean n\u00fai v\u00e0 c\u00e1 t\u00f4m d\u01b0\u1edbi n\u01b0\u1edbc \u0111\u1ec1u l\u00e0 c\u1ee7a \u00f4ng ta,`,
  `Kh\u00f4ng cho ph\u00e9p d\u00e2n ch\u00fang b\u00e0n t\u00e1n v\u1ec1 \u00f4ng ta,`,
  `n\u1ebfu ai n\u00f3i v\u1ec1 \u00f4ng ta th\u00ec ph\u1ea3i x\u1eed t\u1eed.`,
  `D\u01b0\u1edbi s\u1ef1 t\u00e0n b\u1ea1o c\u1ee7a Chu L\u1ec7 V\u01b0\u01a1ng,`,
  `cu\u1ed1i c\u00f9ng \u0111\u00e3 x\u1ea3y ra cu\u1ed9c b\u1ea1o lo\u1ea1n c\u1ee7a ng\u01b0\u1eddi d\u00e2n, \u00f4ng ta b\u1ecb l\u1eadt \u0111\u1ed5.`,
  `Chu L\u1ec7 V\u01b0\u01a1ng cu\u1ed1i c\u00f9ng ch\u1ebft n\u01a1i \u0111\u1ea5t kh\u00e1ch qu\u00ea ng\u01b0\u1eddi,`,
  `con trai \u00f4ng l\u00e0 Chu Tuy\u00ean V\u01b0\u01a1ng l\u00ean ng\u00f4i.`,
  `Tuy\u00ean V\u01b0\u01a1ng th\u1ef1c ra kh\u00e1 t\u1ed1t,`,
  `trong th\u1eddi gian t\u1ea1i v\u1ecb qu\u1ed1c gia t\u1eebng gi\u00e0u m\u1ea1nh,`,
  `sau khi \u00f4ng m\u1ea5t, con trai \u00f4ng l\u00e0 Chu U V\u01b0\u01a1ng l\u00ean ng\u00f4i.`,
  `Chu U V\u01b0\u01a1ng c\u00f3 m\u1ed9t s\u1ee7ng phi t\u00ean l\u00e0 Bao T\u1ef1,`,
  `l\u00e0 m\u1ed9t ng\u01b0\u1eddi ph\u1ee5 n\u1eef r\u1ea5t kh\u00f3 c\u01b0\u1eddi.`,
  `\u0110\u1ec3 l\u00e0m n\u00e0ng c\u01b0\u1eddi,`,
  `U V\u01b0\u01a1ng \u0111\u00e3 s\u1eafp x\u1ebfp m\u1ed9t m\u00e0n bi\u1ec3u di\u1ec5n l\u1edbn,`,
  `ch\u00ednh l\u00e0 \u0111\u1ed1t l\u1eeda hi\u1ec7u tri\u1ec7u ch\u01b0 h\u1ea7u.`,
  `Th\u1eddi c\u1ed5 \u0111\u1ea1i, \u0111\u00e0i l\u1eeda hi\u1ec7u l\u00e0 d\u00f9ng \u0111\u1ec3 truy\u1ec1n tin khi c\u00f3 chi\u1ebfn tranh,`,
  `U V\u01b0\u01a1ng ra l\u1ec7nh cho binh l\u00ednh \u0111\u1ed1t \u0111\u00e0i l\u1eeda hi\u1ec7u,`,
  `C\u00e1c ch\u01b0 h\u1ea7u c\u00e1c n\u01a1i v\u1eeba th\u1ea5y b\u00e1o \u0111\u1ed9ng,`,
  `T\u01b0\u1edfng r\u1eb1ng qu\u00e2n \u0111\u1ecbch \u0111\u1ebfn x\u00e2m ph\u1ea1m,`,
  `M\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u d\u1eabn qu\u00e2n \u0111\u1ebfn c\u1ee9u gi\u00e1.`,
  `\u0110\u1ebfn n\u01a1i th\u00ec th\u1ea5y, U V\u01b0\u01a1ng v\u00e0 Bao T\u1ef1 \u0111ang u\u1ed1ng r\u01b0\u1ee3u \u1edf \u0111\u00f3,`,
  `L\u00e0m g\u00ec c\u00f3 b\u00f3ng d\u00e1ng k\u1ebb \u0111\u1ecbch.`,
  `U V\u01b0\u01a1ng n\u00f3i: "M\u1ecdi ng\u01b0\u1eddi v\u1ea5t v\u1ea3 r\u1ed3i,`,
  `Kh\u00f4ng c\u00f3 chuy\u1ec7n g\u00ec \u0111\u00e2u,`,
  `Ch\u1ec9 l\u00e0 ta v\u00e0 \u00e1i phi \u0111\u00f9a ch\u00fat th\u00f4i,`,
  `M\u1ecdi ng\u01b0\u1eddi \u0111\u1eebng \u0111\u1ec3 \u00fd.`,
  `Bao T\u1ef1 th\u00ec nh\u00ecn th\u1ea5y ng\u00e0n v\u1ea1n qu\u00e2n l\u00ednh,`,
  `G\u1ecdi \u0111\u1ebfn l\u00e0 \u0111\u1ebfn, xua \u0111i l\u00e0 \u0111i,`,
  `C\u1ee9 nh\u01b0 ch\u01a1i tr\u00f2 tr\u1ebb con v\u1eady,`,
  `C\u0169ng c\u1ea3m th\u1ea5y r\u1ea5t th\u00fa v\u1ecb,`,
  `Cu\u1ed1i c\u00f9ng c\u0169ng b\u1eadt c\u01b0\u1eddi.`,
  `U V\u01b0\u01a1ng r\u1ea5t h\u00e0i l\u00f2ng,`,
  `Sau \u0111\u00f3, nhi\u1ec1u l\u1ea7n d\u00f9ng c\u00e1ch n\u00e0y \u0111\u1ec3 ch\u1ecdc Bao T\u1ef1 vui,`,
  `D\u1ea7n d\u1ea7n m\u1ea5t \u0111i s\u1ef1 \u1ee7ng h\u1ed9 c\u1ee7a c\u00e1c ch\u01b0 h\u1ea7u.`,
  `Nh\u01b0 v\u1eady v\u1eabn ch\u01b0a \u0111\u1ee7,`,
  `U V\u01b0\u01a1ng mu\u1ed1n l\u1eadp con c\u1ee7a Bao T\u1ef1 l\u00e0m ng\u01b0\u1eddi th\u1eeba k\u1ebf,`,
  `Ph\u1ebf b\u1ecf th\u00e1i t\u1eed Nghi C\u1ef1u tr\u01b0\u1edbc \u0111\u00f3.`,
  `\u00d4ng ngo\u1ea1i c\u1ee7a Nghi C\u1ef1u l\u00e0 Th\u00e2n H\u1ea7u kh\u00f4ng \u0111\u1ed3ng \u00fd,`,
  `Th\u1ebf l\u00e0 Th\u00e2n H\u1ea7u li\u00ean k\u1ebft v\u1edbi c\u00e1c b\u1ed9 t\u1ed9c du m\u1ee5c ph\u00eda B\u1eafc,`,
  `Khuy\u1ec3n Nhung t\u1ea5n c\u00f4ng kinh \u0111\u00f4 T\u00e2y Chu l\u00e0 H\u1ea1o Kinh,`,
  `T\u1ee9c l\u00e0 T\u00e2y An ng\u00e0y nay,`,
  `Gi\u1ebft ch\u1ebft U V\u01b0\u01a1ng,`,
  `T\u00e2y Chu t\u1ed3n t\u1ea1i hai tr\u0103m b\u1ea3y m\u01b0\u01a1i l\u0103m n\u0103m di\u1ec7t vong.`,
  `Th\u00e1i t\u1eed Nghi C\u1ef1u l\u00ean ng\u00f4i d\u01b0\u1edbi s\u1ef1 ph\u00f2 t\u00e1 c\u1ee7a c\u00e1c \u0111\u1ea1i th\u1ea7n,`,
  `T\u1ef1 x\u01b0ng l\u00e0 Chu B\u00ecnh V\u01b0\u01a1ng.`,
  `D\u1eddi \u0111\u00f4 v\u1ec1 L\u1ea1c \u1ea4p, t\u1ee9c l\u00e0 L\u1ea1c D\u01b0\u01a1ng ng\u00e0y nay.`,
  `T\u00e2y Chu v\u00e0 \u0110\u00f4ng Chu \u0111\u1ec1u thu\u1ed9c nh\u00e0 Chu,`,
  `\u0111i\u1ec3m kh\u00e1c bi\u1ec7t l\u00e0 \u0110\u00f4ng Chu suy y\u1ebfu nghi\u00eam tr\u1ecdng sau khi d\u1eddi \u0111\u00f4 v\u1ec1 L\u1ea1c D\u01b0\u01a1ng.`,
  `Thi\u00ean t\u1eed nh\u00e0 Chu ch\u1ec9 c\u00f2n h\u01b0 danh,`,
  `\u0111\u00e1nh m\u1ea5t quy\u1ec1n l\u1ef1c t\u1ed1i cao \u0111\u1ec3 cai tr\u1ecb,`,
  `tr\u1edf th\u00e0nh con r\u1ed1i. C\u00e1c ch\u01b0 h\u1ea7u kh\u00f4ng c\u00f2n nghe l\u1ec7nh thi\u00ean t\u1eed n\u1eefa,`,
  `khi th\u1ee7 l\u0129nh kh\u00f4ng c\u00f2n th\u1ef1c l\u1ef1c,`,
  `c\u00e1c ch\u01b0 h\u1ea7u nh\u00ecn th\u1ea5y th\u1eddi c\u01a1 li\u1ec1n n\u1ed5i d\u1eady,`,
  `ai n\u1ea5y \u0111\u1ec1u tranh gi\u00e0nh \u0111\u1ea5t \u0111ai v\u00e0 d\u00e2n s\u1ed1,`,
  `giao chi\u1ebfn l\u1eabn nhau. Trung Qu\u1ed1c t\u1eeb \u0111\u00f3 b\u01b0\u1edbc v\u00e0o th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c v\u1edbi c\u1ee5c di\u1ec7n qu\u1ea7n h\u00f9ng c\u00e1t c\u1ee9.`,
  `K\u1ec3 t\u1eeb khi Chu U V\u01b0\u01a1ng, v\u1ecb thi\u00ean t\u1eed g\u00e2y ra tr\u00f2 \u0111\u00f9a 'phong h\u1ecfa h\u00ed ch\u01b0 h\u1ea7u', b\u1ecb d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 gi\u1ebft ch\u1ebft,`,
  `nh\u00e0 Chu bu\u1ed9c ph\u1ea3i d\u1eddi \u0111\u00f4 t\u1eeb H\u1ea1o Kinh v\u1ec1 L\u1ea1c \u1ea4p.`,
  `T\u00e2y Chu di\u1ec7t vong, \u0110\u00f4ng Chu b\u1eaft \u0111\u1ea7u.`,
  `\u0110\u00f4ng Chu l\u1ea1i \u0111\u01b0\u1ee3c chia th\u00e0nh hai th\u1eddi k\u1ef3 Xu\u00e2n Thu v\u00e0 Chi\u1ebfn Qu\u1ed1c,`,
  `trong th\u1eddi gian n\u00e0y, thi\u00ean t\u1eed nh\u00e0 Chu \u0111\u00e3 ho\u00e0n to\u00e0n m\u1ea5t h\u1ebft th\u1ef1c l\u1ef1c,`,
  `ch\u1ec9 c\u00f2n l\u00e0 m\u1ed9t v\u1eadt trang tr\u00ed.`,
  `C\u00e1c ti\u1ec3u \u0111\u1ec7 ch\u01b0 h\u1ea7u \u0111\u1ec1u kh\u00f4ng m\u1ea5y b\u1eadn t\u00e2m \u0111\u1ebfn \u00f4ng ta,`,
  `M\u1ed7i ng\u01b0\u1eddi l\u1ea7n l\u01b0\u1ee3t tr\u1ed7i d\u1eady.`,
  `\u0110\u1ea7u th\u1eddi Xu\u00e2n Thu, trong v\u00f4 s\u1ed1 ti\u1ec3u \u0111\u1ec7 ch\u01b0 h\u1ea7u, n\u01b0\u1edbc T\u1ec1 l\u00e0 n\u01b0\u1edbc \u0111\u1ea7u ti\u00ean n\u1ed5i l\u00ean.`,
  `T\u1ea1i sao l\u1ea1i l\u00e0 h\u1ecd, th\u1ef1c ra c\u00f3 l\u00fd do.`,
  `Tr\u01b0\u1edbc h\u1ebft, n\u01b0\u1edbc T\u1ec1 c\u00f3 xu\u1ea5t th\u00e2n cao qu\u00fd,`,
  `\u0110\u01b0\u1ee3c gi\u00e1o d\u1ee5c t\u1ed1t.`,
  `V\u1ecb ch\u01b0 h\u1ea7u v\u01b0\u01a1ng \u0111\u1ea7u ti\u00ean c\u1ee7a T\u1ec1 l\u00e0 Kh\u01b0\u01a1ng Th\u00e1i c\u00f4ng Kh\u01b0\u01a1ng T\u1eed Nha, ng\u01b0\u1eddi \u0111\u00e3 gi\u00fap Chu V\u0169 v\u01b0\u01a1ng x\u00e2y d\u1ef1ng c\u01a1 \u0111\u1ed3, c\u00f3 c\u00f4ng l\u1edbn kh\u00f4ng th\u1ec3 b\u1ecf qua.`,
  `V\u00ec v\u1eady, n\u01b0\u1edbc T\u1ec1 lu\u00f4n ph\u00e1t tri\u1ec3n t\u1ed1t.`,
  `Th\u1ee9 hai, n\u01b0\u1edbc T\u1ec1 \u0111\u00e3 t\u00ecm \u0111\u01b0\u1ee3c m\u1ed9t v\u1ecb th\u1ea7y r\u1ea5t l\u1ee3i h\u1ea1i l\u00e0 Qu\u1ea3n Tr\u1ecdng.`,
  `Ngay khi Qu\u1ea3n Tr\u1ecdng l\u00ean n\u1eafm quy\u1ec1n, \u00f4ng \u0111\u00e3 t\u1eadp trung ph\u00e1t tri\u1ec3n kinh t\u1ebf v\u00e0 qu\u1ea3n l\u00fd.`,
  `M\u1ed9t lo\u1ea1t c\u1ea3i c\u00e1ch \u0111\u00e3 \u0111\u1ea1t \u0111\u01b0\u1ee3c hi\u1ec7u qu\u1ea3 r\u00f5 r\u1ec7t.`,
  `D\u01b0\u1edbi s\u1ef1 c\u1ea3i c\u00e1ch v\u00e0 ph\u00e1t tri\u1ec3n c\u1ee7a Qu\u1ea3n Tr\u1ecdng,`,
  `S\u1ee9c m\u1ea1nh c\u1ee7a T\u1ec1 t\u0103ng v\u1ecdt, tr\u1edf th\u00e0nh m\u1ed9t si\u00eau c\u01b0\u1eddng qu\u1ed1c.`,
  `C\u00f3 th\u1ef1c l\u1ef1c r\u1ed3i b\u1eaft \u0111\u1ea7u thu nh\u1eadn \u0111\u00e0n em, l\u00fac b\u1ea5y gi\u1edd m\u1ed9t s\u1ed1 ti\u1ec3u qu\u1ed1c ch\u01b0 h\u1ea7u th\u01b0\u1eddng b\u1ecb c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 \u0111e d\u1ecda.`,
  `N\u01b0\u1edbc T\u1ec1 \u0111\u00e3 ra m\u1eb7t gi\u00fap h\u1ecd gi\u1ea3i quy\u1ebft nh\u1eefng r\u1eafc r\u1ed1i n\u00e0y.`,
  `C\u1ee9 nh\u01b0 th\u1ebf, uy t\u00edn c\u1ee7a n\u01b0\u1edbc T\u1ec1 trong s\u1ed1 c\u00e1c ch\u01b0 h\u1ea7u ng\u00e0y c\u00e0ng cao,`,
  `tr\u1edf th\u00e0nh qu\u1ed1c gia \u0111\u1ea7u ti\u00ean x\u01b0ng b\u00e1.`,
  `T\u1ec1 Ho\u00e0n c\u00f4ng, qu\u00e2n v\u01b0\u01a1ng l\u00fac b\u1ea5y gi\u1edd, v\u1edbi t\u01b0 c\u00e1ch l\u00e0 m\u1ed9t b\u00e1 ch\u1ee7 \u0111\u1eddi,`,
  `oai phong l\u1eabm li\u1ec7t, nh\u01b0ng tu\u1ed5i gi\u00e0 c\u1ee7a \u00f4ng l\u1ea1i v\u00f4 c\u00f9ng th\u00ea l\u01b0\u01a1ng.`,
  `Sau khi T\u1ec1 Ho\u00e0n c\u00f4ng v\u1ec1 gi\u00e0, n\u0103m ng\u01b0\u1eddi con trai c\u1ee7a \u00f4ng b\u1eadn r\u1ed9n tranh gi\u00e0nh \u0111\u1ecba v\u1ecb,`,
  `t\u00e0n s\u00e1t l\u1eabn nhau, th\u1eadm ch\u00ed c\u00f2n giam l\u1ecfng cha gi\u00e0,`,
  `bu\u1ed9c T\u1ec1 Ho\u00e0n c\u00f4ng cu\u1ed1i c\u00f9ng ph\u1ea3i t\u1ef1 s\u00e1t.`,
  `M\u00e0 \u0111\u00e1ng th\u01b0\u01a1ng h\u01a1n l\u00e0,`,
  `kh\u00f4ng ai li\u1ec7m x\u00e1c cho \u00f4ng, m\u00e3i \u0111\u1ebfn khi thi th\u1ec3 m\u1ee5c n\u00e1t m\u1edbi \u0111\u01b0\u1ee3c ph\u00e1t hi\u1ec7n.`,
  `Nh\u1edd \u01a1n c\u1ee7a \u0111\u00e1m con b\u1ea5t hi\u1ebfu n\u00e0y, n\u01b0\u1edbc T\u1ec1 t\u1eeb sau c\u00e1i ch\u1ebft c\u1ee7a T\u1ec1 Ho\u00e0n c\u00f4ng d\u1ea7n d\u1ea7n suy y\u1ebfu.`,
  `Sau \u0111\u00f3, n\u01b0\u1edbc T\u1ea5n, n\u01b0\u1edbc T\u1ea7n,`,
  `v\u00e0 n\u01b0\u1edbc S\u1edf l\u1ea7n l\u01b0\u1ee3t tr\u1ed7i d\u1eady.`,
  `Tr\u01b0\u1edbc h\u1ebft ph\u1ea3i n\u00f3i r\u1eb1ng,`,
  `n\u01b0\u1edbc S\u1edf th\u1ef1c ch\u1ea5t kh\u00f4ng thu\u1ed9c ch\u01b0 h\u1ea7u c\u1ee7a nh\u00e0 Chu,`,
  `m\u00e0 th\u1ef1c ch\u1ea5t l\u00e0 m\u1ed9t b\u1ed9 l\u1ea1c l\u1edbn \u1edf ph\u00eda nam,`,
  `Sau \u0111\u00f3 t\u1ef1 x\u01b0ng v\u01b0\u01a1ng.`,
  `D\u00f9 huy\u1ebft th\u1ed1ng kh\u00f4ng thu\u1ea7n nh\u01b0ng th\u1ef1c l\u1ef1c h\u00f9ng m\u1ea1nh,`,
  `c\u00f3 th\u1ec3 \u0111\u00e1nh nhau. Nh\u00ecn th\u1ea5y nh\u00e0 Chu l\u00e0 m\u1ed9t mi\u1ebfng m\u1ed3i b\u00e9o b\u1edf,`,
  `n\u00ean mu\u1ed1n chen ch\u00e2n v\u00e0o chia m\u1ed9t ph\u1ea7n.`,
  `B\u00e2y gi\u1edd n\u00f3i v\u1ec1 n\u01b0\u1edbc T\u1ea7n,`,
  `nh\u00ecn t\u1ea5m b\u1ea3n \u0111\u1ed3 n\u00e0y,`,
  `c\u00f3 th\u1ea5y v\u1ecb tr\u00ed \u0111\u1ecba l\u00fd c\u1ee7a T\u1ea7n r\u1ea5t quen thu\u1ed9c kh\u00f4ng?`,
  `\u0110\u00fang, kh\u00f4ng sai, ch\u00ednh l\u00e0 \u0111\u00f4 th\u00e0nh H\u1ea1o Kinh c\u1ee7a T\u00e2y Chu ng\u00e0y x\u01b0a.`,
  `N\u0103m \u0111\u00f3 n\u01b0\u1edbc T\u1ea7n trong nh\u00e0 Chu ch\u1ec9 l\u00e0 m\u1ed9t \u0111\u1ed9i nh\u1ecf nu\u00f4i ng\u1ef1a,`,
  `khi Chu Thi\u00ean T\u1eed b\u1ecb Khuy\u1ec3n Nhung b\u1eaft n\u1ea1t \u0111\u00e3 ch\u1ea1y \u0111\u1ebfn L\u1ea1c \u1ea4p,`,
  `ch\u00ednh n\u01b0\u1edbc T\u1ea7n \u0111\u00e3 h\u1ed9 t\u1ed1ng tr\u00ean \u0111\u01b0\u1eddng \u0111i.`,
  `V\u00ec v\u1eady \u0111\u1ec3 th\u01b0\u1edfng cho ti\u1ec3u \u0111\u1ec7 c\u00f3 c\u00f4ng h\u1ed9 ch\u1ee7,`,
  `Chu Thi\u00ean T\u1eed \u0111\u00e3 phong \u0111\u1ea5t H\u1ea1o Kinh cho n\u01b0\u1edbc T\u1ea7n.`,
  `Khi \u0111\u00f3 n\u01b0\u1edbc T\u1ea7n v\u1eabn l\u00e0 m\u1ed9t \u0111\u1ee9a tr\u1ebb ngoan ngo\u00e3n,`,
  `kh\u00f4ng tranh gi\u00e0nh, s\u1eb5n l\u00f2ng gi\u00fap \u0111\u1ee1.`,
  `Trong khi \u0111\u00f3, \u1edf ph\u00eda t\u00e2y, \u00f4ng l\u1eb7ng l\u1ebd n\u1ed7 l\u1ef1c chinh ph\u1ee5c c\u00e1c b\u1ed9 l\u1ea1c ngo\u1ea1i t\u1ed9c,`,
  `d\u1ea7n tr\u1edf th\u00e0nh b\u00e1 ch\u1ee7 ph\u00eda t\u00e2y.`,
  `C\u00f2n n\u01b0\u1edbc T\u1ea5n, v\u1edbi t\u01b0 c\u00e1ch l\u00e0 b\u00e1 ch\u1ee7 m\u1edbi sau n\u01b0\u1edbc T\u1ec1,`,
  `m\u00e2u thu\u1eabn v\u1edbi n\u01b0\u1edbc S\u1edf kh\u00f4ng ng\u1eebng ngh\u1ec9 t\u1eeb tr\u01b0\u1edbc \u0111\u1ebfn nay,`,
  `\u0111\u00e1nh nhau g\u1ea7n m\u1ed9t tr\u0103m n\u0103m,`,
  `s\u1eed g\u1ecdi l\u00e0 T\u1ea5n S\u1edf tranh b\u00e1.`,
  `Cu\u1ed9c chi\u1ebfn gi\u1eb1ng co k\u00e9o d\u00e0i, n\u01b0\u1edbc S\u1edf th\u1eafng \u00edt thua nhi\u1ec1u,`,
  `th\u1ef1c l\u1ef1c d\u1ea7n suy y\u1ebfu.`,
  `L\u00fac n\u00e0y, Ng\u00f4 v\u01b0\u01a1ng H\u1ea1p L\u01b0 \u1edf b\u00ean c\u1ea1nh l\u1ea1i c\u00f3 \u0111\u01b0\u1ee3c hai d\u0169ng t\u01b0\u1edbng,`,
  `m\u1ed9t l\u00e0 Ng\u0169 T\u1eed T\u01b0, m\u1ed9t l\u00e0 T\u00f4n V\u0169.`,
  `Ng\u0169 T\u1eed T\u01b0 v\u1ed1n l\u00e0 ng\u01b0\u1eddi n\u01b0\u1edbc S\u1edf,`,
  `cha v\u00e0 anh trai \u0111\u1ec1u b\u1ecb S\u1edf v\u01b0\u01a1ng gi\u1ebft ch\u1ebft,`,
  `\u00f4ng b\u00e8n ch\u1ea1y sang n\u01b0\u1edbc Ng\u00f4 n\u01b0\u01a1ng t\u1ef1a H\u1ea1p L\u01b0.`,
  `Ng\u0169 T\u1eed T\u01b0 v\u1ed1n l\u00e0 ng\u01b0\u1eddi n\u01b0\u1edbc S\u1edf, n\u00ean r\u1ea5t am hi\u1ec3u t\u00ecnh h\u00ecnh n\u1ed9i b\u1ed9 n\u01b0\u1edbc S\u1edf,`,
  `h\u01a1n n\u1eefa \u00f4ng c\u00f2n c\u00f3 t\u00e0i n\u0103ng phi th\u01b0\u1eddng.`,
  `V\u1ec1 T\u00f4n V\u0169 th\u00ec kh\u00f4ng c\u1ea7n ph\u1ea3i n\u00f3i r\u1ed3i,`,
  `T\u00f4n V\u0169 ch\u00ednh l\u00e0 t\u00e1c gi\u1ea3 c\u1ee7a T\u00f4n T\u1eed Binh Ph\u00e1p.`,
  `Ngo\u00e0i ra,`,
  `n\u01b0\u1edbc T\u1ea5n, k\u1ebb th\u00f9 kh\u00f4ng \u0111\u1ed9i tr\u1eddi chung c\u1ee7a n\u01b0\u1edbc S\u1edf, c\u0169ng ng\u1ea5m ng\u1ea7m gi\u00fap n\u01b0\u1edbc Ng\u00f4 h\u1ecdc h\u1ecfi k\u1ef9 thu\u1eadt ti\u00ean ti\u1ebfn,`,
  `t\u0103ng c\u01b0\u1eddng s\u1ee9c m\u1ea1nh qu\u00e2n s\u1ef1,`,
  `m\u1ee5c \u0111\u00edch l\u00e0 \u0111\u1ec3 nu\u00f4i d\u01b0\u1ee1ng m\u1ed9t qu\u1ea3 bom h\u1eb9n gi\u1edd b\u00ean c\u1ea1nh n\u01b0\u1edbc S\u1edf.`,
  `Qu\u1ea3 nhi\u00ean, n\u01b0\u1edbc Ng\u00f4 sau \u0111\u00f3 \u0111\u00e3 ch\u1edbp th\u1eddi c\u01a1 xu\u1ea5t binh \u0111\u00e1nh n\u01b0\u1edbc S\u1edf,`,
  `v\u1eeba ra qu\u00e2n \u0111\u00e3 gi\u00e1ng cho n\u01b0\u1edbc S\u1edf m\u1ed9t \u0111\u00f2n n\u1eb7ng n\u1ec1, khi\u1ebfn n\u01b0\u1edbc S\u1edf nguy\u00ean kh\u00ed \u0111\u1ea1i th\u01b0\u01a1ng.`,
  `T\u1eeb \u0111\u00f3 v\u1ec1 sau kh\u00f4ng g\u01b0\u1ee3ng d\u1eady n\u1ed5i, g\u1ea7n nh\u01b0 r\u00fat lui kh\u1ecfi v\u0169 \u0111\u00e0i tranh b\u00e1 cu\u1ed1i th\u1eddi k\u1ef3.`,
  `N\u01b0\u1edbc Ng\u00f4 \u0111\u1ea1i b\u1ea1i n\u01b0\u1edbc S\u1edf xong c\u0169ng ch\u1eb3ng uy phong \u0111\u01b0\u1ee3c m\u1ea5y ng\u00e0y,`,
  `n\u01b0\u1edbc Vi\u1ec7t b\u00ean c\u1ea1nh \u0111\u00e3 ra khi\u00eau chi\u1ebfn v\u1edbi h\u1ecd.`,
  `Ng\u00f4 Vi\u1ec7t Xu\u00e2n Thu ph\u1ea3i b\u1eaft \u0111\u1ea7u t\u1eeb vi\u1ec7c Vi\u1ec7t v\u01b0\u01a1ng C\u00e2u Ti\u1ec5n \u0111\u00e3 gi\u1ebft Ng\u00f4 v\u01b0\u01a1ng H\u1ea1p L\u01b0.`,
  `Sau khi H\u1ea1p L\u01b0 ch\u1ebft, con trai Ph\u00f9 Sai k\u1ebf v\u1ecb,`,
  `Ph\u00f9 Sai v\u00ec mu\u1ed1n b\u00e1o th\u00f9 cho cha n\u00ean \u0111\u00e3 b\u1eaft C\u00e2u Ti\u1ec5n.`,
  `N\u1ebfu l\u00fac n\u00e0y Ph\u00f9 Sai gi\u1ebft C\u00e2u Ti\u1ec5n,`,
  `Sau \u0111\u00f3 kh\u00f4ng c\u00f3 chuy\u1ec7n g\u00ec n\u1eefa.`,
  `Nh\u01b0ng Ph\u00f9 Sai l\u1ea1i kh\u00f4ng ch\u1ecbu.`,
  `M\u1edbi c\u00f3 c\u00e2u chuy\u1ec7n v\u1ec1 sau C\u00e2u Ti\u1ec5n n\u1eb1m gai n\u1ebfm m\u1eadt, d\u00f9ng m\u1ef9 nh\u00e2n k\u1ebf T\u00e2y Thi \u0111\u1ec3 lo\u1ea1i b\u1ecf Ph\u00f9 Sai,`,
  `Di\u1ec7t n\u01b0\u1edbc Ng\u00f4, c\u00e2u chuy\u1ec7n truy\u1ec1n c\u1ea3m h\u1ee9ng v\u1ec1 s\u1ef1 ph\u1ea3n c\u00f4ng th\u00e0nh c\u00f4ng.`,
  `Th\u1eddi Xu\u00e2n Thu \u0111\u1ebfn \u0111\u00e2y l\u00e0 k\u1ebft th\u00fac.`,
  `Ti\u1ebfp theo l\u00e0 th\u1eddi Chi\u1ebfn Qu\u1ed1c,`,
  `Nh\u00e2n ti\u1ec7n n\u00f3i th\u00eam,`,
  `Trong th\u1eddi Xu\u00e2n Thu, c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u n\u00e0y ch\u1ec9 \u0111\u00e1nh nh\u1eefng tr\u1eadn nh\u1ecf,`,
  `Kh\u00f4ng ai ra tay t\u00e0n nh\u1eabn, \u0111\u00e1nh xong th\u00ec ai v\u1ec1 nh\u00e0 n\u1ea5y.`,
  `C\u0169ng ch\u00ednh v\u00ec trong th\u1eddi k\u1ef3 n\u00e0y c\u00f3 r\u1ea5t nhi\u1ec1u qu\u1ed1c gia,`,
  `M\u1ed7i qu\u1ed1c gia l\u1ea1i c\u00f3 nh\u1eefng t\u01b0 t\u01b0\u1edfng v\u0103n h\u00f3a kh\u00e1c nhau \u0111\u01b0\u1ee3c \u0111\u1ec1 cao,`,
  `V\u00ec v\u1eady, v\u00e0o th\u1eddi Xu\u00e2n Thu, b\u00e1ch gia tranh minh, xu\u1ea5t hi\u1ec7n m\u1ed9t lo\u1ea1t c\u00e1c nh\u00e2n v\u1eadt ki\u1ec7t xu\u1ea5t,`,
  `L\u00e3o T\u1eed, Kh\u1ed5ng T\u1eed, Trang T\u1eed, M\u1ea1nh T\u1eed, H\u00e0n Phi T\u1eed,`,
  `M\u1eb7c T\u1eed, v.v. Nh\u01b0ng \u1edf th\u1eddi Chi\u1ebfn Qu\u1ed1c ti\u1ebfp theo,`,
  `C\u00e1c ch\u01b0 h\u1ea7u kh\u00f4ng c\u00f2n ch\u1ec9 l\u00e0 \u0111\u00e1nh nhau nh\u1ecf n\u1eefa.`,
  `Sau khi C\u00e2u Ti\u1ec5n di\u1ec7t n\u01b0\u1edbc Ng\u00f4,`,
  `c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u kh\u00e1c th\u1ea5y r\u1eb1ng,`,
  `\u00e0, tr\u00f2 ch\u01a1i c\u00f3 th\u1ec3 ch\u01a1i nh\u01b0 th\u1ebf n\u00e0y.`,
  `T\u1eeb \u0111\u00f3 v\u1ec1 sau, nh\u1eefng cu\u1ed9c chi\u1ebfn nh\u1ecf kh\u00f4ng c\u00f2n th\u1ecbnh h\u00e0nh n\u1eefa,`,
  `c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u c\u00f3 th\u1ef1c l\u1ef1c b\u1eaft \u0111\u1ea7u tr\u1ef1c ti\u1ebfp th\u00f4n t\u00ednh c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u y\u1ebfu h\u01a1n.`,
  `V\u00ec v\u1eady, sau n\u00e0y ch\u00fang ta g\u1ecdi th\u1eddi k\u1ef3 h\u1ed7n lo\u1ea1n v\u1edbi s\u1ef1 th\u00f4n t\u00ednh l\u1eabn nhau n\u00e0y l\u00e0 th\u1eddi Chi\u1ebfn Qu\u1ed1c.`,
  `B\u1ea1n c\u00f2n nh\u1edb nh\u1eefng qu\u1ed1c gia \u0111\u00e3 x\u01b0ng b\u00e1 v\u00e0o th\u1eddi Xu\u00e2n Thu kh\u00f4ng?`,
  `T\u1ec1, T\u1ea5n, S\u1edf, Ng\u00f4, T\u1ea7n.`,
  `Khi \u0111\u00f3, nh\u00e0 Chu l\u00e0 l\u00e3nh \u0111\u1ea1o, \u0111\u1ea5t \u0111ai qu\u00e1 r\u1ed9ng l\u1edbn,`,
  `kh\u00f4ng qu\u1ea3n l\u00fd xu\u1ec3 n\u00ean \u0111\u00e3 chia cho c\u00e1c ch\u01b0 h\u1ea7u l\u00e0 \u0111\u00e0n em c\u1ee7a m\u00ecnh.`,
  `C\u00e1c ch\u01b0 h\u1ea7u c\u0169ng c\u00f3 c\u00e1c \u0111\u1ea1i phu c\u1ee7a ri\u00eang m\u00ecnh.`,
  `N\u01b0\u1edbc T\u1ea5n \u0111\u00e3 nu\u00f4i v\u00f4 s\u1ed1 \u0111\u1ea1i phu v\u00e0o th\u1eddi Xu\u00e2n Thu,`,
  `trong s\u1ed1 \u0111\u00f3 c\u00f3 ba gia t\u1ed9c, sau nhi\u1ec1u n\u0103m ph\u1ea5n \u0111\u1ea5u,`,
  `c\u00f3 th\u1ef1c l\u1ef1c si\u00eau vi\u1ec7t, h\u1ecd l\u00e0 H\u00e0n,`,
  `Tri\u1ec7u v\u00e0 Ng\u1ee5y. Ba gia t\u1ed9c n\u00e0y m\u1ea1nh \u0111\u1ebfn m\u1ee9c n\u00e0o?`,
  `M\u1ea1nh \u0111\u1ebfn m\u1ee9c cu\u1ed1i c\u00f9ng \u0111\u00e3 chia c\u1eaft T\u1ea5n qu\u1ed1c, th\u1ee7 l\u0129nh c\u1ee7a m\u00ecnh,`,
  `th\u00e0nh l\u1eadp ba qu\u1ed1c gia m\u1edbi.`,
  `T\u1ea5n qu\u1ed1c di\u1ec7t vong. N\u01b0\u1edbc T\u1ec1, m\u1ed9t c\u01b0\u1eddng qu\u1ed1c kh\u00e1c th\u1eddi Xu\u00e2n Thu, c\u0169ng ch\u1eb3ng kh\u00e1 h\u01a1n l\u00e0 bao.`,
  `B\u1ecb m\u1ed9t thu\u1ed9c h\u1ea1 h\u1ecd \u0110i\u1ec1n c\u1ee7a ch\u00ednh m\u00ecnh \u00e1m h\u1ea1i,`,
  `quy\u1ec1n l\u1ef1c r\u01a1i v\u00e0o tay k\u1ebb kh\u00e1c, b\u1ecb h\u1ecd \u0110i\u1ec1n thay th\u1ebf.`,
  `N\u00f3i r\u00f5 h\u01a1n m\u1ed9t ch\u00fat,`,
  `N\u01b0\u1edbc T\u1ec1 th\u1eddi Xu\u00e2n Thu l\u00e0 n\u01b0\u1edbc T\u1ec1 c\u1ee7a h\u1ecd Kh\u01b0\u01a1ng, h\u1eadu du\u1ec7 c\u1ee7a Kh\u01b0\u01a1ng T\u1eed Nha.`,
  `\u0110\u1ebfn th\u1eddi Chi\u1ebfn Qu\u1ed1c, n\u01b0\u1edbc T\u1ec1 tr\u1edf th\u00e0nh n\u01b0\u1edbc T\u1ec1 c\u1ee7a h\u1ecd \u0110i\u1ec1n.`,
  `V\u1edf k\u1ecbch Chi\u1ebfn Qu\u1ed1c c\u00f3 v\u00f4 s\u1ed1 nh\u00e2n v\u1eadt,`,
  `ch\u1eb3ng qua l\u00e0 s\u00e1p nh\u1eadp v\u00e0 b\u1ecb s\u00e1p nh\u1eadp, cu\u1ed1i c\u00f9ng c\u00f2n l\u1ea1i b\u1ea3y si\u00eau c\u01b0\u1eddng qu\u1ed1c:`,
  `H\u00e0n, Tri\u1ec7u, Ng\u1ee5y, T\u1ea7n, T\u1ec1,`,
  `S\u1edf v\u00e0 Y\u00ean, s\u1eed g\u1ecdi l\u00e0 Chi\u1ebfn Qu\u1ed1c Th\u1ea5t H\u00f9ng.`,
  `Khi \u0111\u00e3 tr\u1edf th\u00e0nh si\u00eau c\u01b0\u1eddng qu\u1ed1c, kh\u00f4ng th\u1ec3 ch\u1ec9 d\u1ef1a v\u00e0o v\u0169 l\u1ef1c,`,
  `m\u00e0 c\u00f2n ph\u1ea3i c\u00f3 \u00fd th\u1ee9c \u0111\u1ed5i m\u1edbi.`,
  `C\u00e1c qu\u1ed1c gia n\u00e0y\u7eb7\u7eb7 ti\u1ebfn h\u00e0nh bi\u1ebfn ph\u00e1p,`,
  `N\u01b0\u1edbc T\u1ea7n c\u00f3 v\u1eadn may \u0111\u1eb7c bi\u1ec7t khi g\u1eb7p \u0111\u01b0\u1ee3c Th\u01b0\u01a1ng \u01af\u1edfng.`,
  `Sau c\u1ea3i c\u00e1ch c\u1ee7a Th\u01b0\u01a1ng \u01af\u1edfng, ch\u1ec9 trong h\u01a1n m\u01b0\u1eddi n\u0103m, s\u1ee9c m\u1ea1nh c\u1ee7a n\u01b0\u1edbc T\u1ea7n \u0111\u00e3 ph\u00e1t tri\u1ec3n v\u01b0\u1ee3t b\u1eadc,`,
  `Tr\u1edf th\u00e0nh m\u1ed9t si\u00eau si\u00eau si\u00eau si\u00eau c\u01b0\u1eddng qu\u1ed1c.`,
  `Tr\u01b0\u1edbc \u0111\u00e2y, th\u1ef1c l\u1ef1c c\u1ee7a b\u1ea3y n\u01b0\u1edbc ch\u01b0 h\u1ea7u t\u01b0\u01a1ng \u0111\u01b0\u01a1ng nhau,`,
  `\u0110\u1ed9t nhi\u00ean m\u1ed9t trong s\u1ed1 \u0111\u00f3 tr\u1edf n\u00ean c\u1ef1c k\u1ef3 m\u1ea1nh, v\u01b0\u1ee3t xa t\u1ea5t c\u1ea3 nh\u1eefng ng\u01b0\u1eddi kh\u00e1c,`,
  `B\u1ea1n \u0111o\u00e1n xem chuy\u1ec7n g\u00ec s\u1ebd x\u1ea3y ra?`,
  `\u0110\u01b0\u01a1ng nhi\u00ean l\u00e0 c\u00f9ng nhau h\u1ee3p s\u1ee9c t\u1ea5n c\u00f4ng h\u1eafn.`,
  `Y\u1ebfn qu\u1ed1c c\u00f3 m\u1ed9t m\u01b0u s\u0129 t\u00ean l\u00e0 Th\u01b0 T\u1ea7n, \u0111\u00e3 \u0111\u1ec1 ngh\u1ecb s\u00e1u n\u01b0\u1edbc li\u00ean minh \u0111\u1ec3 ch\u1ed1ng l\u1ea1i T\u1ea7n qu\u1ed1c.`,
  `S\u00e1u n\u01b0\u1edbc nghe xong, l\u1eadp t\u1ee9c \u0111\u1ed3ng \u00fd, t\u1ea1o th\u00e0nh c\u1ee5c di\u1ec7n s\u00e1u \u0111\u1ea5u m\u1ed9t,`,
  `S\u1eed g\u1ecdi l\u00e0 L\u1ee5c qu\u1ed1c h\u1ee3p tung.`,
  `N\u01b0\u1edbc T\u1ea7n c\u0169ng kh\u00f4ng ph\u1ea3i l\u00e0 k\u1ebb ng\u1ed1c, m\u1ed9t m\u01b0u s\u0129 t\u00ean l\u00e0 T\u00f4n Nghi \u0111\u00e3 hi\u1ebfn k\u1ebf cho T\u1ea7n v\u01b0\u01a1ng,`,
  `T\u00ean l\u00e0 Li\u00ean ho\u00e0nh. Th\u1ef1c ch\u1ea5t l\u00e0 ch\u01a1i chi\u1ebfn thu\u1eadt t\u00e2m l\u00fd,`,
  `Chia r\u1ebd quan h\u1ec7 gi\u1eefa s\u00e1u n\u01b0\u1edbc, \u0111\u00e1nh b\u1ea1i t\u1eebng n\u01b0\u1edbc m\u1ed9t.`,
  `C\u00f2n c\u00f3 m\u1ed9t m\u01b0u s\u0129 t\u00ean l\u00e0 Ph\u1ea1m Th\u01b0, c\u0169ng \u0111\u01b0a ra \u00fd ki\u1ebfn cho T\u1ea7n l\u00e0 Vi\u1ec5n giao c\u1eadn c\u00f4ng,`,
  `C\u00e1c n\u01b0\u1edbc xa T\u1ea7n th\u00ec k\u1ebft giao h\u1eefu h\u1ea3o,`,
  `C\u00e1c n\u01b0\u1edbc l\u00e2n c\u1eadn T\u1ea7n kh\u00f4ng c\u00f3 vi\u1ec7c g\u00ec l\u00e0m l\u00e0 \u0111\u00e1nh n\u01b0\u1edbc n\u00e0y m\u1ed9t tr\u1eadn.`,
  `Tuy\u1ec7t chi\u00eau n\u00e0y \u0111\u1eb7c bi\u1ec7t l\u1ee3i h\u1ea1i, c\u00f4 l\u1eadp t\u1ea5t c\u1ea3 c\u00e1c \u0111\u1ed1i th\u1ee7.`,
  `\u0110\u00e3 h\u00f3a gi\u1ea3i ho\u00e0n h\u1ea3o c\u1ee5c di\u1ec7n b\u1ea5t l\u1ee3i s\u00e1u \u0111\u1ed1i m\u1ed9t.`,
  `M\u1ed9t khi li\u00ean minh tan r\u00e3, n\u00f3i v\u1ec1 \u0111\u00e1nh \u0111\u01a1n, kh\u00f4ng ai l\u00e0 \u0111\u1ed1i th\u1ee7 c\u1ee7a T\u1ea7n.`,
  `Nh\u1eefng chuy\u1ec7n c\u00f2n l\u1ea1i th\u00ec m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u bi\u1ebft r\u1ed3i,`,
  `S\u00e1u n\u01b0\u1edbc l\u1ea7n l\u01b0\u1ee3t b\u1ecb T\u1ea7n ti\u00eau di\u1ec7t theo th\u1ee9 t\u1ef1 H\u00e0n,`,
  `Tri\u1ec7u, Ng\u1ee5y, S\u1edf, Y\u00ean, T\u1ec1.`,
  `\u00c0, c\u00f2n c\u00f3 Chu Thi\u00ean T\u1eed,`,
  `V\u00ec qu\u00e1 m\u1edd nh\u1ea1t, Chu l\u00e3o \u0111\u1ea1i \u0111\u00e3 \u0111\u00e1nh nhau h\u01a1n 500 n\u0103m trong th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c,`,
  `\u0110\u00e3 b\u1ecb T\u1ea7n di\u1ec7t tr\u01b0\u1edbc khi s\u00e1u n\u01b0\u1edbc di\u1ec7t vong.`,
  `T\u1ea7n cu\u1ed1i c\u00f9ng \u0111\u00e3 ti\u00eau di\u1ec7t h\u1ebft v\u00e0 th\u1ed1ng nh\u1ea5t giang h\u1ed3.`,
  `Th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c \u0111\u1ebfn \u0111\u00e2y l\u00e0 k\u1ebft th\u00fac.`,
  `N\u00f3i v\u1ec1 nh\u00e0 T\u1ea7n, ch\u1ee7 y\u1ebfu l\u00e0 n\u00f3i v\u1ec1 T\u1ea7n Th\u1ee7y Ho\u00e0ng, v\u00ec nh\u00e0 T\u1ea7n qu\u00e1 ng\u1eafn ng\u1ee7i,`,
  `ch\u1ec9 c\u00f3 m\u01b0\u1eddi l\u0103m n\u0103m.`,
  `N\u0103m 221 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `T\u1ea7n di\u1ec7t s\u00e1u n\u01b0\u1edbc, ch\u1ea5m d\u1ee9t th\u1eddi k\u1ef3 ch\u01b0 h\u1ea7u tranh gi\u00e0nh k\u00e9o d\u00e0i h\u01a1n 500 n\u0103m th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c,`,
  `th\u1ed1ng nh\u1ea5t Trung Hoa. \u0110\u1ea5t n\u01b0\u1edbc \u0111\u00e3 th\u1ed1ng nh\u1ea5t, nh\u01b0ng tr\u01b0\u1edbc l\u1ecbch s\u1eed \u0111\u1eabm m\u00e1u c\u1ee7a nh\u00e0 Chu, tri\u1ec1u \u0111\u1ea1i tr\u01b0\u1edbc \u0111\u00f3,`,
  `nh\u00e0 T\u1ea7n suy ngh\u0129 l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 kh\u00f4ng \u0111i v\u00e0o v\u1ebft xe \u0111\u1ed5.`,
  `Th\u1ec3 ch\u1ebf c\u1ee7a nh\u00e0 Chu khi \u0111\u00f3 ch\u1ee7 y\u1ebfu l\u00e0 ch\u1ebf \u0111\u1ed9 phong ki\u1ebfn,`,
  `Thi\u00ean t\u1eed nh\u00e0 Chu phong \u0111\u1ea5t \u0111ai c\u1ee7a m\u00ecnh cho ng\u01b0\u1eddi th\u00e2n ho\u1eb7c th\u1ea7n t\u1eed,`,
  `m\u1ed7i phong \u0111\u1ecba l\u00e0 m\u1ed9t n\u01b0\u1edbc ch\u01b0 h\u1ea7u.`,
  `N\u00f3i c\u00e1ch kh\u00e1c, \u0111\u1ea5t \u0111ai kh\u00f4ng ho\u00e0n to\u00e0n thu\u1ed9c v\u1ec1 ho\u00e0ng th\u1ea5t,`,
  `c\u00e1c v\u01b0\u01a1ng ch\u01b0 h\u1ea7u c\u00f3 quy\u1ec1n l\u1ef1c tuy\u1ec7t \u0111\u1ed1i tr\u00ean \u0111\u1ea5t phong c\u1ee7a m\u00ecnh,`,
  `c\u00f3 th\u1ec3 th\u1ebf t\u1eadp, c\u00f3 th\u1ec3 c\u00f3 qu\u00e2n \u0111\u1ed9i ri\u00eang,`,
  `v\u00e0 c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u ph\u1ea3i n\u1ed9p thu\u1ebf c\u1ed1ng cho ho\u00e0ng th\u1ea5t.`,
  `Ch\u1ebf \u0111\u1ed9 n\u00e0y ban \u0111\u1ea7u th\u00ec v\u1eabn \u1ed5n,`,
  `v\u00ec Thi\u00ean t\u1eed nh\u00e0 Chu v\u00e0 c\u00e1c ch\u01b0 h\u1ea7u \u0111\u1ec1u l\u00e0 ng\u01b0\u1eddi th\u00e2n, quen bi\u1ebft,`,
  `nh\u01b0ng l\u00e2u d\u1ea7n, c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u s\u1ebd c\u00f3 th\u1ebf l\u1ef1c v\u01b0\u1ee3t qua ho\u00e0ng th\u1ea5t,`,
  `d\u1eabn \u0111\u1ebfn c\u1ee5c di\u1ec7n c\u00e1c ch\u01b0 h\u1ea7u l\u1edbn h\u00f9ng c\u1ee9 nhi\u1ec1u n\u01a1i.`,
  `Th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c l\u00e0 v\u00ec th\u1ebf m\u00e0 c\u00f3.`,
  `nh\u00e0 T\u1ea7n r\u00fat kinh nghi\u1ec7m t\u1eeb s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a nh\u00e0 Chu,`,
  `l\u1ea7n \u0111\u1ea7u ti\u00ean t\u1ea1o ra ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n.`,
  `ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n l\u1ea5y Ho\u00e0ng \u0111\u1ebf l\u00e0m ng\u01b0\u1eddi \u0111\u1ee9ng \u0111\u1ea7u,`,
  `Tam C\u00f4ng C\u1eedu Khanh l\u00e0m \u0111\u1ea1i di\u1ec7n c\u1ee7a ch\u1ebf \u0111\u1ed9 t\u1eadp quy\u1ec1n c\u1ee7a ch\u00ednh ph\u1ee7 trung \u01b0\u01a1ng,`,
  `chia \u0111\u1ea5t n\u01b0\u1edbc th\u00e0nh ba m\u01b0\u01a1i s\u00e1u qu\u1eadn,`,
  `d\u01b0\u1edbi qu\u1eadn l\u1ea1i chia th\u00e0nh h\u01a1n m\u1ed9t ngh\u00ecn huy\u1ec7n,`,
  `quan l\u1ea1i \u0111\u1ee9ng \u0111\u1ea7u m\u1ed7i qu\u1eadn huy\u1ec7n \u0111\u1ec1u do trung \u01b0\u01a1ng b\u1ed5 nhi\u1ec7m,`,
  `kh\u00f4ng c\u00f3 b\u1ea5t k\u1ef3 m\u1ed1i quan h\u1ec7 huy\u1ebft th\u1ed1ng n\u00e0o v\u1edbi nhau.`,
  `kh\u00e1c v\u1edbi vi\u1ec7c c\u00e1c ch\u01b0 h\u1ea7u nh\u00e0 Chu n\u1ed9p c\u1ed1ng n\u1ea1p cho nh\u00e0 n\u01b0\u1edbc,`,
  `ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n c\u1ee7a Ho\u00e0ng \u0111\u1ebf tr\u1ea3 b\u1ed5ng l\u1ed9c cho ho\u1ea1n quan.`,
  `m\u00f4 h\u00ecnh ph\u00e2n c\u1ea5p n\u00e0y l\u00e0m cho quy\u1ec1n l\u1ef1c trung \u01b0\u01a1ng t\u1eadp trung cao \u0111\u1ed9,`,
  `ng\u01b0\u1eddi cai tr\u1ecb c\u00f3 quy\u1ec1n l\u1ef1c tuy\u1ec7t \u0111\u1ed1i,`,
  `c\u00f3 l\u1ee3i cho vi\u1ec7c t\u0103ng c\u01b0\u1eddng t\u1eadp quy\u1ec1n trung \u01b0\u01a1ng v\u00e0 th\u1ed1ng nh\u1ea5t \u0111\u1ea5t n\u01b0\u1edbc.`,
  `c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u hi\u1ec7n nay c\u00f3 th\u1ec3 ch\u1ebf ri\u00eang \u1edf nhi\u1ec1u m\u1eb7t,`,
  `nh\u01b0ng sau khi th\u1ed1ng nh\u1ea5t c\u1ea3 n\u01b0\u1edbc, c\u00e1c th\u1ec3 ch\u1ebf n\u00e0y s\u1ebd g\u00e2y ra nhi\u1ec1u r\u1eafc r\u1ed1i,`,
  `V\u00ed d\u1ee5, Ti\u1ec1n t\u1ec7 kh\u00f4ng \u0111\u1ed3ng nh\u1ea5t,`,
  `Th\u01b0\u01a1ng m\u1ea1i v\u00e0 c\u00f4ng nghi\u1ec7p kh\u00f4ng th\u1ec3 ph\u00e1t tri\u1ec3n,`,
  `Khi \u0111\u01a1n v\u1ecb \u0111o l\u01b0\u1eddng kh\u00f4ng th\u1ed1ng nh\u1ea5t, vi\u1ec7c mua b\u00e1n r\u1ea5t b\u1ea5t ti\u1ec7n,`,
  `Ng\u00f4n ng\u1eef b\u1ea5t \u0111\u1ed3ng th\u00ec kh\u00f4ng th\u1ec3 giao ti\u1ebfp.`,
  `V\u00ec v\u1eady, T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 th\u1ed1ng nh\u1ea5t ti\u1ec1n t\u1ec7 v\u00e0 \u0111o l\u01b0\u1eddng tr\u00ean to\u00e0n qu\u1ed1c,`,
  `\u0110\u1eb7t n\u1ec1n m\u00f3ng cho giao th\u01b0\u01a1ng kinh t\u1ebf c\u1ee7a nh\u00e0 T\u1ea7n,`,
  `L\u1ea5y ch\u1eef Ti\u1ec3u tri\u1ec7n l\u00e0m v\u0103n t\u1ef1 chung tr\u00ean to\u00e0n qu\u1ed1c,`,
  `C\u00f3 l\u1ee3i cho vi\u1ec7c ph\u1ed5 c\u1eadp v\u0103n h\u00f3a v\u00e0 th\u1ed1ng nh\u1ea5t t\u01b0 t\u01b0\u1edfng c\u1ee7a ng\u01b0\u1eddi d\u00e2n.`,
  `N\u00f3i \u0111\u1ebfn th\u1ed1ng nh\u1ea5t t\u01b0 t\u01b0\u1edfng, ti\u1ec7n th\u1ec3 nh\u1eafc \u0111\u1ebfn vi\u1ec7c \u0111\u1ed1t s\u00e1ch ch\u00f4n Nho lu\u00f4n.`,
  `Tr\u01b0\u1edbc \u0111\u00e2y, c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u c\u00f3 c\u00e1c quan ni\u1ec7m v\u0103n h\u00f3a kh\u00e1c nhau,`,
  `M\u1edbi c\u00f3`,
  `\u0110\u1ebfn khi T\u1ea7n th\u1ed1ng nh\u1ea5t,`,
  `Hai tr\u00e0o l\u01b0u t\u01b0 t\u01b0\u1edfng l\u1edbn nh\u1ea5t l\u00fac b\u1ea5y gi\u1edd l\u00e0 v\u0103n h\u00f3a Nho gia v\u00e0 v\u0103n h\u00f3a Ph\u00e1p gia.`,
  `Nho gia nh\u1ea5n m\u1ea1nh tr\u1ecb n\u01b0\u1edbc b\u1eb1ng l\u00f2ng nh\u00e2n, ph\u1ee5c ng\u01b0\u1eddi b\u1eb1ng l\u1ec5 ngh\u0129a;`,
  `Ph\u00e1p gia nh\u1ea5n m\u1ea1nh tr\u1ecb n\u01b0\u1edbc b\u1eb1ng v\u0169 l\u1ef1c, cai tr\u1ecb con ng\u01b0\u1eddi b\u1eb1ng quy\u1ec1n l\u1ef1c.`,
  `Th\u1ec3 ch\u1ebf Ph\u00e1p gia \u0111\u01b0\u1ee3c nh\u00e0 T\u1ea7n \u0111\u1ec1 cao \u0111\u00e3 v\u1ea5p ph\u1ea3i s\u1ef1 ph\u1ea3n \u0111\u1ed1i c\u1ee7a c\u00e1c nh\u00e0 nho s\u0129,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 h\u1ee7y ho\u1ea1i s\u00e1ch s\u1eed,`,
  `ch\u00f4n s\u1ed1ng c\u00e1c nh\u00e0 nho \u0111\u1ec3 \u0111\u00e0n \u00e1p c\u00e1c n\u1ec1n v\u0103n h\u00f3a kh\u00e1c,`,
  `nh\u1eb1m duy tr\u00ec s\u1ef1 th\u1ed1ng nh\u1ea5t v\u0129 \u0111\u1ea1i.`,
  `Ch\u00ednh t\u01b0 t\u01b0\u1edfng l\u1ea5y v\u00f5 tr\u1ecb qu\u1ed1c c\u1ee7a T\u1ea7n Th\u1ee7y Ho\u00e0ng n\u00e0y,`,
  `c\u0169ng \u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng cho s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a nh\u00e0 T\u1ea7n sau n\u00e0y.`,
  `\u0110\u1ec3 ch\u1ed1ng l\u1ea1i s\u1ef1 x\u00e2m l\u01b0\u1ee3c c\u1ee7a ngo\u1ea1i t\u1ed9c,`,
  `nh\u00e0 T\u1ea7n \u0111\u00e3 huy \u0111\u1ed9ng h\u00e0ng ch\u1ee5c v\u1ea1n lao c\u00f4ng x\u00e2y d\u1ef1ng V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh.`,
  `Th\u1ef1c ra, V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng s\u1edbm nh\u1ea5t v\u00e0o th\u1eddi Xu\u00e2n Thu,`,
  `sau khi nh\u00e0 T\u1ea7n th\u1ed1ng nh\u1ea5t \u0111\u00e3 c\u1ee7ng c\u1ed1 v\u00e0 s\u1eeda ch\u1eefa n\u00f3,`,
  `v\u00e0 k\u1ebft n\u1ed1i ho\u00e0n ch\u1ec9nh.`,
  `Ngo\u00e0i ra, nh\u00e0 T\u1ea7n c\u00f2n x\u00e2y d\u1ef1ng cung A Ph\u00f2ng, s\u1eeda sang l\u0103ng m\u1ed9 ho\u00e0ng gia,`,
  `huy \u0111\u1ed9ng h\u00e0ng tri\u1ec7u lao \u0111\u1ed9ng,`,
  `lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n h\u00e0 kh\u1eafc, lao d\u1ecbch n\u1eb7ng n\u1ec1 v\u00e0 \u00e1p b\u1ee9c khi\u1ebfn d\u00e2n ch\u00fang l\u1ea7m than,`,
  `m\u00e2u thu\u1eabn x\u00e3 h\u1ed9i ng\u00e0y c\u00e0ng gia t\u0103ng.`,
  `N\u0103m 210 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng th\u1ef1c hi\u1ec7n chuy\u1ebfn tu\u1ea7n du cu\u1ed1i c\u00f9ng,`,
  `v\u00e0 \u0111\u1ed9t ng\u1ed9t b\u0103ng h\u00e0 t\u1ea1i h\u00e0nh cung Sa Kh\u00e2u.`,
  `\u0110\u00fang v\u1eady, ghi ch\u00e9p ch\u00ednh s\u1eed ch\u1ec9 c\u00f3 hai ch\u1eef:`,
  `\u0111\u1ed9t t\u1eed. D\u00e2n gian c\u00f3 hai gi\u1ea3 thuy\u1ebft v\u1ec1 nguy\u00ean nh\u00e2n c\u00e1i ch\u1ebft c\u1ee7a \u00f4ng,`,
  `m\u1ed9t l\u00e0 \u00f4ng ch\u1ebft v\u00ec b\u1ec7nh, hai l\u00e0 \u00f4ng b\u1ecb Tri\u1ec7u Cao m\u01b0u h\u1ea1i,`,
  `b\u1edfi v\u00ec c\u00e1i ch\u1ebft qu\u00e1 \u0111\u1ed9t ng\u1ed9t.`,
  `Nguy\u00ean do di chi\u1ebfu c\u1ee7a \u00f4ng l\u00e0 mu\u1ed1n ho\u00e0ng t\u1eed tr\u01b0\u1edfng Ph\u00f9 T\u00f4 k\u1ebf v\u1ecb,`,
  `nh\u01b0ng khi T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u1ec3 l\u1ea1i di chi\u1ebfu,`,
  `b\u00ean c\u1ea1nh \u00f4ng ch\u1ec9 c\u00f3 ho\u00e0ng t\u1eed \u00fat H\u1ed3 H\u1ee3i,`,
  `th\u00e1i gi\u00e1m Tri\u1ec7u Cao v\u00e0 th\u1eeba t\u01b0\u1edbng L\u00fd T\u01b0.`,
  `Tri\u1ec7u Cao c\u00f3 m\u00e2u thu\u1eabn v\u1edbi Ph\u00f9 T\u00f4,`,
  `n\u00ean h\u1eafn s\u1ee3 Ph\u00f9 T\u00f4 k\u1ebf v\u1ecb s\u1ebd tr\u1ea3 th\u00f9 m\u00ecnh,`,
  `v\u00ec v\u1eady Tri\u1ec7u Cao \u0111\u00e3 thuy\u1ebft ph\u1ee5c H\u1ed3 H\u1ee3i,`,
  `\u0111e d\u1ecda L\u00fd T\u01b0 s\u1eeda \u0111\u1ed5i di chi\u1ebfu c\u1ee7a T\u1ea7n Th\u1ee7y Ho\u00e0ng,`,
  `ra l\u1ec7nh cho Ph\u00f9 T\u00f4 t\u1ef1 s\u00e1t,`,
  `do H\u1ed3 H\u1ee3i k\u1ebf v\u1ecb.`,
  `Sau \u0111\u00f3, L\u00fd T\u01b0 c\u0169ng b\u1ecb H\u1ed3 H\u1ee3i ch\u00e9m ngang l\u01b0ng,`,
  `Tri\u1ec7u Cao \u0111\u1ed9c chi\u1ebfm quy\u1ec1n h\u00e0nh.`,
  `Sau \u0111\u00f3, chuy\u1ec7n g\u00ec \u0111\u00e3 x\u1ea3y ra?`,
  `Nh\u00e0 T\u1ea7n \u0111\u00e3 s\u1ee5p \u0111\u1ed5 nh\u01b0 th\u1ebf n\u00e0o?`,
  `T\u1ea7n Nh\u1ecb Th\u1ebf H\u1ed3 H\u1ee3i sau khi l\u00ean ng\u00f4i, ch\u1ec9 lo h\u01b0\u1edfng l\u1ea1c,`,
  `kh\u00f4ng m\u00e0ng tri\u1ec1u ch\u00ednh, l\u1ea1i c\u00f2n tin l\u1eddi gi\u00e8m pha c\u1ee7a Tri\u1ec7u Cao,`,
  `s\u00e1t h\u1ea1i trung l\u01b0\u01a1ng. Tri\u1ec7u Cao trong tri\u1ec1u \u0111\u00ecnh nh\u00e0 T\u1ea7n h\u00f4 m\u01b0a g\u1ecdi gi\u00f3,`,
  `l\u00e0m \u0111\u1ee7 \u0111i\u1ec1u x\u1eb1ng b\u1eady, l\u00e0m t\u0103ng th\u00eam s\u1ef1 t\u00e0n b\u1ea1o trong cai tr\u1ecb c\u1ee7a ho\u00e0ng th\u1ea5t,`,
  `th\u1eadm ch\u00ed c\u00f2n t\u00e0n kh\u1ed1c h\u01a1n th\u1eddi T\u1ea7n Th\u1ee7y Ho\u00e0ng.`,
  `C\u1ea3 n\u01b0\u1edbc l\u1ea7m than, d\u00e2n ch\u00fang k\u00eau than kh\u1eafp n\u01a1i,`,
  `d\u01b0\u1edbi b\u1ea1o ch\u00ednh \u1eaft s\u1ebd c\u00f3 ph\u1ea3n kh\u00e1ng.`,
  `Trong c\u00e1c cu\u1ed9c ph\u1ea3n kh\u00e1ng l\u1edbn nh\u1ecf,`,
  `\u0111\u00e1ng k\u1ec3 nh\u1ea5t l\u00e0 cu\u1ed9c kh\u1edfi ngh\u0129a \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng.`,
  `\u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng c\u00f3 th\u1ec3 b\u1ea1n kh\u00f4ng bi\u1ebft, nh\u01b0ng Tr\u1ea7n Th\u1eafng,`,
  `Ng\u00f4 Qu\u1ea3ng ch\u1eafc ch\u1eafn b\u1ea1n \u0111\u00e3 t\u1eebng nghe qua.`,
  `V\u00e0o n\u0103m 209 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean, hai v\u1ecb t\u01b0\u1edbng \u1edf H\u00e0 Nam \u0111\u00e3 \u00e1p gi\u1ea3i m\u1ed9t nh\u00f3m 900 lao \u0111\u1ed9ng \u0111\u1ebfn B\u1eafc Kinh.`,
  `Vi\u00ean quan \u0111\u00e3 ch\u1ecdn hai lao \u0111\u1ed9ng trong s\u1ed1 \u0111\u00f3 \u0111\u1ec3 qu\u1ea3n l\u00fd nh\u1eefng ng\u01b0\u1eddi c\u00f2n l\u1ea1i,`,
  `\u0111\u00f3 ch\u00ednh l\u00e0 Tr\u1ea7n Th\u1eafng v\u00e0 Ng\u00f4 Qu\u1ea3ng.`,
  `Khi \u0111o\u00e0n ng\u01b0\u1eddi c\u1ee7a h\u1ecd \u0111\u1ebfn \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng,`,
  `tr\u1eddi \u0111\u1ed5 m\u01b0a l\u1edbn,`,
  `to\u00e0n b\u1ed9 \u0111\u01b0\u1eddng s\u00e1 b\u1ecb ng\u1eadp n\u01b0\u1edbc, m\u1ecdi ng\u01b0\u1eddi kh\u00f4ng th\u1ec3 \u0111\u1ebfn B\u1eafc Kinh \u0111\u00fang th\u1eddi h\u1ea1n quy \u0111\u1ecbnh.`,
  `Lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n th\u1eddi b\u1ea5y gi\u1edd v\u00f4 c\u00f9ng h\u00e0 kh\u1eafc,`,
  `n\u1ebfu qu\u00e1 th\u1eddi h\u1ea1n \u0111\u1ebfn n\u01a1i s\u1ebd b\u1ecb ch\u00e9m \u0111\u1ea7u.`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng ngh\u0129,`,
  `ki\u1ec3u g\u00ec c\u0169ng ch\u1ebft, chi b\u1eb1ng c\u1ee9 li\u1ec1u m\u1ed9t phen.`,
  `Trong t\u00ecnh th\u1ebf c\u1ea5p b\u00e1ch,`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng \u0111\u00e3 l\u00e3nh \u0111\u1ea1o c\u00e1c lao c\u00f4ng kh\u00e1c gi\u1ebft ch\u1ebft vi\u00ean t\u01b0\u1edbng \u00e1p b\u1ee9c h\u1ecd,`,
  `ph\u00e1t \u0111\u1ed9ng binh bi\u1ebfn,`,
  `V\u00e0 li\u00ean t\u1ee5c gi\u00e0nh th\u1eafng l\u1ee3i nh\u01b0 ch\u1ebb tre.`,
  `Qu\u00e2n kh\u1edfi ngh\u0129a d\u1ea7n l\u1edbn m\u1ea1nh, chi\u1ebfm \u0111\u01b0\u1ee3c v\u00e0i huy\u1ec7n l\u00e2n c\u1eadn.`,
  `Ch\u01b0a \u0111\u1ea7y ba th\u00e1ng sau kh\u1edfi ngh\u0129a, nh\u1eefng ng\u01b0\u1eddi ch\u1ed1ng T\u1ea7n c\u0169ng nhao nhao n\u1ed5i d\u1eady,`,
  `T\u1ea1i Tri\u1ec7u, T\u1ec1, Y\u00ean, Ng\u1ee5y v\u00e0 c\u00e1c n\u01a1i kh\u00e1c \u0111\u1ec1u c\u00f3 ng\u01b0\u1eddi l\u1ea5y danh ngh\u0129a kh\u00f4i ph\u1ee5c s\u00e1u n\u01b0\u1edbc m\u00e0 t\u1ef1 x\u01b0ng v\u01b0\u01a1ng.`,
  `Sau \u0111\u00f3, qu\u00e2n c\u1ee7a Tr\u1ea7n Th\u1eafng t\u1ea5n c\u00f4ng v\u1ec1 ph\u00eda t\u00e2y,`,
  `Ti\u1ebfn s\u00e1t kinh \u0111\u00f4 H\u00e0m D\u01b0\u01a1ng c\u1ee7a n\u01b0\u1edbc T\u1ea7n.`,
  `H\u1ed3 H\u1ee3i li\u1ec1n ph\u00e1i qu\u00e2n tr\u1ea5n \u00e1p,`,
  `B\u1edfi v\u00ec ph\u1ea7n l\u1edbn qu\u00e2n kh\u1edfi ngh\u0129a l\u00e0 n\u00f4ng d\u00e2n,`,
  `C\u0169ng kh\u00f4ng ph\u1ea3i qu\u00e2n ch\u00ednh quy.`,
  `V\u00ec v\u1eady cu\u1ed1i c\u00f9ng, qu\u00e2n kh\u1edfi ngh\u0129a \u0111\u00e3 th\u1ea5t b\u1ea1i,`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng b\u1ecb gi\u1ebft.`,
  `M\u1eb7c d\u00f9 h\u1ecd th\u1ea5t b\u1ea1i, nh\u01b0ng cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n quy m\u00f4 l\u1edbn n\u00e0y \u0111\u00e3 l\u00e0m lung lay n\u1ec1n th\u1ed1ng tr\u1ecb c\u0103n b\u1ea3n c\u1ee7a nh\u00e0 T\u1ea7n,`,
  `T\u1ea1o \u0111i\u1ec1u ki\u1ec7n thu\u1eadn l\u1ee3i cho L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169 di\u1ec7t T\u1ea7n sau n\u00e0y.`,
  `L\u00fac n\u00e0y n\u00f3i v\u1ec1 tri\u1ec1u \u0111\u00ecnh nh\u00e0 T\u1ea7n,`,
  `Hai n\u0103m sau cu\u1ed9c kh\u1edfi ngh\u0129a \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng,`,
  `H\u1ed3 H\u1ee3i b\u1ecb Tri\u1ec7u Cao \u00e9p t\u1ef1 s\u00e1t.`,
  `Tri\u1ec7u Cao th\u1ef1c ra mu\u1ed1n t\u1ef1 m\u00ecnh x\u01b0ng \u0111\u1ebf, nh\u01b0ng b\u1ecb tri\u1ec1u th\u1ea7n k\u1ecbch li\u1ec7t ph\u1ea3n \u0111\u1ed1i.`,
  `Kh\u00f4ng c\u00f2n c\u00e1ch n\u00e0o, Tri\u1ec7u Cao b\u00e8n t\u00ecm con c\u1ee7a Ph\u00f9 T\u00f4 l\u00e0 T\u1eed Anh,`,
  `mu\u1ed1n \u0111\u01b0a h\u1eafn l\u00ean ng\u00f4i l\u00e0m b\u00f9 nh\u00ecn.`,
  `Nh\u01b0ng \u0111i\u1ec1u Tri\u1ec7u Cao kh\u00f4ng ng\u1edd l\u00e0,`,
  `T\u1eed Anh kh\u00f4ng h\u1ec1 ngu ng\u1ed1c.`,
  `V\u00e0o ng\u00e0y th\u1ee9 n\u0103m sau khi T\u1eed Anh \u0111\u0103ng c\u01a1,`,
  `\u00f4ng \u0111\u00e3 l\u1eadp k\u1ebf ho\u1ea1ch lo\u1ea1i b\u1ecf Tri\u1ec7u Cao.`,
  `\u0110\u00e1ng ti\u1ebfc, nh\u00e0 T\u1ea7n l\u00fac b\u1ea5y gi\u1edd \u0111\u00e3 lung lay s\u1eafp \u0111\u1ed5,`,
  `d\u00f9 T\u1eed Anh c\u00f3 t\u00e0i gi\u1ecfi \u0111\u1ebfn m\u1ea5y c\u0169ng kh\u00f4ng th\u1ec3 c\u1ee9u v\u00e3n \u0111\u01b0\u1ee3c n\u1eefa.`,
  `Kh\u1eafp n\u01a1i tr\u00ean \u0111\u1ea5t n\u01b0\u1edbc, c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a n\u1ed5i d\u1eady,`,
  `trong \u0111\u00f3 c\u00f3 L\u01b0u Bang \u1edf B\u00e1i huy\u1ec7n v\u00e0 H\u1ea1ng V\u0169, qu\u00fd t\u1ed9c c\u1ee7a n\u01b0\u1edbc S\u1edf c\u0169.`,
  `T\u1eed Anh t\u1ea1i v\u1ecb ch\u1ec9 v\u1ecfn v\u1eb9n 46 ng\u00e0y th\u00ec b\u1ecb L\u01b0u Bang, ng\u01b0\u1eddi \u0111\u00e3 t\u1ea5n c\u00f4ng H\u00e0m D\u01b0\u01a1ng, b\u1eaft gi\u1eef.`,
  `T\u1eed Anh \u0111\u1ea7u h\u00e0ng, nh\u00e0 T\u1ea7n di\u1ec7t vong.`,
  `Sau \u0111\u00f3, H\u1ea1ng V\u0169 c\u0169ng d\u1eabn qu\u00e2n t\u1ea5n c\u00f4ng H\u00e0m D\u01b0\u01a1ng,`,
  `T\u1eed Anh b\u1ecb H\u1ea1ng V\u0169 gi\u1ebft ch\u1ebft,`,
  `Cung \u0111i\u1ec7n nh\u00e0 T\u1ea7n c\u0169ng b\u1ecb H\u1ea1ng V\u0169 san b\u1eb1ng.`,
  `\u0110\u1ebfn \u0111\u00e2y, nh\u00e0 T\u1ea7n v\u0129nh vi\u1ec5n r\u00fat kh\u1ecfi v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed.`,
  `Sau khi nh\u00e0 T\u1ea7n s\u1ee5p \u0111\u1ed5 l\u00e0 cu\u1ed9c chi\u1ebfn S\u1edf H\u00e1n.`,
  `Tr\u01b0\u1edbc ti\u00ean h\u00e3y n\u00f3i v\u1ec1 hai nh\u00e2n v\u1eadt ch\u00ednh l\u00e0 L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169.`,
  `L\u01b0u Bang thu\u1ed9c tu\u00fdp ng\u01b0\u1eddi th\u00e0nh c\u00f4ng mu\u1ed9n,`,
  `Th\u1eddi nh\u00e0 T\u1ea7n, \u00f4ng ch\u1ec9 l\u00e0 m\u1ed9t th\u01b0\u1eddng d\u00e2n nh\u1ecf \u1edf huy\u1ec7n B\u00e1i,`,
  `L\u00e0m m\u1ed9t ch\u1ee9c quan nh\u1ecf, T\u1ef7 Th\u1ee7y \u0110\u00ecnh Tr\u01b0\u1edfng,`,
  `C\u00f4ng vi\u1ec7c l\u00e0 ch\u1ea1y vi\u1ec7c v\u1eb7t, \u00e1p gi\u1ea3i phu t\u00f9, v.v.`,
  `C\u00f3 l\u1ea7n, L\u01b0u Bang ph\u1ea3i \u00e1p gi\u1ea3i m\u1ed9t t\u1ed1p phu t\u00f9 \u0111\u1ebfn L\u1ec7 S\u01a1n \u0111\u1ec3 x\u00e2y l\u0103ng m\u1ed9 ho\u00e0ng gia,`,
  `M\u1edbi kh\u1edfi h\u00e0nh kh\u00f4ng l\u00e2u, m\u1ea5y ng\u01b0\u1eddi phu t\u00f9 \u0111\u00e3 nh\u00e2n l\u00fac \u00f4ng kh\u00f4ng ch\u00fa \u00fd m\u00e0 b\u1ecf tr\u1ed1n.`,
  `Vi\u1ec7c n\u00e0y c\u00f2n t\u1ec7 h\u01a1n, lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n th\u1eddi \u0111\u00f3 r\u1ea5t nghi\u00eam kh\u1eafc,`,
  `L\u01b0u Bang ch\u1eafc ch\u1eafn s\u1ebd b\u1ecb tr\u1ecb t\u1ed9i,`,
  `Th\u1ebf l\u00e0 \u00f4ng ta d\u1ee9t kho\u00e1t th\u1ea3 nh\u1eefng phu t\u00f9 c\u00f2n l\u1ea1i,`,
  `B\u1ea3n th\u00e2n c\u0169ng chu\u1ea9n b\u1ecb b\u1ecf tr\u1ed1n.`,
  `Nh\u1eefng lao \u0111\u1ed9ng n\u00e0y c\u0169ng kh\u00f4ng c\u00f3 n\u01a1i n\u00e0o kh\u00e1c \u0111\u1ec3 \u0111i,`,
  `\u0111\u00e0nh theo L\u01b0u Bang l\u00e0m gi\u1eb7c c\u01b0\u1edbp.`,
  `Sau khi Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng kh\u1edfi ngh\u0129a, n\u00f4ng d\u00e2n c\u00e1c n\u01a1i c\u1ee7a nh\u00e0 T\u1ea7n c\u0169ng n\u1ed5i d\u1eady h\u01b0\u1edfng \u1ee9ng,`,
  `gi\u01b0\u01a1ng cao ng\u1ecdn c\u1edd ph\u1ea3n T\u1ea7n.`,
  `\u0110\u1ed9i c\u1ee7a L\u01b0u Bang nh\u00e2n c\u01a1 h\u1ed9i n\u00e0y \u0111\u00e3 gi\u1ebft ch\u1ebft huy\u1ec7n l\u1ec7nh huy\u1ec7n B\u00e1i,`,
  `L\u01b0u Bang \u0111\u01b0\u1ee3c b\u1ea7u l\u00e0m huy\u1ec7n l\u1ec7nh m\u1edbi,`,
  `x\u01b0ng l\u00e0 B\u00e1i C\u00f4ng. C\u1ee9 nh\u01b0 v\u1eady, B\u00e1i C\u00f4ng L\u01b0u Bang b\u1eaft \u0111\u1ea7u b\u01b0\u1edbc l\u00ean v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed.`,
  `N\u0103m \u0111\u00f3, \u00f4ng \u0111\u00e3 48 tu\u1ed5i.`,
  `C\u00f2n v\u1ec1 ph\u00eda H\u1ea1ng V\u0169 th\u00ec t\u00ecnh h\u00ecnh ho\u00e0n to\u00e0n kh\u00e1c,`,
  `H\u1ea1ng V\u0169 l\u00e0 h\u1eadu du\u1ec7 c\u1ee7a \u0111\u1ea1i t\u01b0\u1edbng H\u1ea1ng Y\u00ean n\u01b0\u1edbc S\u1edf ng\u00e0y tr\u01b0\u1edbc,`,
  `\u0111\u01b0\u1ee3c coi l\u00e0 con ch\u00e1u danh gia v\u1ecdng t\u1ed9c.`,
  `Sau khi Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng kh\u1edfi ngh\u0129a,`,
  `m\u1ed9t ng\u01b0\u1eddi ch\u00fa c\u1ee7a H\u1ea1ng V\u0169 l\u00e0 H\u1ea1ng L\u01b0\u01a1ng c\u0169ng d\u1eabn H\u1ea1ng V\u0169, l\u00fac \u0111\u00f3 v\u1eabn c\u00f2n l\u00e0 m\u1ed9t thanh ni\u00ean, gia nh\u1eadp qu\u00e2n \u0111\u1ed9i ph\u1ea3n T\u1ea7n.`,
  `H\u1ea1ng V\u0169 gi\u1ebft ch\u1ebft qu\u1eadn tr\u01b0\u1edfng qu\u1eadn C\u1ed1i K\u00ea, H\u1ea1ng L\u01b0\u01a1ng nh\u1eadm ch\u1ee9c qu\u1eadn tr\u01b0\u1edfng m\u1edbi,`,
  `H\u1ea1ng V\u0169 l\u00e0m ph\u00f3 t\u01b0\u1edbng.`,
  `D\u00f9 sao th\u00ec nh\u00e0 h\u1ecd H\u1ea1ng t\u1eebng l\u00e0 m\u1ed9t d\u00f2ng d\u00f5i danh gi\u00e1 m\u00e0.`,
  `B\u1ea1n b\u00e8 th\u00ec nhi\u1ec1u, quan h\u1ec7 r\u1ed9ng r\u00e3i.`,
  `H\u1ea1ng L\u01b0\u01a1ng \u0111\u00e3 hi\u1ec7u tri\u1ec7u t\u1ea5t c\u1ea3 nh\u00e2n t\u00e0i t\u1eeb kh\u1eafp v\u00f9ng T\u00f4 Ch\u00e2u,`,
  `c\u00f9ng nhau ch\u1ed1ng T\u1ea7n, v\u00e0 l\u1eadp ch\u00e1u c\u1ee7a S\u1edf Ho\u00e0i V\u01b0\u01a1ng n\u0103m x\u01b0a, H\u00f9ng T\u00e2m l\u00e0m S\u1edf Ho\u00e0i V\u01b0\u01a1ng m\u1edbi.`,
  `L\u00fac n\u00e0y, L\u01b0u Bang c\u0169ng \u0111\u1ebfn \u0111\u1ea7u qu\u00e2n cho H\u1ea1ng L\u01b0\u01a1ng.`,
  `Sau \u0111\u00f3, L\u01b0u Bang theo H\u1ea1ng V\u0169, H\u1ea1ng L\u01b0\u01a1ng chinh chi\u1ebfn kh\u1eafp n\u01a1i,`,
  `giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ea7n.`,
  `Qu\u00e2n T\u1ea7n l\u00fac b\u1ea5y gi\u1edd v\u1eabn c\u00f2n kh\u00e1 m\u1ea1nh,`,
  `trong m\u1ed9t tr\u1eadn giao chi\u1ebfn,`,
  `H\u1ea1ng L\u01b0\u01a1ng b\u1ecb danh t\u01b0\u1edbng Tr\u01b0\u01a1ng H\u00e0n c\u1ee7a nh\u00e0 T\u1ea7n gi\u1ebft ch\u1ebft.`,
  `Khi H\u1ea1ng V\u0169 v\u00e0 L\u01b0u Bang\u8d76 \u0111\u1ebfn th\u00ec \u0111\u00e3 mu\u1ed9n r\u1ed3i.`,
  `L\u00fac n\u00e0y, S\u1edf Ho\u00e0i V\u01b0\u01a1ng tri\u1ec7u h\u1ed3i t\u1ea5t c\u1ea3 c\u00e1c \u0111\u1ea1i t\u01b0\u1edbng,`,
  `h\u1ee9a v\u1edbi h\u1ecd, ai c\u00f4ng ph\u00e1 \u0111\u01b0\u1ee3c kinh \u0111\u00f4 H\u00e0m D\u01b0\u01a1ng c\u1ee7a nh\u00e0 T\u1ea7n tr\u01b0\u1edbc,`,
  `ng\u01b0\u1eddi \u0111\u00f3 c\u00f3 th\u1ec3 x\u01b0ng v\u01b0\u01a1ng.`,
  `Tuy n\u00f3i l\u00e0 v\u1eady,`,
  `Tr\u01b0\u1edbc \u0111\u1ea1o qu\u00e2n T\u1ea7n nh\u01b0 h\u1ed5 \u0111\u00f3i, ai d\u00e1m ch\u1ed1ng l\u1ea1i?`,
  `R\u1ea5t c\u00f3 th\u1ec3 s\u1ebd u\u1ed5ng c\u00f4ng v\u00f4 \u00edch.`,
  `L\u00fac n\u00e0y, trong s\u1ed1 t\u1ea5t c\u1ea3 c\u00e1c t\u01b0\u1edbng l\u0129nh, ch\u1ec9 c\u00f3 L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169 s\u1eb5n s\u00e0ng giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ea7n.`,
  `H\u1ecd chia qu\u00e2n th\u00e0nh hai \u0111\u01b0\u1eddng, m\u1ed7i ng\u01b0\u1eddi \u0111i m\u1ed9t ng\u1ea3, ai c\u00f3 th\u1ec3 \u0111\u1ebfn H\u00e0m D\u01b0\u01a1ng tr\u01b0\u1edbc th\u00ec ph\u1ea3i xem \u00fd tr\u1eddi.`,
  `Tr\u00ean \u0111\u01b0\u1eddng \u0111i, c\u1ea3 hai b\u00ean \u0111\u1ec1u ch\u1ea1m tr\u00e1n qu\u00e2n T\u1ea7n.`,
  `Ph\u00eda L\u01b0u Bang th\u00ec thu\u1eadn l\u1ee3i h\u01a1n, m\u1ed9t m\u1ea1ch v\u01b0\u1ee3t qua m\u1ecdi c\u1eeda \u1ea3i.`,
  `Khi \u00f4ng ta \u0111\u1ebfn ngo\u1ea1i \u00f4 H\u00e0m D\u01b0\u01a1ng,`,
  `H\u1ea1ng V\u0169 v\u1eabn c\u00f2n \u0111ang giao tranh v\u1edbi qu\u00e2n c\u1ee7a Ch\u01b0\u01a1ng H\u00e0m.`,
  `\u0110\u00fang, ch\u00ednh l\u00e0 Ch\u01b0\u01a1ng H\u00e0m, k\u1ebb \u0111\u00e3 gi\u1ebft ch\u1ebft H\u1ea1ng L\u01b0\u01a1ng.`,
  `Cu\u1ed1i c\u00f9ng, H\u1ea1ng V\u0169 \u0111\u00e3 gi\u00e0nh chi\u1ebfn th\u1eafng,`,
  `nh\u01b0ng tr\u1eadn chi\u1ebfn n\u00e0y \u0111\u00e3 l\u00e3ng ph\u00ed r\u1ea5t nhi\u1ec1u th\u1eddi gian.`,
  `Khi H\u1ea1ng V\u0169 \u0111\u1ebfn b\u00ean ngo\u00e0i H\u00e0m D\u01b0\u01a1ng,`,
  `qu\u00e2n \u0111\u1ed9i c\u1ee7a L\u01b0u Bang \u0111\u00e3 ch\u1edd s\u1eb5n \u1edf \u0111\u00f3 r\u1ed3i.`,
  `H\u1ea1ng V\u0169 r\u1ea5t t\u1ee9c gi\u1eadn, h\u1eafn ngh\u0129: "Ta l\u00e0 ai ch\u1ee9?`,
  `Ng\u01b0\u01a1i ch\u1ec9 l\u00e0 m\u1ed9t k\u1ebb v\u00f4 danh ti\u1ec3u t\u1ed1t, v\u1eady m\u00e0 l\u1ea1i \u0111\u1ebfn tr\u01b0\u1edbc ta, ng\u01b0\u01a1i mu\u1ed1n x\u01b0ng v\u01b0\u01a1ng sao?`,
  `\u0110\u1ecbnh gi\u1eabm l\u00ean \u0111\u1ea7u t\u00f4i sao?`,
  `Th\u1ebf l\u00e0 theo l\u1eddi khuy\u00ean c\u1ee7a m\u01b0u s\u0129 Ph\u1ea1m T\u0103ng,`,
  `M\u1ed9t \u00e2m m\u01b0u \u0111\u00e3 ra \u0111\u1eddi, \u0111\u00f3 ch\u00ednh l\u00e0 b\u1eefa ti\u1ec7c \u1edf H\u1ed3ng M\u00f4n.`,
  `H\u1ea1ng V\u0169 chu\u1ea9n b\u1ecb m\u1edf ti\u1ec7c chi\u00eau \u0111\u00e3i L\u01b0u Bang t\u1ea1i H\u1ed3ng M\u00f4n,`,
  `Th\u1ef1c ch\u1ea5t l\u00e0 \u0111\u1ec3 lo\u1ea1i b\u1ecf L\u01b0u Bang, nh\u01b0ng kh\u00f4ng hi\u1ec3u sao tin t\u1ee9c n\u00e0y l\u1ea1i b\u1ecb l\u1ed9 ra,`,
  `B\u1ecb H\u1ea1ng B\u00e1 bi\u1ebft \u0111\u01b0\u1ee3c.`,
  `H\u1ea1ng B\u00e1 l\u00e0 m\u1ed9t ng\u01b0\u1eddi ch\u00fa kh\u00e1c c\u1ee7a H\u1ea1ng V\u0169,`,
  `\u0110\u00e3 l\u00e0 ng\u01b0\u1eddi nh\u00e0 bi\u1ebft th\u00ec ch\u1eafc c\u0169ng kh\u00f4ng c\u00f3 v\u1ea5n \u0111\u1ec1 l\u1edbn g\u00ec \u0111\u00e2u nh\u1ec9.`,
  `V\u1ea5n \u0111\u1ec1 l\u00e0 H\u1ea1ng B\u00e1 quen Tr\u01b0\u01a1ng L\u01b0\u01a1ng, m\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng n\u00e0y l\u00e0 ai?`,
  `Tr\u01b0\u01a1ng L\u01b0\u01a1ng l\u00e0 m\u1ed9t \u0111\u1ea1i t\u01b0\u1edbng trong qu\u00e2n c\u1ee7a L\u01b0u Bang.`,
  `M\u1ed1i quan h\u1ec7 gi\u1eefa H\u1ea1ng B\u00e1 v\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng kh\u00f4ng h\u1ec1 b\u00ecnh th\u01b0\u1eddng,`,
  `Tr\u01b0\u01a1ng L\u01b0\u01a1ng t\u1eebng c\u1ee9u m\u1ea1ng H\u1ea1ng B\u00e1.`,
  `Th\u1ef1c ra L\u01b0u Bang ch\u1ebft hay kh\u00f4ng kh\u00f4ng li\u00ean quan g\u00ec \u0111\u1ebfn H\u1ea1ng B\u00e1,`,
  `Nh\u01b0ng n\u1ebfu L\u01b0u Bang ch\u1ebft,`,
  `Li\u1ec7u c\u00f3 li\u00ean l\u1ee5y \u0111\u1ebfn \u00e2n nh\u00e2n c\u1ee9u m\u1ea1ng c\u1ee7a m\u00ecnh l\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng kh\u00f4ng?`,
  `Th\u1eadt kh\u00f3 n\u00f3i.`,
  `Th\u1ebf n\u00ean H\u1ea1ng B\u00e1 \u0111\u00e3 b\u00e1o tin n\u00e0y cho Tr\u01b0\u01a1ng L\u01b0\u01a1ng,`,
  `V\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng l\u1ea1i b\u00e1o cho L\u01b0u Bang.`,
  `M\u1ea1ng l\u01b0\u1edbi quan h\u1ec7 th\u1eadt k\u1ef3 di\u1ec7u.`,
  `L\u01b0u Bang b\u00ean n\u00e0y \u0111\u00e3 bi\u1ebft H\u1ea1ng V\u0169 mu\u1ed1n gi\u1ebft m\u00ecnh,`,
  `Kh\u00f4ng \u0111i ch\u1eb3ng ph\u1ea3i l\u00e0 \u0111\u01b0\u1ee3c r\u1ed3i sao?`,
  `Kh\u00f4ng \u0111\u01b0\u1ee3c, l\u00fac b\u1ea5y gi\u1edd qu\u00e2n H\u1ea1ng V\u0169 v\u1eabn m\u1ea1nh h\u01a1n qu\u00e2n L\u01b0u Bang r\u1ea5t nhi\u1ec1u,`,
  `N\u00ean kh\u00f4ng c\u00f3 c\u00e1ch n\u00e0o kh\u00e1c \u0111\u00e0nh ph\u1ea3i c\u1ee9ng \u0111\u1ea7u m\u00e0 \u0111i th\u00f4i.`,
  `C\u0169ng may L\u01b0u Bang \u0111\u00e3 l\u00e0 m\u1ed9t l\u00e3o l\u00e0ng r\u1ed3i,`,
  `V\u1eeba \u0111\u1ebfn ti\u1ec7c \u0111\u00e3 b\u1eaft \u0111\u1ea7u t\u00ecm c\u00e1ch l\u1ea5y l\u00f2ng H\u1ea1ng V\u0169,`,
  `Kh\u00fam n\u00fam, \u0111\u1ea1i v\u01b0\u01a1ng d\u00e0i \u0111\u1ea1i v\u01b0\u01a1ng ng\u1eafn, n\u00f3i r\u1eb1ng nh\u1eefng tin \u0111\u1ed3n m\u00ecnh mu\u1ed1n x\u01b0ng \u0111\u1ebf \u0111\u1ec1u l\u00e0 tin \u0111\u1ed3n nh\u1ea3m,`,
  `Ai \u0111\u00f3 mu\u1ed1n chia r\u1ebd ch\u00fang ta, ng\u00e0i \u0111\u1eebng tin nh\u1eefng l\u1eddi nh\u01b0 v\u1eady.`,
  `H\u1ea1ng V\u0169 tuy d\u0169ng m\u00e3nh, nh\u01b0ng t\u00e2m t\u01b0 t\u01b0\u01a1ng \u0111\u1ed1i \u0111\u01a1n gi\u1ea3n,`,
  `B\u1ecb chi\u00eau tr\u00f2 n\u00e0y c\u1ee7a L\u01b0u Bang l\u00e0m cho ng\u1edb ng\u01b0\u1eddi ra,`,
  `Ng\u01b0\u1ee3c l\u1ea1i c\u00f2n c\u1ea3m th\u1ea5y m\u00ecnh \u0111\u00e3 hi\u1ec3u l\u1ea7m L\u01b0u Bang.`,
  `V\u1ed1n d\u0129, K\u1ebf ho\u1ea1ch ban \u0111\u1ea7u l\u00e0 \u0111\u1ec3 H\u1ea1ng Trang gi\u1ebft L\u01b0u Bang khi m\u00faa ki\u1ebfm,`,
  `Nh\u01b0ng l\u00fac n\u00e0y H\u1ea1ng V\u0169 \u0111\u00e3 \u0111\u1ed9ng l\u00f2ng tr\u1eafc \u1ea9n,`,
  `Ph\u1ea1m T\u0103ng \u0111\u00e3 nhi\u1ec1u l\u1ea7n ra hi\u1ec7u th\u00fac gi\u1ee5c nh\u01b0ng \u00f4ng \u0111\u1ec1u l\u00e0m ng\u01a1.`,
  `L\u01b0u Bang vi\u1ec7n c\u1edb \u0111i v\u1ec7 sinh trong b\u1eefati\u1ec7c,`,
  `R\u1ed3i tr\u1ed1n v\u1ec1 \u0111\u1ea1i b\u1ea3n doanh c\u1ee7a m\u00ecnh.`,
  `Sau b\u1eefa ti\u1ec7c H\u1ed3ng K\u00f4ng, L\u01b0u Bang b\u1eaft \u0111\u1ea7u \u0111\u1ec1 ph\u00f2ng H\u1ea1ng V\u0169 kh\u1eafp m\u1ecdi n\u01a1i,`,
  `V\u1ed1n d\u0129 \u00f4ng l\u00e0 ng\u01b0\u1eddi \u0111\u1ea7u ti\u00ean \u0111\u1ebfn H\u00e0m D\u01b0\u01a1ng, l\u1ebd ra \u00f4ng ph\u1ea3i x\u01b0ng v\u01b0\u01a1ng,`,
  `Nh\u01b0ng \u0111\u1ed1i m\u1eb7t v\u1edbi H\u1ea1ng V\u0169 h\u00f9ng m\u1ea1nh, L\u01b0u Bang bi\u1ebft th\u1eddi c\u01a1 ch\u01b0a \u0111\u1ebfn,`,
  `V\u00ec v\u1eady, \u00f4ng \u0111\u00e3 \u0111\u1ec3 H\u1ea1ng V\u0169 d\u1eabn qu\u00e2n ti\u1ebfn v\u00e0o H\u00e0m D\u01b0\u01a1ng tr\u01b0\u1edbc.`,
  `Sau \u0111\u00f3, H\u1ea1ng V\u0169 gi\u1ebft T\u1eed Anh, \u0111\u1ed1t cung T\u1ea7n,`,
  `T\u1ef1 l\u1eadp l\u00e0m T\u00e2y S\u1edf B\u00e1 V\u01b0\u01a1ng, phong L\u01b0u Bang l\u00e0m H\u00e1n V\u01b0\u01a1ng.`,
  `Cu\u1ed9c chi\u1ebfn H\u00e1n S\u1edf ch\u00ednh th\u1ee9c b\u1eaft \u0111\u1ea7u t\u1eeb \u0111\u00e2y.`,
  `Sau khi H\u1ea1ng V\u0169 tr\u1edf th\u00e0nh T\u00e2y S\u1edf B\u00e1 V\u01b0\u01a1ng, \u00f4ng b\u1eaft \u0111\u1ea7u noi theo Chu Thi\u00ean t\u1eed ph\u00e2n phong ch\u01b0 h\u1ea7u,`,
  `Nh\u01b0ng H\u1ea1ng V\u0169 kh\u00f4ng theo l\u1ebd th\u01b0\u1eddng, vi\u1ec7c ph\u00e2n phong c\u1ee7a \u00f4ng kh\u00f4ng x\u00e9t c\u00f4ng lao,`,
  `M\u00e0 ho\u00e0n to\u00e0n d\u1ef1a v\u00e0o s\u1edf th\u00edch c\u1ee7a b\u1ea3n th\u00e2n,`,
  `Ng\u01b0\u1eddi c\u00f3 c\u00f4ng th\u00ec kh\u00f4ng \u0111\u01b0\u1ee3c phong, ng\u01b0\u1eddi kh\u00f4ng c\u00f4ng l\u1ea1i chi\u1ebfm kh\u00f4ng \u00edt l\u1ee3i l\u1ed9c.`,
  `\u00d4ng ta \u0111\u00e3 c\u1eed L\u01b0u Bang \u0111\u1ebfn v\u00f9ng H\u00e1n Trung Ba Th\u1ee5c xa x\u00f4i h\u1ebbo l\u00e1nh,`,
  `Chuy\u1ec7n n\u00e0y khi\u1ebfn m\u1ed9t s\u1ed1 t\u01b0\u1edbng l\u0129nh trong qu\u00e2n \u0111\u1ed9i th\u1ef1c s\u1ef1 kh\u00f4ng th\u1ec3 ch\u1ea5p nh\u1eadn \u0111\u01b0\u1ee3c,`,
  `H\u1ecd c\u1ea3m th\u1ea5y H\u1ea1ng V\u0169 kh\u00f4ng ph\u1ea3i l\u00e0 ng\u01b0\u1eddi \u0111\u00e1ng tin c\u1eady,`,
  `Ng\u01b0\u1ee3c l\u1ea1i, L\u01b0u Bang gi\u00e0 d\u1eb7n, v\u1eefng v\u00e0ng, l\u00e0 ng\u01b0\u1eddi c\u00f3 th\u1ec3 l\u00e0m n\u00ean vi\u1ec7c l\u1edbn.`,
  `V\u00ec v\u1eady, h\u1ecd \u0111\u00e3 \u00e2m th\u1ea7m b\u1ecf sang theo L\u01b0u Bang,`,
  `Trong s\u1ed1 \u0111\u00f3 c\u00f3 H\u00e0n T\u00edn,`,
  `H\u00e3y nh\u1edb k\u1ef9 ng\u01b0\u1eddi n\u00e0y.`,
  `Sau \u0111\u00f3, L\u01b0u Bang d\u1eabn qu\u00e2n \u0111\u1ed9i c\u1ee7a m\u00ecnh \u0111\u1ebfn nh\u1eadm ch\u1ee9c t\u1ea1i v\u00f9ng H\u00e1n Trung Ba Th\u1ee5c.`,
  `Ba Th\u1ee5c m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u bi\u1ebft m\u00e0,`,
  `Nam c\u1ee7a Th\u1ee5c l\u00e0 T\u1ee9 Xuy\u00ean v\u1edbi n\u00fai non tr\u00f9ng \u0111i\u1ec7p, \u0111\u01b0\u1eddng l\u00ean tr\u1eddi xanh.`,
  `N\u0103m x\u01b0a, n\u01b0\u1edbc T\u1ea7n \u0111\u1ec3 qu\u1ea3n l\u00fd \u0111\u1ea5t Th\u1ee5c, \u0111\u00e3 s\u1eeda ch\u1eefa \u0111\u01b0\u1eddng s\u1ea1n \u0111\u1ea1o,`,
  `\u0110\u00f3 l\u00e0 nh\u1eefng con \u0111\u01b0\u1eddng nh\u1ecf \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng d\u1ecdc theo v\u00e1ch n\u00fai,`,
  `v\u00e0 c\u00e1c \u0111\u00ecnh tr\u1ea1m,`,
  `\u0111\u1ec3 thu\u1eadn ti\u1ec7n cho m\u1ecdi ng\u01b0\u1eddi ra v\u00e0o \u0111\u1ea5t Th\u1ee5c.`,
  `\u0110\u1ec3 x\u00f3a tan nghi ng\u1edd c\u1ee7a H\u1ea1ng V\u0169, L\u01b0u Bang \u0111\u1ed1t ch\u00e1y \u0111\u01b0\u1eddng s\u1ea1n \u0111\u1ea1o sau khi \u0111\u1ebfn Ba Th\u1ee5c,`,
  `\u00e1m ch\u1ec9 r\u1eb1ng sau n\u00e0y \u00f4ng s\u1ebd an ph\u1eadn \u1edf H\u00e1n Trung v\u00e0 \u0111\u1ea5t Th\u1ee5c,`,
  `tuy\u1ec7t \u0111\u1ed1i s\u1ebd kh\u00f4ng \u0111e d\u1ecda H\u1ea1ng V\u0169 n\u1eefa.`,
  `L\u01b0u Bang c\u00f3 th\u1ef1c s\u1ef1 cam t\u00e2m an ph\u1eadn c\u1ea3 \u0111\u1eddi nh\u01b0 v\u1eady kh\u00f4ng?`,
  `\u0110\u00e2y ch\u1eb3ng qua ch\u1ec9 l\u00e0 m\u1ed9t th\u1ee7 \u0111o\u1ea1n che m\u1eaft.`,
  `Qu\u00e2n c\u1ee7a L\u01b0u Bang d\u01b0\u1ee1ng s\u1ee9c \u1edf \u0111\u1ea5t Th\u1ee5c, ch\u1edd \u0111\u1ee3i th\u1eddi c\u01a1,`,
  `nh\u01b0ng c\u00f3 m\u1ed9t v\u1ea5n \u0111\u1ec1,`,
  `\u0111\u01b0\u1eddng s\u1ea1n \u0111\u1ea1o \u0111\u1ec1u b\u1ecb \u0111\u1ed1t ch\u00e1y h\u1ebft, d\u00f9 binh l\u00ednh \u0111\u00e3 sung s\u1ee9c,`,
  `nh\u01b0ng l\u00e0m sao \u0111\u1ec3 ra ngo\u00e0i?`,
  `\u0110i\u1ec1u n\u00e0y l\u1ea1i ph\u1ea3i n\u00f3i v\u1ec1 H\u00e0n T\u00edn, ng\u01b0\u1eddi tr\u01b0\u1edbc \u0111\u00f3 \u0111\u00e3 \u0111\u1ea7u qu\u00e2n cho L\u01b0u Bang.`,
  `Sau khi H\u00e0n T\u00edn \u0111\u1ebfn qu\u00e2n c\u1ee7a L\u01b0u Bang, \u00f4ng \u0111\u01b0\u1ee3c phong l\u00e0m \u0110\u1ea1i T\u01b0\u1edbng qu\u00e2n,`,
  `nhi\u1ec7m v\u1ee5 t\u00ecm m\u1ed9t con \u0111\u01b0\u1eddng m\u1edbi sau khi \u0111\u1ed1t s\u1ea1n \u0111\u1ea1o r\u01a1i v\u00e0o tay \u00f4ng.`,
  `Qu\u1ea3 nhi\u00ean, \u00f4ng \u0111\u00e3 t\u00ecm th\u1ea5y m\u1ed9t con \u0111\u01b0\u1eddng c\u1ed5 Tr\u1ea7n Th\u01b0\u01a1ng d\u1eabn ra b\u00ean ngo\u00e0i.`,
  `V\u1eady th\u00ec l\u1ea1i c\u00f3 v\u1ea5n \u0111\u1ec1,`,
  `qu\u00e2n c\u1ee7a L\u01b0u Bang \u0111\u00e3 t\u00ecm \u0111\u01b0\u1ee3c m\u1ed9t con \u0111\u01b0\u1eddng c\u1ed5, ch\u1eb3ng l\u1ebd qu\u00e2n c\u1ee7a H\u1ea1ng V\u0169 l\u1ea1i kh\u00f4ng bi\u1ebft sao?`,
  `N\u1ebfu h\u1ecd bi\u1ebft \u0111\u01b0\u1eddng n\u00e0y, khi giao chi\u1ebfn,`,
  `H\u1ea1ng V\u0169 ph\u00e1i binh ch\u1eb7n C\u1ed5 \u0111\u1ea1o Tr\u1ea7n Th\u01b0\u01a1ng, ch\u1eb3ng ph\u1ea3i qu\u00e2n c\u1ee7a L\u01b0u Bang s\u1ebd tan t\u00e0nh sao?`,
  `\u0110i\u1ec3m n\u00e0y kh\u00f4ng ai n\u00f3i tr\u01b0\u1edbc \u0111\u01b0\u1ee3c.`,
  `V\u00ec v\u1eady, H\u00e0n T\u00edn \u0111\u00e3 ngh\u0129 ra m\u1ed9t k\u1ebf n\u1ed5i ti\u1ebfng kh\u00e1c,`,
  `C\u00f4ng khai s\u1eeda s\u1ea1n \u0111\u1ea1o, b\u00ed m\u1eadt v\u01b0\u1ee3t Tr\u1ea7n Th\u01b0\u01a1ng,`,
  `D\u00f9ng vi\u1ec7c s\u1eeda s\u1ea1n \u0111\u1ea1o l\u00e0m m\u00e0n kh\u00f3i, th\u1ef1c ch\u1ea5t b\u00ed m\u1eadt b\u1ed1 tr\u00ed qu\u00e2n \u1edf Tr\u1ea7n Th\u01b0\u01a1ng,`,
  `T\u1eebng ch\u00fat m\u1ed9t ti\u1ebfn v\u00e0o Quan Trung.`,
  `Tuy\u1ec7t chi\u00eau n\u00e0y \u0111\u00e3 \u0111\u00e1nh l\u1eeba \u0111\u01b0\u1ee3c \u0111\u1ea1i qu\u00e2n c\u1ee7a H\u1ea1ng V\u0169 v\u00e0o th\u1eddi \u0111i\u1ec3m \u0111\u00f3.`,
  `\u1ede v\u00f9ng \u0111\u1ea5t T\u1ee9 Xuy\u00ean n\u00e0y,`,
  `N\u00fai n\u1ed1i n\u00fai, vi\u1ec7c s\u1eeda s\u1ea1n \u0111\u1ea1o kh\u00f3 kh\u0103n \u0111\u1ebfn m\u1ee9c n\u00e0o?`,
  `Kh\u00f4ng s\u1eeda m\u1ea5y n\u0103m, c\u0103n b\u1ea3n kh\u00f4ng th\u1ec3 s\u1eeda xong s\u1ea1n \u0111\u1ea1o.`,
  `V\u00ec v\u1eady, H\u1ea1ng V\u0169 \u0111\u00e3 n\u1edbi l\u1ecfng c\u1ea3nh gi\u00e1c.`,
  `B\u00e2y gi\u1edd ch\u00fang ta h\u00e3y quay l\u1ea1i m\u1ed9t vi\u1ec7c,`,
  `Tr\u01b0\u1edbc \u0111\u00e2y H\u1ea1ng V\u0169 kh\u00f4ng ph\u1ea3i \u0111\u00e3 giao chi\u1ebfn v\u1edbi t\u01b0\u1edbng l\u0129nh T\u1ea7n Qu\u1ed1c l\u00e0 Tr\u01b0\u01a1ng H\u00e0m sao?`,
  `Sau khi H\u1ea1ng V\u0169 chi\u1ebfn th\u1eafng \u0111\u00e3 kh\u00f4ng gi\u1ebft Tr\u01b0\u01a1ng H\u00e0m \u0111\u1ea7u h\u00e0ng,`,
  `Thay v\u00e0o \u0111\u00f3, sau khi chi\u1ebfm \u0111\u01b0\u1ee3c thi\u00ean h\u1ea1, \u00f4ng ta giao Quan Trung cho m\u00ecnh v\u00e0 hai v\u1ecb t\u01b0\u1edbng kh\u00e1c c\u1ee7a nh\u00e0 T\u1ea7n qu\u1ea3n l\u00fd.`,
  `L\u00e0m v\u1eady l\u00e0 v\u00ec H\u1ea1ng V\u0169 l\u00e0 ng\u01b0\u1eddi ph\u01b0\u01a1ng Nam,`,
  `\u00d4ng ta kh\u00f4ng c\u00f3 h\u1ee9ng th\u00fa v\u1edbi Quan Trung,`,
  `D\u00f9 sao c\u0169ng \u0111\u00e3 n\u1eafm \u0111\u1ea1i quy\u1ec1n, chi b\u1eb1ng \u0111\u1ec3 Tr\u01b0\u01a1ng H\u00e0n v\u00e0 nh\u1eefng ng\u01b0\u1eddi quen thu\u1ed9c v\u1edbi t\u00ecnh h\u00ecnh \u0111\u1ecba ph\u01b0\u01a1ng h\u01a1n qu\u1ea3n l\u00fd.`,
  `Th\u00e1ng 8 n\u0103m 206 TCN,`,
  `H\u00e1n V\u01b0\u01a1ng L\u01b0u Bang xu\u1ea5t qu\u00e2n t\u1eeb Tr\u1ea7n Th\u01b0\u01a1ng \u0111\u00e1nh Tr\u01b0\u01a1ng H\u00e0n,`,
  `Cu\u1ed9c xu\u1ea5t qu\u00e2n l\u1ea7n n\u00e0y nh\u01b0 t\u1eeb tr\u00ean tr\u1eddi r\u01a1i xu\u1ed1ng, Tr\u01b0\u01a1ng H\u00e0n cho\u00e1ng v\u00e1ng,`,
  `Qu\u00e2n H\u00e1n ch\u1eb3ng ph\u1ea3i v\u1eabn \u0111ang s\u1eeda s\u1ea1n \u0111\u1ea1o sao?`,
  `Sao ch\u1ec9 sau m\u1ed9t \u0111\u00eam l\u1ea1i ch\u1ea1y ra t\u1eeb Ba Th\u1ee5c?`,
  `Tr\u01b0\u01a1ng H\u00e0n c\u00f2n ch\u01b0a k\u1ecbp ph\u1ea3n \u1ee9ng,`,
  `\u0110\u1ea1i c\u1ee5c \u0111\u00e3 \u0111\u1ecbnh. Sau \u0111\u00f3 qu\u00e2n H\u00e1n th\u1eeba th\u1eafng truy k\u00edch,`,
  `Ch\u1eb3ng bao l\u00e2u, L\u01b0u Bang \u0111\u00e3 chi\u1ebfm \u0111\u01b0\u1ee3c Quan Trung.`,
  `H\u1ea1ng V\u0169 b\u00ean n\u00e0y sau khi bi\u1ebft Quan Trung b\u1ecb chi\u1ebfm,`,
  `L\u1eadp t\u1ee9c t\u1eadp h\u1ee3p \u0111\u1ea1i qu\u00e2n,`,
  `Chu\u1ea9n b\u1ecb ti\u1ebfn v\u00e0o Quan Trung t\u1ea5n c\u00f4ng L\u01b0u Bang,`,
  `Nh\u01b0ng ngay l\u00fac n\u00e0y, m\u1ed9t qu\u1ea3 bom h\u1eb9n gi\u1edd b\u00ean c\u1ea1nh \u00f4ng ta \u0111\u00e3 ph\u00e1t n\u1ed5.`,
  `Khi anh h\u00f9ng Thi\u00ean T\u01b0\u1ee3ng gi\u01b0\u01a1ng cao ng\u1ecdn c\u1edd ch\u1ed1ng T\u1ea7n,`,
  `\u0110i\u1ec1n Vinh, T\u1ec3 t\u01b0\u1edbng n\u01b0\u1edbc T\u1ec1, c\u0169ng \u0111i \u0111\u1ea7u,`,
  `gi\u00e0nh l\u1ea1i \u0111\u1ea5t \u0111ai c\u0169 c\u1ee7a n\u01b0\u1edbc T\u1ec1, c\u00f9ng H\u1ea1ng V\u0169 ti\u1ebfn v\u00e0o Quan Trung.`,
  `Nh\u01b0ng sau \u0111\u00f3 H\u1ea1ng V\u0169 phong th\u01b0\u1edfng kh\u00f4ng c\u00f4ng b\u1eb1ng,`,
  `\u0110i\u1ec1n Vinh l\u00e0 m\u1ed9t trong nh\u1eefng n\u1ea1n nh\u00e2n l\u00fac \u0111\u00f3,`,
  `\u00f4ng ta kh\u00f4ng \u0111\u01b0\u1ee3c phong g\u00ec c\u1ea3.`,
  `V\u00ec v\u1eady, \u0110i\u1ec1n Vinh \u0111\u00e3 \u00f4m h\u1eadn t\u1eeb l\u00e2u, nh\u00e2n c\u01a1 h\u1ed9i L\u01b0u Bang \u0111\u00e1nh v\u1ec1 Quan Trung,`,
  `nh\u1ea3y ra ph\u1ea3n c\u00f4ng H\u1ea1ng V\u0169.`,
  `L\u00fac n\u00e0y H\u1ea1ng V\u0169 b\u1ecb t\u1ea5n c\u00f4ng c\u1ea3 hai m\u1eb7t, d\u00f9 \u00f4ng ta \u0111\u00e1nh ai tr\u01b0\u1edbc,`,
  `ng\u01b0\u1eddi kia c\u0169ng s\u1ebd \u0111\u00e2m sau l\u01b0ng \u00f4ng ta.`,
  `Cu\u1ed1i c\u00f9ng, H\u1ea1ng V\u0169 ch\u1ecdn \u0111i d\u1eb9p \u0110i\u1ec1n Vinh tr\u01b0\u1edbc,`,
  `L\u01b0u Bang l\u00e0m sao c\u00f3 th\u1ec3 b\u1ecf qua m\u1ed9t c\u01a1 h\u1ed9i ng\u00e0n n\u0103m c\u00f3 m\u1ed9t nh\u01b0 v\u1eady.`,
  `Khi H\u1ea1ng V\u0169 v\u00e0 \u0110i\u1ec1n Vinh \u0111ang \u0111\u00e1nh nhau, \u00f4ng ta \u0111\u00e3 li\u00ean k\u1ebft v\u1edbi c\u00e1c ch\u01b0 h\u1ea7u kh\u00e1c kh\u00f4ng \u01b0a H\u1ea1ng V\u0169 c\u00f9ng ti\u1ebfn \u0111\u00e1nh B\u00e0nh Th\u00e0nh, kinh \u0111\u00f4 n\u01b0\u1edbc S\u1edf c\u1ee7a H\u1ea1ng V\u0169.`,
  `H\u1ecd \u0111\u00e3 l\u00e0m \u0111\u01b0\u1ee3c,`,
  `\u0111\u00e3 \u0111\u00e1nh chi\u1ebfm B\u00e0nh Th\u00e0nh, nh\u01b0ng B\u00e0nh Th\u00e0nh t\u1ed1t, c\u00f3 nhi\u1ec1u \u0111\u1ed3 \u0103n,`,
  `nhi\u1ec1u m\u1ef9 n\u1eef, so v\u1edbi \u0111\u1ea5t Th\u1ee5c kh\u00f4ng c\u00f3 g\u00ec,`,
  `n\u01a1i \u0111\u00e2y qu\u1ea3 l\u00e0 thi\u00ean \u0111\u01b0\u1eddng.`,
  `Qu\u00e2n c\u1ee7a L\u01b0u Bang sau khi \u0111\u1ebfn \u0111\u00e2y th\u00ec v\u00f4 c\u00f9ng vui s\u01b0\u1edbng,`,
  `qu\u00e2n H\u00e1n nh\u1ea5t th\u1eddi l\u01a1i l\u1ecfng c\u1ea3nh gi\u00e1c, b\u1eaft \u0111\u1ea7u ngh\u0129 ng\u1ee3i,`,
  `H\u1ea1ng V\u0169 c\u0169ng kh\u00f4ng ph\u1ea3i t\u1ea7m th\u01b0\u1eddng.`,
  `Khi \u00f4ng ta nghe tin n\u00e0y, li\u1ec1n l\u1eadp t\u1ee9c d\u1eabn qu\u00e2n c\u00f4ng k\u00edch tr\u1edf l\u1ea1i.`,
  `Qu\u00e2n c\u1ee7a H\u1ea1ng V\u0169 \u0111\u00e3 \u0111\u00e1nh tan t\u00e1c qu\u00e2n H\u00e1n \u0111ang r\u00e3 r\u1eddi,`,
  `L\u01b0u Bang ho\u1ea3ng lo\u1ea1n b\u1ecf ch\u1ea1y,`,
  `H\u1ea1ng V\u0169 thu ph\u1ee5c B\u00e0nh Th\u00e0nh, nh\u01b0ng \u00f4ng ta \u0111\u00e3 ph\u1ea1m m\u1ed9t sai l\u1ea7m ch\u1ebft ng\u01b0\u1eddi,`,
  `c\u00f3 l\u1ebd v\u00ec H\u1ea1ng V\u0169 qu\u00e1 t\u1ef1 ph\u1ee5, cho r\u1eb1ng L\u01b0u Bang d\u1ec5 b\u1ecb \u0111\u00e1nh b\u1ea1i,`,
  `n\u00ean \u0111\u00e3 kh\u00f4ng ti\u1ebfp t\u1ee5c truy s\u00e1t \u00f4ng ta.`,
  `V\u00e0 L\u01b0u Bang sau khi ch\u1ea1y v\u1ec1 Quan Trung, sau m\u1ed9t th\u1eddi gian ch\u1ec9nh \u0111\u1ed1n,`,
  `l\u1ea1i h\u1ed3i ph\u1ee5c s\u1ee9c l\u1ef1c.`,
  `Nh\u1eefng n\u0103m sau \u0111\u00f3, l\u1ea1i c\u00f9ng H\u1ea1ng V\u0169 qua l\u1ea1i \u0111\u00e1nh nhau v\u00f4 s\u1ed1 l\u1ea7n,`,
  `C\u1ee9 th\u1ebf n\u00e0y c\u0169ng kh\u00f4ng ph\u1ea3i l\u00e0 c\u00e1ch hay.`,
  `Hai b\u00ean \u0111\u00e3 ti\u1ebfn h\u00e0nh m\u1ed9t cu\u1ed9c \u0111\u00e0m ph\u00e1n v\u00e0o n\u0103m 203 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `Th\u1ed1ng nh\u1ea5t l\u1ea5y H\u1ed3ng C\u00e2u l\u00e0m ranh gi\u1edbi,`,
  `Ph\u00eda T\u00e2y thu\u1ed9c v\u1ec1 L\u01b0u Bang,`,
  `Ph\u00eda \u0110\u00f4ng thu\u1ed9c v\u1ec1 H\u1ea1ng V\u0169,`,
  `T\u1eeb \u0111\u00f3 v\u1ec1 sau s\u1ebd kh\u00f4ng x\u00e2m ph\u1ea1m l\u1eabn nhau.`,
  `\u0110\u00e2y ch\u00ednh l\u00e0 S\u1edf H\u00e0 H\u00e1n Gi\u1edbi.`,
  `H\u1ea1ng V\u0169 l\u00e0 ng\u01b0\u1eddi gi\u1eef ch\u1eef t\u00edn,`,
  `Sau khi th\u1ecfa thu\u1eadn, \u00f4ng \u0111\u00e3 th\u1ea3 L\u1eef Tr\u0129, v\u1ee3 c\u1ee7a L\u01b0u Bang v\u00e0 cha L\u01b0u Bang, nh\u1eefng con tin m\u00e0 \u00f4ng \u0111\u00e3 b\u1eaft tr\u01b0\u1edbc \u0111\u00f3,`,
  `V\u00e0 ra l\u1ec7nh cho qu\u00e2n S\u1edf r\u00fat lui.`,
  `V\u00ec v\u1eady n\u00f3i H\u1ea1ng V\u0169 ng\u00e2y th\u01a1 m\u00e0, \u00f4ng ta c\u0103n b\u1ea3n kh\u00f4ng ngh\u0129 t\u1edbi qu\u00e2n S\u1edf c\u00f2n ch\u01b0a \u0111i xa,`,
  `L\u01b0u Bang \u0111\u00e3 \u0111\u01a1n ph\u01b0\u01a1ng x\u00e9 b\u1ecf hi\u1ec7p \u01b0\u1edbc H\u1ed3ng C\u00e2u v\u1edbi H\u1ea1ng V\u0169,`,
  `D\u1eabn qu\u00e2n truy k\u00edch \u0111\u1ea1i qu\u00e2n H\u1ea1ng V\u0169,`,
  `Th\u1ebf l\u00e0 l\u1ea1i b\u1eaft \u0111\u1ea7u ch\u1ebf \u0111\u1ed9 \u0111\u00e1nh gi\u1ebft \u1ea7m \u0129.`,
  `L\u1ea7n n\u00e0y qu\u00e2n S\u1edf kh\u00f4ng may m\u1eafn nh\u01b0 v\u1eady n\u1eefa,`,
  `Sau nh\u1eefng th\u1ea5t b\u1ea1i li\u00ean ti\u1ebfp,`,
  `qu\u00e2n S\u1edf b\u1ecb d\u1ed3n \u0111\u1ebfn Cai H\u1ea1.`,
  `L\u00fac n\u00e0y, qu\u00e2n S\u1edf \u0111\u00e3 c\u1ea1n l\u01b0\u01a1ng th\u1ea3o, \u0111\u1ea1i b\u1ea3n doanh ph\u00eda sau c\u0169ng \u0111\u00e3 th\u1ea5t th\u1ee7,`,
  `nh\u1eefng \u0111\u00f2n gi\u00e1ng k\u00e9p c\u1ea3 v\u1ec1 th\u1ec3 x\u00e1c l\u1eabn tinh th\u1ea7n khi\u1ebfn qu\u00e2n S\u1edf v\u00f4 c\u00f9ng m\u1ec7t m\u1ecfi.`,
  `V\u00e0o ban \u0111\u00eam,`,
  `qu\u00e2n H\u00e1n c\u1ee7a L\u01b0u Bang l\u1ea1i c\u1ea5t ti\u1ebfng h\u00e1t nh\u1eefng b\u00e0i ca dao c\u1ee7a \u0111\u1ea5t S\u1edf xung quanh Cai H\u1ea1,`,
  `qu\u00e2n S\u1edf nghe th\u1ea5y ti\u1ebfng h\u00e1t, n\u1ed7i nh\u1edb qu\u00ea h\u01b0\u01a1ng tr\u00e0o d\u00e2ng trong l\u00f2ng,`,
  `h\u1ecd ch\u1ec9 mu\u1ed1n nhanh ch\u00f3ng k\u1ebft th\u00fac cu\u1ed9c chi\u1ebfn v\u00e0 tr\u1edf v\u1ec1 nh\u00e0.`,
  `Tuy\u1ec7t chi\u00eau n\u00e0y ph\u1ea3i n\u00f3i l\u00e0 cao tay,`,
  `th\u1ef1c s\u1ef1 cao tay, kh\u00f4ng ch\u1ec9 \u0111\u00e1nh tan ph\u00f2ng tuy\u1ebfn t\u00e2m l\u00fd c\u1ee7a qu\u00e2n S\u1edf,`,
  `m\u00e0 c\u00f2n khi\u1ebfn H\u1ea1ng V\u0169 tin r\u1eb1ng qu\u00e2n H\u00e1n \u0111\u00e3 ho\u00e0n to\u00e0n chi\u1ebfm \u0111\u01b0\u1ee3c \u0111\u1ea5t S\u1edf,`,
  `b\u1ea3n th\u00e2n m\u00ecnh \u0111\u00e3 kh\u00f4ng c\u00f2n hy v\u1ecdng chi\u1ebfn th\u1eafng.`,
  `H\u01a1n n\u1eefa, \u0111\u1ed1i m\u1eb7t v\u1edbi nh\u1eefng huynh \u0111\u1ec7 n\u01b0\u1edbc S\u1edf \u0111\u00e3 theo m\u00ecnh bao n\u0103m,`,
  `H\u1ea1ng V\u0169 l\u1ea1i c\u1ea3m th\u1ea5y m\u00ecnh kh\u00f4ng th\u1ec3 gi\u1ea3i th\u00edch \u0111\u01b0\u1ee3c.`,
  `Cu\u1ed1i c\u00f9ng, H\u1ea1ng V\u0169 ch\u1ea1y \u0111\u1ebfn b\u1edd \u00d4 Giang, k\u1ebft th\u00fac cu\u1ed9c \u0111\u1eddi m\u00ecnh b\u1eb1ng c\u00e1ch t\u1ef1 v\u1eabn.`,
  `N\u0103m 202 TCN,`,
  `L\u01b0u Bang l\u00ean ng\u00f4i, ch\u00ednh th\u1ee9c m\u1edf ra tri\u1ec1u \u0111\u1ea1i nh\u00e0 H\u00e1n.`,
  `L\u01b0u Bang x\u01b0ng \u0111\u1ebf, s\u1eed g\u1ecdi l\u00e0 T\u00e2y H\u00e1n,`,
  `sau n\u00e0y c\u00f2n c\u00f3 \u0110\u00f4ng H\u00e1n, \u0111i\u1ec1u n\u00e0y s\u1ebd \u0111\u01b0\u1ee3c n\u00f3i \u0111\u1ebfn sau.`,
  `C\u0169ng nh\u01b0 c\u00e1c tri\u1ec1u \u0111\u1ea1i kh\u00e1c, sau khi L\u01b0u Bang l\u00ean ng\u00f4i,`,
  `\u00f4ng \u0111\u00e3 phong th\u01b0\u1edfng cho c\u00e1c c\u00f4ng th\u1ea7n d\u01b0\u1edbi tr\u01b0\u1edbng,`,
  `v\u00e0 ch\u1ecdn c\u1ed1 \u0111\u00f4 c\u1ee7a T\u1ea7n tri\u1ec1u c\u0169,`,
  `nay l\u00e0 T\u00e2y An \u0111\u1ec3 x\u00e2y d\u1ef1ng kinh \u0111\u00f4.`,
  `Th\u00e0nh ph\u1ed1 m\u1edbi n\u00e0y l\u00e0 Tr\u01b0\u1eddng An,`,
  `sau khi \u0111\u1ecbnh \u0111\u00f4 \u1edf Tr\u01b0\u1eddng An, khi L\u01b0u Bang chu\u1ea9n b\u1ecb cai tr\u1ecb t\u1ed1t tri\u1ec1u \u0111\u1ea1i \u0110\u1ea1i H\u00e1n c\u1ee7a m\u00ecnh,`,
  `th\u00ec l\u00e1ng gi\u1ec1ng ph\u00eda b\u1eafc l\u00e0 Hung N\u00f4 l\u1ea1i ra g\u00e2y s\u1ef1,`,
  `chi\u1ebfm \u0111\u00f3ng v\u00e0i th\u00e0nh tr\u00ec \u1edf bi\u00ean gi\u1edbi \u0110\u1ea1i H\u00e1n.`,
  `Hung N\u00f4 l\u00e0 k\u1ebb th\u00f9 c\u0169 c\u1ee7a v\u00f9ng Trung Nguy\u00ean,`,
  `lu\u00f4n l\u00e0 m\u1ed1i \u0111e d\u1ecda l\u1edbn.`,
  `L\u01b0u Bang ngh\u0129: "Ta \u0111\u00e3 \u0111\u00e1nh b\u1ea1i T\u00e2y S\u1edf B\u00e1 v\u01b0\u01a1ng H\u1ea1ng V\u0169,`,
  `T\u00f4i c\u00f2n ph\u1ea3i s\u1ee3 c\u00e1c ng\u01b0\u1eddi \u00e0?`,
  `Th\u1ebf n\u00ean L\u01b0u Bang quy\u1ebft \u0111\u1ecbnh \u0111\u00edch th\u00e2n xu\u1ea5t chinh.`,
  `\u0110\u1ea1i qu\u00e2n c\u1ee7a \u00f4ng ta ti\u1ebfn \u0111\u1ebfn bi\u00ean \u1ea3i, giao chi\u1ebfn v\u1edbi qu\u00e2n Hung N\u00f4.`,
  `V\u1ed1n d\u0129 L\u01b0u Bang gi\u00e0nh thi\u00ean h\u1ea1 b\u1eb1ng v\u0169 l\u1ef1c,`,
  `H\u00e1n qu\u00e2n c\u1ee7a \u00f4ng ta kh\u00f4ng ph\u1ea3i d\u1ea1ng v\u1eeba, nhanh ch\u00f3ng gi\u00e0nh l\u1ea1i c\u00e1c th\u00e0nh tr\u00ec bi\u00ean c\u01b0\u01a1ng,`,
  `v\u00e0 truy \u0111u\u1ed5i qu\u00e2n Hung N\u00f4 \u0111ang b\u1ecf ch\u1ea1y.`,
  `N\u1ebfu cu\u1ed9c chi\u1ebfn c\u1ee9 thu\u1eadn l\u1ee3i nh\u01b0 v\u1eady,`,
  `th\u00ec \u0111\u00e3 kh\u00f4ng c\u00f3 c\u00e2u chuy\u1ec7n v\u1ec1 sau.`,
  `H\u00e1n qu\u00e2n truy \u0111u\u1ed5i qu\u00e2n Hung N\u00f4 \u0111\u1ebfn B\u00ecnh Th\u00e0nh,`,
  `th\u00ec b\u1ecb m\u1ed9t \u0111\u1ea1o qu\u00e2n Hung N\u00f4 d\u1ee5 v\u00e0o n\u00fai B\u1ea1ch \u0110\u0103ng.`,
  `Sau khi ti\u1ebfn v\u00e0o con \u0111\u01b0\u1eddng n\u00fai ch\u1eadt h\u1eb9p, \u01b0u th\u1ebf t\u00e1c chi\u1ebfn c\u1ee7a H\u00e1n qu\u00e2n ho\u00e0n to\u00e0n kh\u00f4ng th\u1ec3 ph\u00e1t huy,`,
  `l\u1ea1i th\u00eam \u0111\u1ecba h\u00ecnh xa l\u1ea1, qu\u00e2n Hung N\u00f4 ph\u1ea7n l\u1edbn l\u00e0 k\u1ef5 binh,`,
  `sau khi v\u00e0o n\u00fai ch\u1ec9 ch\u1edbp m\u1eaft \u0111\u00e3 bi\u1ebfn m\u1ea5t.`,
  `L\u00fac n\u00e0y, M\u1eb7c \u0110\u1ed1n Thi\u1ec1n Vu c\u1ee7a Hung N\u00f4 quy\u1ebft \u0111\u1ecbnh t\u00f3m g\u1ecdn qu\u00e2n L\u01b0u Bang trong m\u1ed9t m\u1ebb l\u01b0\u1edbi,`,
  `c\u00f3 l\u1ebd l\u00e0 \u00fd tr\u1eddi.`,
  `\u0110\u00fang v\u00e0o th\u1eddi kh\u1eafc nguy hi\u1ec3m n\u00e0y, tr\u00ean tr\u1eddi \u0111\u1ed9t nhi\u00ean s\u01b0\u01a1ng m\u00f9 d\u00e0y \u0111\u1eb7c,`,
  `l\u00e0m \u0111\u1ea3o l\u1ed9n k\u1ebf ho\u1ea1ch c\u1ee7a M\u1eb7c \u0110\u1ed9c.`,
  `Qu\u00e2n L\u01b0u Bang nh\u00e2n l\u00fac s\u01b0\u01a1ng m\u00f9 d\u00e0y \u0111\u1eb7c \u0111\u00e3 ph\u00e1 v\u00e2y,`,
  `tho\u00e1t ch\u1ebft trong gang t\u1ea5c. Sau \u0111\u00f3 hai b\u00ean r\u00fat qu\u00e2n,`,
  `\u0111\u00e2y ch\u00ednh l\u00e0 s\u1ef1 ki\u1ec7n Bao V\u00e2y B\u1ea1ch \u0110\u0103ng n\u1ed5i ti\u1ebfng trong l\u1ecbch s\u1eed.`,
  `Sau s\u1ef1 ki\u1ec7n Bao V\u00e2y B\u1ea1ch \u0110\u0103ng, L\u01b0u Bang nh\u1eadn ra qu\u00e2n \u0111\u1ed9i c\u1ee7a m\u00ecnh ch\u01b0a \u0111\u1ee7 m\u1ea1nh,`,
  `qu\u1ed1c gia c\u0169ng ch\u01b0a \u0111\u1ee7 th\u1ecbnh v\u01b0\u1ee3ng,`,
  `n\u00ean nh\u1eefng ng\u01b0\u1eddi Hung N\u00f4 n\u00e0y m\u1edbi d\u00e1m th\u1ec9nh tho\u1ea3ng \u0111\u1ebfn th\u00e1ch th\u1ee9c.`,
  `Sau khi v\u1ec1 nh\u00e0, L\u01b0u Bang \u0111\u00e3 v\u1ea1ch ra m\u1ed9t lo\u1ea1t c\u00e1c bi\u1ec7n ph\u00e1p \u0111\u1ec3 ngh\u1ec9 ng\u01a1i, ph\u1ee5c h\u1ed3i,`,
  `th\u00fac \u0111\u1ea9y n\u0103ng su\u1ea5t,`,
  `\u0111\u1ed3ng th\u1eddi d\u00f9ng ph\u01b0\u01a1ng th\u1ee9c h\u00f2a th\u00e2n v\u1edbi Hung N\u00f4 \u0111\u1ec3 t\u1ea1m th\u1eddi xoa d\u1ecbu m\u00e2u thu\u1eabn,`,
  `nh\u1eb1m t\u00ecm ki\u1ebfm m\u1ed9t m\u00f4i tr\u01b0\u1eddng b\u00ean ngo\u00e0i \u1ed5n \u0111\u1ecbnh.`,
  `C\u00e1c m\u1ed1i \u0111e d\u1ecda b\u00ean ngo\u00e0i \u0111\u00e3 \u0111\u01b0\u1ee3c gi\u1ea3i quy\u1ebft, nh\u01b0ng v\u1ea5n \u0111\u1ec1 n\u1ed9i b\u1ed9 l\u1ea1i n\u1ea3y sinh.`,
  `V\u00e0o \u0111\u1ea7u th\u1eddi H\u00e1n, sau khi L\u01b0u Bang ph\u00e2n phong,`,
  `c\u00f3 v\u00e0i ch\u01b0 h\u1ea7u kh\u00f4ng ph\u1ee5c \u0111\u00e3 n\u1ed5i d\u1eady ch\u1ed1ng \u0111\u1ed1i,`,
  `M\u1eb7c d\u00f9 cu\u1ed1i c\u00f9ng b\u1ecb L\u01b0u Bang tr\u1ea5n \u00e1p, nh\u01b0ng qua nh\u1eefng vi\u1ec7c n\u00e0y,`,
  `L\u01b0u Bang n\u1ea3y sinh t\u00e2m b\u1ec7nh.`,
  `Nh\u1eefng ch\u01b0 h\u1ea7u kh\u00f4ng c\u00f3 b\u1ea3n l\u0129nh g\u00ec \u0111\u00e1ng k\u1ec3 n\u00e0y \u0111\u1ec1u n\u1ed5i d\u1eady m\u01b0u ph\u1ea3n.`,
  `V\u1eady c\u00f4ng th\u1ea7n l\u1edbn H\u00e0n T\u00edn, ng\u01b0\u1eddi t\u1eebng gi\u00fap m\u00ecnh gi\u00e0nh thi\u00ean h\u1ea1,`,
  `li\u1ec7u c\u00f3 \u00fd ngh\u0129 t\u01b0\u01a1ng t\u1ef1 kh\u00f4ng?`,
  `H\u00e0n T\u00edn kh\u00e1c v\u1edbi nh\u1eefng k\u1ebb ti\u1ec3u t\u1ed1t n\u00e0y,`,
  `\u00f4ng l\u00e0 \u0111\u1ea1i l\u00e3o s\u1ed1 m\u1ed9t trong qu\u00e2n \u0111\u1ed9i, c\u00f3 uy t\u00edn tuy\u1ec7t \u0111\u1ed1i.`,
  `Ngo\u00e0i L\u01b0u Bang ra, th\u1ef1c ra c\u00f2n c\u00f3 m\u1ed9t ng\u01b0\u1eddi kh\u00e1c c\u0169ng r\u1ea5t ki\u00eang k\u1ef5 H\u00e0n T\u00edn,`,
  `\u0111\u00f3 ch\u00ednh l\u00e0 L\u1eef Tr\u0129, v\u1ee3 c\u1ee7a L\u01b0u Bang.`,
  `V\u00ec l\u00fac \u0111\u00f3 L\u01b0u Bang \u0111\u00e3 s\u00e1u m\u01b0\u01a1i tu\u1ed5i,`,
  `m\u00e0 H\u00e0n T\u00edn m\u1edbi ba m\u01b0\u01a1i t\u01b0 tu\u1ed5i.`,
  `N\u1ebfu m\u1ed9t ng\u00e0y L\u01b0u Bang qua \u0111\u1eddi,`,
  `sau khi con trai L\u1eef Tr\u0129 l\u00e0 L\u01b0u Doanh l\u00ean ng\u00f4i,`,
  `li\u1ec7u c\u00f3 b\u1ecb H\u00e0n T\u00edn uy hi\u1ebfp kh\u00f4ng?`,
  `L\u1eef Tr\u0129 l\u00e0 m\u1ed9t ng\u01b0\u1eddi t\u00e0n nh\u1eabn, \u0111\u1ec3 gi\u00fap con trai b\u1edbt \u0111i ch\u01b0\u1edbng ng\u1ea1i,`,
  `\u00d4ng ta l\u1eeba H\u00e0n T\u00edn v\u00e0o cung r\u1ed3i gi\u1ebft ch\u1ebft.`,
  `Sau \u0111\u00f3 L\u01b0u Bang c\u0169ng lo s\u1ee3 quy\u1ec1n l\u1ef1c c\u1ee7a m\u00ecnh kh\u00f4ng v\u1eefng ch\u1eafc,`,
  `b\u1eaft \u0111\u1ea7u \u0111\u00e0n \u00e1p c\u00e1c ch\u01b0 h\u1ea7u d\u1ecb h\u1ecd kh\u00e1c.`,
  `N\u0103m 195 TCN,`,
  `sau khi L\u01b0u Bang ti\u00eau di\u1ec7t v\u1ecb v\u01b0\u01a1ng d\u1ecb h\u1ecd ph\u1ea3n lo\u1ea1n cu\u1ed1i c\u00f9ng,`,
  `\u00f4ng l\u00e2m b\u1ec7nh n\u1eb7ng. Gi\u1eefa th\u00e1ng T\u01b0,`,
  `H\u00e1n Cao T\u1ed5 L\u01b0u Bang qua \u0111\u1eddi t\u1ea1i Tr\u01b0\u1eddng L\u1ea1c Cung,`,
  `Th\u00e1i t\u1eed, t\u1ee9c H\u00e1n Hu\u1ec7 \u0110\u1ebf L\u01b0u Doanh sau n\u00e0y, l\u00ean ng\u00f4i.`,
  `L\u01b0u Doanh kh\u00e1c h\u1eb3n cha m\u00ecnh,`,
  `t\u00ednh t\u00ecnh qu\u00e1 nh\u00e2n h\u1eadu, l\u1ea1i r\u1ea5t nhu nh\u01b0\u1ee3c v\u00e0 nh\u00fat nh\u00e1t.`,
  `M\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf y\u1ebfu \u1edbt nh\u01b0 v\u1eady l\u1ea1i c\u00f3 m\u1ed9t ng\u01b0\u1eddi m\u1eb9 r\u1ea5t m\u1ea1nh m\u1ebd l\u00e0 L\u00e3 Tr\u0129.`,
  `Trong tay L\u00e3 Tr\u0129, L\u01b0u Doanh g\u1ea7n nh\u01b0 l\u00e0 m\u1ed9t con r\u1ed1i.`,
  `Thu\u1edf nh\u1ecf L\u00e3 Tr\u0129 th\u1ef1c ra c\u0169ng l\u00e0 m\u1ed9t ti\u1ec3u th\u01b0 khu\u00ea c\u00e1c,`,
  `cha b\u00e0 l\u00e0 l\u00e3o L\u00e3 \u0111\u00e3 \u0111\u1ec3 m\u1eaft \u0111\u1ebfn L\u01b0u Bang, l\u00fac \u0111\u00f3 v\u1eabn l\u00e0 m\u1ed9t k\u1ebb lang thang tu\u1ed5i trung ni\u00ean \u1edf huy\u1ec7n B\u00e1i,`,
  `v\u00e0 g\u1ea3 L\u00e3 Tr\u0129 cho L\u01b0u Bang.`,
  `Kh\u00f4ng th\u1ec3 kh\u00f4ng n\u00f3i, t\u1ea7m nh\u00ecn c\u1ee7a L\u00e3o L\u1eef \u0111\u00fang l\u00e0 r\u1ea5t tinh t\u01b0\u1eddng.`,
  `Nh\u01b0ng sau khi k\u1ebft h\u00f4n, L\u01b0u Bang ch\u1ec9 m\u1ed9t l\u00f2ng lo s\u1ef1 nghi\u1ec7p c\u1ee7a m\u00ecnh,`,
  `\u0110\u1ec3 L\u00e3 Tr\u0129 v\u00e0 con c\u00e1i \u1edf l\u1ea1i qu\u00ea nh\u00e0, kh\u00f4ng h\u1ec1 quan t\u00e2m \u0111\u1ebfn h\u1ecd.`,
  `Trong th\u1eddi lo\u1ea1n, L\u00e3 Tr\u0129 ch\u1eadt v\u1eadt c\u1ea7u sinh,`,
  `V\u00e0i n\u0103m sau, cu\u1ed1i c\u00f9ng c\u0169ng tr\u1edf v\u1ec1 b\u00ean L\u01b0u Bang,`,
  `Nh\u01b0ng l\u00fac n\u00e0y L\u01b0u Bang \u0111\u00e3 l\u00e0 H\u00e1n v\u01b0\u01a1ng c\u00f3 m\u1ef9 nh\u00e2n Th\u00edch phu nh\u00e2n \u1edf b\u00ean.`,
  `Ch\u1ed3ng b\u1ecb c\u01b0\u1edbp \u0111\u00e3 \u0111\u00e0nh,`,
  `Th\u00edch phu nh\u00e2n c\u00f2n mu\u1ed1n L\u01b0u Bang ph\u1ebf tru\u1ea5t th\u00e1i t\u1eed L\u01b0u Doanh,`,
  `L\u1eadp con trai m\u00ecnh l\u00e0 Tri\u1ec7u V\u01b0\u01a1ng Nh\u01b0 \u00dd l\u00e0m th\u00e1i t\u1eed.`,
  `M\u1eb7c d\u00f9 cu\u1ed1i c\u00f9ng kh\u00f4ng th\u00e0nh c\u00f4ng, nh\u01b0ng L\u00e3 Tr\u0129 \u0111\u00e3 ghi nh\u1edb m\u1ed1i th\u00f9 n\u00e0y.`,
  `Sau khi L\u01b0u Bang ch\u1ebft, L\u00e3 Tr\u0129 \u0111\u00e3 giam l\u1ecfng Th\u00edch phu nh\u00e2n,`,
  `\u0110\u1ec3 b\u00e0 t\u01b0\u1edbi hoa qu\u00e9t d\u1ecdn, t\u00f3m l\u1ea1i l\u00e0 l\u00e0m nh\u1eefng c\u00f4ng vi\u1ec7c n\u1eb7ng nh\u1ecdc c\u1ee7a ng\u01b0\u1eddi h\u1ea7u.`,
  `C\u00f2n Th\u00edch phu nh\u00e2n th\u00ec c\u0169ng l\u00e0 m\u1ed9t k\u1ebb n\u00e3o t\u00e0n, kh\u00f4ng bi\u1ebft b\u00e0 ta b\u00e2y gi\u1edd \u0111\u00e3 kh\u00f4ng c\u00f2n ch\u1ed7 d\u1ef1a sao?`,
  `Trong l\u00fac d\u1ecdn d\u1eb9p,`,
  `B\u00e0 ta c\u00f2n t\u1ef1 m\u00ecnh s\u00e1ng t\u00e1c m\u1ed9t b\u00e0i h\u00e1t,`,
  `Ng\u00e0y n\u00e0o c\u0169ng h\u00e1t, n\u00f3i r\u1eb1ng: \u201cCon \u01a1i, con c\u00f3 bi\u1ebft m\u1eb9 con kh\u1ed5 s\u1edf l\u1eafm kh\u00f4ng?`,
  `Con l\u00e0 Tri\u1ec7u V\u01b0\u01a1ng, c\u00f2n m\u1eb9 th\u00ec l\u00e0m vi\u1ec7c \u1edf \u0111\u00e2y, nh\u01b0 m\u1ed9t n\u00f4 l\u1ec7,`,
  `\u0111\u1ee7 th\u1ee9 chuy\u1ec7n.`,
  `Th\u1ebf n\u00e0y th\u00ec hay r\u1ed3i, b\u00e0 ta \u0111\u00e3 th\u00e0nh c\u00f4ng ch\u1ecdc gi\u1eadn L\u00e3 H\u1eadu.`,
  `L\u00e3 H\u1eadu \u0111\u00e3 h\u1ea1 \u0111\u1ed9c Tri\u1ec7u V\u01b0\u01a1ng Nh\u01b0 \u00dd, ch\u1eb7t \u0111\u1ee9t tay ch\u00e2n T\u00edch phu nh\u00e2n,`,
  `m\u00f3c m\u1eaft, c\u1eaft l\u01b0\u1ee1i,`,
  `bi\u1ebfn th\u00e0nh \u201cng\u01b0\u1eddi heo\u201d r\u1ed3i n\u00e9m v\u00e0o nh\u00e0 x\u00ed.`,
  `Nh\u00ecn th\u1ea5y m\u1ed9t lo\u1ea1t h\u00e0nh \u0111\u1ed9ng c\u1ee7a m\u1eb9 m\u00ecnh,`,
  `L\u01b0u Doanh v\u1ed1n \u0111\u00e3 y\u1ebfu \u0111u\u1ed1i l\u1ea1i c\u00e0ng th\u00eam n\u1eb7ng g\u00e1nh t\u00e2m l\u00fd,`,
  `s\u1ee9c kh\u1ecfe c\u0169ng ng\u00e0y c\u00e0ng t\u1ed3i t\u1ec7,`,
  `m\u1edbi hai m\u01b0\u01a1i ba tu\u1ed5i \u0111\u00e3 b\u1ec7nh ch\u1ebft.`,
  `Sau \u0111\u00f3 L\u00e3 H\u1eadu \u0111\u00e3 \u0111\u01b0a con trai ba tu\u1ed5i c\u1ee7a L\u01b0u Doanh l\u00e0 L\u01b0u Cung l\u00ean k\u1ebf v\u1ecb,`,
  `nh\u01b0ng L\u01b0u Cung kh\u00f4ng \u0111\u01b0\u1ee3c v\u00e2ng l\u1eddi,`,
  `sau b\u1ed1n n\u0103m t\u1ea1i v\u1ecb \u0111\u00e3 b\u1ecb L\u00e3 H\u1eadu gi\u1ebft ch\u1ebft,`,
  `l\u1ea1i \u0111\u01b0a m\u1ed9t ng\u01b0\u1eddi con kh\u00e1c c\u1ee7a L\u01b0u Doanh l\u00ean.`,
  `L\u01b0u H\u1ed3ng 4 tu\u1ed5i \u0111\u01b0\u1ee3c l\u1eadp l\u00e0m ho\u00e0ng \u0111\u1ebf.`,
  `M\u1eb7c d\u00f9 \u0111\u00e3 c\u00f3 qu\u00e2n c\u1edd l\u00e0 ho\u00e0ng \u0111\u1ebf, nh\u01b0ng c\u00e1c \u0111\u1ea1i th\u1ea7n trong tri\u1ec1u \u0111\u00ecnh \u0111\u1ec1u l\u00e0 thu\u1ed9c h\u1ea1 c\u1ee7a L\u01b0u Bang,`,
  `h\u1ecd c\u0169ng kh\u00f4ng nghe l\u1eddi L\u1eef Tr\u0129.`,
  `L\u1eef Tr\u0129 t\u1ef1 m\u00ecnh bi\u1ebft \u0111i\u1ec1u n\u00e0y,`,
  `ch\u1ec9 n\u1eafm quy\u1ec1n ho\u00e0ng \u0111\u1ebf v\u1eabn ch\u01b0a \u0111\u1ee7, c\u00f2n ph\u1ea3i c\u00f3 ng\u01b0\u1eddi trong tri\u1ec1u.`,
  `V\u00ec v\u1eady, sau khi L\u01b0u Doanh m\u1ea5t,`,
  `L\u1eef Tr\u0129 \u0111\u00e3 c\u1ea5t nh\u1eafc nhi\u1ec1u ng\u01b0\u1eddi th\u00e2n c\u1ee7a h\u1ecd L\u1eef,`,
  `d\u1ea7n d\u1ea7n c\u00e1c v\u1ecb tr\u00ed quan tr\u1ecdng trong v\u00e0 ngo\u00e0i tri\u1ec1u \u0111\u00ecnh \u0111\u1ec1u \u0111\u01b0\u1ee3c thay th\u1ebf b\u1eb1ng ng\u01b0\u1eddi h\u1ecd L\u1eef.`,
  `Trong t\u00ecnh hu\u1ed1ng n\u00e0y,`,
  `li\u1ec7u c\u00e1c c\u1ef1u th\u1ea7n c\u1ee7a L\u01b0u Bang v\u00e0 h\u1eadu du\u1ec7 nh\u00e0 L\u01b0u c\u00f3 cam t\u00e2m nh\u00ecn quy\u1ec1n l\u1ef1c r\u01a1i v\u00e0o tay k\u1ebb kh\u00e1c,`,
  `m\u00e0 kh\u00f4ng ra tay ch\u1ed1ng \u0111\u1ed1i sao?`,
  `Kh\u00f4ng ph\u1ea3i h\u1ecd kh\u00f4ng mu\u1ed1n, ch\u1ec9 l\u00e0 L\u1eef Tr\u0129 qu\u00e1 l\u1ee3i h\u1ea1i,`,
  `lu\u00f4n kh\u00f4ng t\u00ecm \u0111\u01b0\u1ee3c c\u01a1 h\u1ed9i.`,
  `Tuy nhi\u00ean, con ng\u01b0\u1eddi ai r\u1ed3i c\u0169ng ph\u1ea3i ch\u1ebft, L\u1eef Tr\u0129 c\u0169ng \u0111\u1ebfn ng\u00e0y \u0111\u00f3.`,
  `Sau khi L\u1eef Tr\u0129 ch\u1ebft, hai ch\u00e1u trai c\u1ee7a b\u00e0 l\u00e0 L\u1eef L\u1ed9c v\u00e0 L\u1eef S\u1ea3n \u0111\u00e3 d\u1ef1a v\u00e0o vi\u1ec7c n\u1eafm gi\u1eef tr\u1ecdng binh chu\u1ea9n b\u1ecb l\u00e0m ph\u1ea3n,`,
  `\u0110\u1ec3 giang s\u01a1n ho\u00e0n to\u00e0n mang h\u1ecd L\u1eef.`,
  `Nh\u01b0ng h\u1ecd v\u1eabn c\u00f2n qu\u00e1 non n\u1edbt,`,
  `Tuy c\u00f3 d\u00e3 t\u00e2m nh\u01b0ng kh\u00f4ng c\u00f3 \u0111\u1ea7u \u00f3c,`,
  `Ho\u00e0n to\u00e0n kh\u00f4ng ph\u1ea3i l\u00e0 \u0111\u1ed1i th\u1ee7 c\u1ee7a c\u00e1c l\u00e3o th\u1ea7n L\u01b0u Bang.`,
  `Sau \u0111\u00f3, c\u00e1c anh em h\u1ecd L\u1eef l\u1ea7n l\u01b0\u1ee3t b\u1ecb gi\u1ebft,`,
  `Nh\u00e0 h\u1ecd L\u1eef b\u1ecb di\u1ec7t to\u00e0n t\u1ed9c ch\u01b0a \u0111\u1ea7y n\u1eeda n\u0103m sau khi L\u1eef H\u1eadu ch\u1ebft,`,
  `\u0110\u00e3 gi\u1ea3i quy\u1ebft nh\u00e0 h\u1ecd L\u1eef xong.`,
  `V\u1ea5n \u0111\u1ec1 l\u1edbn nh\u1ea5t ti\u1ebfp theo l\u00e0 ch\u1ecdn ai l\u00e0m t\u00e2n ho\u00e0ng \u0111\u1ebf.`,
  `Th\u1ef1c ra l\u00fac n\u00e0y kh\u00f4ng ph\u1ea3i l\u00e0 kh\u00f4ng c\u00f3 ho\u00e0ng \u0111\u1ebf,`,
  `Ch\u1eb3ng ph\u1ea3i v\u1eabn c\u00f2n m\u1ed9t ti\u1ec3u ho\u00e0ng \u0111\u1ebf b\u00f9 nh\u00ecn L\u01b0u H\u1ed3ng do L\u1eef H\u1eadu l\u1eadp ra sao?`,
  `\u0110\u1ec3 L\u01b0u H\u1ed3ng tho\u00e1i v\u1ecb, \u0111\u00e1m l\u00e3o th\u1ea7n n\u00e0y \u0111\u00e3 tung tin \u0111\u1ed3n,`,
  `N\u00f3i r\u1eb1ng L\u01b0u H\u1ed3ng kh\u00f4ng ph\u1ea3i con ru\u1ed9t c\u1ee7a L\u01b0u Anh.`,
  `C\u1ee9 nh\u01b0 v\u1eady, h\u1ecd \u0111\u00e3 l\u1eadp t\u00e2n ho\u00e0ng \u0111\u1ebf H\u00e1n Hi\u1ebfu V\u0103n \u0110\u1ebf L\u01b0u H\u1eb1ng,`,
  `C\u00f3 ph\u1ea3i v\u00ec L\u01b0u H\u1eb1ng r\u1ea5t \u01b0u t\u00fa, r\u1ea5t anh d\u0169ng, r\u1ea5t m\u1ea1nh m\u1ebd,`,
  `N\u00ean m\u1edbi l\u1eadp \u00f4ng \u1ea5y kh\u00f4ng?`,
  `Ho\u00e0n to\u00e0n ng\u01b0\u1ee3c l\u1ea1i, L\u01b0u H\u1eb1ng l\u00fac \u0111\u00f3 ch\u1ec9 l\u00e0 m\u1ed9t ng\u01b0\u1eddi v\u00f4 danh.`,
  `L\u01b0u H\u1eb1ng l\u00e0 con trai c\u1ee7a L\u01b0u Bang v\u00e0 B\u1ea1c C\u01a1, m\u1ed9t n\u1eef c\u00f4ng l\u00e0m ngh\u1ec1 d\u1ec7t v\u1ea3i trong cung.`,
  `L\u01b0u Bang v\u00e0 B\u1ea1c C\u01a1 kh\u00f4ng c\u00f3 t\u00ecnh c\u1ea3m g\u00ec v\u1edbi nhau.`,
  `Ch\u1ec9 l\u00e0 m\u1ed9t ng\u00e0y n\u1ecd, L\u01b0u Bang nh\u00ecn th\u1ea5y B\u1ea1c C\u01a1,`,
  `nh\u1ea5t th\u1eddi h\u1ee9ng th\u00fa \u0111\u00e3 s\u1ee7ng \u00e1i b\u00e0.`,
  `Sau khi L\u01b0u H\u1eb1ng ra \u0111\u1eddi, \u00f4ng c\u0169ng kh\u00f4ng \u0111\u01b0\u1ee3c coi tr\u1ecdng nh\u01b0 m\u1eb9 m\u00ecnh.`,
  `Nh\u01b0ng d\u00f9 sao \u00f4ng c\u0169ng l\u00e0 con trai c\u1ee7a L\u01b0u Bang,`,
  `sau n\u00e0y \u0111\u01b0\u1ee3c phong l\u00e0m \u0110\u1ea1i V\u01b0\u01a1ng \u1edf \u0111\u1ea5t \u0110\u1ea1i.`,
  `C\u00e1c l\u00e3o th\u1ea7n ch\u1ecdn L\u01b0u H\u1eb1ng v\u00ec nh\u00ecn tr\u00fang s\u1ef1 khi\u00eam t\u1ed1n, kh\u00f4ng ph\u00f4 tr\u01b0\u01a1ng c\u1ee7a \u00f4ng,`,
  `d\u1ec5 ki\u1ec3m so\u00e1t. M\u1eb7c d\u00f9 L\u01b0u H\u1eb1ng khi\u00eam t\u1ed1n nh\u01b0ng \u00f4ng kh\u00f4ng ng\u1ed1c.`,
  `Sau khi l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf, \u00f4ng c\u0169ng bi\u1ebft r\u1eb1ng nh\u00f3m l\u00e3o th\u1ea7n n\u00e0y r\u1ea5t m\u1ea1nh,`,
  `ho\u00e0ng quy\u1ec1n c\u1ee7a m\u00ecnh kh\u00f4ng v\u1eefng ch\u1eafc.`,
  `V\u00ec v\u1eady, \u0111\u1ec3 t\u0103ng c\u01b0\u1eddng t\u1eadp quy\u1ec1n, \u00f4ng \u0111\u00e3 th\u1ef1c hi\u1ec7n m\u1ed9t s\u1ed1 ch\u00ednh s\u00e1ch,`,
  `t\u1eebng b\u01b0\u1edbc l\u00e0m suy y\u1ebfu th\u1ebf l\u1ef1c c\u1ee7a c\u00e1c ch\u01b0 h\u1ea7u v\u01b0\u01a1ng, v\u00e0 trong vi\u1ec7c cai tr\u1ecb \u0111\u1ea5t n\u01b0\u1edbc,`,
  `L\u01b0u H\u1eb1ng \u0111\u00e3 gi\u1ea3m thu\u1ebf,`,
  `Khuy\u1ebfn kh\u00edch s\u1ea3n xu\u1ea5t n\u00f4ng nghi\u1ec7p,`,
  `sau n\u00e0y th\u1eadm ch\u00ed c\u00f2n mi\u1ec5n to\u00e0n b\u1ed9 thu\u1ebf ru\u1ed9ng cho n\u00f4ng d\u00e2n.`,
  `Nh\u1edd \u0111\u00f3, kinh t\u1ebf c\u1ea3 n\u01b0\u1edbc ph\u00e1t tri\u1ec3n v\u01b0\u1ee3t b\u1eadc,`,
  `d\u00e2n ch\u00fang an c\u01b0 l\u1ea1c nghi\u1ec7p, nh\u1eefng vi\u1ec7c l\u00e0m n\u00e0y \u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng v\u1eefng ch\u1eafc cho m\u1ed9t th\u1eddi k\u1ef3 th\u1ecbnh v\u01b0\u1ee3ng sau n\u00e0y.`,
  `N\u0103m 157 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `L\u01b0u H\u1eb1ng qua \u0111\u1eddi v\u00ec b\u1ec7nh, con trai \u00f4ng l\u00e0 H\u00e1n C\u1ea3nh \u0110\u1ebf L\u01b0u Kh\u1ea3i l\u00ean ng\u00f4i.`,
  `L\u01b0u Kh\u1ea3i t\u1eeb nh\u1ecf \u0111\u00e3 kh\u00f4ng ph\u1ea3i l\u00e0 m\u1ed9t \u0111\u1ee9a tr\u1ebb ngoan ngo\u00e3n.`,
  `Khi c\u00f2n l\u00e0 th\u00e1i t\u1eed, c\u00f3 l\u1ea7n \u00f4ng ch\u01a1i c\u1edd v\u1edbi con trai c\u1ee7a Ng\u00f4 v\u01b0\u01a1ng L\u01b0u T\u1ef5,`,
  `hai b\u00ean x\u1ea3y ra tranh c\u00e3i,`,
  `L\u01b0u Kh\u1ea3i li\u1ec1n c\u1ea7m b\u00e0n c\u1edd,`,
  `\u0111\u1eadp ch\u1ebft con trai c\u1ee7a L\u01b0u T\u1ef5 ngay t\u1ea1i ch\u1ed7.`,
  `Chuy\u1ec7n n\u00e0y khi\u1ebfn L\u01b0u T\u1ef5 lu\u00f4n ghi h\u1eadn trong l\u00f2ng,`,
  `nh\u01b0ng L\u01b0u Kh\u1ea3i l\u00e0 th\u00e1i t\u1eed, \u00f4ng c\u0169ng kh\u00f4ng th\u1ec3 l\u00e0m g\u00ec \u0111\u01b0\u1ee3c.`,
  `Sau khi L\u01b0u Kh\u1ea3i l\u00ean ng\u00f4i,`,
  `th\u1ebf l\u1ef1c c\u1ee7a c\u00e1c ch\u01b0 h\u1ea7u \u0111e d\u1ecda nghi\u00eam tr\u1ecdng \u0111\u1ebfn quy\u1ec1n l\u1ef1c t\u1eadp trung c\u1ee7a tri\u1ec1u \u0111\u00ecnh,`,
  `L\u01b0u Kh\u1ea3i l\u1eadp t\u1ee9c quy\u1ebft \u0111\u1ecbnh c\u1eaft gi\u1ea3m phi\u00ean tr\u1ea5n.`,
  `L\u00fac n\u00e0y, h\u1eadn m\u1edbi ch\u1ed3ng h\u1eadn c\u0169, L\u01b0u B\u1ecb l\u1eadp t\u1ee9c d\u1ea5y binh l\u00e0m ph\u1ea3n,`,
  `C\u00f3 b\u1ea3y v\u01b0\u01a1ng h\u1ea7u tham gia v\u00e0o cu\u1ed9c n\u1ed5i lo\u1ea1n, s\u1eed g\u1ecdi l\u00e0 Lo\u1ea1n b\u1ea3y n\u01b0\u1edbc.`,
  `L\u01b0u Kh\u1ea3i ph\u00e1i danh t\u01b0\u1edbng Chu \u00c1 Phu \u0111i d\u1eb9p lo\u1ea1n,`,
  `Chu \u00c1 Phu qu\u1ea3 th\u1ef1c l\u00e0 th\u1ea7n t\u01b0\u1edbng,`,
  `Ch\u1ec9 m\u1ea5t ba th\u00e1ng \u0111\u1ec3 d\u1eb9p y\u00ean Lo\u1ea1n b\u1ea3y n\u01b0\u1edbc,`,
  `C\u1ee7ng c\u1ed1 quy\u1ec1n l\u1ef1c t\u1eadp trung c\u1ee7a tri\u1ec1u \u0111\u00ecnh.`,
  `Tr\u1eadn chi\u1ebfn n\u00e0y c\u0169ng khi\u1ebfn L\u01b0u Kh\u1ea3i tr\u01b0\u1edfng th\u00e0nh h\u01a1n,`,
  `\u00d4ng \u1ea5y hi\u1ec3u r\u1eb1ng \u0111\u1ec3 m\u1edf ra m\u1ed9t th\u1eddi k\u1ef3 th\u1ecbnh v\u01b0\u1ee3ng, \u00f4ng \u1ea5y ph\u1ea3i \u0111i theo con \u0111\u01b0\u1eddng m\u00e0 cha m\u00ecnh \u0111\u00e3 \u0111i,`,
  `Ph\u00e1t tri\u1ec3n n\u00f4ng nghi\u1ec7p, chu\u1ea9n h\u00f3a ph\u00e1p lu\u1eadt,`,
  `\u1ee6ng h\u1ed9 c\u00e1c tr\u01b0\u1eddng ph\u00e1i t\u01b0 t\u01b0\u1edfng kh\u00e1c nhau.`,
  `Trong th\u1eddi gian \u00f4ng tr\u1ecb v\u00ec, kinh t\u1ebf \u0111\u1ea5t n\u01b0\u1edbc,`,
  `V\u0103n h\u00f3a, th\u1ec3 ch\u1ebf \u0111\u1ec1u ph\u00e1t tri\u1ec3n nhanh ch\u00f3ng.`,
  `Sau khi L\u01b0u Kh\u1ea3i \u0111\u00e3 d\u1ecdn s\u1eb5n m\u1ecdi con \u0111\u01b0\u1eddng cho con trai m\u00ecnh,`,
  `C\u0169ng \u0111\u00e3 gi\u00e3 t\u1eeb v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed.`,
  `Sau \u0111\u00f3, L\u01b0u Tri\u1ec7t, ph\u00fa tam \u0111\u1ea1i th\u1eeba k\u1ebf gia s\u1ea3n c\u1ee7a cha v\u00e0 \u00f4ng n\u1ed9i, l\u00ean ng\u00f4i.`,
  `\u00d4ng ch\u00ednh l\u00e0 H\u00e1n V\u0169 \u0110\u1ebf n\u1ed5i ti\u1ebfng.`,
  `Tr\u1ea3i qua hai \u0111\u1eddi \u00f4ng v\u00e0 cha tr\u1ecb v\u00ec \u1ed5n \u0111\u1ecbnh, t\u00edch l\u0169y ban \u0111\u1ea7u,`,
  `\u0111\u1ebfn th\u1eddi H\u00e1n V\u0169 \u0110\u1ebf L\u01b0u Tri\u1ec7t ti\u1ebfp qu\u1ea3n,`,
  `gia nghi\u1ec7p \u0111\u00e3 l\u1edbn m\u1ea1nh.`,
  `L\u01b0u Tri\u1ec7t kh\u00f4ng mu\u1ed1n l\u00e0m m\u1ed9t ph\u00fa tam \u0111\u1ea1i t\u1ea7m th\u01b0\u1eddng,`,
  `\u00f4ng c\u00f3 ho\u00e0i b\u00e3o, c\u00f3 tham v\u1ecdng,`,
  `sau n\u00e0y s\u1ef1 th\u1eadt c\u0169ng ch\u1ee9ng minh \u00f4ng c\u00e0ng c\u00f3 n\u0103ng l\u1ef1c.`,
  `Vi\u1ec7c \u0111\u1ea7u ti\u00ean L\u01b0u Tri\u1ec7t l\u00e0m sau khi nh\u1eadm ch\u1ee9c l\u00e0 tuy\u1ec3n ch\u1ecdn nh\u00e2n t\u00e0i,`,
  `\u00f4ng \u0111\u00e3 t\u1ed5 ch\u1ee9c m\u1ed9t k\u1ef3 thi tuy\u1ec3n ch\u1ecdn ch\u01b0a t\u1eebng c\u00f3 trong l\u1ecbch s\u1eed tr\u00ean to\u00e0n qu\u1ed1c,`,
  `m\u1ed9t nho sinh t\u00ean \u0110\u1ed5ng Tr\u1ecdng Th\u01b0 \u0111\u00e3 xu\u1ea5t s\u1eafc v\u01b0\u1ee3t qua.`,
  `Khi \u0110\u1ed5ng Tr\u1ecdng Th\u01b0 \u0111\u01b0a ra m\u1ed9t b\u1ed9 l\u00fd lu\u1eadn tr\u1ecb qu\u1ed1c Nho h\u1ecdc ho\u00e0n ch\u1ec9nh tr\u01b0\u1edbc m\u1eb7t L\u01b0u Tri\u1ec7t,`,
  `L\u01b0u Tri\u1ec7t t\u00e2m ph\u1ee5c kh\u1ea9u ph\u1ee5c.`,
  `Sau \u0111\u00f3, \u00f4ng \u0111\u00e3 ch\u1ea5p nh\u1eadn ki\u1ebfn ngh\u1ecb c\u1ee7a \u0110\u1ed5ng Tr\u1ecdng Th\u01b0,`,
  `b\u00e3i b\u1ecf tr\u0103m nh\u00e0, \u0111\u1ed9c t\u00f4n Nho thu\u1eadt,`,
  `khi\u1ebfn Nho gi\u00e1o tr\u1edf th\u00e0nh t\u01b0 t\u01b0\u1edfng ch\u00ednh th\u1ed1ng c\u1ee7a x\u00e3 h\u1ed9i phong ki\u1ebfn Trung Qu\u1ed1c,`,
  `\u0111\u00e3 k\u00e9o d\u00e0i h\u01a1n hai ng\u00e0n n\u0103m,`,
  `\u1ea3nh h\u01b0\u1edfng s\u00e2u r\u1ed9ng \u0111\u1ebfn Trung Qu\u1ed1c \u0111\u1eddi sau.`,
  `Tuy nhi\u00ean, ph\u1ea3i n\u00f3i r\u1eb1ng,`,
  `vi\u1ec7c \u0111\u1ed9c t\u00f4n Nho gi\u00e1o c\u0169ng c\u00f3 nh\u01b0\u1ee3c \u0111i\u1ec3m, \u0111\u00f3 l\u00e0 kh\u00f4ng c\u00f3 l\u1ee3i cho s\u1ef1 \u0111a d\u1ea1ng t\u01b0 t\u01b0\u1edfng.`,
  `T\u1eeb H\u00e1n Cao T\u1ed5 L\u01b0u Bang tr\u1edf \u0111i,`,
  `T\u00e2y H\u00e1n v\u00e0 Hung N\u00f4 \u0111\u00e3 duy tr\u00ec m\u1ed1i quan h\u1ec7 h\u00f4n nh\u00e2n,`,
  `nh\u01b0ng Hung N\u00f4 kh\u00f4ng bi\u1ebft \u0111\u1ee7,`,
  `v\u1eabn th\u01b0\u1eddng xuy\u00ean qu\u1ea5y ph\u00e1 bi\u00ean gi\u1edbi \u0110\u1ea1i H\u00e1n,`,
  `c\u01b0\u1edbp b\u00f3c ti\u1ec1n b\u1ea1c, gia s\u00fac, v.v.`,
  `L\u01b0u Tri\u1ec7t c\u0169ng lu\u00f4n coi th\u01b0\u1eddng h\u1ecd.`,
  `C\u00f3 l\u1ea7n \u00f4ng nghe n\u00f3i,`,
  `\u1edf T\u00e2y V\u1ef1c c\u00f3 t\u1ed5ng c\u1ed9ng m\u01b0\u1eddi s\u00e1u qu\u1ed1c gia,`,
  `trong \u0111\u00f3 c\u00f3 m\u1ed9t qu\u1ed1c gia th\u00f9 gh\u00e9t Hung N\u00f4 gi\u1ed1ng nh\u01b0 \u0110\u1ea1i H\u00e1n,`,
  `g\u1ecdi l\u00e0 \u0110\u1ea1i Nh\u1ee5c Chi. K\u1ebb th\u00f9 c\u1ee7a k\u1ebb th\u00f9 ch\u00ednh l\u00e0 b\u1ea1n.`,
  `\u0110\u1ec3 li\u00ean l\u1ea1c v\u1edbi \u0110\u1ea1i Nh\u1ee5c Chi,`,
  `v\u00e0 \u0111\u1ec3 kh\u00e1m ph\u00e1 v\u00f9ng \u0111\u1ea5t b\u00ed \u1ea9n \u1edf T\u00e2y V\u1ef1c,`,
  `H\u00e1n V\u0169 \u0110\u1ebf c\u1eed Tr\u01b0\u01a1ng Khi\u00ean c\u00f9ng \u0111o\u00e0n t\u00f9y t\u00f9ng \u0111i s\u1ee9 T\u00e2y V\u1ef1c,`,
  `nh\u00ecn v\u00e0o b\u1ea3n \u0111\u1ed3 n\u00e0y.`,
  `N\u1ebfu mu\u1ed1n \u0111\u1ebfn \u0110\u1ea1i Nh\u1ee5c Chi, tr\u01b0\u1edbc ti\u00ean ph\u1ea3i \u0111i qua Hung N\u00f4.`,
  `Tr\u01b0\u01a1ng Khi\u00ean l\u00e0 m\u1ed9t ng\u01b0\u1eddi k\u00e9m may m\u1eafn,`,
  `v\u1eeba \u0111\u1eb7t ch\u00e2n v\u00e0o l\u00e3nh th\u1ed5 Hung N\u00f4 \u0111\u00e3 b\u1ecb b\u1eaft.`,
  `\u0110\u1ed1i m\u1eb7t v\u1edbi s\u1ef1 th\u1ea9m v\u1ea5n c\u1ee7a Hung N\u00f4, t\u1ea5t nhi\u00ean \u00f4ng kh\u00f4ng th\u1ec3 n\u00f3i:`,
  `T\u00f4i \u0111\u1ebfn \u0111\u1ec3 li\u00ean minh v\u1edbi \u0110\u1ea1i Nh\u1ee5c Chi \u0111\u1ec3 \u0111\u1ed1i ph\u00f3 v\u1edbi c\u00e1c ng\u01b0\u1eddi.`,
  `Th\u1ebf l\u00e0 Tr\u01b0\u01a1ng Khi\u00ean n\u00f3i: "T\u00f4i \u0111\u1ebfn \u0111\u1ec3 l\u00e0m \u0103n v\u1edbi \u0110\u1ea1i Nh\u1ee5c Chi,`,
  `xin l\u1ed7i, ch\u1ec9 l\u00e0 \u0111i ngang qua th\u00f4i".`,
  `Hung N\u00f4 kh\u00f4ng tin l\u1eddi \u00f4ng ta, nh\u01b0ng c\u0169ng kh\u00f4ng gi\u1ebft \u00f4ng ta,`,
  `c\u0169ng kh\u00f4ng th\u1ea3 \u00f4ng ta,`,
  `m\u00e0 giam l\u1ecfng \u00f4ng ta su\u1ed1t m\u01b0\u1eddi n\u0103m.`,
  `M\u01b0\u1eddi n\u0103m d\u00e0i \u0111\u1eb1ng \u0111\u1eb5ng \u0111\u00f3,`,
  `Tr\u01b0\u01a1ng Khi\u00ean ch\u0103n th\u1ea3 ng\u1ef1a v\u00e0 c\u1eebu nh\u01b0 ng\u01b0\u1eddi Hung N\u00f4,`,
  `nh\u01b0ng \u00f4ng ch\u01b0a bao gi\u1edd qu\u00ean th\u00e2n ph\u1eadn c\u1ee7a m\u00ecnh.`,
  `Cu\u1ed1i c\u00f9ng, m\u1ed9t ng\u00e0y n\u1ecd, \u00f4ng t\u00ecm \u0111\u01b0\u1ee3c c\u01a1 h\u1ed9i tr\u1ed1n v\u1ec1 H\u00e1n tri\u1ec1u.`,
  `M\u1eb7c d\u00f9 kh\u00f4ng ho\u00e0n th\u00e0nh s\u1ee9 m\u1ec7nh li\u00ean l\u1ea1c v\u1edbi \u0110\u1ea1i Nh\u1ee5c Chi l\u00fac \u0111\u1ea7u,`,
  `nh\u01b0ng Tr\u01b0\u01a1ng Khi\u00ean \u0111\u00e3 mang v\u1ec1 r\u1ea5t nhi\u1ec1u th\u00f4ng tin v\u1ec1 T\u00e2y V\u1ef1c v\u00e0 Hung N\u00f4.`,
  `Phong t\u1ee5c t\u1eadp qu\u00e1n v\u00e0 s\u1ea3n v\u1eadt phong ph\u00fa c\u1ee7a nh\u1eefng qu\u1ed1c gia n\u00e0y,`,
  `\u0111\u00e3 thu h\u00fat s\u00e2u s\u1eafc L\u01b0u Tri\u1ec7t.`,
  `V\u1eady l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 c\u00f3 \u0111\u01b0\u1ee3c nh\u1eefng th\u1ee9 n\u00e0y?`,
  `Kh\u00f4ng b\u1eb1ng th\u00f4ng qua vi\u1ec7c bu\u00f4n b\u00e1n,`,
  `t\u01b0 t\u01b0\u1edfng n\u00e0y \u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng cho vi\u1ec7c m\u1edf ra Con \u0111\u01b0\u1eddng T\u01a1 l\u1ee5a v\u1ec1 sau.`,
  `Tuy nhi\u00ean, l\u00fac n\u00e0y L\u01b0u Tri\u1ec7t c\u00f2n c\u00f3 vi\u1ec7c quan tr\u1ecdng h\u01a1n ph\u1ea3i ho\u00e0n th\u00e0nh.`,
  `Thi\u1ec1n Vu Hung N\u00f4 l\u00fac n\u00e0y t\u00ean l\u00e0 Y Ch\u00ed S\u00e1t,`,
  `l\u00e0 m\u1ed9t ng\u01b0\u1eddi \u0111\u1ea7y tham v\u1ecdng.`,
  `Trong v\u00e0i n\u0103m ng\u1eafn ng\u1ee7i, h\u1eafn kh\u00f4ng ch\u1ec9 c\u01b0\u1edbp b\u00f3c, gi\u1ebft ch\u00f3c \u1edf bi\u00ean gi\u1edbi,`,
  `m\u00e0 c\u00f2n gi\u1ebft ch\u1ebft quan l\u1ea1i \u0111\u1ecba ph\u01b0\u01a1ng c\u1ee7a H\u00e1n tri\u1ec1u,`,
  `th\u00e1ch th\u1ee9c quy\u1ec1n uy c\u1ee7a nh\u00e0 H\u00e1n.`,
  `Cu\u1ed1i c\u00f9ng, L\u01b0u Tri\u1ec7t kh\u00f4ng th\u1ec3 nh\u1eabn nh\u1ecbn th\u00eam n\u1eefa.`,
  `N\u0103m 124 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `L\u01b0u Tri\u1ec7t ph\u00e1i \u0110\u1ea1i t\u01b0\u1edbng qu\u00e2n V\u1ec7 Thanh \u0111i \u0111\u00e1nh Hung N\u00f4.`,
  `N\u00f3i s\u01a1 qua v\u1ec1 V\u1ec7 Thanh,`,
  `V\u1ec7 Thanh c\u00f2n c\u00f3 m\u1ed9t ng\u01b0\u1eddi ch\u1ecb t\u00ean l\u00e0 V\u1ec7 T\u1eed Phu,`,
  `Hai ng\u01b0\u1eddi ban \u0111\u1ea7u \u0111\u1ec1u l\u00e0 gia n\u00f4 trong ph\u1ee7 c\u00f4ng ch\u00faa B\u00ecnh D\u01b0\u01a1ng, ch\u1ecb c\u1ee7a L\u01b0u Tri\u1ec7t.`,
  `V\u1ec7 T\u1eed Phu l\u00e0 m\u1ed9t m\u1ef9 nh\u00e2n, l\u00e0m ca k\u1ef9 trong ph\u1ee7 c\u00f4ng ch\u00faa.`,
  `L\u01b0u Tri\u1ec7t c\u00f3 l\u1ea7n \u0111\u1ebfn ph\u1ee7 c\u00f4ng ch\u00faa, nh\u00ecn th\u1ea5y V\u1ec7 T\u1eed Phu \u0111ang m\u00faa th\u00ec v\u1eeba \u00fd,`,
  `Sau khi V\u1ec7 T\u1eed Phu \u0111\u01b0\u1ee3c s\u1ee7ng \u00e1i,`,
  `em trai V\u1ec7 Thanh c\u0169ng v\u00e0o cung,`,
  `h\u01a1n n\u1eefa V\u1ec7 Thanh b\u1ea3n th\u00e2n c\u0169ng r\u1ea5t xu\u1ea5t s\u1eafc,`,
  `l\u1ea1i hi\u1ebfu h\u1ecdc, sau n\u00e0y li\u1ec1n th\u0103ng ti\u1ebfn nhanh ch\u00f3ng.`,
  `Sau khi ch\u1ecb V\u1ec7 T\u1eed Phu v\u00e0o cung, c\u0169ng sinh ra con trai L\u01b0u C\u1ee9,`,
  `r\u1ea5t \u0111\u01b0\u1ee3c L\u01b0u Tri\u1ec7t s\u1ee7ng \u00e1i.`,
  `Sau \u0111\u00f3, L\u01b0u Tri\u1ec7t c\u00f2n ph\u1ebf tru\u1ea5t Tr\u1ea7n A Ki\u1ec1u, ng\u01b0\u1eddi kh\u00f4ng c\u00f3 t\u00ecnh c\u1ea3m s\u00e2u n\u1eb7ng v\u1edbi \u00f4ng,`,
  `v\u00e0 c\u0169ng l\u00e0 Ho\u00e0ng h\u1eadu Nguy\u00ean chuy\u00ean quy\u1ec1n h\u1ed1ng h\u00e1ch,`,
  `l\u1eadp V\u1ec7 T\u1eed Phu l\u00e0m Ho\u00e0ng h\u1eadu.`,
  `N\u00f3i l\u1ea1i v\u1ec1 l\u1ea7n V\u1ec7 Thanh t\u1ea5n c\u00f4ng Hung N\u00f4 n\u00e0y,`,
  `\u0111\u1ea1i th\u1eafng tr\u1edf v\u1ec1, \u0111\u00e1nh \u0111u\u1ed5i Hung N\u00f4 kh\u1ecfi bi\u00ean gi\u1edbi,`,
  `m\u1ed9t nh\u00e0 h\u1ecd V\u1ec7 vinh quang v\u00f4 h\u1ea1n.`,
  `Nh\u01b0ng ch\u01b0a \u0111\u01b0\u1ee3c v\u00e0i th\u00e1ng,`,
  `Hung N\u00f4 l\u1ea1i quay tr\u1edf l\u1ea1i.`,
  `Th\u1ebf l\u00e0 v\u00e0o n\u0103m sau,`,
  `nh\u00e0 H\u00e1n l\u1ea1i m\u1ed9t l\u1ea7n n\u1eefa xu\u1ea5t binh,`,
  `l\u1ea7n n\u00e0y \u0110\u1ea1i t\u01b0\u1edbng qu\u00e2n V\u1ec7 Thanh c\u0169ng \u0111\u01b0a theo ch\u00e1u m\u00ecnh,`,
  `m\u1ed9t \u0111\u1eddi chi\u1ebfn th\u1ea7n Ho\u1eafc Kh\u1ee9 B\u1ec7nh.`,
  `Trong l\u1ecbch s\u1eed c\u00f3 r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi gi\u1ecfi \u0111\u00e1nh tr\u1eadn,`,
  `nh\u01b0ng \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 chi\u1ebfn th\u1ea7n th\u00ec kh\u00f4ng c\u00f3 m\u1ea5y ng\u01b0\u1eddi.`,
  `V\u1eady Ho\u1eafc Kh\u1ee9 B\u1ec7nh \u0111\u00e3 l\u00e0m nh\u1eefng g\u00ec?`,
  `L\u1ea7n t\u1ea5n c\u00f4ng qu\u00e2n Hung N\u00f4 n\u00e0y,`,
  `nh\u00e0 H\u00e1n \u0111\u00e3 c\u1eed m\u1ed9t \u0111\u1ed9i qu\u00e2n c\u1ef1c k\u1ef3 h\u00f9ng h\u1eadu,`,
  `nh\u01b0ng m\u1ed9t nh\u00f3m l\u00e3o t\u01b0\u1edbng l\u1ea1i \u0111\u1ea1t th\u00e0nh t\u00edch b\u00ecnh th\u01b0\u1eddng,`,
  `ch\u1ec9 Ho\u1eafc Kh\u1ee9 B\u1ec7nh l\u00e0 n\u1ed5i b\u1eadt nh\u1ea5t.`,
  `Anh ta ch\u1ec9 d\u1eabn t\u00e1m tr\u0103m k\u1ef5 binh, x\u00f4ng th\u1eb3ng v\u00e0o s\u00e2u trong l\u00e3nh th\u1ed5 Hung N\u00f4,`,
  `ti\u00eau di\u1ec7t m\u1ed9t s\u00e0o huy\u1ec7t c\u1ee7a Hung N\u00f4,`,
  `gi\u1ebft ch\u1ebft h\u01a1n hai ng\u00e0n binh l\u00ednh Hung N\u00f4,`,
  `c\u00f2n b\u1eaft s\u1ed1ng r\u1ea5t nhi\u1ec1u v\u01b0\u01a1ng t\u01b0\u1edbc Hung N\u00f4 l\u1edbn nh\u1ecf,`,
  `khi\u1ebfn Hung N\u00f4 b\u1ecb t\u1ed5n th\u1ea5t n\u1eb7ng n\u1ec1.`,
  `Khi \u0111\u00f3 anh ta m\u1edbi m\u01b0\u1eddi b\u1ea3y tu\u1ed5i.`,
  `Trong nh\u1eefng n\u0103m sau \u0111\u00f3, Ho\u1eafc Kh\u1ee9 B\u1ec7nh l\u1ea1i nhi\u1ec1u l\u1ea7n giao chi\u1ebfn v\u1edbi Hung N\u00f4,`,
  `h\u1ec5 g\u1eb7p anh ta l\u00e0 Hung N\u00f4 li\u00ean t\u1ee5c b\u1ea1i tr\u1eadn.`,
  `N\u0103m 121 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean, Ho\u1eafc Kh\u1ee9 B\u1ec7nh l\u1ea1i m\u1ed9t l\u1ea7n n\u1eefa \u0111\u1ea1i ph\u00e1 Hung N\u00f4 \u1edf n\u00fai K\u1ef3 Li\u00ean,`,
  `thu ph\u1ee5c v\u00f9ng H\u00e0 T\u00e2y,`,
  `m\u1edf th\u00f4ng con \u0111\u01b0\u1eddng \u0111\u1ebfn T\u00e2y V\u1ef1c.`,
  `Ng\u01b0\u1eddi Hung N\u00f4 \u0111\u00e0nh ph\u1ea3i r\u00fat lui v\u1ec1 khu v\u1ef1c ph\u00eda b\u1eafc sa m\u1ea1c r\u1ed9ng l\u1edbn xa x\u00f4i.`,
  `Ch\u01b0a d\u1eebng l\u1ea1i \u1edf \u0111\u00f3, v\u00e0o n\u0103m 119 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `Ho\u1eafc Kh\u1ee9 B\u1ec7nh v\u00e0 V\u1ec7 Thanh m\u1ed9t l\u1ea7n n\u1eefa ti\u1ebfn s\u00e2u v\u00e0o M\u1ea1c B\u1eafc.`,
  `L\u1ea7n n\u00e0y, Ho\u1eafc Kh\u1ee9 B\u1ec7nh truy \u0111u\u1ed5i ng\u01b0\u1eddi Hung N\u00f4 \u0111\u1ebfn t\u1eadn Lang C\u01b0 H\u01b0 S\u01a1n, n\u01a1i t\u1ebf tr\u1eddi c\u1ee7a ng\u01b0\u1eddi Hung N\u00f4,`,
  `t\u1ee9c l\u00e0 khu v\u1ef1c N\u1ed9i M\u00f4ng C\u1ed5 ng\u00e0y nay.`,
  `T\u1ea1i \u0111\u00e2y, \u00f4ng \u0111\u00e3 d\u1eabn d\u1eaft qu\u00e2n H\u00e1n ti\u1ebfn h\u00e0nh nghi l\u1ec5 t\u1ebf tr\u1eddi \u0111\u1ea5t.`,
  `Ho\u1eafc Kh\u1ee9 B\u1ec7nh \u0111\u00e3 cho th\u1ebf gi\u1edbi th\u1ea5y s\u1ef1 tr\u1ed7i d\u1eady c\u1ee7a \u0110\u1ebf qu\u1ed1c \u0110\u1ea1i H\u00e1n.`,
  `Sau tr\u1eadn chi\u1ebfn n\u00e0y, ng\u01b0\u1eddi Hung N\u00f4 b\u1ecb Ho\u1eafc Kh\u1ee9 B\u1ec7nh \u0111\u1ea9y v\u1ec1 ch\u00e2u \u00c2u \u0111\u00e3 kh\u00f4ng c\u00f2n kh\u1ea3 n\u0103ng v\u00e0 d\u0169ng kh\u00ed \u0111\u1ec3 khi\u00eau kh\u00edch nh\u00e0 H\u00e1n n\u1eefa.`,
  `Nh\u00e0 H\u00e1n cu\u1ed1i c\u00f9ng \u0111\u00e3 lo\u1ea1i b\u1ecf \u0111\u01b0\u1ee3c m\u1ed1i \u0111e d\u1ecda t\u1eeb ng\u01b0\u1eddi Hung N\u00f4,`,
  `m\u00e0 l\u00fac n\u00e0y Ho\u1eafc Kh\u1ee9 B\u1ec7nh c\u0169ng ch\u1ec9 m\u1edbi hai m\u01b0\u01a1i hai tu\u1ed5i.`,
  `Tuy nhi\u00ean, r\u1ea5t \u0111\u00e1ng ti\u1ebfc, c\u00f3 l\u1ebd l\u00e0 do tr\u1eddi ghen t\u00e0i n\u0103ng,`,
  `Ho\u1eafc Kh\u1ee9 B\u1ec7nh \u0111\u00e3 qua \u0111\u1eddi v\u00ec b\u1ec7nh t\u1eadt v\u00e0o n\u0103m hai m\u01b0\u01a1i t\u01b0 tu\u1ed5i.`,
  `Sau \u0111\u00f3 Tr\u01b0\u01a1ng Khi\u00ean l\u1ea1i m\u1ed9t l\u1ea7n n\u1eefa \u0111i s\u1ee9 T\u00e2y V\u1ef1c,`,
  `l\u1ea7n n\u00e0y \u00f4ng \u0111\u00e3 \u0111i theo m\u1ed9t con \u0111\u01b0\u1eddng m\u1edbi,`,
  `v\u00e0 con \u0111\u01b0\u1eddng m\u1edbi n\u00e0y ch\u00ednh l\u00e0 Con \u0111\u01b0\u1eddng t\u01a1 l\u1ee5a sau n\u00e0y.`,
  `Sau \u0111\u00f3, L\u01b0u Tri\u1ec7t \u0111\u1ea7y tham v\u1ecdng l\u1ea1i t\u1ea5n c\u00f4ng Nam Vi\u1ec7t,`,
  `Tri\u1ec1u Ti\u00ean v\u00e0 m\u1ed9t s\u1ed1 ti\u1ec3u qu\u1ed1c \u1edf T\u00e2y Nam,`,
  `m\u1edf r\u1ed9ng \u0111\u00e1ng k\u1ec3 l\u00e3nh th\u1ed5 nh\u00e0 H\u00e1n.`,
  `L\u00fac n\u00e0y, L\u01b0u Tri\u1ec7t \u0111\u00e3 d\u00f9ng th\u1ef1c l\u1ef1c ch\u1ee9ng minh s\u1ef1 h\u00f9ng m\u1ea1nh c\u1ee7a \u0111\u1ebf qu\u1ed1c H\u00e1n,`,
  `nh\u01b0ng c\u0169ng v\u00ec chi\u1ebfn tranh li\u00ean mi\u00ean, qu\u1ed1c kh\u1ed1 tr\u1ed1ng r\u1ed7ng,`,
  `L\u01b0u Tri\u1ec7t v\u1ec1 c\u01a1 b\u1ea3n \u0111\u00e3 v\u00e9t s\u1ea1ch ng\u00e2n kh\u1ed1 nh\u00e0 H\u00e1n,`,
  `m\u00e2u thu\u1eabn n\u1ed9i b\u1ed9 nh\u00e0 H\u00e1n c\u0169ng d\u1ea7n xu\u1ea5t hi\u1ec7n.`,
  `N\u1eeda \u0111\u1eddi \u0111\u1ea7u H\u00e1n V\u0169 \u0110\u1ebf L\u01b0u Tri\u1ec7t d\u1ed3n s\u1ee9c v\u00e0o vi\u1ec7c m\u1edf r\u1ed9ng l\u00e3nh th\u1ed5 b\u00ean ngo\u00e0i,`,
  `n\u1eeda \u0111\u1eddi sau \u00f4ng s\u1ebd quay tr\u1edf l\u1ea1i tri\u1ec1u \u0111\u00ecnh.`,
  `Ho\u00e0ng h\u1eadu V\u1ec7 T\u1eed Phu n\u0103m x\u01b0a xinh \u0111\u1eb9p nh\u01b0 hoa c\u0169ng kh\u00f4ng tho\u00e1t kh\u1ecfi l\u01b0\u1ee1i dao c\u1ee7a th\u1eddi gian.`,
  `S\u1ee7ng phi m\u1edbi c\u1ee7a L\u01b0u Tri\u1ec7t t\u00ean L\u00fd phu nh\u00e2n,`,
  `sau khi \u0111\u01b0\u1ee3c s\u1ee7ng \u00e1i, b\u00e0 c\u0169ng sinh cho L\u01b0u Tri\u1ec7t m\u1ed9t ng\u01b0\u1eddi con trai.`,
  `L\u00fd phu nh\u00e2n c\u00f3 m\u1ed9t ng\u01b0\u1eddi anh t\u00ean L\u00fd Qu\u1ea3ng L\u1ee3i,`,
  `nh\u1edd L\u00fd phu nh\u00e2n m\u00e0 \u0111\u01b0\u1ee3c l\u00e0m quan.`,
  `L\u00fd phu nh\u00e2n m\u1ecdi th\u1ee9 \u0111\u1ec1u t\u1ed1t, ch\u1ec9 c\u00f3 s\u1ee9c kh\u1ecfe kh\u00f4ng t\u1ed1t.`,
  `Kh\u00f4ng l\u00e2u sau khi sinh con trai, b\u00e0 qua \u0111\u1eddi.`,
  `Tr\u01b0\u1edbc khi ch\u1ebft, b\u00e0 mong L\u01b0u Tri\u1ec7t \u0111\u1ed1i x\u1eed t\u1ed1t v\u1edbi anh trai m\u00ecnh l\u00e0 L\u00fd Qu\u1ea3ng L\u1ee3i.`,
  `L\u01b0u Tri\u1ec7t th\u00edch ng\u1ef1a, bi\u1ebft T\u00e2y V\u1ef1c \u0110\u1ea1i Uy\u00ean c\u00f3 m\u1ed9t lo\u1ea1i ng\u1ef1a H\u00e3n Huy\u1ebft B\u1ea3o M\u00e3 n\u1ed5i ti\u1ebfng.`,
  `Ban \u0111\u1ea7u \u00f4ng mu\u1ed1n mua, nh\u01b0ng ng\u01b0\u1eddi ta kh\u00f4ng b\u00e1n.`,
  `Th\u1ebf l\u00e0 L\u01b0u Tri\u1ec7t c\u1eed L\u00fd Qu\u1ea3ng L\u1ee3i \u0111i \u0111\u00e1nh \u0110\u1ea1i Uy\u00ean \u0111\u1ec3 c\u01b0\u1edbp ng\u1ef1a.`,
  `Th\u1ef1c ra L\u00fd Qu\u1ea3ng L\u1ee3i kh\u00f4ng c\u00f3 t\u00e0i c\u00e1n g\u00ec, anh ta ch\u1ec9 g\u1eb7p may.`,
  `Khi \u0111\u00e1nh \u0111\u1ebfn \u0110\u1ea1i Uy\u00ean, \u0110\u1ea1i Uy\u00ean \u0111ang x\u1ea3y ra n\u1ed9i chi\u1ebfn.`,
  `L\u00fd Qu\u1ea3ng L\u1ee3i \u0111\u00e3 ch\u1edbp th\u1eddi c\u01a1, kh\u00f4ng ch\u1ec9 c\u01b0\u1edbp \u0111\u01b0\u1ee3c ng\u1ef1a v\u1ec1,`,
  `m\u00e0 c\u00f2n khi\u1ebfn c\u00e1c n\u01b0\u1edbc T\u00e2y V\u1ef1c \u0111\u1ec1u th\u1ea7n ph\u1ee5c nh\u00e0 \u0110\u1ea1i H\u00e1n.`,
  `Sau khi tr\u1edf v\u1ec1, anh ta \u0111\u01b0\u1ee3c L\u01b0u Tri\u1ec7t phong l\u00e0m H\u1ea3i T\u00e2y H\u1ea7u.`,
  `L\u00fd Qu\u1ea3ng L\u1ee3i t\u1eeb \u0111\u00f3 tr\u1edf n\u00ean ki\u00eau ng\u1ea1o. H\u1eafn ngh\u0129 m\u00ecnh t\u00e0i gi\u1ecfi nh\u01b0 v\u1eady,`,
  `ho\u00e0ng th\u01b0\u1ee3ng l\u1ea1i y\u00eau qu\u00fd em g\u00e1i m\u00ecnh \u0111\u1ebfn th\u1ebf,`,
  `m\u1eb7c d\u00f9 em g\u00e1i \u0111\u00e3 qua \u0111\u1eddi, nh\u01b0ng v\u1eabn \u0111\u1ec3 l\u1ea1i m\u1ed9t ng\u01b0\u1eddi con trai l\u00e0 X\u01b0\u01a1ng \u1ea4p V\u01b0\u01a1ng.`,
  `\u0110\u1ec1u l\u00e0 con c\u1ee7a L\u01b0u Tri\u1ec7t, t\u1ea1i sao con trai c\u1ee7a V\u1ec7 T\u1eed Phu l\u00e0 L\u01b0u C\u1ee9 c\u00f3 th\u1ec3 l\u00e0m th\u00e1i t\u1eed,`,
  `c\u00f2n ch\u00e1u ngo\u1ea1i c\u1ee7a m\u00ecnh l\u00e0 X\u01b0\u01a1ng \u1ea4p V\u01b0\u01a1ng l\u1ea1i kh\u00f4ng th\u1ec3?`,
  `Th\u1ebf l\u00e0 m\u1ed9t \u00e2m m\u01b0u d\u1ea7n \u0111\u01b0\u1ee3c nung n\u1ea5u d\u01b0\u1edbi s\u1ef1 thao t\u00fang c\u1ee7a L\u00fd Qu\u1ea3ng L\u1ee3i v\u00e0 b\u00e8 \u0111\u1ea3ng.`,
  `M\u1ed9t h\u00f4m, L\u01b0u Tri\u1ec7t \u0111ang \u0111i d\u1ea1o trong cung,`,
  `b\u1ed7ng nhi\u00ean nh\u00ecn th\u1ea5y m\u1ed9t ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng kh\u1ea3 nghi,`,
  `\u00f4ng li\u1ec1n sai ng\u01b0\u1eddi \u0111i b\u1eaft nh\u01b0ng ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng \u0111\u00f3 \u0111\u00e3 tr\u1ed1n tho\u00e1t,`,
  `m\u00e0 trong cung kh\u00f4ng ai bi\u1ebft ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng \u0111\u00f3 v\u00e0o b\u1eb1ng c\u00e1ch n\u00e0o.`,
  `M\u1ed9t ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng kh\u00f4ng r\u00f5 th\u00e2n ph\u1eadn v\u00e0o trong cung,`,
  `r\u1ed3i l\u1ea1i bi\u1ebfn m\u1ea5t m\u1ed9t c\u00e1ch kh\u00f3 hi\u1ec3u,`,
  `th\u1eadm ch\u00ed kh\u00f4ng m\u1ed9t ai bi\u1ebft.`,
  `L\u01b0u Tri\u1ec7t n\u1ed5i gi\u1eadn, l\u1eadp t\u1ee9c \u0111\u00f3ng c\u1eeda th\u00e0nh Tr\u01b0\u1eddng An,`,
  `th\u1ec1 ph\u1ea3i t\u00ecm ra ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng \u0111\u00f3.`,
  `L\u00fac n\u00e0y, t\u1ec3 t\u01b0\u1edbng nh\u00e0 H\u00e1n l\u00e0 C\u00f4ng T\u00f4n H\u1ea1, \u00f4ng c\u00f3 m\u1ed9t ng\u01b0\u1eddi con trai t\u00ean l\u00e0 C\u00f4ng T\u00f4n K\u00ednh S\u00e2m.`,
  `C\u00f4ng T\u00f4n K\u00ednh S\u00e2m \u0111\u00e3 bi\u1ec3n th\u1ee7 c\u00f4ng qu\u1ef9 n\u00ean b\u1ecb t\u1ed1ng v\u00e0o ng\u1ee5c.`,
  `C\u00f4ng T\u00f4n H\u1ea1 mu\u1ed1n l\u1eadp c\u00f4ng chu\u1ed9c t\u1ed9i cho con trai,`,
  `n\u00ean \u0111\u00e3 t\u1ef1 m\u00ecnh xung phong \u0111i b\u1eaft ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng \u0111\u00e3 bi\u1ebfn m\u1ea5t trong cung.`,
  `Ng\u01b0\u1eddi m\u00e0 L\u01b0u Tri\u1ec7t \u0111\u00e3 m\u1ea5t bao c\u00f4ng s\u1ee9c v\u1eabn kh\u00f4ng t\u00ecm th\u1ea5y,`,
  `\u0110\u00e3 b\u1ecb C\u00f4ng T\u00f4n H\u1ea1 b\u1eaft m\u1ed9t c\u00e1ch d\u1ec5 d\u00e0ng.`,
  `T\u1ea5t nhi\u00ean, b\u00e2y gi\u1edd t\u1eeb g\u00f3c \u0111\u1ed9 c\u1ee7a ch\u00fang ta,`,
  `\u0110\u00e2y l\u00e0 m\u1ed9t c\u00e1i b\u1eaby, nh\u01b0ng C\u00f4ng T\u00f4n H\u1ea1 l\u00fac \u0111\u00f3 kh\u00f4ng h\u1ec1 hay bi\u1ebft.`,
  `Ng\u01b0\u1eddi b\u1ecb b\u1eaft t\u00ean l\u00e0 Chu Th\u1ebf An,`,
  `Sau khi b\u1ecb b\u1eaft, h\u1eafn d\u00e2ng th\u01b0 v\u1ea1ch tr\u1ea7n, n\u00f3i C\u00f4ng T\u00f4n K\u00ednh Th\u00e2m v\u00e0 con g\u00e1i c\u1ee7a V\u1ec7 T\u1eed Phu, c\u00f4ng ch\u00faa D\u01b0\u01a1ng th\u1ecb, t\u01b0 th\u00f4ng.`,
  `Hai ng\u01b0\u1eddi h\u1ee3p s\u1ee9c d\u00f9ng thu\u1eadt ph\u00f9 th\u1ee7y nguy\u1ec1n r\u1ee7a H\u00e1n V\u0169 \u0110\u1ebf L\u01b0u Tri\u1ec7t.`,
  `Thu\u1eadt ph\u00f9 th\u1ee7y l\u00e0 vi\u1ebft t\u00ean m\u1ed9t ng\u01b0\u1eddi l\u00ean h\u00ecnh n\u1ed9m,`,
  `Sau \u0111\u00f3 ch\u00f4n xu\u1ed1ng \u0111\u1ea5t,`,
  `Thi tri\u1ec3n ph\u00e9p thu\u1eadt v\u00e0 ni\u1ec7m ch\u00fa, ng\u01b0\u1eddi b\u1ecb vi\u1ebft t\u00ean s\u1ebd g\u1eb7p xui x\u1ebbo.`,
  `L\u01b0u Tri\u1ec7t nghe l\u1eddi Chu Th\u1ebf An, li\u1ec1n ph\u00e1i ng\u01b0\u1eddi \u0111i \u0111i\u1ec1u tra,`,
  `T\u1ea1i n\u01a1i Chu Th\u1ebf An n\u00f3i, qu\u1ea3 nhi\u00ean t\u00ecm th\u1ea5y h\u00ecnh n\u1ed9m,`,
  `D\u00e1m nguy\u1ec1n r\u1ee7a ho\u00e0ng \u0111\u1ebf, k\u1ebft qu\u1ea3 th\u00ec kh\u1ecfi ph\u1ea3i n\u00f3i,`,
  `L\u01b0u Tri\u1ec7t l\u1eadp t\u1ee9c tru di tam t\u1ed9c nh\u00e0 h\u1ecd C\u00f4ng T\u00f4n.`,
  `V\u1ee3 c\u1ee7a C\u00f4ng T\u00f4n H\u1ea1 l\u00e0 ch\u1ecb ru\u1ed9t c\u1ee7a V\u1ec7 T\u1eed Phu v\u00e0 V\u1ec7 Thanh,`,
  `V\u00ec v\u1eady, nh\u00e0 h\u1ecd V\u1ec7 c\u0169ng b\u1ecb li\u00ean l\u1ee5y.`,
  `Con g\u00e1i V\u1ec7 T\u1eed Phu v\u00e0 con trai c\u1ea3 c\u1ee7a V\u1ec7 Thanh l\u1ea7n l\u01b0\u1ee3t b\u1ecb gi\u1ebft.`,
  `V\u1ec7 Thanh v\u00e0 Ho\u1eafc Kh\u1ee9 B\u1ec7nh, ni\u1ec1m t\u1ef1 h\u00e0o c\u1ee7a gia t\u1ed9c h\u1ecd V\u1ec7, c\u0169ng \u0111\u00e3 qua \u0111\u1eddi.`,
  `Cu\u1ed1i c\u00f9ng, nh\u00e0 h\u1ecd V\u1ec7 ch\u1ec9 c\u00f2n l\u1ea1i duy nh\u1ea5t ho\u00e0ng h\u1eadu V\u1ec7 T\u1eed Phu.`,
  `Chuy\u1ec7n ch\u01b0a d\u1eebng l\u1ea1i \u1edf \u0111\u00f3,`,
  `Trong tri\u1ec1u c\u00f3 m\u1ed9t \u0111\u1ea1i th\u1ea7n t\u00ean Tr\u01b0\u01a1ng An, c\u00f3 m\u1ed1i quan h\u1ec7 kh\u00f4ng t\u1ed1t v\u1edbi th\u00e1i t\u1eed L\u01b0u C\u1ee9.`,
  `\u00d4ng ta s\u1ee3 r\u1eb1ng sau khi L\u01b0u Tri\u1ec7t m\u1ea5t, L\u01b0u C\u1ee9 l\u00ean ng\u00f4i s\u1ebd gi\u1ebft m\u00ecnh,`,
  `Quy\u1ebft \u0111\u1ecbnh ra tay tr\u01b0\u1edbc \u0111\u1ec3 chi\u1ebfm \u01b0u th\u1ebf,`,
  `L\u1ee3i d\u1ee5ng v\u1ee5 \u00e1n Vu c\u1ed5 \u0111\u1ec3 vu oan cho L\u01b0u C\u1ee9.`,
  `Tr\u01b0\u01a1ng An gi\u1ea3 th\u1ea7n gi\u1ea3 qu\u1ef7, l\u00e9n l\u00fat \u0111\u00e0o \u0111\u01b0\u1ee3c m\u1ed9t con r\u1ed1i g\u1ed7 \u1edf ch\u1ed7 c\u1ee7a L\u01b0u C\u1ee9.`,
  `L\u01b0u C\u1ee9 l\u00e0 ng\u01b0\u1eddi \u00f4n h\u00f2a, th\u1eadt th\u00e0, s\u1ee3 m\u00ecnh kh\u00f4ng gi\u1ea3i th\u00edch r\u00f5 r\u00e0ng \u0111\u01b0\u1ee3c,`,
  `L\u1ea1i ngh\u0129 \u0111\u1ebfn k\u1ebft c\u1ee5c bi th\u1ea3m c\u1ee7a nh\u1eefng ng\u01b0\u1eddi t\u1eebng b\u1ecb li\u00ean l\u1ee5y b\u1edfi thu\u1eadt Vu c\u1ed5 tr\u01b0\u1edbc \u0111\u00e2y.`,
  `Trong l\u00fac ho\u1ea3ng lo\u1ea1n, L\u01b0u C\u1ee9 \u0111\u00e3 t\u1ef1 \u00fd x\u1eed t\u1eed Tr\u01b0\u01a1ng An,`,
  `\u0110\u1ec3 t\u1ef1 b\u1ea3o v\u1ec7 m\u00ecnh c\u00f2n ph\u00e1t \u0111\u1ed9ng binh bi\u1ebfn.`,
  `C\u00f2n \u0111\u1ed1i v\u1edbi L\u01b0u Tri\u1ec7t,`,
  `L\u01b0u C\u1ee9 l\u00e0 ng\u01b0\u1eddi k\u1ebf nhi\u1ec7m \u0111\u01b0\u1ee3c L\u01b0u Tri\u1ec7t b\u1ed3i d\u01b0\u1ee1ng nhi\u1ec1u n\u0103m,`,
  `\u00d4ng \u1ea5y ch\u01b0a bao gi\u1edd ngh\u0129 \u0111\u1ebfn vi\u1ec7c gi\u1ebft L\u01b0u C\u1ee9.`,
  `Tuy nhi\u00ean, l\u00fac n\u00e0y m\u1ecdi vi\u1ec7c \u0111\u00e3 v\u01b0\u1ee3t kh\u1ecfi t\u1ea7m ki\u1ec3m so\u00e1t,`,
  `Hi\u1ec7n t\u1ea1i \u0111\u00e3 bi\u1ebfn th\u00e0nh L\u01b0u Tri\u1ec7t v\u00e0 L\u01b0u C\u1ee9 hai cha con \u0111\u1ed1i \u0111\u1ea7u binh \u0111ao.`,
  `Sau \u0111\u00f3, L\u01b0u C\u1ee9 th\u1ea5t b\u1ea1i v\u00e0 t\u1ef1 s\u00e1t,`,
  `M\u1eb9 \u00f4ng l\u00e0 V\u1ec7 T\u1eed Phu c\u0169ng t\u1ef1 s\u00e1t trong \u0111au bu\u1ed3n v\u00e0 ph\u1eabn u\u1ea5t.`,
  `Gia \u0111\u00ecnh L\u01b0u C\u1ee9 b\u1ecb di\u1ec7t m\u00f4n,`,
  `Ch\u1ec9 c\u00f3 m\u1ed9t \u0111\u1ee9a ch\u00e1u nh\u1ecf c\u1ee7a L\u01b0u C\u1ee9 may m\u1eafn tho\u00e1t n\u1ea1n,`,
  `\u0110\u00e2y l\u00e0 chuy\u1ec7n sau n\u00e0y.`,
  `Tai h\u1ecda Vu C\u1ed5 \u0111\u00e3 khi\u1ebfn h\u00e0ng v\u1ea1n ng\u01b0\u1eddi ch\u1ebft oan.`,
  `Sau khi tai h\u1ecda l\u1eafng xu\u1ed1ng,`,
  `L\u01b0u Tri\u1ec7t nh\u1eadn ra r\u1eb1ng m\u1ecdi chuy\u1ec7n c\u00f3 l\u1ebd kh\u00f4ng \u0111\u01a1n gi\u1ea3n nh\u01b0 \u00f4ng ngh\u0129,`,
  `Th\u1ebf l\u00e0 \u00f4ng cho \u0111i\u1ec1u tra l\u1ea1i to\u00e0n b\u1ed9 s\u1ef1 vi\u1ec7c,`,
  `M\u1edbi ph\u00e1t hi\u1ec7n m\u00ecnh \u0111\u00e3 oan u\u1ed5ng cho L\u01b0u C\u1ee9.`,
  `Nh\u01b0ng t\u1ea5t c\u1ea3 \u0111\u00e3 qu\u00e1 mu\u1ed9n r\u1ed3i,`,
  `L\u01b0u Tri\u1ec7t tu\u1ed5i gi\u00e0 s\u1ee9c y\u1ebfu v\u00f4 c\u00f9ng t\u1ef1 tr\u00e1ch b\u1ea3n th\u00e2n,`,
  `v\u00e0 \u0111\u1ed1i m\u1eb7t v\u1edbi vi\u1ec7c ng\u00e2n kh\u1ed1 tr\u1ed1ng r\u1ed7ng sau khi chinh ph\u1ea1t Hung N\u00f4,`,
  `m\u00e2u thu\u1eabn trong n\u01b0\u1edbc ng\u00e0y c\u00e0ng gay g\u1eaft.`,
  `L\u00fac n\u00e0y, L\u01b0u Tri\u1ec7t nh\u00ecn l\u1ea1i cu\u1ed9c \u0111\u1eddi m\u00ecnh,`,
  `\u00f4ng quy\u1ebft \u0111\u1ecbnh th\u1ef1c hi\u1ec7n ch\u00ednh s\u00e1ch ph\u1ee5c h\u01b0ng,`,
  `ngh\u1ec9 ng\u01a1i d\u01b0\u1ee1ng s\u1ee9c. H\u00e0nh \u0111\u1ed9ng n\u00e0y \u0111\u00e3 phanh g\u1ea5p cho nh\u00e0 H\u00e1n \u0111ang tr\u00ean \u0111\u00e0 suy t\u00e0n.`,
  `Sau \u0111\u00f3, \u00f4ng \u0111\u01b0a ra quy\u1ebft \u0111\u1ecbnh cu\u1ed1i c\u00f9ng trong cu\u1ed9c \u0111\u1eddi,`,
  `l\u1eadp con trai \u00fat L\u01b0u Ph\u1ea5t L\u0103ng l\u00e0m th\u00e1i t\u1eed.`,
  `\u0110\u1ec3 ng\u0103n ch\u1eb7n s\u1ef1 vi\u1ec7c L\u00e3 Tr\u0129 thao t\u00fang ho\u00e0ng \u0111\u1ebf n\u0103m x\u01b0a t\u00e1i di\u1ec5n,`,
  `L\u01b0u Tri\u1ec7t \u0111\u00e3 gi\u1ebft m\u1eb9 ru\u1ed9t c\u1ee7a L\u01b0u Ph\u1ea5t L\u0103ng l\u00e0 Tri\u1ec7u Ti\u1ec7p D\u01b0,`,
  `t\u1ee9c C\u00e2u D\u1eb7c phu nh\u00e2n,`,
  `v\u00e0 ch\u1ecdn b\u1ed1n \u0111\u1ea1i th\u1ea7n ph\u1ee5 ch\u00ednh,`,
  `trong \u0111\u00f3 c\u00f3 Ho\u1eafc Quang.`,
  `Ho\u1eafc Quang l\u00e0 em c\u00f9ng cha kh\u00e1c m\u1eb9 v\u1edbi Ho\u1eafc Kh\u1ee9 B\u1ec7nh,`,
  `trong khi anh trai t\u1ecfa s\u00e1ng tr\u00ean chi\u1ebfn tr\u01b0\u1eddng,`,
  `Ho\u1eafc Quang l\u00e0m m\u1ed9t ch\u1ee9c quan nh\u1ecf trong cung.`,
  `\u00d4ng ta l\u00e0 ng\u01b0\u1eddi c\u1ea9n tr\u1ecdng, t\u1ec9 m\u1ec9,`,
  `r\u1ea5t th\u1ea5u hi\u1ec3u \u0111\u1ea1o l\u00e0m quan,`,
  `d\u1ea7n d\u1ea7n \u0111\u01b0\u1ee3c L\u01b0u Tri\u1ec7t tin t\u01b0\u1edfng s\u00e2u s\u1eafc.`,
  `V\u00ec v\u1eady, cu\u1ed1i c\u00f9ng \u00f4ng ta \u0111\u00e3 giao ph\u00f3 con trai \u00fat L\u01b0u Ph\u00fac L\u00e2m cho Ho\u1eafc Quang.`,
  `Ho\u00e0n th\u00e0nh t\u1ea5t c\u1ea3 nh\u1eefng vi\u1ec7c n\u00e0y, H\u00e1n V\u0169 \u0110\u1ebf L\u01b0u Tri\u1ec7t c\u0169ng \u0111i \u0111\u1ebfn cu\u1ed1i \u0111\u1eddi.`,
  `H\u00e1n Chi\u00eau \u0110\u1ebf L\u01b0u Ph\u00fac L\u00e2m l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf \u0111\u00e1ng \u0111\u01b0\u1ee3c k\u1ef3 v\u1ecdng,`,
  `\u00f4ng ta tr\u1ebb tu\u1ed5i t\u00e0i cao, r\u1ea5t gi\u1ed1ng H\u00e1n V\u0169 \u0110\u1ebf khi c\u00f2n tr\u1ebb,`,
  `d\u01b0\u1edbi s\u1ef1 gi\u00fap \u0111\u1ee1 c\u1ee7a Ho\u1eafc Quang, \u0111\u00e3 qu\u1ea3n l\u00fd \u0111\u1ea5t n\u01b0\u1edbc r\u1ea5t t\u1ed1t,`,
  `l\u00e0m d\u1ecbu \u0111i c\u00e1c m\u00e2u thu\u1eabn x\u00e3 h\u1ed9i cu\u1ed1i th\u1eddi H\u00e1n V\u0169 \u0110\u1ebf.`,
  `Nh\u01b0ng \u00f4ng ta ch\u1ec9 s\u1ed1ng \u0111\u1ebfn hai m\u01b0\u01a1i m\u1ed1t tu\u1ed5i th\u00ec l\u00e2m b\u1ec7nh qua \u0111\u1eddi,`,
  `l\u1ea1i kh\u00f4ng c\u00f3 con trai.`,
  `L\u00fac n\u00e0y, Ho\u1eafc Quang \u0111\u00e3 tr\u1edf th\u00e0nh quy\u1ec1n th\u1ea7n s\u1ed1 m\u1ed9t c\u1ee7a nh\u00e0 H\u00e1n,`,
  `\u00f4ng ta \u0111\u00e3 ch\u1ecdn m\u1ed9t ng\u01b0\u1eddi ch\u00e1u c\u1ee7a L\u01b0u Tri\u1ec7t l\u00e0 L\u01b0u H\u1ea1 l\u00ean k\u1ebf v\u1ecb.`,
  `Nh\u01b0ng L\u01b0u H\u1ea1 kh\u00f4ng l\u00e0m n\u00ean tr\u00f2 tr\u1ed1ng g\u00ec,`,
  `ch\u01b0a l\u00ean ng\u00f4i \u0111\u01b0\u1ee3c bao l\u00e2u, \u00f4ng ta \u0111\u00e3 b\u1eaft \u0111\u1ea7u ham \u0103n l\u01b0\u1eddi l\u00e0m,`,
  `Hoang d\u00e2m v\u00f4 \u0111\u1ed9. Ho\u1eafc Quang th\u1ef1c s\u1ef1 kh\u00f4ng th\u1ec3 ch\u1ecbu \u0111\u1ef1ng th\u00eam n\u1eefa,`,
  `T\u1ef1 m\u00ecnh ch\u1ecdn ra c\u00e1i th\u1ee9 g\u00ec th\u1ebf n\u00e0y?`,
  `C\u00f3 th\u1ec3 l\u1eadp ng\u01b0\u01a1i th\u00ec c\u0169ng c\u00f3 th\u1ec3 ph\u1ebf ng\u01b0\u01a1i.`,
  `Th\u1ebf l\u00e0 L\u01b0u H\u1ea1, ch\u1ec9 l\u00e0m ho\u00e0ng \u0111\u1ebf 27 ng\u00e0y, \u0111\u00e3 b\u1ecb ph\u1ebf tru\u1ea5t.`,
  `Sau \u0111\u00f3 b\u1ecb \u0111\u00e0y \u0111\u1ebfn Giang T\u00e2y l\u00e0m H\u1ea3i H\u00f4n H\u1ea7u.`,
  `V\u00ec b\u1ecb ph\u1ebf tru\u1ea5t, n\u00ean \u00f4ng \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 H\u00e1n Ph\u1ebf \u0110\u1ebf.`,
  `Sau khi ph\u1ebf tru\u1ea5t L\u01b0u H\u1ea1, n\u00ean ch\u1ecdn ai l\u00e0m ho\u00e0ng \u0111\u1ebf \u0111\u00e2y?`,
  `L\u1ea7n n\u00e0y Ho\u1eafc Quang t\u00ecm th\u1ea5y L\u01b0u B\u1ec7nh D\u0129, t\u1ee9c H\u00e1n Tuy\u00ean \u0110\u1ebf L\u01b0u Tu\u00e2n sau n\u00e0y.`,
  `Th\u00e2n th\u1ebf c\u1ee7a H\u00e1n Tuy\u00ean \u0110\u1ebf L\u01b0u B\u1ec7nh D\u0129 kh\u00e1 \u0111\u1eb7c bi\u1ec7t,`,
  `N\u0103m \u0111\u00f3 Th\u00e1i t\u1eed L\u01b0u C\u1ee9 v\u00ec lo\u1ea1n Vu C\u1ed5 m\u00e0 c\u1ea3 gia \u0111\u00ecnh b\u1ecb gi\u1ebft,`,
  `Ch\u1ec9 c\u00f2n s\u00f3t l\u1ea1i m\u1ed9t \u0111\u1ee9a ch\u00e1u nh\u1ecf l\u01b0u l\u1ea1c trong d\u00e2n gian,`,
  `\u0110\u00f3 ch\u00ednh l\u00e0 L\u01b0u B\u1ec7nh D\u0129.`,
  `Sau n\u00e0y H\u00e1n V\u0169 \u0110\u1ebf L\u01b0u Tri\u1ec7t bi\u1ebft m\u00ecnh \u0111\u00e3 gi\u1ebft nh\u1ea7m L\u01b0u C\u1ee9,`,
  `Bi\u1ebft L\u01b0u B\u1ec7nh D\u0129 v\u1eabn c\u00f2n s\u1ed1ng, \u00f4ng \u0111\u00e3 kh\u00f4i ph\u1ee5c th\u00e2n ph\u1eadn ho\u00e0ng t\u1ed9c cho L\u01b0u B\u1ec7nh D\u0129.`,
  `V\u00ec L\u01b0u B\u1ec7nh D\u0129 t\u1eeb nh\u1ecf \u0111\u00e3 l\u1edbn l\u00ean trong d\u00e2n gian,`,
  `Khi c\u00f2n tr\u1ebb, \u00f4ng c\u01b0\u1edbi H\u1ee9a B\u00ecnh Qu\u00e2n, con g\u00e1i c\u1ee7a m\u1ed9t th\u1ecb v\u1ec7.`,
  `Sau khi l\u00ean ng\u00f4i, Ho\u1eafc Quang n\u1eafm h\u1ebft quy\u1ec1n h\u00e0nh trong tri\u1ec1u, L\u01b0u B\u1ec7nh D\u0129 kh\u00f4ng c\u00f3 th\u1ef1c quy\u1ec1n.`,
  `\u00d4ng \u0111\u00e0nh ngoan ngo\u00e3n l\u00e0m m\u1ed9t con r\u1ed1i c\u00f3 n\u0103ng l\u1ef1c d\u01b0\u1edbi tay Ho\u1eafc Quang.`,
  `Sau n\u00e0y, H\u1ee9a Ho\u00e0ng h\u1eadu v\u1ed1n r\u1ea5t t\u00ecnh c\u1ea3m v\u1edbi L\u01b0u B\u1ec7nh D\u0129 b\u1ecb v\u1ee3 c\u1ee7a Ho\u1eafc Quang \u0111\u1ea7u \u0111\u1ed9c ch\u1ebft.`,
  `L\u01b0u B\u1ec7nh D\u0129 \u0111\u00e0nh n\u00edn nh\u1ecbn l\u1eadp Ho\u1eafc Th\u1eeba Qu\u00e2n, con g\u00e1i c\u1ee7a Ho\u1eafc Quang, l\u00e0m ho\u00e0ng h\u1eadu.`,
  `Sau khi Ho\u1eafc Quang ch\u1ebft, ng\u01b0\u1eddi nh\u00e0 h\u1ecd Ho\u1eafc th\u1eadm ch\u00ed c\u00f2n mu\u1ed1n \u0111\u1ea7u \u0111\u1ed9c L\u01b0u B\u1ec7nh D\u0129 \u0111\u1ec3 c\u01b0\u1edbp ng\u00f4i.`,
  `L\u01b0u B\u1ec7nh D\u0129, ng\u01b0\u1eddi \u0111\u00e3 n\u00edn nh\u1ecbn nhi\u1ec1u n\u0103m, cu\u1ed1i c\u00f9ng kh\u00f4ng c\u00f2n nh\u01b0\u1ee3ng b\u1ed9 n\u1eefa.`,
  `V\u1edbi th\u1ef1c l\u1ef1c nh\u1ea5t \u0111\u1ecbnh, \u00f4ng \u0111\u00e3 nh\u1ed5 t\u1eadn g\u1ed1c to\u00e0n b\u1ed9 gia t\u1ed9c h\u1ecd Ho\u1eafc.`,
  `V\u00e0 gi\u00e0nh l\u1ea1i quy\u1ec1n l\u1ef1c ho\u00e0ng gia c\u1ee7a m\u00ecnh.`,
  `V\u00ec l\u1edbn l\u00ean trong d\u00e2n gian, \u00f4ng r\u1ea5t hi\u1ec3u n\u1ed7i kh\u1ed5 c\u1ee7a d\u00e2n ch\u00fang.`,
  `Trong th\u1eddi gian t\u1ea1i v\u1ecb, L\u01b0u B\u1ec7nh D\u0129 \u0111\u00e3 th\u1ef1c hi\u1ec7n nhi\u1ec1u ch\u00ednh s\u00e1ch c\u00f3 l\u1ee3i cho d\u00e2n.`,
  `D\u1eabn d\u1eaft T\u00e2y H\u00e1n m\u1ed9t l\u1ea7n n\u1eefa \u0111i \u0111\u1ebfn th\u1ecbnh v\u01b0\u1ee3ng.`,
  `Ho\u00e0ng \u0111\u1ebf sau n\u00e0y l\u00e0 H\u00e1n Nguy\u00ean \u0110\u1ebf L\u01b0u Th\u00edch, con trai c\u1ee7a L\u01b0u B\u1ec7nh D\u0129 v\u00e0 H\u1ee9a B\u00ecnh Qu\u00e2n.`,
  `\u00d4ng l\u00e0 m\u1ed9t thanh ni\u00ean v\u0103n ngh\u1ec7.`,
  `T\u00ednh c\u00e1ch do d\u1ef1, thi\u1ebfu quy\u1ebft \u0111o\u00e1n.`,
  `T\u00ednh c\u00e1ch n\u00e0y r\u00f5 r\u00e0ng l\u00e0 kh\u00f4ng ph\u00f9 h\u1ee3p \u0111\u1ec3 l\u00e0m ho\u00e0ng \u0111\u1ebf v\u00e0 x\u1eed l\u00fd ch\u00ednh s\u1ef1.`,
  `H\u01a1n n\u1eefa, s\u1ee9c kh\u1ecfe c\u1ee7a \u00f4ng c\u0169ng kh\u00f4ng t\u1ed1t.`,
  `\u00d4ng giao h\u1ebft vi\u1ec7c tri\u1ec1u ch\u00ednh cho c\u00e1c ho\u1ea1n quan th\u1eddi b\u1ea5y gi\u1edd x\u1eed l\u00fd tr\u01b0\u1edbc.`,
  `\u0110i\u1ec1u n\u00e0y d\u1eabn \u0111\u1ebfn vi\u1ec7c ho\u1ea1n quan l\u1ed9ng quy\u1ec1n, tri\u1ec1u ch\u00ednh h\u1ed7n lo\u1ea1n.`,
  `T\u00e2y H\u00e1n t\u1eeb \u0111\u00f3 \u0111i \u0111\u1ebfn suy vong.`,
  `Sau \u0111\u00f3 con trai \u00f4ng l\u00e0 L\u01b0u Ngao k\u1ebf v\u1ecb.`,
  `L\u01b0u Ngao n\u1ed5i ti\u1ebfng nh\u1ea5t l\u00e0 h\u00e1o s\u1eafc, \u00f4ng ta v\u1eaft \u00f3c t\u1eadn h\u01b0\u1edfng l\u1ea1c th\u00fa.`,
  `Hai ch\u1ecb em Tri\u1ec7u Phi Y\u1ebfn v\u00e0 Tri\u1ec7u H\u1ee3p \u0110\u1ee9c \u0111\u01b0\u1ee3c \u00f4ng ta s\u1ee7ng \u00e1i \u0111\u1ebfn t\u1eadn tr\u1eddi.`,
  `C\u00f3 v\u1ecb ho\u00e0ng \u0111\u1ebf nh\u01b0 v\u1eady, l\u00e0m sao tri\u1ec1u ch\u00ednh c\u00f3 th\u1ec3 t\u1ed1t \u0111\u01b0\u1ee3c?`,
  `\u00d4ng ta kh\u00f4ng qu\u1ea3n l\u00fd \u0111\u01b0\u1ee3c tri\u1ec1u ch\u00ednh, m\u1eb9 \u00f4ng ta li\u1ec1n ra m\u1eb7t gi\u00fap \u00f4ng ta qu\u1ea3n l\u00fd.`,
  `M\u1eb9 ru\u1ed9t c\u1ee7a L\u01b0u Ngao t\u00ean l\u00e0 V\u01b0\u01a1ng Ch\u1ea5n Qu\u00e2n.`,
  `V\u01b0\u01a1ng Ch\u1ea5n Qu\u00e2n qu\u1ea3 th\u1ef1c l\u00e0 m\u1ed9t ng\u01b0\u1eddi m\u1eb9 t\u1ed1t, kh\u00f4ng ch\u1ec9 t\u1ef1 m\u00ecnh gi\u00fap con trai qu\u1ea3n l\u00fd,`,
  `m\u00e0 c\u00f2n c\u1ea5t nh\u1eafc anh em trong nh\u00e0 c\u00f9ng gi\u00fap con trai qu\u1ea3n l\u00fd.`,
  `C\u1ee9 nh\u01b0 v\u1eady, th\u1ebf l\u1ef1c c\u1ee7a gia t\u1ed9c h\u1ecd V\u01b0\u01a1ng d\u1ea7n d\u1ea7n ki\u1ec3m so\u00e1t ho\u00e0ng th\u1ea5t T\u00e2y H\u00e1n.`,
  `V\u01b0\u01a1ng M\u00e3ng l\u00ean v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed trong ho\u00e0n c\u1ea3nh nh\u01b0 v\u1eady.`,
  `L\u01b0u Ngao ch\u00ecm \u0111\u1eafm trong t\u1eedu s\u1eafc n\u00ean nhanh ch\u00f3ng qua \u0111\u1eddi.`,
  `\u00d4ng kh\u00f4ng c\u00f3 con n\u1ed1i d\u00f5i.`,
  `Ch\u00e1u c\u1ee7a \u00f4ng l\u00e0 H\u00e1n Ai \u0110\u1ebf L\u01b0u H\u01b0ng k\u1ebf v\u1ecb.`,
  `L\u01b0u H\u01b0ng kh\u00f4ng gi\u1ed1ng ch\u00fa c\u1ee7a m\u00ecnh, \u00f4ng kh\u00f4ng ham m\u00ea n\u1eef s\u1eafc.`,
  `V\u1eady \u00f4ng c\u00f3 ph\u1ea3i l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf xu\u1ea5t s\u1eafc kh\u00f4ng?`,
  `B\u1edfi v\u00ec th\u1ee9 \u00f4ng ham m\u00ea l\u00e0 nam s\u1eafc.`,
  `Th\u00e0nh ng\u1eef`,
  `Nh\u01b0ng \u00f4ng c\u0169ng kh\u00f4ng s\u1ed1ng \u0111\u01b0\u1ee3c bao l\u00e2u, ch\u1ebft khi c\u00f2n tr\u1ebb.`,
  `Sau \u0111\u00f3 l\u00e0 \u0111\u01b0\u1eddng \u0111\u1ec7 c\u1ee7a \u00f4ng, L\u01b0u Kh\u1ea3n k\u1ebf v\u1ecb. L\u01b0u Kh\u1ea3n c\u00f2n l\u00e0 m\u1ed9t \u0111\u1ee9a tr\u1ebb.`,
  `Ho\u00e0ng \u0111\u1ebf nh\u1ecf tu\u1ed5i \u0111\u0103ng c\u01a1.`,
  `\u00d4ng c\u0169ng c\u00f3 th\u1ec3 \u0111o\u00e1n \u0111\u01b0\u1ee3c L\u01b0u Kh\u1ea3n ch\u1ec9 l\u00e0 m\u1ed9t con r\u1ed1i,`,
  `Ng\u01b0\u1eddi th\u1ef1c s\u1ef1 n\u1eafm quy\u1ec1n l\u00e0 Th\u00e1i ho\u00e0ng th\u00e1i h\u1eadu V\u01b0\u01a1ng Ch\u00ednh Qu\u00e2n v\u00e0 \u0110\u1ea1i t\u01b0 m\u00e3 V\u01b0\u01a1ng M\u00e3ng.`,
  `Sau \u0111\u00f3, L\u01b0u Kh\u1ea3n kh\u00f4ng nghe l\u1eddi n\u00ean b\u1ecb V\u01b0\u01a1ng M\u00e3ng h\u1ea1 \u0111\u1ed9c ch\u1ebft.`,
  `V\u01b0\u01a1ng M\u00e3ng l\u1ea1i l\u1eadp m\u1ed9t ho\u00e0ng \u0111\u1ebf tr\u1ebb con hai tu\u1ed5i kh\u00e1c.`,
  `\u0110\u00e3 l\u00e0m \u0111\u1ebfn b\u01b0\u1edbc n\u00e0y r\u1ed3i th\u00ec c\u0169ng n\u00ean c\u01b0\u1edbp ng\u00f4i th\u00f4i.`,
  `N\u0103m th\u1ee9 6 C\u00f4ng Nguy\u00ean, V\u01b0\u01a1ng M\u00e3ng l\u00ean ng\u00f4i,`,
  `th\u00e0nh l\u1eadp tri\u1ec1u \u0111\u1ea1i nh\u00e0 T\u00e2n. V\u01b0\u01a1ng M\u00e3ng v\u1eabn lu\u00f4n b\u1ecb tr\u00eau ch\u1ecdc l\u00e0 ng\u01b0\u1eddi xuy\u00ean kh\u00f4ng v\u1ec1 t\u1eeb t\u01b0\u01a1ng lai,`,
  `ch\u1ec9 v\u00ec t\u01b0 t\u01b0\u1edfng c\u1ee7a \u00f4ng qu\u00e1 v\u01b0\u1ee3t th\u1eddi \u0111\u1ea1i.`,
  `Sau khi l\u00ean ng\u00f4i,`,
  `\u00f4ng ch\u1ee7 tr\u01b0\u01a1ng b\u00e3i b\u1ecf ch\u1ebf \u0111\u1ed9 n\u00f4 l\u1ec7, m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u b\u00ecnh \u0111\u1eb3ng, ph\u00e1t \u0111\u1ed9ng c\u1ea3i c\u00e1ch ru\u1ed9ng \u0111\u1ea5t,`,
  `\u0111\u1ea5t \u0111ai thu\u1ed9c s\u1edf h\u1eefu nh\u00e0 n\u01b0\u1edbc,`,
  `sau \u0111\u00f3 ph\u00e2n ph\u1ed1i b\u00ecnh qu\u00e2n,`,
  `th\u1ef1c hi\u1ec7n kinh t\u1ebf k\u1ebf ho\u1ea1ch,`,
  `\u0111\u00e1nh ph\u00e1 nh\u1eefng th\u01b0\u01a1ng nh\u00e2n b\u1ea5t ch\u00ednh t\u00edch tr\u1eef h\u00e0ng h\u00f3a,`,
  `th\u00fac \u0111\u1ea9y c\u1ea3i c\u00e1ch ti\u1ec1n t\u1ec7,`,
  `th\u00e0nh l\u1eadp ng\u00e2n h\u00e0ng qu\u1ed1c gia,`,
  `s\u1eed d\u1ee5ng ti\u1ec1n t\u1ec7 m\u1edbi thay th\u1ebf v\u00e0ng b\u1ea1c, v.v.`,
  `Ch\u00e0, tho\u1ea1t nghe nh\u1eefng bi\u1ec7n ph\u00e1p c\u1ea3i c\u00e1ch n\u00e0y th\u1eadt qu\u00e1 tuy\u1ec7t v\u1eddi,`,
  `\u0111\u00e2y ch\u1eb3ng ph\u1ea3i l\u00e0 ch\u1ee7 ngh\u0129a x\u00e3 h\u1ed9i hi\u1ec7n \u0111\u1ea1i sao?`,
  `Nh\u01b0ng \u0111\u1eebng qu\u00ean, \u0111\u00e2y l\u00e0 th\u1eddi k\u1ef3 phong ki\u1ebfn hai ngh\u00ecn n\u0103m tr\u01b0\u1edbc,`,
  `B\u01b0\u1edbc \u0111i n\u00e0y c\u1ee7a \u00f4ng ta qu\u00e1 l\u1edbn,`,
  `x\u00e3 h\u1ed9i kh\u00f4ng theo k\u1ecbp.`,
  `C\u1ea3i c\u00e1ch kh\u00f4ng ch\u1ec9 l\u00e0m t\u1ed5n h\u1ea1i l\u1ee3i \u00edch c\u1ee7a gi\u1edbi qu\u00fd t\u1ed9c,`,
  `m\u00e0 ng\u01b0\u1eddi d\u00e2n c\u0169ng kh\u00f4ng nh\u1eadn \u0111\u01b0\u1ee3c l\u1ee3i \u00edch th\u1ef1c t\u1ebf n\u00e0o,`,
  `khi\u1ebfn m\u1ecdi t\u1ea7ng l\u1edbp trong n\u01b0\u1edbc \u0111\u1ec1u \u0111\u1eafc t\u1ed9i v\u1edbi \u00f4ng ta.`,
  `Th\u1ea5t b\u1ea1i c\u1ee7a c\u1ea3i c\u00e1ch c\u0169ng d\u1eabn \u0111\u1ebfn m\u00e2u thu\u1eabn x\u00e3 h\u1ed9i gay g\u1eaft h\u01a1n.`,
  `O\u00e1i o\u0103m thay, l\u00fac \u0111\u00f3 trong n\u01b0\u1edbc l\u1ea1i x\u1ea3y ra h\u1ea1n h\u00e1n v\u00e0 n\u1ea1n ch\u00e2u ch\u1ea5u,`,
  `n\u00f4ng d\u00e2n kh\u00f4ng s\u1ed1ng n\u1ed5i n\u00ean n\u1ed5i d\u1eady kh\u1edfi ngh\u0129a.`,
  `L\u00e0m sao con ch\u00e1u L\u01b0u gia c\u00f3 th\u1ec3 b\u1ecf l\u1ee1 c\u01a1 h\u1ed9i kh\u00f4i ph\u1ee5c H\u00e1n th\u1ea5t n\u00e0y,`,
  `c\u0169ng nhao nhao h\u1ee3p t\u00e1c v\u1edbi qu\u00e2n kh\u1edfi ngh\u0129a l\u1eadt \u0111\u1ed5 V\u01b0\u01a1ng M\u00e3ng.`,
  `Sau m\u1ed9t phen h\u1ed7n chi\u1ebfn, h\u1eadu du\u1ec7 L\u01b0u gia l\u00e0 L\u01b0u T\u00fa \u0111\u00e3 ch\u00e9m gi\u1ebft V\u01b0\u01a1ng M\u00e3ng,`,
  `l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf. V\u00ec gi\u1eefa tri\u1ec1u H\u00e1n c\u00f3 m\u1ed9t tri\u1ec1u T\u00e2n,`,
  `n\u00ean tri\u1ec1u H\u00e1n tr\u01b0\u1edbc V\u01b0\u01a1ng M\u00e3ng g\u1ecdi l\u00e0 T\u00e2y H\u00e1n,`,
  `tri\u1ec1u H\u00e1n sau L\u01b0u T\u00fa g\u1ecdi l\u00e0 \u0110\u00f4ng H\u00e1n.`,
  `Sau chi\u1ebfn tranh ph\u1ea3i ngh\u1ec9 ng\u01a1i d\u01b0\u1ee1ng s\u1ee9c, \u0111\u00e2y l\u00e0 chuy\u1ec7n c\u0169 r\u00edch r\u1ed3i.`,
  `Nh\u00e0 H\u00e1n d\u01b0\u1edbi tay L\u01b0u T\u00fa \u0111\u00e3 tr\u1edf l\u1ea1i \u0111\u00fang qu\u1ef9 \u0111\u1ea1o.`,
  `Sau khi L\u01b0u T\u00fa m\u1ea5t, \u0111\u01b0\u1ee3c truy th\u1ee5y hi\u1ec7u Quang V\u0169 \u0110\u1ebf.`,
  `C\u00e1c \u0111\u1eddi H\u00e1n Minh \u0110\u1ebf, H\u00e1n Ch\u01b0\u01a1ng \u0110\u1ebf, H\u00e1n H\u00f2a \u0110\u1ebf sau n\u00e0y \u0111\u1ec1u cai tr\u1ecb \u0111\u1ea5t n\u01b0\u1edbc r\u1ea5t t\u1ed1t.`,
  `\u0110\u00f4ng H\u00e1n b\u01b0\u1edbc v\u00e0o th\u1eddi k\u1ef3 th\u1ecbnh v\u01b0\u1ee3ng.`,
  `Tuy nhi\u00ean, \u0111\u1ebfn giai \u0111o\u1ea1n trung v\u00e0 cu\u1ed1i, \u0111\u1ea5t n\u01b0\u1edbc b\u1eaft \u0111\u1ea7u lo\u1ea1n l\u1ea1c.`,
  `Nhi\u1ec1u v\u1ecb ho\u00e0ng \u0111\u1ebf tr\u1ebb tu\u1ed5i tr\u1edf th\u00e0nh con r\u1ed1i c\u1ee7a ngo\u1ea1i t\u1ed9c v\u00e0 ho\u1ea1n quan.`,
  `Tri\u1ec1u \u0111\u00ecnh th\u1ed1i n\u00e1t, n\u00f4ng d\u00e2n kh\u00f4ng s\u1ed1ng n\u1ed5i, n\u00f4ng d\u00e2n kh\u00f4ng s\u1ed1ng n\u1ed5i th\u00ec ph\u1ea3i n\u1ed5i d\u1eady.`,
  `N\u0103m 184 c\u00f4ng nguy\u00ean n\u1ed5 ra cu\u1ed9c kh\u1edfi ngh\u0129a Kh\u0103n v\u00e0ng.`,
  `M\u1edf ra m\u00e0n h\u1ed7n chi\u1ebfn qu\u00e2n phi\u1ec7t cu\u1ed1i \u0110\u00f4ng H\u00e1n.`,
  `Sau \u0111\u00f3 b\u01b0\u1edbc v\u00e0o th\u1eddi Tam Qu\u1ed1c.`,
  `Cu\u1ed1i \u0110\u00f4ng H\u00e1n xu\u1ea5t hi\u1ec7n hai v\u1ecb ho\u00e0ng \u0111\u1ebf c\u1ef1c ph\u1ea9m.`,
  `H\u00e1n Ho\u00e0n \u0110\u1ebf L\u01b0u Ch\u00ed v\u00e0 H\u00e1n Linh \u0110\u1ebf L\u01b0u Ho\u00e0nh sau n\u00e0y.`,
  `Kh\u00f4ng ch\u1ec9 b\u1ecf b\u00ea tri\u1ec1u ch\u00ednh m\u00e0 c\u00f2n s\u1ee7ng \u00e1i ho\u1ea1n quan, \u0111\u00e0n \u00e1p v\u0103n nh\u00e2n s\u0129 phu.`,
  `V\u00f4 c\u00f9ng xa hoa tr\u1ee5y l\u1ea1c, \u0111\u1eb7c bi\u1ec7t l\u00e0 L\u01b0u Ho\u00e0nh, v\u1edbi t\u01b0 c\u00e1ch m\u1ed9t ho\u00e0ng \u0111\u1ebf.`,
  `\u00d4ng ta th\u1eadm ch\u00ed c\u00f2n b\u00e1n quan ch\u1ee9c \u0111\u1ec3 v\u01a1 v\u00e9t ti\u1ec1n c\u1ee7a.`,
  `Ai c\u00f3 ti\u1ec1n th\u00ec \u0111\u01b0\u1ee3c l\u00e0m quan,`,
  `\u0110\u1ee7 gi\u00e0u c\u00f2n c\u00f3 th\u1ec3 l\u00e0m quan to.`,
  `H\u1eafn l\u1ea1i c\u1ef1c k\u1ef3 h\u00e1o s\u1eafc, th\u01b0\u1eddng t\u1ed5 ch\u1ee9c ti\u1ec7c kh\u1ecfa th\u00e2n v\u1edbi cung n\u1eef trong cung,`,
  `Kh\u00f4ng th\u1ec3 d\u00f9ng t\u1eeb h\u00f4n qu\u00e2n \u0111\u1ec3 h\u00ecnh dung h\u1eafn \u0111\u01b0\u1ee3c n\u1eefa,`,
  `H\u1eafn qu\u1ea3 th\u1ef1c l\u00e0 m\u1ed9t k\u1ebb bi\u1ebfn th\u00e1i.`,
  `Tri\u1ec1u \u0111\u00ecnh m\u1ee5c n\u00e1t, quan l\u1ea1i b\u00f3c l\u1ed9t d\u00e2n ch\u00fang,`,
  `L\u1ea1i th\u00eam thi\u00ean tai li\u00ean mi\u00ean.`,
  `Cu\u1ed1i c\u00f9ng, v\u00e0o n\u0103m 184, cu\u1ed9c kh\u1edfi ngh\u0129a Kh\u0103n V\u00e0ng do Tr\u01b0\u01a1ng Gi\u00e1c l\u00e3nh \u0111\u1ea1o \u0111\u00e3 b\u00f9ng n\u1ed5.`,
  `Tr\u01b0\u01a1ng Gi\u00e1c l\u00e0 m\u1ed9t nh\u00e0 th\u1ea7n h\u1ecdc, r\u1ea5t am hi\u1ec3u v\u1ec1 ph\u00f9 th\u1ee7y,`,
  `D\u00e2n ch\u00fang s\u1ed1ng kh\u00f4ng t\u1ed1t th\u00ec th\u01b0\u1eddng \u0111\u1eb7t hy v\u1ecdng v\u00e0o th\u1ea7n h\u1ecdc.`,
  `Trong b\u1ed1i c\u1ea3nh nh\u01b0 v\u1eady,`,
  `Tr\u01b0\u01a1ng Gi\u00e1c c\u00f9ng hai ng\u01b0\u1eddi em c\u1ee7a m\u00ecnh \u0111\u00e3 th\u00e0nh l\u1eadp Th\u00e1i B\u00ecnh \u0110\u1ea1o,`,
  `Ch\u1ee7 tr\u01b0\u01a1ng b\u00ecnh \u0111\u1eb3ng, ph\u1ea3n \u0111\u1ed1i b\u00f3c l\u1ed9t, \u0111i\u1ec1u n\u00e0y ch\u1eb3ng ph\u1ea3i \u0111\u00e3 \u0111\u00e1nh tr\u00fang t\u00e2m l\u00fd c\u1ee7a d\u00e2n ch\u00fang sao?`,
  `V\u00ec v\u1eady r\u1ea5t \u0111\u01b0\u1ee3c l\u00f2ng d\u00e2n,`,
  `Ch\u1ec9 trong h\u01a1n m\u01b0\u1eddi n\u0103m ng\u1eafn ng\u1ee7i,`,
  `T\u00edn \u0111\u1ed3 Th\u00e1i B\u00ecnh \u0110\u1ea1o \u0111\u00e3 \u0111\u1ea1t \u0111\u1ebfn h\u00e0ng tr\u0103m ngh\u00ecn ng\u01b0\u1eddi,`,
  `Lan r\u1ed9ng kh\u1eafp g\u1ea7n h\u1ebft \u0111\u1ea5t n\u01b0\u1edbc.`,
  `Tr\u01b0\u01a1ng Gi\u00e1c ch\u1ec9 v\u00ec mu\u1ed1n ph\u00e1t huy th\u1ea7n h\u1ecdc sao?`,
  `\u0110\u01b0\u01a1ng nhi\u00ean kh\u00f4ng ph\u1ea3i, th\u1ef1c ra m\u1ee5c \u0111\u00edch th\u1eadt s\u1ef1 c\u1ee7a Tr\u01b0\u01a1ng Gi\u00e1c l\u00e0 l\u1ee3i d\u1ee5ng h\u00ecnh th\u1ee9c t\u00f4n gi\u00e1o \u0111\u1ec3 ph\u00e1t \u0111\u1ed9ng ph\u1ea3n lo\u1ea1n.`,
  `Sau khi Th\u00e1i B\u00ecnh \u0110\u1ea1o l\u1edbn m\u1ea1nh,`,
  `Tr\u01b0\u01a1ng Gi\u00e1c c\u1ea3m th\u1ea5y th\u1eddi c\u01a1 \u0111\u00e3 ch\u00edn mu\u1ed3i,`,
  `\u00d4ng li\u1ec1n li\u00ean l\u1ea1c v\u1edbi c\u00e1c t\u00edn \u0111\u1ed3 \u1edf kh\u1eafp n\u01a1i chu\u1ea9n b\u1ecb l\u00e0m ph\u1ea3n,`,
  `Nh\u01b0ng kh\u00f4ng may tin t\u1ee9c b\u1ecb l\u1ed9,`,
  `Tri\u1ec1u \u0111\u00ecnh l\u1eadp t\u1ee9c c\u1eed qu\u00e2n \u0111\u1ebfn tr\u1ea5n \u00e1p.`,
  `T\u00ecnh th\u1ebf nguy c\u1ea5p, Tr\u01b0\u01a1ng Gi\u00e1c quy\u1ebft \u0111\u1ecbnh kh\u1edfi ngh\u0129a ngay l\u1eadp t\u1ee9c,`,
  `Qu\u00e2n kh\u1edfi ngh\u0129a m\u1ed7i ng\u01b0\u1eddi \u0111\u1ec1u \u0111\u1ed9i kh\u0103n v\u00e0ng,`,
  `T\u01b0\u1ee3ng tr\u01b0ng cho s\u1ed1 m\u1ec7nh tr\u1eddi ban.`,
  `Sau khi kh\u1edfi ngh\u0129a, b\u00e1ch t\u00ednh l\u0169 l\u01b0\u1ee3t h\u01b0\u1edfng \u1ee9ng,`,
  `Kh\u1eafp c\u1ea3 n\u01b0\u1edbc \u0111\u1ec1u b\u00f9ng n\u1ed5 c\u00e1c cu\u1ed9c n\u1ed5i d\u1eady quy m\u00f4 l\u1edbn.`,
  `Tri\u1ec1u \u0111\u00ecnh nh\u00ecn th\u1ea5y, kh\u00f4ng \u1ed5n, s\u1ed1 ng\u01b0\u1eddi kh\u1edfi ngh\u0129a n\u00e0y qu\u00e1 nhi\u1ec1u r\u1ed3i.`,
  `Ph\u1ea3i qu\u1ea3n l\u00fd nhi\u1ec1u n\u01a1i nh\u01b0 v\u1eady, c\u0103n b\u1ea3n l\u00e0 kh\u00f4ng th\u1ec3 qu\u1ea3n l\u00fd xu\u1ec3.`,
  `V\u1eady n\u00ean tri\u1ec1u \u0111\u00ecnh \u0111\u00e3 trao quy\u1ec1n cho c\u00e1c c\u01a1 quan \u0111\u1ecba ph\u01b0\u01a1ng, n\u00f3i r\u1eb1ng:`,
  `Ta kh\u00f4ng qu\u1ea3n l\u00fd \u0111\u01b0\u1ee3c nhi\u1ec1u nh\u01b0 th\u1ebf, c\u00e1c ng\u01b0\u01a1i t\u1ef1 m\u00ecnh ngh\u0129 c\u00e1ch \u0111i.`,
  `C\u1ee9 nh\u01b0 v\u1eady, nh\u1eefng h\u00e0o tr\u01b0\u1edfng, ph\u00fa \u00f4ng c\u00e1c n\u01a1i \u0111\u1ec3 b\u1ea3o v\u1ec7 t\u00e0i s\u1ea3n c\u1ee7a m\u00ecnh,`,
  `t\u1ea5t c\u1ea3 \u0111\u1ec1u \u0111\u1ee9ng ra, h\u1ee3p t\u00e1c v\u1edbi quan ph\u1ee7 tr\u1ea5n \u00e1p qu\u00e2n Kh\u0103n V\u00e0ng.`,
  `Cu\u1ed1i c\u00f9ng, Tr\u01b0\u01a1ng Gi\u00e1c l\u00e2m b\u1ec7nh qua \u0111\u1eddi, hai ng\u01b0\u1eddi em trai c\u1ee7a \u00f4ng b\u1ecb gi\u1ebft,`,
  `kh\u1edfi ngh\u0129a Kh\u0103n V\u00e0ng k\u1ebft th\u00fac trong th\u1ea5t b\u1ea1i.`,
  `Nh\u01b0ng sau cu\u1ed9c kh\u1edfi ngh\u0129a l\u1ea7n n\u00e0y,`,
  `m\u01b0\u1ee3n c\u1edb tr\u1ea5n \u00e1p qu\u00e2n Kh\u0103n V\u00e0ng,`,
  `th\u1ebf l\u1ef1c qu\u00e2n phi\u1ec7t c\u00e1c n\u01a1i \u0111\u00e3 nhanh ch\u00f3ng m\u1edf r\u1ed9ng th\u1ef1c l\u1ef1c c\u1ee7a m\u00ecnh.`,
  `Trong \u0111\u1ed9i qu\u00e2n tr\u1ea5n \u00e1p kh\u1edfi ngh\u0129a,`,
  `c\u00e1c anh h\u00f9ng Tam Qu\u1ed1c b\u1eaft \u0111\u1ea7u n\u1ed5i l\u00ean.`,
  `Quay tr\u1edf l\u1ea1i tri\u1ec1u \u0111\u00ecnh,`,
  `v\u00e0i n\u0103m sau kh\u1edfi ngh\u0129a Kh\u0103n V\u00e0ng,`,
  `H\u00e1n Linh \u0110\u1ebf L\u01b0u Ho\u00e0nh b\u0103ng h\u00e0, con trai \u00f4ng l\u00e0 L\u01b0u Bi\u1ec7n k\u1ebf v\u1ecb.`,
  `Tri\u1ec1u \u0111\u00ecnh l\u00fac b\u1ea5y gi\u1edd c\u00f3 hai th\u1ebf l\u1ef1c,`,
  `ho\u1ea1n quan v\u00e0 s\u0129 \u0111\u1ea1i phu.`,
  `H\u1ecd \u0111\u00e3 \u0111\u00e1nh nhau r\u1ea5t l\u00e2u r\u1ed3i.`,
  `Vi\u1ec7c Quan \u00c2n l\u00e0m cho Vi\u00ean Thi\u1ec7u thu\u1ed9c phe c\u00e1nh s\u0129 \u0111\u1ea1i phu.`,
  `C\u00f3 l\u1ea7n, \u00f4ng ta c\u00f9ng ng\u01b0\u1eddi b\u1ea1n th\u00e2n thi\u1ebft l\u00e0 \u0110\u1ea1i t\u01b0\u1edbng qu\u00e2n H\u00e0 Ti\u1ebfn b\u00e0n c\u00e1ch di\u1ec7t tr\u1eeb ho\u1ea1n quan.`,
  `\u0110\u1ec3 c\u00f3 th\u00eam s\u1ee9c m\u1ea1nh, h\u1ecd c\u00f2n g\u1ecdi \u0111\u1ea1i qu\u00e2n phi\u1ec7t \u0110\u1ed5ng Tr\u00e1c t\u1eeb bi\u00ean \u1ea3i v\u1ec1.`,
  `L\u00e0m vi\u1ec7n tr\u1ee3 b\u00ean ngo\u00e0i.`,
  `\u0110\u1ed5ng Tr\u00e1c c\u00f2n ch\u01b0a \u0111\u1ebfn, th\u00ec`,
  `H\u00e0 Ti\u1ebfn \u0111\u00e3 b\u1ecb ho\u1ea1n quan ch\u00e9m ch\u1ebft.`,
  `\u0110\u1ed3ng \u0111\u1ed9i`,
  `c\u0169ng l\u00e0 \u0111\u1ed3ng \u0111\u1ed9i, Vi\u00ean Thi\u1ec7u t\u1ee9c gi\u1eadn gi\u1ebft h\u01a1n hai ng\u00e0n ho\u1ea1n quan,`,
  `C\u01a1 b\u1ea3n qu\u00e9t s\u1ea1ch ho\u1ea1n quan.`,
  `Nh\u01b0ng r\u1eafc r\u1ed1i th\u1ef1c s\u1ef1 m\u1edbi b\u1eaft \u0111\u1ea7u,`,
  `\u0110\u1ed5ng Tr\u00e1c \u0111\u00e3 \u0111\u1ebfn L\u1ea1c D\u01b0\u01a1ng.`,
  `Nh\u00e2n ti\u1ec7n n\u00f3i th\u00eam,`,
  `\u0110\u1ed5ng Tr\u00e1c v\u1ed1n \u0111\u1ebfn \u0111\u1ec3 \u0111\u00e1nh ho\u1ea1n quan, ai ng\u1edd Vi\u00ean Thi\u1ec7u \u0111\u00e3 t\u1ef1 m\u00ecnh gi\u1ea3i quy\u1ebft xong,`,
  `n\u00ean kh\u00f4ng c\u00f2n vi\u1ec7c g\u00ec c\u1ee7a h\u1eafn n\u1eefa.`,
  `Nh\u01b0ng \u0110\u1ed5ng Tr\u00e1c kh\u00f4ng quan t\u00e2m \u0111\u1ebfn nh\u1eefng \u0111i\u1ec1u n\u00e0y, h\u1eafn l\u00e0 m\u1ed9t t\u00ean c\u01b0\u1eddng h\u00e0o,`,
  `lo\u1ea1i r\u1ea5t x\u1ea5u xa.`,
  `C\u00e1c quan trong tri\u1ec1u th\u1ea5y kh\u00f4ng ai c\u00f3 th\u1ec3 tr\u1ecb \u0111\u01b0\u1ee3c h\u1eafn,`,
  `kh\u00f4ng ch\u1ecdc v\u00e0o \u0111\u01b0\u1ee3c th\u00ec kh\u00f4ng tr\u1ed1n \u0111\u01b0\u1ee3c sao?`,
  `Th\u1ebf l\u00e0 m\u1ecdi ng\u01b0\u1eddi l\u0169 l\u01b0\u1ee3t b\u1ecf tr\u1ed1n,`,
  `trong \u0111\u00f3 c\u00f3 Vi\u00ean Thi\u1ec7u v\u00e0 T\u00e0o Th\u00e1o.`,
  `N\u00f3i v\u1ec1 T\u00e0o Th\u00e1o,`,
  `cha c\u1ee7a T\u00e0o Th\u00e1o t\u00ean l\u00e0 T\u00e0o Tung,`,
  `T\u00e0o Tung l\u00e0 con nu\u00f4i c\u1ee7a ho\u1ea1n quan T\u00e0o \u0110\u1eb1ng.`,
  `Th\u00e2n ph\u1eadn c\u1ee7a T\u00e0o Th\u00e1o tr\u00ean tri\u1ec1u \u0111\u00ecnh tuy kh\u00f4ng cao b\u1eb1ng Vi\u00ean Thi\u1ec7u,`,
  `nh\u01b0ng d\u00f9 sao c\u0169ng l\u00e0 m\u1ed9t quan.`,
  `Sau khi hai ng\u01b0\u1eddi b\u1ecf tr\u1ed1n th\u00ec b\u1eaft \u0111\u1ea7u t\u1ef1 m\u00ecnh g\u00e2y d\u1ef1ng s\u1ef1 nghi\u1ec7p,`,
  `c\u00f2n v\u1ec1 ph\u00eda tri\u1ec1u \u0111\u00ecnh, \u0110\u1ed5ng Tr\u00e1c \u0111\u00e3 ki\u1ec3m so\u00e1t ho\u00e0ng th\u1ea5t,`,
  `\u0110\u1ec3 t\u1ea1o uy th\u1ebf, \u00f4ng ph\u1ebf L\u01b0u Bi\u1ec7n, l\u1eadp L\u01b0u Hi\u1ec7p l\u00e0m H\u00e1n Hi\u1ebfn \u0110\u1ebf.`,
  `V\u00e0 d\u1eddi \u0111\u00f4 t\u1eeb L\u1ea1c D\u01b0\u01a1ng \u0111\u1ebfn Tr\u01b0\u1eddng An.`,
  `\u0110\u1ed3ng th\u1eddi \u0111\u1ed1t ch\u00e1y L\u1ea1c D\u01b0\u01a1ng.`,
  `\u0110\u1eebng th\u1ea5y h\u1eafn l\u00fac n\u00e0y d\u01b0\u1eddng nh\u01b0 \u0111\u00e3 \u0111\u1ea1t \u0111\u1ebfn \u0111\u1ec9nh cao cu\u1ed9c \u0111\u1eddi,`,
  `Nh\u01b0ng kh\u00f4ng l\u00e2u sau \u0111\u00f3,`,
  `\u0110\u1ed5ng Tr\u00e1c \u0111\u00e3 b\u1ecb v\u1ecb quan l\u00e3o th\u1ea7n V\u01b0\u01a1ng Do\u00e3n gi\u1ebft ch\u1ebft.`,
  `C\u00e2u chuy\u1ec7n n\u00e0y ph\u1ea3i b\u1eaft \u0111\u1ea7u t\u1eeb m\u1ef9 n\u1eef \u0110i\u00eau Thuy\u1ec1n.`,
  `\u0110\u1ed5ng Tr\u00e1c c\u00f3 m\u1ed9t ng\u01b0\u1eddi con nu\u00f4i t\u00ean l\u00e0 L\u00e3 B\u1ed1.`,
  `V\u01b0\u01a1ng Do\u00e3n m\u1ed9t m\u1eb7t g\u1ea3 \u0110i\u00eau Thuy\u1ec1n cho L\u00e3 B\u1ed1,`,
  `M\u1ed9t m\u1eb7t l\u1ea1i d\u00e2ng cho \u0110\u1ed5ng Tr\u00e1c.`,
  `L\u00e3 B\u1ed1 n\u1ed5i c\u01a1n ghen, li\u1ec1n \u0111\u00e2m ch\u1ebft cha nu\u00f4i \u0110\u1ed5ng Tr\u00e1c.`,
  `V\u1ec1 \u0110i\u00eau Thuy\u1ec1n, ch\u00ednh s\u1eed kh\u00f4ng c\u00f3 ghi ch\u00e9p,`,
  `C\u00f3 ng\u01b0\u1eddi n\u00e0y hay kh\u00f4ng kh\u00f3 n\u00f3i,`,
  `Nh\u01b0ng L\u00e3 B\u1ed1 gi\u1ebft \u0110\u1ed5ng Tr\u00e1c l\u00e0 s\u1ef1 th\u1eadt.`,
  `Sau \u0111\u00f3, hai thu\u1ed9c h\u1ea1 c\u1ee7a \u0110\u1ed5ng Tr\u00e1c quay v\u1ec1 b\u00e1o th\u00f9.`,
  `gi\u1ebft V\u01b0\u01a1ng Do\u00e3n. Sau \u0111\u00f3, hai t\u00ean \u0111\u00e0n em n\u00e0y l\u1ea1i b\u1eaft \u0111\u1ea7u tranh gi\u00e0nh nhau,`,
  `Hi\u1ebfn \u0110\u1ebf v\u00e0 b\u00e1 quan th\u1eeba c\u01a1 h\u1ed7n lo\u1ea1n tr\u1ed1n v\u1ec1 L\u1ea1c D\u01b0\u01a1ng,`,
  `m\u00e0 L\u1ea1c D\u01b0\u01a1ng \u0111\u1ea1i b\u1ea3n doanh tr\u01b0\u1edbc \u0111\u00f3 \u0111\u00e3 b\u1ecb \u0110\u1ed5ng Tr\u00e1c \u0111\u1ed1t ch\u00e1y.`,
  `Tri\u1ec1u \u0111\u00ecnh l\u00fac n\u00e0y ch\u00ednh l\u00e0 m\u1ed9t tr\u00f2 c\u01b0\u1eddi l\u1edbn,`,
  `t\u1eeb \u0111\u00f3 v\u1ec1 sau uy t\u00edn ho\u00e0n to\u00e0n bi\u1ebfn m\u1ea5t.`,
  `Tuy nhi\u00ean d\u00f9 sao v\u1eabn l\u00e0 thi\u00ean t\u1eed, kh\u00f4ng c\u00f2n th\u1ef1c quy\u1ec1n nh\u01b0ng v\u1eabn c\u00f2n danh ti\u1ebfng.`,
  `T\u00e0o Th\u00e1o l\u00fac n\u00e0y th\u1eeba c\u01a1 \u0111\u00f3n Hi\u1ebfn \u0110\u1ebf v\u1ec1 H\u1ee9a X\u01b0\u01a1ng,`,
  `th\u1ef1c ra h\u1eafn ch\u1ec9 mu\u1ed1n m\u01b0\u1ee3n danh thi\u00ean t\u1eed \u0111\u1ec3 hi\u1ec7u l\u1ec7nh ch\u01b0 h\u1ea7u.`,
  `C\u00f3 \u0111\u01b0\u1ee3c t\u1ea5m kim b\u00e0i ho\u00e0ng \u0111\u1ebf n\u00e0y, th\u1ebf l\u1ef1c c\u1ee7a T\u00e0o Th\u00e1o qu\u1ea3 nhi\u00ean t\u0103ng m\u1ea1nh,`,
  `d\u1ea7n d\u1ea7n ph\u00e1t tri\u1ec3n th\u00e0nh b\u00e1 ch\u1ee7 ph\u01b0\u01a1ng B\u1eafc.`,
  `V\u1eady th\u00ec l\u00fac n\u00e0y c\u00e1c qu\u1ea7n h\u00f9ng kh\u00e1c \u0111ang l\u00e0m g\u00ec?`,
  `Tr\u01b0\u1edbc ti\u00ean h\u00e3y n\u00f3i v\u1ec1 L\u01b0u B\u1ecb,`,
  `L\u01b0u B\u1ecb l\u00e0 h\u1eadu du\u1ec7 ch\u00ednh th\u1ed1ng c\u1ee7a d\u00f2ng d\u00f5i H\u00e1n th\u1ea5t,`,
  `nh\u01b0ng \u0111\u1ebfn \u0111\u1eddi \u00f4ng th\u00ec gia t\u1ed9c sa s\u00fat.`,
  `V\u00ec cha \u00f4ng m\u1ea5t s\u1edbm, L\u01b0u B\u1ecb v\u00e0 m\u1eb9 \u00f4ng n\u01b0\u01a1ng t\u1ef1a v\u00e0o nhau,`,
  `Ki\u1ebfm s\u1ed1ng ch\u1eadt v\u1eadt b\u1eb1ng ngh\u1ec1 \u0111an d\u00e9p c\u1ecf, chi\u1ebfu c\u1ecf.`,
  `N\u0103m Kh\u1edfi ngh\u0129a Kh\u0103n V\u00e0ng, \u00f4ng \u1ea5y 23 tu\u1ed5i.`,
  `D\u01b0\u1edbi chi\u00eau b\u00e0i H\u00e1n v\u01b0\u01a1ng th\u1ea5t, \u00f4ng \u1ea5y chi\u00eau m\u1ed9 binh m\u00e3 v\u1edbi s\u1ef1 t\u00e0i tr\u1ee3 c\u1ee7a c\u00e1c th\u01b0\u01a1ng gia l\u1edbn.`,
  `Quan V\u0169, Tr\u01b0\u01a1ng Phi ch\u00ednh l\u00e0 quy ph\u1ee5c \u00f4ng \u1ea5y v\u00e0o th\u1eddi \u0111i\u1ec3m n\u00e0y.`,
  `V\u00ec c\u00f3 c\u00f4ng \u0111\u00e1nh d\u1eb9p qu\u00e2n Kh\u0103n V\u00e0ng, \u00f4ng \u1ea5y c\u00f2n \u0111\u01b0\u1ee3c phong m\u1ed9t ch\u1ee9c quan nh\u1ecf.`,
  `Khi T\u00e0o Th\u00e1o \u0111ang ''hi\u1ec7p thi\u00ean t\u1eed d\u0129 l\u1ec7nh ch\u01b0 h\u1ea7u'' (c\u01b0\u1ee1ng \u0111o\u1ea1t thi\u00ean t\u1eed \u0111\u1ec3 ra l\u1ec7nh cho c\u00e1c ch\u01b0 h\u1ea7u),`,
  `\u00d4ng \u1ea5y v\u1eabn \u0111ang ph\u1ea5n \u0111\u1ea5u \u0111\u1ec3 th\u0103ng quan ti\u1ebfn ch\u1ee9c.`,
  `C\u00f2n v\u1ec1 Vi\u00ean Thi\u1ec7u, sau khi ch\u1ea1y kh\u1ecfi tri\u1ec1u \u0111\u00ecnh, \u00f4ng \u1ea5y b\u1eaft \u0111\u1ea7u tranh gi\u00e0nh khu v\u1ef1c Hoa B\u1eafc v\u1edbi C\u00f4ng T\u00f4n To\u1ea3n.`,
  `Cu\u1ed1i c\u00f9ng, Vi\u00ean Thi\u1ec7u gi\u00e0nh chi\u1ebfn th\u1eafng, s\u00e1p nh\u1eadp \u0111\u1ecba b\u00e0n c\u1ee7a C\u00f4ng T\u00f4n To\u1ea3n,`,
  `Tr\u1edf th\u00e0nh m\u1ed9t b\u00e1 ch\u1ee7 kh\u00e1c \u1edf ph\u01b0\u01a1ng B\u1eafc.`,
  `C\u00e1c th\u1ebf l\u1ef1c l\u1edbn kh\u00e1c \u0111\u1ea1i kh\u00e1i l\u00e0 nh\u01b0 h\u00ecnh n\u00e0y,`,
  `M\u1ed7i b\u00ean c\u00e1t c\u1ee9 m\u1ed9t ph\u01b0\u01a1ng.`,
  `\u1ede ph\u01b0\u01a1ng B\u1eafc l\u00e0 hai th\u1ebf l\u1ef1c l\u1edbn Vi\u00ean Thi\u1ec7u v\u00e0 T\u00e0o Th\u00e1o,`,
  `\u0110\u1ec3 tranh gi\u00e0nh v\u1ecb tr\u00ed s\u1ed1 m\u1ed9t, kh\u00f4ng th\u1ec3 tr\u00e1nh kh\u1ecfi m\u1ed9t tr\u1eadn chi\u1ebfn.`,
  `N\u0103m 200 sau C\u00f4ng nguy\u00ean, t\u1ea1i Quan \u0110\u1ed9,`,
  `t\u1ee9c l\u00e0 khu v\u1ef1c H\u00e0 Nam ng\u00e0y nay.`,
  `Hai qu\u00e2n \u0111\u1ed1i \u0111\u1ea7u. Qu\u00e2n Vi\u00ean Thi\u1ec7u l\u00fac \u0111\u00f3 c\u00f3 m\u01b0\u1eddi v\u1ea1n ng\u01b0\u1eddi,`,
  `qu\u00e2n T\u00e0o Th\u00e1o ch\u1ec9 c\u00f3 hai v\u1ea1n ng\u01b0\u1eddi,`,
  `l\u1ef1c l\u01b0\u1ee3ng ch\u00eanh l\u1ec7ch nh\u01b0 v\u1eady.`,
  `Vi\u00ean Thi\u1ec7u \u0111\u00e1ng l\u1ebd \u0111\u00e3 th\u1eafng ch\u1eafc, nh\u01b0ng s\u1ef1 xu\u1ea5t hi\u1ec7n c\u1ee7a m\u1ed9t ng\u01b0\u1eddi \u0111\u00e3 xoay chuy\u1ec3n c\u1ee5c di\u1ec7n,`,
  `H\u1ee9a Du. \u00d4ng ta v\u1ed1n l\u00e0 m\u01b0u s\u0129 c\u1ee7a Vi\u00ean Thi\u1ec7u,`,
  `trong tr\u1eadn Quan \u0110\u1ed9, gia \u0111\u00ecnh \u00f4ng ta b\u1ecb b\u1eaft v\u00ec ph\u1ea1m ph\u00e1p,`,
  `H\u1ee9a Du v\u00ec th\u1ebf \u00f4m h\u1eadn, ph\u1ea3n b\u1ed9i Vi\u00ean Thi\u1ec7u,`,
  `\u0111\u1ea7u qu\u00e2n cho T\u00e0o Th\u00e1o.`,
  `\u00d4ng ta \u0111\u00e3 n\u00f3i cho T\u00e0o Th\u00e1o bi\u1ebft \u00d4 S\u00e0o l\u00e0 n\u01a1i c\u1ea5t gi\u1eef l\u01b0\u01a1ng th\u1ef1c c\u1ee7a qu\u00e2n ti\u1ebfp vi\u1ec7n,`,
  `T\u00e0o Th\u00e1o li\u1ec1n ph\u00f3ng h\u1ecfa \u0111\u1ed1t \u00d4 S\u00e0o,`,
  `kh\u00f4ng c\u00f2n g\u00ec \u0111\u1ec3 \u0103n th\u00ec \u0111\u00e1nh \u0111\u1ea5m g\u00ec n\u1eefa?`,
  `Th\u1ebf l\u00e0 Vi\u00ean Thi\u1ec7u \u0111\u1ea1i b\u1ea1i,`,
  `c\u00f3 l\u1ebd l\u00e0 thua tr\u1eadn, t\u00e2m tr\u1ea1ng kh\u00f4ng t\u1ed1t, kh\u00f4ng l\u00e2u sau Vi\u00ean Thi\u1ec7u b\u1ec7nh ch\u1ebft.`,
  `G\u1ea7n nh\u01b0 to\u00e0n b\u1ed9 ph\u00eda B\u1eafc thu\u1ed9c v\u1ec1 T\u00e0o Th\u00e1o,`,
  `T\u00e0o Th\u00e1o l\u00e0 ai?`,
  `Th\u1ed1ng nh\u1ea5t ph\u01b0\u01a1ng B\u1eafc l\u00e0 \u0111\u1ee7 r\u1ed3i sao?`,
  `Th\u1ebf l\u00e0 T\u00e0o Th\u00e1o ti\u1ebfn xu\u1ed1ng ph\u00eda nam, vi\u1ec7c \u0111\u1ea7u ti\u00ean l\u00e0 chi\u1ebfm c\u1ee9 Kinh Ch\u00e2u, \u0111\u1ea1i b\u1ea3n doanh c\u1ee7a L\u01b0u Bi\u1ec3u.`,
  `L\u00fac n\u00e0y, L\u01b0u B\u1ecb c\u00f9ng hai em trai tr\u01b0\u1edbc \u0111\u00f3 v\u1ed1n kh\u00f4ng m\u1ea5y ti\u1ebfng t\u0103m c\u0169ng \u0111\u00e3 ba l\u1ea7n \u0111\u1ebfn l\u1ec1u tranh m\u1eddi \u0111\u01b0\u1ee3c Gia C\u00e1t L\u01b0\u1ee3ng \u1edf Kinh Ch\u00e2u.`,
  `Sau khi T\u00e0o Th\u00e1o \u0111\u1ebfn, Gia C\u00e1t L\u01b0\u1ee3ng d\u1eabn L\u01b0u B\u1ecb v\u00e0 T\u00f4n Quy\u1ec1n li\u00ean minh ch\u1ed1ng l\u1ea1i T\u00e0o Th\u00e1o.`,
  `Sau \u0111\u00f3 l\u00e0 tr\u1eadn X\u00edch B\u00edch n\u1ed5i ti\u1ebfng.`,
  `T\u00e0o Th\u00e1o d\u1eabn hai m\u01b0\u01a1i v\u1ea1n \u0111\u1ea1i qu\u00e2n d\u00e0n tr\u1eadn \u1edf X\u00edch B\u00edch.`,
  `Trong khi li\u00ean qu\u00e2n T\u00f4n \u2013 L\u01b0u ch\u1ec9 c\u00f3 n\u0103m v\u1ea1n ng\u01b0\u1eddi.`,
  `Nh\u01b0ng qu\u00e2n T\u00e0o Th\u00e1o \u0111\u1ec1u l\u00e0 binh l\u00ednh ph\u01b0\u01a1ng B\u1eafc, kh\u00f4ng gi\u1ecfi th\u1ee7y chi\u1ebfn.`,
  `\u0110\u1ec3 gi\u1ea3m b\u1edbt s\u1ef1 chao \u0111\u1ea3o c\u1ee7a thuy\u1ec1n.`,
  `T\u00e0o Th\u00e1o ra l\u1ec7nh d\u00f9ng d\u00e2y x\u00edch n\u1ed1i c\u00e1c chi\u1ebfn thuy\u1ec1n l\u1ea1i v\u1edbi nhau.`,
  `T\u00f4n Quy\u1ec1n c\u00f3 hai \u0111\u1ea1i t\u01b0\u1edbng.`,
  `Chu Du v\u00e0 Ho\u00e0ng C\u00e1i.`,
  `Khi Ho\u00e0ng C\u00e1i nghe tin qu\u00e2n T\u00e0o n\u1ed1i thuy\u1ec1n l\u1ea1i v\u1edbi nhau.`,
  `\u00d4ng li\u1ec1n \u0111\u1ec1 ngh\u1ecb Chu Du d\u00f9ng h\u1ecfa c\u00f4ng.`,
  `Nh\u01b0ng l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 ch\u00e2m ng\u00f2i cho qu\u00e2n T\u00e0o \u0111\u00e2y?`,
  `\u0110\u1ec3 \u0111\u1ea1t \u0111\u01b0\u1ee3c m\u1ee5c \u0111\u00edch n\u00e0y,`,
  `Ho\u00e0ng C\u00e1i v\u00e0 Chu Du \u0111\u00e3 d\u00e0n d\u1ef1ng m\u1ed9t m\u00e0n kh\u1ed5 nh\u1ee5c k\u1ebf.`,
  `Ho\u00e0ng C\u00e1i vi\u1ebft th\u01b0 cho T\u00e0o Th\u00e1o, n\u00f3i r\u1eb1ng h\u1eafn c\u1ea3m th\u1ea5y qu\u00e2n T\u00e0o m\u1ea1nh m\u1ebd \u0111\u1ebfn nh\u01b0\u1eddng n\u00e0o,`,
  `li\u00ean qu\u00e2n y\u1ebfu \u1edbt kh\u00f4ng th\u1ec3 ch\u1ecbu n\u1ed5i m\u1ed9t \u0111\u00f2n ra sao,`,
  `v\u00e0 mu\u1ed1n \u0111\u1ea7u h\u00e0ng T\u00e0o Th\u00e1o.`,
  `T\u00e0o Th\u00e1o c\u1ea3m th\u1ea5y l\u1eddi h\u1eafn n\u00f3i r\u1ea5t c\u00f3 l\u00fd, li\u1ec1n ch\u1ea5p nh\u1eadn s\u1ef1 \u0111\u1ea7u h\u00e0ng c\u1ee7a Ho\u00e0ng C\u00e1i,`,
  `v\u00e0 h\u1eb9n th\u1eddi gian g\u1eb7p m\u1eb7t.`,
  `\u0110\u1ebfn ng\u00e0y g\u1eb7p m\u1eb7t,`,
  `Ho\u00e0ng C\u00e1i d\u1eabn m\u01b0\u1eddi chi\u1ebfc thuy\u1ec1n l\u1edbn ti\u1ebfn v\u1ec1 ph\u00eda qu\u00e2n T\u00e0o,`,
  `tr\u00ean thuy\u1ec1n ch\u1ea5t \u0111\u1ea7y c\u1ecf kh\u00f4 t\u1ea9m d\u1ea7u.`,
  `Khi g\u1ea7n \u0111\u1ebfn doanh tr\u1ea1i T\u00e0o,`,
  `Ho\u00e0ng C\u00e1i li\u1ec1n ra l\u1ec7nh \u0111\u1ed1t thuy\u1ec1n.`,
  `H\u00f4m \u0111\u00f3 gi\u00f3 r\u1ea5t l\u1edbn,`,
  `thuy\u1ec1n c\u1ee9 th\u1ebf thu\u1eadn gi\u00f3 nhanh ch\u00f3ng lao v\u1ec1 ph\u00eda doanh tr\u1ea1i T\u00e0o,`,
  `Doanh tr\u1ea1i T\u00e0o b\u1ed7ng ch\u1ed1c bi\u1ebfn th\u00e0nh bi\u1ec3n l\u1eeda,`,
  `Qu\u00e2n T\u00e0o \u0111\u1ea1i lo\u1ea1n, li\u00ean qu\u00e2n T\u00f4n-L\u01b0u ch\u1edbp th\u1eddi c\u01a1 x\u00f4ng t\u1edbi ti\u00eau di\u1ec7t.`,
  `Qu\u00e2n T\u00e0o \u0111\u1ea1i b\u1ea1i, T\u00e0o Th\u00e1o ch\u1ea1y v\u1ec1 ph\u01b0\u01a1ng B\u1eafc l\u1ea7n n\u00e0y ch\u1ecbu t\u1ed5n th\u1ea5t n\u1eb7ng n\u1ec1,`,
  `\u00d4ng ta kh\u00f4ng c\u00f2n d\u00e1m t\u00f9y ti\u1ec7n nam chinh n\u1eefa.`,
  `Sau \u0111\u00f3, L\u01b0u B\u1ecb l\u1ea1i chi\u1ebfm \u0111\u00f3ng T\u1ee9 Xuy\u00ean,`,
  `T\u00e0o Th\u00e1o chi\u1ebfm H\u00e1n Trung, T\u00f4n Quy\u1ec1n th\u1ed1ng nh\u1ea5t ph\u01b0\u01a1ng Nam,`,
  `Th\u1ebf c\u1ee5c thi\u00ean h\u1ea1 di\u1ec5n bi\u1ebfn th\u00e0nh nh\u01b0 v\u1eady.`,
  `N\u0103m 220 sau C\u00f4ng nguy\u00ean,`,
  `T\u00e0o Th\u00e1o b\u1ec7nh m\u1ea5t, T\u00e0o Phi k\u1ebf v\u1ecb.`,
  `T\u00e0o Phi v\u1eeba l\u00ean ng\u00f4i \u0111\u00e3 ph\u1ebf H\u00e1n Hi\u1ebfn \u0110\u1ebf, l\u1eadp ra n\u01b0\u1edbc Ng\u1ee5y.`,
  `L\u01b0u B\u1ecb v\u00e0 T\u00f4n Quy\u1ec1n th\u1ea5y v\u1eady,`,
  `Nh\u00e0 h\u1ecd T\u00e0o \u0111\u00e3 x\u01b0ng \u0111\u1ebf r\u1ed3i, v\u1eady ch\u00fang ta c\u00f2n ch\u1edd g\u00ec n\u1eefa?`,
  `N\u0103m 221, L\u01b0u B\u1ecb l\u1eadp ra n\u01b0\u1edbc Th\u1ee5c,`,
  `N\u0103m 222, T\u00f4n Quy\u1ec1n l\u1eadp ra \u0110\u00f4ng Ng\u00f4.`,
  `V\u1eady l\u00e0 th\u1ef1c s\u1ef1 h\u00ecnh th\u00e0nh c\u1ee5c di\u1ec7n Tam qu\u1ed1c \u0111\u1ee9ng v\u1eefng.`,
  `C\u00f9ng l\u00fac Th\u1ee5c v\u00e0 Ng\u00f4 tuy\u00ean b\u1ed1 th\u00e0nh l\u1eadp qu\u1ed1c gia,`,
  `tr\u1eadn chi\u1ebfn cu\u1ed1i c\u00f9ng c\u1ee7a Tam Qu\u1ed1c, tr\u1eadn Di L\u0103ng, n\u1ed5 ra.`,
  `L\u00fd do th\u1ef1c ra r\u1ea5t \u0111\u01a1n gi\u1ea3n:`,
  `T\u00f4n Quy\u1ec1n \u0111\u00e3 gi\u1ebft Quan V\u0169, ng\u01b0\u1eddi anh em k\u1ebft ngh\u0129a th\u1ee9 hai c\u1ee7a L\u01b0u B\u1ecb,`,
  `L\u01b0u B\u1ecb mu\u1ed1n b\u00e1o th\u00f9.`,
  `Trong tr\u1eadn n\u00e0y, L\u01b0u B\u1ecb d\u1ed1c to\u00e0n l\u1ef1c d\u1eabn qu\u00e2n t\u1ea5n c\u00f4ng \u0110\u00f4ng Ng\u00f4.`,
  `T\u00f4n Quy\u1ec1n c\u1eed m\u1ed9t th\u01b0 sinh l\u00e0 L\u1ee5c T\u1ed1n \u0111\u1ed1i \u0111\u1ea7u v\u1edbi qu\u00e2n L\u01b0u.`,
  `D\u00f9 L\u01b0u B\u1ecb khi\u00eau chi\u1ebfn th\u1ebf n\u00e0o, L\u1ee5c T\u1ed1n v\u1eabn \u0111\u00f3ng c\u1eeda kh\u00f4ng ra.`,
  `Th\u1ea5y qu\u00e2n \u0110\u00f4ng Ng\u00f4 tr\u00e1nh giao chi\u1ebfn, L\u01b0u B\u1ecb \u0111\u00e3 \u0111\u00f3ng tr\u1ea1i li\u00ean ti\u1ebfp d\u00e0i b\u1ea3y tr\u0103m d\u1eb7m tr\u00ean \u0111\u01b0\u1eddng.`,
  `Th\u1ea5y nh\u1eefng h\u00e0ng tr\u1ea1i li\u00ean ho\u00e0n d\u00e0y \u0111\u1eb7c n\u00e0y,`,
  `L\u1ee5c T\u1ed1n n\u1ea3y ra m\u1ed9t k\u1ebf, \u00f4ng ph\u00e1i m\u1ed9t s\u1ed1 binh l\u00ednh l\u1ebbn v\u00e0o doanh tr\u1ea1i qu\u00e2n L\u01b0u v\u00e0o ban \u0111\u00eam,`,
  `\u0111\u1ed1t ph\u00e1 doanh tr\u1ea1i.`,
  `V\u00ec c\u00e1c doanh tr\u1ea1i n\u1ed1i li\u1ec1n nhau, n\u00ean khi m\u1ed9t ch\u1ed7 b\u1ed1c ch\u00e1y l\u00e0 to\u00e0n b\u1ed9 \u0111\u1ec1u ch\u00e1y r\u1ee5i.`,
  `Trong tr\u1eadn n\u00e0y, qu\u00e2n L\u01b0u g\u1ea7n nh\u01b0 b\u1ecb ti\u00eau di\u1ec7t ho\u00e0n to\u00e0n, L\u01b0u B\u1ecb may m\u1eafn tho\u00e1t ch\u1ebft.`,
  `Nh\u01b0ng ch\u1ec9 v\u00e0i ng\u00e0y sau, \u00f4ng c\u0169ng ra \u0111i.`,
  `Con trai \u00f4ng l\u00e0 L\u01b0u Thi\u1ec7n l\u00ean n\u1ed1i ng\u00f4i,`,
  `Gia C\u00e1t L\u01b0\u1ee3ng ph\u00f2 tr\u1ee3.`,
  `Sau \u0111\u00f3, th\u1ebf c\u1ee5c Tam qu\u1ed1c\u9f0e l\u1eadp k\u00e9o d\u00e0i h\u01a1n 40 n\u0103m,`,
  `cho \u0111\u1ebfn khi gia t\u1ed9c T\u01b0 M\u00e3, m\u1ed9t chi nh\u1ecf c\u1ee7a nh\u00e0 T\u00e0o, b\u1ea5t ng\u1edd tr\u1ed7i d\u1eady,`,
  `m\u1edbi thay \u0111\u1ed5i c\u1ee5c di\u1ec7n hi\u1ec7n t\u1ea1i.`,
  `Gia t\u1ed9c T\u01b0 M\u00e3 tr\u01b0\u1edbc ti\u00ean di\u1ec7t Th\u1ee5c,`,
  `sau \u0111\u00f3 th\u00f4n t\u00ednh T\u00e0o Ng\u1ee5y, cu\u1ed1i c\u00f9ng chi\u1ebfm l\u1ea5y \u0110\u00f4ng Ng\u00f4,`,
  `th\u1ed1ng nh\u1ea5t thi\u00ean h\u1ea1, l\u1eadp n\u00ean nh\u00e0 T\u1ea5n.`,
  `Nh\u00e0 T\u1ea5n c\u00f3 th\u1ec3 n\u00f3i l\u00e0 giai \u0111o\u1ea1n h\u1ed7n lo\u1ea1n nh\u1ea5t,`,
  `\u0111en t\u1ed1i nh\u1ea5t trong l\u1ecbch s\u1eed Trung Qu\u1ed1c.`,
  `Th\u1eddi Tam Qu\u1ed1c, T\u01b0 M\u00e3 \u00dd l\u00e0 qu\u00e2n s\u01b0 c\u1ee7a T\u00e0o Th\u00e1o, c\u00f9ng T\u00f4n Quy\u1ec1n,`,
  `L\u01b0u B\u1ecb giao chi\u1ebfn. Nh\u1edd n\u0103ng l\u1ef1c qu\u00e2n s\u1ef1 ch\u00ednh tr\u1ecb xu\u1ea5t s\u1eafc,`,
  `\u00f4ng li\u00ean t\u1ee5c ph\u00f2 t\u00e1 con trai T\u00e0o Th\u00e1o l\u00e0 T\u00e0o Phi,`,
  `ch\u00e1u n\u1ed9i T\u00e0o Du\u1ec7, ch\u1eaft T\u00e0o Ph\u01b0\u01a1ng ba \u0111\u1eddi ho\u00e0ng \u0111\u1ebf,`,
  `tr\u1edf th\u00e0nh nh\u00e2n v\u1eadt quy\u1ec1n l\u1ef1c th\u1ef1c s\u1ef1 c\u1ee7a n\u01b0\u1edbc Ng\u1ee5y.`,
  `Sau khi T\u01b0 M\u00e3 \u00dd ch\u1ebft, con trai \u00f4ng l\u00e0 T\u01b0 M\u00e3 Chi\u00eau n\u1eafm quy\u1ec1n,`,
  `T\u01b0 M\u00e3 Chi\u00eau c\u00f3 quy\u1ec1n th\u1ebf c\u1ef1c l\u1edbn,`,
  `T\u1ef1 phong m\u00ecnh l\u00e0 T\u1ea5n V\u01b0\u01a1ng,`,
  `Phong con trai m\u00ecnh l\u00e0 T\u01b0 M\u00e3 Vi\u00eam l\u00e0m Th\u00e1i t\u1eed,`,
  `B\u1eaft \u0111\u1ea7u chu\u1ea9n b\u1ecb thay th\u1ebf nh\u00e0 T\u00e0o.`,
  `Th\u1eddi k\u1ef3 n\u00e0y, T\u01b0 M\u00e3 Chi\u00eau \u0111\u00e3 di\u1ec7t Th\u1ee5c qu\u1ed1c.`,
  `Sau khi T\u01b0 M\u00e3 Chi\u00eau ch\u1ebft,`,
  `N\u0103m 265 sau C\u00f4ng nguy\u00ean,`,
  `T\u01b0 M\u00e3 Vi\u00eam ph\u1ebf b\u1ecf Ng\u1ee5y \u0110\u1ebf T\u00e0o Ho\u00e1n \u0111\u01b0\u01a1ng th\u1eddi,`,
  `T\u1ef1 l\u1eadp l\u00e0m Ho\u00e0ng \u0111\u1ebf, l\u1eadp ra n\u01b0\u1edbc T\u1ea5n,`,
  `\u0110\u1ecbnh \u0111\u00f4 \u1edf L\u1ea1c D\u01b0\u01a1ng, s\u1eed g\u1ecdi l\u00e0 T\u00e2y T\u1ea5n.`,
  `Vi\u1ec7c \u0111\u1ea7u ti\u00ean T\u01b0 M\u00e3 Vi\u00eam l\u00e0m sau khi l\u00ean ng\u00f4i l\u00e0 di\u1ec7t n\u1ed1t \u0110\u00f4ng Ng\u00f4, qu\u1ed1c gia cu\u1ed1i c\u00f9ng trong ba n\u01b0\u1edbc.`,
  `N\u0103m 280 sau C\u00f4ng nguy\u00ean, \u0110\u00f4ng Ng\u00f4 \u0111\u1ea7u h\u00e0ng,`,
  `K\u1ec3 t\u1eeb \u0111\u00f3 k\u1ebft th\u00fac t\u00ecnh tr\u1ea1ng chia c\u1eaft k\u00e9o d\u00e0i h\u00e0ng tr\u0103m n\u0103m,`,
  `Qu\u1ed1c gia m\u1ed9t l\u1ea7n n\u1eefa ho\u00e0n th\u00e0nh th\u1ed1ng nh\u1ea5t.`,
  `M\u01b0\u1eddi n\u0103m sau, T\u01b0 M\u00e3 Vi\u00eam l\u00e2m b\u1ec7nh qua \u0111\u1eddi, ng\u01b0\u1eddi con trai th\u1ee9 hai c\u1ee7a \u00f4ng l\u00e0 T\u01b0 M\u00e3 Trung l\u00ean ng\u00f4i.`,
  `Nh\u01b0ng T\u01b0 M\u00e3 Trung l\u1ea1i l\u00e0 m\u1ed9t k\u1ebb ng\u1ed1c.`,
  `C\u00f3 m\u1ed9t n\u0103m m\u1ea5t m\u00f9a \u0111\u00f3i k\u00e9m, c\u00f3 \u0111\u1ea1i th\u1ea7n t\u00e2u r\u1eb1ng d\u00e2n ch\u00fang v\u00f9ng thi\u00ean tai kh\u00f4ng c\u00f3 l\u01b0\u01a1ng th\u1ef1c \u0111\u1ec3 \u0103n,`,
  `c\u00f3 ng\u01b0\u1eddi \u0111\u00e3 ch\u1ebft \u0111\u00f3i. T\u01b0 M\u00e3 Trung v\u1eabn ng\u00e2y ng\u00f4 h\u1ecfi:`,
  `Kh\u00f4ng c\u00f3 l\u01b0\u01a1ng th\u1ef1c \u0111\u1ec3 \u0103n, v\u1eady sao kh\u00f4ng \u0103n th\u1ecbt?`,
  `K\u1ebb ng\u1ed1c l\u00e0m sao c\u00f3 th\u1ec3 cai tr\u1ecb \u0111\u1ea5t n\u01b0\u1edbc,`,
  `v\u00ec v\u1eady quy\u1ec1n l\u1ef1c tri\u1ec1u \u0111\u00ecnh r\u01a1i v\u00e0o tay Ho\u00e0ng h\u1eadu Gi\u1ea3 Nam Phong.`,
  `Nh\u1eefng ng\u01b0\u1eddi kh\u00e1c trong d\u00f2ng h\u1ecd T\u01b0 M\u00e3 \u0111\u01b0\u01a1ng nhi\u00ean kh\u00f4ng cam l\u00f2ng,`,
  `\u0111\u1ec1u mu\u1ed1n gi\u1ebft Gi\u1ea3 Nam Phong \u0111\u1ec3 n\u1eafm quy\u1ec1n.`,
  `Th\u1ebf l\u00e0 x\u1ea3y ra lo\u1ea1n B\u00e1t V\u01b0\u01a1ng n\u1ed5i ti\u1ebfng trong l\u1ecbch s\u1eed nh\u00e0 T\u1ea5n.`,
  `T\u00e1m v\u1ecb v\u01b0\u01a1ng n\u00e0y \u0111\u1ec1u l\u00e0 th\u00e0nh vi\u00ean ho\u00e0ng t\u1ed9c,`,
  `n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c l\u1edbn. Ban \u0111\u1ea7u,`,
  `Tri\u1ec7u V\u01b0\u01a1ng T\u01b0 M\u00e3 Lu\u00e2n \u0111\u00e3 gi\u1ebft Gi\u1ea3 Nam Phong v\u00e0 b\u00e8 \u0111\u1ea3ng c\u1ee7a b\u00e0 ta,`,
  `ph\u1ebf tru\u1ea5t Ho\u00e0ng \u0111\u1ebf T\u01b0 M\u00e3 Trung,`,
  `t\u1ef1 l\u1eadp l\u00e0m Ho\u00e0ng \u0111\u1ebf. Nh\u01b0ng c\u00e1c th\u00e0nh vi\u00ean kh\u00e1c trong d\u00f2ng h\u1ecd T\u01b0 M\u00e3 kh\u00f4ng ph\u1ee5c,`,
  `\u00d4ng ta kh\u00f4ng c\u00f2n c\u00e1ch n\u00e0o kh\u00e1c, l\u1ea1i tuy\u00ean b\u1ed1 tho\u00e1i v\u1ecb.`,
  `T\u01b0 M\u00e3 Trung ph\u1ee5c v\u1ecb.`,
  `Sau \u0111\u00f3, \u0110\u00f4ng H\u1ea3i V\u01b0\u01a1ng T\u01b0 M\u00e3 Vi\u1ec7t \u0111\u1ea7u \u0111\u1ed9c T\u01b0 M\u00e3 Trung.`,
  `\u1ee6ng l\u1eadp em trai c\u1ee7a T\u01b0 M\u00e3 Trung l\u00e0 T\u01b0 M\u00e3 X\u00edch k\u1ebf v\u1ecb.`,
  `M\u1edbi k\u1ebft th\u00fac lo\u1ea1n B\u00e1t V\u01b0\u01a1ng k\u00e9o d\u00e0i 5 n\u0103m.`,
  `Tr\u1eadn \u0111\u1ed9ng \u0111\u1ea5t ch\u00ednh tr\u1ecb trong tri\u1ec1u l\u1ea7n n\u00e0y,`,
  `khi\u1ebfn s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a ho\u00e0ng th\u1ea5t T\u00e2y T\u1ea5n b\u1ecb t\u1ed5n th\u1ea5t n\u1eb7ng n\u1ec1.`,
  `Kh\u00f4ng ch\u1ec9 nh\u00e2n d\u00e2n trong n\u01b0\u1edbc n\u1ed5i d\u1eady, c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 b\u00ean ngo\u00e0i c\u0169ng d\u00f2m ng\u00f3 T\u00e2y T\u1ea5n.`,
  `N\u0103m 308 sau C\u00f4ng nguy\u00ean,`,
  `Hung N\u00f4 \u0110\u1ea1i Thi\u1ec1n Vu L\u01b0u Uy\u00ean k\u1ebf v\u1ecb.`,
  `B\u1eaft \u0111\u1ea7u qu\u00e1 tr\u00ecnh di\u1ec7t T\u1ea5n.`,
  `M\u1eb7c d\u00f9 \u00f4ng ta h\u1ecd L\u01b0u, nh\u01b0ng \u00f4ng ta kh\u00f4ng c\u00f3 ch\u00fat li\u00ean h\u1ec7 n\u00e0o v\u1edbi ng\u01b0\u1eddi H\u00e1n.`,
  `L\u00e0 ng\u01b0\u1eddi Hung N\u00f4 100%.`,
  `Sau khi \u0111\u0103ng c\u01a1, L\u01b0u Uy\u00ean l\u1eadp t\u1ee9c sai con trai L\u01b0u Th\u00f4ng d\u1eabn qu\u00e2n t\u1ea5n c\u00f4ng L\u1ea1c D\u01b0\u01a1ng, kinh \u0111\u00f4 c\u1ee7a T\u00e2y T\u1ea5n.`,
  `L\u00fac \u0111\u00f3, ng\u01b0\u1eddi n\u1eafm quy\u1ec1n \u1edf L\u1ea1c D\u01b0\u01a1ng l\u00e0 T\u01b0 M\u00e3 Vi\u1ec7t.`,
  `\u0110\u1ec3 t\u1ef1 b\u1ea3o v\u1ec7, \u00f4ng d\u1eabn 4 v\u1ea1n qu\u00e2n v\u00e0 m\u1ed9t s\u1ed1 l\u01b0\u1ee3ng l\u1edbn tri\u1ec1u th\u1ea7n tr\u1ed1n kh\u1ecfi L\u1ea1c D\u01b0\u01a1ng.`,
  `L\u01b0u Th\u00f4ng nh\u00e2n c\u01a1 h\u1ed9i \u0111\u00f3 \u0111\u00e1nh chi\u1ebfm L\u1ea1c D\u01b0\u01a1ng, b\u1eaft ho\u00e0ng \u0111\u1ebf T\u01b0 M\u00e3 X\u00edch \u0111i.`,
  `Ho\u00e0ng \u0111\u1ebf b\u1ecb b\u1eaft, c\u00e1c quan l\u1ea1i c\u0169ng kh\u00f4ng truy \u0111u\u1ed5i.`,
  `H\u1ecd l\u1ea1i l\u1eadp m\u1ed9t ho\u00e0ng \u0111\u1ebf kh\u00e1c l\u00e0 T\u01b0 M\u00e3 Nghi\u1ec7p,`,
  `d\u1eddi \u0111\u00f4 v\u1ec1 Tr\u01b0\u1eddng An. N\u0103m 316 sau C\u00f4ng nguy\u00ean,`,
  `Tr\u01b0\u1eddng An c\u0169ng b\u1ecb \u0111\u1ea1i qu\u00e2n Hung N\u00f4 c\u00f4ng ph\u00e1.`,
  `T\u01b0 M\u00e3 Nghi\u1ec7p \u0111\u1ea7u h\u00e0ng,`,
  `T\u00e2y T\u1ea5n di\u1ec7t vong, tr\u1edf th\u00e0nh tri\u1ec1u \u0111\u1ea1i \u0111\u1ea7u ti\u00ean b\u1ecb ngo\u1ea1i t\u1ed9c ti\u00eau di\u1ec7t.`,
  `Trung Qu\u1ed1c sau m\u1ed9t th\u1eddi gian th\u1ed1ng nh\u1ea5t ng\u1eafn ng\u1ee7i, l\u1ea1i tr\u1edf l\u1ea1i tr\u1ea1ng th\u00e1i chia c\u1eaft.`,
  `V\u00e0 s\u1ef1 chia c\u1eaft n\u00e0y k\u00e9o d\u00e0i h\u01a1n 300 n\u0103m.`,
  `Sau khi T\u00e2y T\u1ea5n di\u1ec7t vong,`,
  `m\u1ed9t s\u1ed1 c\u1ef1u th\u1ea7n c\u1ee7a tri\u1ec1u \u0111\u00ecnh kh\u00f4ng cam t\u00e2m v\u1edbi s\u1ed1 ph\u1eadn m\u1ea5t n\u01b0\u1edbc,`,
  `v\u1eabn t\u00edch c\u1ef1c ho\u1ea1t \u0111\u1ed9ng kh\u1eafp n\u01a1i tr\u00ean c\u1ea3 n\u01b0\u1edbc,`,
  `chu\u1ea9n b\u1ecb kh\u00f4i ph\u1ee5c s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a nh\u00e0 T\u1ea5n.`,
  `N\u0103m sau, m\u1ed9t qu\u00fd t\u1ed9c h\u1ecd T\u01b0 M\u00e3 l\u00e0 T\u01b0 M\u00e3 Du\u1ec7 \u1edf Ki\u1ebfn Khang,`,
  `t\u1ee9c l\u00e0 h\u00f4m nay x\u01b0ng \u0111\u1ebf \u1edf Nam Kinh,`,
  `qu\u1ed1c hi\u1ec7u v\u1eabn l\u00e0 T\u1ea5n,`,
  `s\u1eed g\u1ecdi l\u00e0 \u0110\u00f4ng T\u1ea5n. T\u1ea1i sao l\u1ea1i x\u01b0ng \u0111\u1ebf \u1edf ph\u01b0\u01a1ng Nam?`,
  `V\u00ec l\u00fac n\u00e0y ph\u01b0\u01a1ng B\u1eafc \u0111\u00e3 b\u1ecb ngo\u1ea1i t\u1ed9c chi\u1ebfm \u0111\u00f3ng,`,
  `h\u1ecd c\u0169ng kh\u00f4ng th\u1ec3 quay v\u1ec1.`,
  `V\u00ec v\u1eady, ph\u1ea1m vi cai tr\u1ecb c\u1ee7a \u0110\u00f4ng T\u1ea5n ch\u1ec9 gi\u1edbi h\u1ea1n \u1edf khu v\u1ef1c Giang Nam.`,
  `M\u1eb7c d\u00f9 trong th\u1eddi gian cai tr\u1ecb c\u0169ng c\u00f3 m\u1ed9t s\u1ed1 cu\u1ed9c n\u1ed5i lo\u1ea1n,`,
  `nh\u01b0ng \u0111\u1ec1u b\u1ecb d\u1eadp t\u1eaft.`,
  `Sau khi \u0110\u00f4ng T\u1ea5n ph\u00e1t tri\u1ec3n t\u01b0\u01a1ng \u0111\u1ed1i \u1ed5n \u0111\u1ecbnh trong v\u00e0i th\u1eadp k\u1ef7,`,
  `nh\u00e0 T\u01b0 M\u00e3 xu\u1ea5t hi\u1ec7n m\u1ed9t v\u00e0i v\u1ecb ho\u00e0ng \u0111\u1ebf ngu\u1ef5 bi\u1ec7n v\u00e0 b\u1ea5t t\u00e0i,`,
  `quy\u1ec1n l\u1ef1c ho\u00e0ng gia b\u1eaft \u0111\u1ea7u suy y\u1ebfu, sau \u0111\u00f3 l\u1ea1i b\u00f9ng n\u1ed5 cu\u1ed9c kh\u1edfi ngh\u0129a c\u1ee7a d\u00e2n th\u01b0\u1eddng k\u00e9o d\u00e0i m\u01b0\u1eddi hai n\u0103m,`,
  `ho\u00e0ng th\u1ea5t c\u00e0ng suy t\u00e0n h\u01a1n.`,
  `N\u0103m 420 sau C\u00f4ng nguy\u00ean,`,
  `l\u00e3nh \u0111\u1ea1o qu\u00e2n \u0111\u1ed9i L\u01b0u D\u1ee5 \u0111\u00e3 ph\u1ebf tru\u1ea5t v\u1ecb ho\u00e0ng \u0111\u1ebf cu\u1ed1i c\u00f9ng c\u1ee7a \u0110\u00f4ng T\u1ea5n l\u00e0 T\u01b0 M\u00e3 \u0110\u1ee9c V\u0103n,`,
  `t\u1ef1 l\u1eadp l\u00e0m vua, l\u1eadp ra nh\u00e0 L\u01b0u T\u1ed1ng.`,
  `Mi\u1ec1n Nam b\u01b0\u1edbc v\u00e0o th\u1eddi Nam Tri\u1ec1u.`,
  `N\u00f3i \u0111\u1ebfn \u0111\u00e2y, th\u1eddi gian quay tr\u1edf l\u1ea1i th\u1eddi Hung N\u00f4 di\u1ec7t T\u00e2y T\u1ea5n,`,
  `Nh\u1eefng qu\u00fd t\u1ed9c \u0111\u00f3 \u0111\u00e3 kh\u00f4ng ch\u1ea1y xu\u1ed1ng Giang Nam \u0111\u1ec3 l\u1eadp ra \u0110\u00f4ng T\u1ea5n sao?`,
  `\u0110\u1ed3ng th\u1eddi, mi\u1ec1n B\u1eafc Trung Qu\u1ed1c b\u1ecb c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 ki\u1ec3m so\u00e1t,`,
  `Chia th\u00e0nh v\u00f4 s\u1ed1 qu\u1ed1c gia v\u00e0 ch\u00ednh quy\u1ec1n,`,
  `Ch\u00fang th\u00f4n t\u00ednh l\u1eabn nhau.`,
  `V\u00ec s\u1ed1 l\u01b0\u1ee3ng qu\u1ed1c gia qu\u00e1 nhi\u1ec1u,`,
  `V\u00e0 s\u1ef1 thay \u0111\u1ed5i ch\u00ednh quy\u1ec1n qu\u00e1 nhanh,`,
  `Ch\u1ec9 m\u01b0\u1eddi s\u00e1u qu\u1ed1c gia c\u00f3 ch\u00fat ti\u1ebfng t\u0103m trong l\u1ecbch s\u1eed \u0111\u01b0\u1ee3c c\u00e1c nh\u00e0 s\u1eed h\u1ecdc ghi l\u1ea1i.`,
  `M\u01b0\u1eddi s\u00e1u qu\u1ed1c gia n\u00e0y h\u1ea7u nh\u01b0 t\u1ea5t c\u1ea3 \u0111\u1ec1u do c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 Hung N\u00f4,`,
  `Ti\u00ean Ti, Kh\u01b0\u01a1ng, \u0110\u00ea, Y\u1ebft th\u00e0nh l\u1eadp,`,
  `V\u00ec v\u1eady \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 Ng\u0169 H\u1ed3 Th\u1eadp L\u1ee5c Qu\u1ed1c.`,
  `Th\u1eddi k\u1ef3 n\u00e0y c\u0169ng l\u00e0 th\u1eddi k\u1ef3 \u0111en t\u1ed1i nh\u1ea5t trong l\u1ecbch s\u1eed Trung Qu\u1ed1c.`,
  `C\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 th\u1eddi b\u1ea5y gi\u1edd r\u1ea5t man r\u1ee3,`,
  `Th\u1ea5y l\u01b0\u01a1ng th\u1ef1c l\u00e0 c\u01b0\u1edbp \u0111o\u1ea1t,`,
  `Gi\u1ebft ng\u01b0\u1eddi nh\u01b0 gi\u1ebft s\u00fac v\u1eadt.`,
  `Ph\u1ee5 n\u1eef H\u00e1n b\u1ecb g\u1ecdi l\u00e0 d\u00ea hai ch\u00e2n,`,
  `b\u1ecb ng\u01b0\u1eddi H\u1ed3 \u0103n th\u1ecbt t\u00e0n nh\u1eabn,`,
  `nh\u1eefng ng\u01b0\u1eddi kh\u00f4ng \u0103n h\u1ebft s\u1ebd b\u1ecb d\u00ecm ch\u1ebft.`,
  `N\u01a1i n\u00e0o ng\u01b0\u1eddi H\u1ed3 \u0111i qua,`,
  `ng\u01b0\u1eddi H\u00e1n ph\u1ea3i ch\u1ecbu tai h\u1ecda di\u1ec7t vong, nh\u01b0 \u0111\u1ecba ng\u1ee5c tr\u1ea7n gian.`,
  `Th\u1eddi \u0111\u00f3, r\u1ea5t \u00edt ng\u01b0\u1eddi H\u00e1n c\u00f3 th\u1ec3 s\u1ed1ng s\u00f3t.`,
  `V\u00e0 c\u1ee9 th\u1ebf, sau h\u01a1n m\u1ed9t tr\u0103m n\u0103m h\u1ed7n chi\u1ebfn \u1edf ph\u01b0\u01a1ng B\u1eafc,`,
  `n\u0103m 439 CN, ch\u00ednh quy\u1ec1n B\u1eafc Ng\u1ee5y do Th\u00e1c B\u1ea1t B\u1ed1 c\u1ee7a t\u1ed9c Ti\u00ean Ti th\u00e0nh l\u1eadp \u0111\u00e3 th\u1ed1ng nh\u1ea5t ph\u01b0\u01a1ng B\u1eafc.`,
  `Ph\u01b0\u01a1ng B\u1eafc b\u01b0\u1edbc v\u00e0o th\u1eddi k\u1ef3 B\u1eafc tri\u1ec1u,`,
  `v\u00e0 c\u00f9ng v\u1edbi c\u00e1c ch\u00ednh quy\u1ec1n do ng\u01b0\u1eddi H\u00e1n th\u00e0nh l\u1eadp \u1edf ph\u01b0\u01a1ng Nam \u0111\u01b0\u1ee3c g\u1ecdi chung l\u00e0 Nam B\u1eafc tri\u1ec1u.`,
  `Sau \u0111\u00f3, Nam B\u1eafc tri\u1ec1u ph\u00e1t tri\u1ec3n ri\u00eang r\u1ebd.`,
  `Tr\u01b0\u1edbc h\u1ebft n\u00f3i v\u1ec1 Nam Tri\u1ec1u,`,
  `k\u1ec3 t\u1eeb khi L\u01b0u D\u1ee5 th\u00e0nh l\u1eadp L\u01b0u T\u1ed1ng,`,
  `Nam tri\u1ec1u \u0111\u00e3 tr\u1ea3i qua b\u1ed1n tri\u1ec1u \u0111\u1ea1i li\u00ean ti\u1ebfp,`,
  `l\u1ea7n l\u01b0\u1ee3t l\u00e0 T\u1ed1ng, T\u1ec1,`,
  `L\u01b0\u01a1ng, Tr\u1ea7n. Th\u1eddi gian t\u1ed3n t\u1ea1i c\u1ee7a c\u00e1c tri\u1ec1u \u0111\u1ea1i n\u00e0y t\u01b0\u01a1ng \u0111\u1ed1i ng\u1eafn,`,
  `d\u00e0i nh\u1ea5t l\u00e0 ch\u00edn m\u01b0\u01a1i l\u0103m n\u0103m, ng\u1eafn nh\u1ea5t ch\u1ec9 c\u00f3 hai m\u01b0\u01a1i ba n\u0103m.`,
  `V\u00ec b\u1ed1n tri\u1ec1u \u0111\u1ea1i Nam tri\u1ec1u \u0111\u1ec1u do ng\u01b0\u1eddi H\u00e1n l\u1eadp n\u00ean,`,
  `tuy th\u1eddi gian ng\u1eafn ng\u1ee7i, nh\u01b0ng v\u1edbi t\u01b0 c\u00e1ch l\u00e0 s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a ng\u01b0\u1eddi H\u00e1n,`,
  `\u0111\u00e3 gi\u00fap v\u0103n h\u00f3a H\u00e1n \u0111\u01b0\u1ee3c b\u1ea3o t\u1ed3n v\u00e0 ph\u00e1t tri\u1ec3n,`,
  `n\u00ean Nam tri\u1ec1u c\u00f3 v\u1ecb tr\u00ed v\u00f4 c\u00f9ng quan tr\u1ecdng trong l\u1ecbch s\u1eed Trung Qu\u1ed1c.`,
  `N\u00f3i v\u1ec1 B\u1eafc tri\u1ec1u,`,
  `nh\u00e0 Th\u00e1c B\u1ea1t qu\u1ea3n l\u00fd kh\u00e1 t\u1ed1t giai \u0111o\u1ea1n \u0111\u1ea7u.`,
  `\u0110\u1ebfn n\u0103m 534 sau C\u00f4ng nguy\u00ean,`,
  `Hi\u1ebfu V\u0169 \u0110\u1ebf Nguy\u00ean Tu c\u1ee7a B\u1eafc Ng\u1ee5y v\u00ec b\u1ea5t m\u00e3n v\u1edbi s\u1ef1 uy hi\u1ebfp c\u1ee7a quy\u1ec1n th\u1ea7n Cao Hoan,`,
  `\u0111\u00e3 b\u1ecf tr\u1ed1n \u0111\u1ebfn gia t\u1ed9c V\u0169 V\u0103n \u1edf Tr\u01b0\u1eddng An,`,
  `c\u00f2n Cao Hoan l\u1eadp m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf kh\u00e1c.`,
  `T\u1eeb \u0111\u00f3, B\u1eafc Ng\u1ee5y chia th\u00e0nh \u0110\u00f4ng Ng\u1ee5y v\u00e0 T\u00e2y Ng\u1ee5y.`,
  `Sau \u0111\u00f3, con trai c\u1ee7a Cao Hoan l\u00e0 Cao D\u01b0\u01a1ng v\u00e0 V\u0169 V\u0103n Gi\u00e1c l\u1ea7n l\u01b0\u1ee3t ph\u1ebf tru\u1ea5t c\u00e1c ho\u00e0ng \u0111\u1ebf \u0110\u00f4ng Ng\u1ee5y v\u00e0 T\u00e2y Ng\u1ee5y,`,
  `Th\u00e0nh l\u1eadp B\u1eafc T\u1ec1 v\u00e0 B\u1eafc Chu.`,
  `Sau \u0111\u00f3, B\u1eafc Chu d\u01b0\u1edbi s\u1ef1 cai tr\u1ecb c\u1ee7a V\u0169 V\u0103n Ung,`,
  `\u0111\u1ea5t n\u01b0\u1edbc gi\u00e0u m\u1ea1nh, d\u00e2n c\u01b0\u1eddng. Sau khi V\u0169 V\u0103n Ung qua \u0111\u1eddi,`,
  `truy\u1ec1n ng\u00f4i cho tr\u01b0\u1edfng t\u1eed V\u0169 V\u0103n U\u00e2n.`,
  `V\u0169 V\u0103n U\u00e2n l\u1ea5y con g\u00e1i D\u01b0\u01a1ng Ki\u00ean l\u00e0 D\u01b0\u01a1ng L\u1ec7 Hoa,`,
  `b\u1ea3n th\u00e2n \u00f4ng ta h\u00f4n \u00e1m t\u00e0n b\u1ea1o, n\u00ean \u0111\u1ea1i quy\u1ec1n d\u1ea7n r\u01a1i v\u00e0o tay \u00f4ng l\u00e3o D\u01b0\u01a1ng Ki\u00ean.`,
  `V\u0169 V\u0103n U\u00e2n qua \u0111\u1eddi khi m\u1edbi hai m\u01b0\u01a1i hai tu\u1ed5i,`,
  `n\u00ean con trai \u00f4ng l\u00e0 T\u1ea5n \u0110\u1ebf k\u1ebf v\u1ecb khi tu\u1ed5i c\u00f2n r\u1ea5t nh\u1ecf.`,
  `Sau \u0111\u00f3, D\u01b0\u01a1ng Ki\u00ean ph\u1ebf b\u1ecf T\u1ea5n \u0110\u1ebf v\u00e0o n\u0103m 581,`,
  `th\u00e0nh l\u1eadp tri\u1ec1u T\u00f9y.`,
  `Sau \u0111\u00f3, T\u00f9y V\u0103n \u0110\u1ebf D\u01b0\u01a1ng Ki\u00ean l\u1ec7nh D\u01b0\u01a1ng Qu\u1ea3ng l\u00e0m nguy\u00ean so\u00e1i,`,
  `d\u1eabn n\u0103m m\u01b0\u01a1i v\u1ea1n \u0111\u1ea1i qu\u00e2n,`,
  `t\u1ea5n c\u00f4ng tri\u1ec1u Tr\u1ea7n, tri\u1ec1u \u0111\u1ea1i cu\u1ed1i c\u00f9ng \u1edf ph\u00eda Nam.`,
  `Tri\u1ec1u Tr\u1ea7n di\u1ec7t vong, ch\u1ea5m d\u1ee9t c\u1ee5c di\u1ec7n chia c\u1eaft g\u1ea7n ba tr\u0103m n\u0103m,`,
  `Trung Qu\u1ed1c l\u1ea1i th\u1ed1ng nh\u1ea5t.`,
  `Trong th\u1eddi Nam-B\u1eafc tri\u1ec1u,`,
  `c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 \u1edf ph\u00eda B\u1eafc Trung Qu\u1ed1c d\u1ea7n b\u1ecb H\u00e1n h\u00f3a,`,
  `\u0111\u1eb7t n\u1ec1n m\u00f3ng v\u1eefng ch\u1eafc cho s\u1ef1 th\u1ed1ng nh\u1ea5t Trung Qu\u1ed1c trong t\u01b0\u01a1ng lai.`,
  `Nh\u00e0 T\u00f9y cai tr\u1ecb Trung Qu\u1ed1c ch\u1ec9 v\u1ecfn v\u1eb9n 38 n\u0103m,`,
  `v\u1edbi hai \u0111\u1eddi vua l\u00e0 T\u00f9y V\u0103n \u0110\u1ebf D\u01b0\u01a1ng Ki\u00ean v\u00e0 T\u00f9y D\u1ea1ng \u0110\u1ebf D\u01b0\u01a1ng Qu\u1ea3ng.`,
  `Sau khi D\u01b0\u01a1ng Ki\u00ean l\u00ean ng\u00f4i,`,
  `\u00f4ng \u0111\u00e3 ki\u00ean quy\u1ebft th\u1ef1c hi\u1ec7n m\u1ed9t lo\u1ea1t c\u00e1c cu\u1ed9c c\u1ea3i c\u00e1ch x\u00e3 h\u1ed9i`,
  `v\u1ec1 ch\u00ednh tr\u1ecb, kinh t\u1ebf v\u00e0 c\u00e1c m\u1eb7t kh\u00e1c.`,
  `C\u1ee7ng c\u1ed1 s\u1ef1 cai tr\u1ecb c\u1ee7a nh\u00e0 T\u00f9y.`,
  `D\u01b0\u01a1ng Ki\u00ean tr\u1ecb v\u00ec hai m\u01b0\u01a1i b\u1ed1n n\u0103m,`,
  `N\u0103m 604 sau C\u00f4ng nguy\u00ean,`,
  `D\u01b0\u01a1ng Ki\u00ean qua \u0111\u1eddi. V\u1ec1 nguy\u00ean nh\u00e2n c\u00e1i ch\u1ebft c\u1ee7a D\u01b0\u01a1ng Ki\u00ean,`,
  `hi\u1ec7n c\u00f3 hai lu\u1ed3ng \u00fd ki\u1ebfn,`,
  `m\u1ed9t l\u00e0 \u00f4ng b\u1ecb con trai m\u00ecnh l\u00e0 D\u01b0\u01a1ng Qu\u1ea3ng ph\u00e1i ng\u01b0\u1eddi \u00e1m s\u00e1t,`,
  `hai l\u00e0 \u00f4ng ch\u1ebft v\u00ec b\u1ec7nh.`,
  `Sau \u0111\u00f3, T\u00f9y D\u1ea1ng \u0110\u1ebf D\u01b0\u01a1ng Qu\u1ea3ng n\u1ed1i ng\u00f4i.`,
  `D\u01b0\u01a1ng Qu\u1ea3ng l\u00e0 b\u1ea1o ch\u00faa n\u1ed5i ti\u1ebfng trong l\u1ecbch s\u1eed, sau khi l\u00ean ng\u00f4i, \u00f4ng ta b\u1eaft \u0111\u1ea7u x\u00e2y d\u1ef1ng c\u00f4ng tr\u00ecnh quy m\u00f4 l\u1edbn,`,
  `X\u00e2y d\u1ef1ng cung \u0111i\u1ec7n xa hoa,`,
  `\u0110\u00e0o \u0110\u1ea1i V\u1eadn H\u00e0 \u0111\u1ec3 th\u1ecfa m\u00e3n h\u01b0\u1edfng th\u1ee5 c\u00e1 nh\u00e2n.`,
  `\u0110\u1ec3 m\u1edf r\u1ed9ng s\u1ef1 cai tr\u1ecb, \u00f4ng ta kh\u00f4ng ng\u1eebng b\u00e0nh tr\u01b0\u1edbng ra b\u00ean ngo\u00e0i,`,
  `Ba l\u1ea7n chinh ph\u1ea1t Cao Ly, t\u1ee9c b\u00e1n \u0111\u1ea3o Tri\u1ec1u Ti\u00ean ng\u00e0y nay,`,
  `Nh\u01b0ng \u0111\u1ec1u kh\u00f4ng th\u00e0nh c\u00f4ng.`,
  `Chi\u1ebfn tranh li\u00ean mi\u00ean v\u00e0 b\u1ea1o ch\u00ednh nhi\u1ec1u n\u0103m,`,
  `Qu\u1ed1c l\u1ef1c c\u1ee7a nh\u00e0 T\u00f9y suy y\u1ebfu nghi\u00eam tr\u1ecdng,`,
  `Th\u1ebf l\u00e0 kh\u1eafp n\u01a1i tr\u00ean c\u1ea3 n\u01b0\u1edbc n\u1ed5i d\u1eady.`,
  `V\u00ec v\u1eady, v\u00e0o cu\u1ed1i th\u1eddi nh\u00e0 T\u00f9y,`,
  `D\u01b0\u01a1ng Qu\u1ea3ng \u0111\u00e0nh ph\u1ea3i \u0111i kh\u1eafp n\u01a1i tr\u1ea5n \u00e1p c\u00e1c cu\u1ed9c n\u1ed5i lo\u1ea1n.`,
  `Nh\u01b0ng r\u1ed1t cu\u1ed9c nh\u00e0 T\u00f9y \u0111\u00e3 m\u1ea5t th\u1ebf.`,
  `N\u0103m 618 sau C\u00f4ng nguy\u00ean,`,
  `V\u0169 V\u0103n H\u00f3a C\u1eadp, m\u1ed9t t\u01b0\u1edbng l\u0129nh nh\u00e0 T\u00f9y, \u0111\u00e3 ph\u00e1t \u0111\u1ed9ng binh bi\u1ebfn,`,
  `Vua T\u00f9y D\u1ea1ng \u0110\u1ebf D\u01b0\u01a1ng Qu\u1ea3ng t\u00e0n b\u1ea1o b\u1ecb th\u1eaft c\u1ed5, nh\u00e0 T\u00f9y di\u1ec7t vong.`,
  `Tri\u1ec1u \u0111\u1ea1i nh\u00e0 T\u00f9y tuy ng\u1eafn ng\u1ee7i,`,
  `nh\u01b0ng l\u1ea1i l\u00e0 m\u1ed9t tri\u1ec1u \u0111\u1ea1i c\u00f3 t\u00ednh k\u1ebf th\u1eeba, kh\u00f4ng ch\u1ec9 c\u00f3 nh\u1eefng \u0111\u00f3ng g\u00f3p n\u1ed5i b\u1eadt v\u1ec1 v\u0103n h\u00f3a,`,
  `kinh t\u1ebf m\u00e0 c\u00f2n kh\u00f4i ph\u1ee5c quan h\u1ec7 \u0111\u1ed1i ngo\u1ea1i g\u1ea7n nh\u01b0 b\u1ecb gi\u00e1n \u0111o\u1ea1n trong nhi\u1ec1u th\u1ebf k\u1ef7 do chia c\u1eaft v\u00e0 tranh ch\u1ea5p.`,
  `Th\u00f4ng qua giao th\u01b0\u01a1ng tr\u00ean con \u0111\u01b0\u1eddng t\u01a1 l\u1ee5a,`,
  `n\u00f3 \u0111\u00e3 th\u00fac \u0111\u1ea9y giao l\u01b0u gi\u1eefa Trung Qu\u1ed1c v\u00e0 T\u00e2y \u00c1,`,
  `\u0111\u1eb7t n\u1ec1n m\u00f3ng cho th\u1eddi th\u1ecbnh \u0110\u01b0\u1eddng sau n\u00e0y.`,
  `V\u00e0i n\u0103m sau khi nh\u00e0 T\u00f9y di\u1ec7t vong, nh\u00e0 \u0110\u01b0\u1eddng th\u1ed1ng nh\u1ea5t thi\u00ean h\u1ea1.`,
  `Nh\u00e0 \u0110\u01b0\u1eddng c\u00f3 t\u1ed5ng c\u1ed9ng hai m\u01b0\u01a1i m\u1ed1t v\u1ecb ho\u00e0ng \u0111\u1ebf,`,
  `tr\u1ea3i qua hai tr\u0103m t\u00e1m m\u01b0\u01a1i ch\u00edn n\u0103m.`,
  `H\u00f4m nay ch\u00fang ta s\u1ebd chia hai m\u01b0\u01a1i m\u1ed1t v\u1ecb ho\u00e0ng \u0111\u1ebf n\u00e0y th\u00e0nh ba nh\u00f3m \u0111\u1ec3 n\u00f3i:`,
  `nh\u1eefng ng\u01b0\u1eddi r\u1ef1c r\u1ee1 bu\u1ed5i \u0111\u1ea7u, nh\u1eefng ng\u01b0\u1eddi t\u1ea7m th\u01b0\u1eddng \u1edf gi\u1eefa v\u00e0 nh\u1eefng ng\u01b0\u1eddi \u0111i\u00ean r\u1ed3 cu\u1ed1i c\u00f9ng.`,
  `Tr\u01b0\u1edbc ti\u00ean h\u00e3y n\u00f3i v\u1ec1 \u0110\u01b0\u1eddng Cao T\u1ed5 L\u00fd Uy\u00ean,`,
  `nh\u00e0 h\u1ecd L\u00fd l\u00e0 m\u1ed9t gia t\u1ed9c qu\u00fd t\u1ed9c, m\u1ed7i th\u1ebf h\u1ec7 \u0111\u1ec1u c\u00f3 ng\u01b0\u1eddi l\u00e0m quan l\u1edbn.`,
  `Cu\u1ed1i th\u1eddi nh\u00e0 T\u00f9y, T\u00f9y D\u1ea1ng \u0110\u1ebf D\u01b0\u01a1ng Qu\u1ea3ng \u0111\u00e3 c\u1eed L\u00fd Uy\u00ean \u0111i tr\u1ea5n \u00e1p c\u00e1c cu\u1ed9c n\u1ed5i d\u1eady,`,
  `\u00d4ng ta \u0111\u00e3 \u0111\u00e1nh b\u1ea1i nhi\u1ec1u l\u1ef1c l\u01b0\u1ee3ng ch\u1ed1ng nh\u00e0 T\u00f9y th\u00e0nh c\u00f4ng,`,
  `v\u00e0 kh\u00f4ng ng\u1eebng t\u0103ng c\u01b0\u1eddng s\u1ee9c m\u1ea1nh b\u1eb1ng c\u00e1ch thu nh\u1eadn c\u00e1c \u0111\u1ed9i qu\u00e2n b\u1ea1i tr\u1eadn.`,
  `C\u00f9ng v\u1edbi s\u1ef1 l\u1edbn m\u1ea1nh c\u1ee7a th\u1ebf l\u1ef1c, c\u1ed9ng th\u00eam s\u1ef1 t\u00e0n b\u1ea1o trong cai tr\u1ecb c\u1ee7a D\u01b0\u01a1ng Qu\u1ea3ng,`,
  `nh\u00e0 T\u00f9y \u0111\u00e3 s\u1edbm m\u1ee5c ru\u1ed7ng.`,
  `L\u00fd Uy\u00ean n\u1eafm b\u1eaft th\u1eddi c\u01a1, d\u00f9ng danh ngh\u0129a ph\u1ebf b\u1ecf h\u00f4n qu\u00e2n,`,
  `c\u0169ng b\u1eaft \u0111\u1ea7u ch\u1ed1ng \u0111\u1ed1i nh\u00e0 T\u00f9y.`,
  `N\u0103m 618 c\u00f4ng nguy\u00ean,`,
  `T\u00f9y D\u1ea1ng \u0110\u1ebf D\u01b0\u01a1ng Qu\u1ea3ng b\u1ecb t\u01b0\u1edbng ph\u1ea3n lo\u1ea1n V\u0169 V\u0103n H\u00f3a C\u1eadp th\u1eaft c\u1ed5.`,
  `L\u00fd Uy\u00ean sau khi nghe tin n\u00e0y, li\u1ec1n l\u1eadp t\u1ee9c d\u1eabn qu\u00e2n chi\u1ebfm Tr\u01b0\u1eddng An,`,
  `l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf, th\u00e0nh l\u1eadp nh\u00e0 \u0110\u01b0\u1eddng.`,
  `Sau \u0111\u00f3, L\u00fd Uy\u00ean d\u1eb9p y\u00ean t\u1ea5t c\u1ea3 th\u1ebf l\u1ef1c \u1edf c\u00e1c v\u00f9ng,`,
  `Trung Qu\u1ed1c ch\u00ednh th\u1ee9c b\u01b0\u1edbc v\u00e0o th\u1eddi k\u1ef3 cai tr\u1ecb c\u1ee7a nh\u00e0 L\u00fd \u0110\u01b0\u1eddng.`,
  `M\u1eb7c d\u00f9 L\u00fd Uy\u00ean r\u1ea5t gi\u1ecfi \u0111\u00e1nh tr\u1eadn, nh\u01b0ng \u00f4ng ta c\u00f3 th\u1ec3 m\u1eafc ch\u1ee9ng r\u1ed1i lo\u1ea1n l\u1ef1a ch\u1ecdn.`,
  `Trong v\u1ea5n \u0111\u1ec1 ng\u01b0\u1eddi th\u1eeba k\u1ebf c\u1ee7a m\u00ecnh, \u00f4ng ta lu\u00f4n do d\u1ef1, thay \u0111\u1ed5i \u00fd \u0111\u1ecbnh nhi\u1ec1u l\u1ea7n,`,
  `d\u1eabn \u0111\u1ebfn con trai l\u1edbn c\u1ee7a \u00f4ng ta l\u00e0 L\u00fd Ki\u1ebfn Th\u00e0nh,`,
  `Con trai th\u1ee9 hai L\u00fd Th\u1ebf D\u00e2n v\u00e0 con trai th\u1ee9 t\u01b0 L\u00fd Nguy\u00ean C\u00e1t th\u01b0\u1eddng xuy\u00ean m\u00e2u thu\u1eabn.`,
  `N\u0103m 626 sau C\u00f4ng Nguy\u00ean,`,
  `L\u00fd Th\u1ebf D\u00e2n ph\u00e1t \u0111\u1ed9ng s\u1ef1 bi\u1ebfn Huy\u1ec1n V\u0169 M\u00f4n, gi\u1ebft ch\u1ebft anh c\u1ea3 L\u00fd Ki\u1ebfn Th\u00e0nh v\u00e0 em trai th\u1ee9 t\u01b0 L\u00fd Nguy\u00ean C\u00e1t, nh\u1eefng ng\u01b0\u1eddi ch\u1ed1ng \u0111\u1ed1i \u00f4ng,`,
  `c\u0169ng \u00e9p cha \u00f4ng l\u00e0 L\u00fd Uy\u00ean tho\u00e1i v\u1ecb,`,
  `l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf, \u0111\u1ed5i ni\u00ean hi\u1ec7u th\u00e0nh Trinh Qu\u00e1n.`,
  `L\u00fd Th\u1ebf D\u00e2n t\u1eeb nh\u1ecf \u0111\u00e3 theo L\u00fd Uy\u00ean chinh chi\u1ebfn kh\u1eafp n\u01a1i,`,
  `hi\u1ec3u r\u00f5 n\u1ed7i kh\u1ed5 c\u1ee7a d\u00e2n ch\u00fang, n\u00ean sau khi \u00f4ng k\u1ebf v\u1ecb,`,
  `\u0111\u1ed1i n\u1ed9i tr\u1ecdng d\u1ee5ng hi\u1ec1n t\u00e0i, ti\u1ebfn h\u00e0nh c\u1ea3i c\u00e1ch \u0111\u1ea5t n\u01b0\u1edbc,`,
  `th\u1ef1c h\u00e0nh ti\u1ebft ki\u1ec7m, gi\u1ea3m thu\u1ebf m\u00e1 lao d\u1ecbch,`,
  `b\u00e1ch t\u00ednh \u0111\u01b0\u1ee3c ngh\u1ec9 ng\u01a1i, \u0111\u1ea5t n\u01b0\u1edbc th\u00e1i b\u00ecnh th\u1ecbnh v\u01b0\u1ee3ng.`,
  `\u0110\u1ed1i ngo\u1ea1i, \u00f4ng chinh ph\u1ea1t Cao C\u00e2u Ly, di\u1ec7t \u0110\u00f4ng \u0110\u1ed9t Quy\u1ebft,`,
  `t\u1eeb \u0111\u00f3 x\u00f3a b\u1ecf m\u1ed1i \u0111e d\u1ecda c\u1ee7a c\u00e1c d\u00e2n t\u1ed9c T\u00e2y V\u1ef1c \u0111\u1ed1i v\u1edbi Trung Nguy\u00ean,`,
  `khi\u1ebfn \u0111\u1ebf qu\u1ed1c \u0110\u1ea1i \u0110\u01b0\u1eddng ph\u1ed3n vinh t\u1ed9t b\u1eadc,`,
  `s\u1eed g\u1ecdi l\u00e0 Trinh Qu\u00e1n Chi Tr\u1ecb.`,
  `Sau khi \u0110\u01b0\u1eddng Th\u00e1i T\u00f4ng L\u00fd Th\u1ebf D\u00e2n b\u0103ng h\u00e0, con trai \u00f4ng l\u00e0 \u0110\u01b0\u1eddng Cao T\u00f4ng L\u00fd Tr\u1ecb k\u1ebf v\u1ecb.`,
  `L\u00fd Tr\u1ecb l\u00e0 m\u1ed9t trong nh\u1eefng ho\u00e0ng \u0111\u1ebf t\u01b0\u01a1ng \u0111\u1ed1i b\u00ecnh th\u01b0\u1eddng v\u00e0o \u0111\u1ea7u th\u1eddi nh\u00e0 \u0110\u01b0\u1eddng,`,
  `nh\u01b0ng \u00f4ng l\u1ea1i c\u00f3 m\u1ed9t ng\u01b0\u1eddi v\u1ee3 c\u1ef1c k\u1ef3 t\u00e0i gi\u1ecfi l\u00e0 V\u00f5 T\u1eafc Thi\u00ean.`,
  `L\u00fd Tr\u1ecb tr\u1ecb v\u00ec kh\u00f4ng c\u00f3 c\u00f4ng tr\u1ea1ng hay sai l\u1ea7m l\u1edbn, \u00f4ng k\u1ebf th\u1eeba s\u1ef1 nghi\u1ec7p huy ho\u00e0ng c\u1ee7a cha l\u00e0 L\u00fd Th\u1ebf D\u00e2n,`,
  `\u0111\u1ea9y nh\u00e0 \u0110\u01b0\u1eddng ti\u1ebfn xa h\u01a1n \u0111\u1ebfn s\u1ef1 th\u1ecbnh v\u01b0\u1ee3ng.`,
  `L\u00fd Tr\u1ecb v\u00e0 V\u00f5 T\u1eafc Thi\u00ean c\u00f3 t\u1ed5ng c\u1ed9ng s\u00e1u ng\u01b0\u1eddi con,`,
  `hai trai, b\u1ed1n g\u00e1i, h\u1ecd l\u1ea7n l\u01b0\u1ee3t l\u00e0 C\u00f4ng ch\u00faa An \u0110\u1ecbnh T\u01b0,`,
  `Th\u00e1i B\u00ecnh C\u00f4ng ch\u00faa, L\u00fd Ho\u1eb1ng,`,
  `L\u00fd Hi\u1ec1n, L\u00fd Hi\u1ec3n v\u00e0 L\u00fd \u0110\u00e1n.`,
  `Cu\u1ed9c \u0111\u1eddi V\u00f5 T\u1eafc Thi\u00ean c\u00f3 th\u1ec3 g\u1ecdi l\u00e0 truy\u1ec1n k\u1ef3, b\u00e0 v\u1ed1n l\u00e0 phi t\u1ea7n c\u1ee7a L\u00fd Th\u1ebf D\u00e2n.`,
  `Sau khi L\u00fd Th\u1ebf D\u00e2n qua \u0111\u1eddi,`,
  `t\u1ea5t c\u1ea3 c\u00e1c phi t\u1ea7n ch\u01b0a sinh con \u0111\u1ec1u ph\u1ea3i xu\u1ea5t gia l\u00e0m ni c\u00f4,`,
  `V\u00f5 T\u1eafc Thi\u00ean l\u00e0 m\u1ed9t trong s\u1ed1 \u0111\u00f3.`,
  `Tuy nhi\u00ean, con trai c\u1ee7a L\u00fd Th\u1ebf D\u00e2n l\u00e0 L\u00fd Tr\u1ecb l\u1ea1i ph\u1ea3i l\u00f2ng ng\u01b0\u1eddi m\u1eb9 k\u1ebf n\u00e0y,`,
  `n\u00ean \u0111\u00e3 \u0111\u00f3n V\u00f5 T\u1eafc Thi\u00ean \u0111\u00e3 xu\u1ea5t gia tr\u1edf v\u1ec1 cung,`,
  `v\u00e0 phong l\u00e0m phi t\u1ea7n c\u1ee7a m\u00ecnh.`,
  `\u0110\u01b0\u01a1ng th\u1eddi, L\u00fd Tr\u1ecb c\u00f3 V\u01b0\u01a1ng ho\u00e0ng h\u1eadu.`,
  `V\u00f5 T\u1eafc Thi\u00ean \u0111\u1ec3 gi\u00e0nh quy\u1ec1n, \u0111\u00e3 t\u1ef1 tay gi\u1ebft ch\u1ebft con g\u00e1i \u0111\u1ea7u l\u00f2ng c\u1ee7a m\u00ecnh,`,
  `l\u00e0 c\u00f4ng ch\u00faa An \u0110\u1ecbnh T\u01b0 c\u00f2n l\u00e0 tr\u1ebb s\u01a1 sinh,`,
  `\u0111\u1ed5 t\u1ed9i cho V\u01b0\u01a1ng ho\u00e0ng h\u1eadu.`,
  `V\u01b0\u01a1ng ho\u00e0ng h\u1eadu b\u1ecb ph\u1ebf,`,
  `V\u00f5 T\u1eafc Thi\u00ean \u0111\u01b0\u1ee3c l\u1eadp l\u00e0m ho\u00e0ng h\u1eadu.`,
  `Sau \u0111\u00f3, V\u00f5 T\u1eafc Thi\u00ean l\u1ea1i b\u1eaft \u0111\u1ea7u can thi\u1ec7p v\u00e0o tri\u1ec1u ch\u00ednh,`,
  `L\u00fd Tr\u1ecb y\u1ebfu \u0111u\u1ed1i, kh\u00f4ng nh\u1eefng kh\u00f4ng ng\u0103n c\u1ea3n,`,
  `sau n\u00e0y c\u00f2n m\u1eddi V\u00f5 T\u1eafc Thi\u00ean c\u00f9ng m\u00ecnh qu\u1ea3n l\u00fd tri\u1ec1u ch\u00ednh.`,
  `T\u1eeb \u0111\u00f3 tr\u1edf \u0111i, V\u00f5 T\u1eafc Thi\u00ean th\u00e2u t\u00f3m \u0111\u1ea1i quy\u1ec1n.`,
  `Sau khi L\u00fd Tr\u1ecb qua \u0111\u1eddi, th\u00e1i t\u1eed L\u00fd Hi\u1ec3n k\u1ebf v\u1ecb,`,
  `n\u0103m m\u01b0\u01a1i t\u01b0 ng\u00e0y sau \u0111\u00e3 b\u1ecb m\u1eb9 gi\u00e0 V\u00f5 T\u1eafc Thi\u00ean ph\u1ebf tru\u1ea5t,`,
  `gi\u00e1ng l\u00e0m L\u01b0 L\u0103ng V\u01b0\u01a1ng, \u0111u\u1ed5i ra kh\u1ecfi Tr\u01b0\u1eddng An.`,
  `Sau \u0111\u00f3 l\u1eadp L\u00fd \u0110\u00e1n l\u00e0m ho\u00e0ng \u0111\u1ebf, nh\u01b0ng c\u0169ng ch\u01b0a \u0111\u01b0\u1ee3c v\u00e0i n\u0103m,`,
  `L\u00fd \u0110\u00e1n c\u0169ng b\u1ecb V\u00f5 T\u1eafc Thi\u00ean ph\u1ebf tru\u1ea5t,`,
  `B\u00e0 t\u1ef1 x\u01b0ng \u0111\u1ebf, \u0111\u1ed5i qu\u1ed1c hi\u1ec7u l\u00e0 Chu, tr\u1edf th\u00e0nh n\u1eef ho\u00e0ng \u0111\u1ebf \u0111\u1ea7u ti\u00ean v\u00e0 duy nh\u1ea5t trong l\u1ecbch s\u1eed Trung Qu\u1ed1c.`,
  `Trong th\u1eddi gian t\u1ea1i v\u1ecb, V\u00f5 T\u1eafc Thi\u00ean ti\u1ebfp t\u1ee5c th\u1ef1c hi\u1ec7n c\u00e1c l\u00fd t\u01b0\u1edfng tr\u1ecb qu\u1ed1c c\u1ee7a L\u00fd Th\u1ebf D\u00e2n v\u00e0 L\u00fd Tr\u1ecb,`,
  `\u0111\u01b0a \u0111\u1ebf ch\u1ebf l\u00ean m\u1ed9t t\u1ea7m cao m\u1edbi,`,
  `\u0111\u1eb7t n\u1ec1n m\u00f3ng v\u1eefng ch\u1eafc cho th\u1eddi k\u1ef3 Khai Nguy\u00ean th\u1ecbnh tr\u1ecb sau n\u00e0y.`,
  `Sau khi V\u00f5 T\u1eafc Thi\u00ean qua \u0111\u1eddi, b\u00e0 kh\u00f4ng giao l\u1ea1i quy\u1ec1n l\u1ef1c cho ng\u01b0\u1eddi nh\u00e0 h\u1ecd V\u00f5,`,
  `m\u00e0 tr\u1ea3 l\u1ea1i quy\u1ec1n ch\u00ednh tr\u1ecb cho ho\u00e0ng t\u1ed9c L\u00fd \u0110\u01b0\u1eddng.`,
  `Sau \u0111\u00f3, L\u01b0 L\u0103ng V\u01b0\u01a1ng L\u00fd Hi\u1ec3n b\u1ecb ph\u1ebf tru\u1ea5t \u0111\u01b0\u1ee3c tri\u1ec7u v\u1ec1 Tr\u01b0\u1eddng An,`,
  `m\u1ed9t l\u1ea7n n\u1eefa l\u00ean ng\u00f4i.`,
  `Tuy nhi\u00ean, s\u1ed1 ph\u1eadn c\u1ee7a L\u00fd Hi\u1ec3n v\u00f4 c\u00f9ng bi th\u1ea3m,`,
  `kh\u00f4ng l\u00e2u sau khi l\u00ean ng\u00f4i,`,
  `l\u1ea1i b\u1ecb Ho\u00e0ng h\u1eadu Vi H\u1eadu c\u1ee7a m\u00ecnh \u0111\u1ea7u \u0111\u1ed9c ch\u1ebft.`,
  `Vi H\u1eadu mu\u1ed1n h\u1ecdc theo V\u00f5 T\u1eafc Thi\u00ean, m\u1edf ra m\u1ed9t k\u1ef7 nguy\u00ean n\u1eef quy\u1ec1n kh\u00e1c.`,
  `Sau khi \u0111\u1ea7u \u0111\u1ed9c L\u00fd Hi\u1ec3n, b\u00e0 l\u1ea1i l\u1eadp m\u1ed9t ng\u01b0\u1eddi con trai c\u1ee7a L\u00fd Hi\u1ec3n l\u00e0 L\u00fd Tr\u1ecdng M\u1eadu l\u00e0m ho\u00e0ng \u0111\u1ebf b\u00f9 nh\u00ecn,`,
  `nh\u01b0ng V\u00f5 T\u1eafc Thi\u00ean l\u00e0 duy nh\u1ea5t, Vi H\u1eadu kh\u00f4ng ph\u1ea3i l\u00e0 b\u00e0 \u1ea5y th\u1ee9 hai.`,
  `Sau \u0111\u00f3, con trai c\u1ee7a L\u00fd \u0110\u00e1n l\u00e0 L\u00fd Long C\u01a1 v\u00e0 c\u00f4 ru\u1ed9t c\u1ee7a \u00f4ng l\u00e0 C\u00f4ng ch\u00faa Th\u00e1i B\u00ecnh \u0111\u00e3 ph\u00e1t \u0111\u1ed9ng ch\u00ednh bi\u1ebfn,`,
  `Gi\u1ebft Vi H\u1eadu, \u1ee7ng h\u1ed9 L\u00fd \u0110\u00e1n l\u00ean ng\u00f4i.`,
  `C\u00f3 th\u1ec3 L\u00fd \u0110\u00e1n t\u00ednh c\u00e1ch kh\u00e1 an ph\u1eadn, ho\u1eb7c c\u00f3 l\u1ebd \u00f4ng \u0111\u00e3 ch\u00e1n gh\u00e9t nh\u1eefng cu\u1ed9c tranh gi\u00e0nh trong ho\u00e0ng t\u1ed9c.`,
  `Ch\u1eb3ng bao l\u00e2u sau, b\u00e0 \u0111\u00e3 nh\u01b0\u1eddng ng\u00f4i cho con trai m\u00ecnh l\u00e0 L\u00fd Long C\u01a1.`,
  `L\u00fd Long C\u01a1 l\u00ean ng\u00f4i, ni\u00ean hi\u1ec7u l\u00e0 Khai Nguy\u00ean.`,
  `\u00d4ng ch\u00ednh l\u00e0 ng\u01b0\u1eddi \u0111\u00e3 t\u1ea1o n\u00ean th\u1eddi k\u1ef3 Khai Nguy\u00ean th\u1ecbnh tr\u1ecb.`,
  `S\u1ef1 cai tr\u1ecb s\u00e1ng su\u1ed1t c\u1ee7a L\u00fd Long C\u01a1, c\u00f9ng v\u1edbi n\u1ec1n t\u1ea3ng v\u1eefng ch\u1eafc do L\u00fd Th\u1ebf D\u00e2n,`,
  `L\u00fd Tr\u1ecb, V\u00f5 T\u1eafc Thi\u00ean \u0111\u00e3 g\u00e2y d\u1ef1ng tr\u01b0\u1edbc \u0111\u00f3,`,
  `khi\u1ebfn kinh t\u1ebf,`,
  `v\u0103n h\u00f3a, ngh\u1ec7 thu\u1eadt, khoa h\u1ecdc k\u1ef9 thu\u1eadt c\u1ee7a nh\u00e0 \u0110\u01b0\u1eddng \u0111\u1ec1u ph\u00e1t tri\u1ec3n r\u1ef1c r\u1ee1.`,
  `C\u00e1c n\u01b0\u1edbc l\u00e1ng gi\u1ec1ng \u0111\u1ec1u \u0111\u1ebfn th\u00f4ng th\u01b0\u01a1ng tri\u1ec1u c\u1ed1ng.`,
  `V\u0103n tr\u1ecb v\u00f5 c\u00f4ng \u0111\u1ec1u h\u01b0ng th\u1ecbnh.`,
  `Nh\u00e0 \u0110\u01b0\u1eddng tr\u1edf th\u00e0nh \u0111\u1ebf qu\u1ed1c h\u00f9ng m\u1ea1nh nh\u1ea5t th\u1ebf gi\u1edbi l\u00fac b\u1ea5y gi\u1edd.`,
  `Tuy nhi\u00ean, v\u00e0o cu\u1ed1i \u0111\u1eddi, L\u00fd Long C\u01a1 qu\u00e1 s\u1ee7ng \u00e1i Qu\u00fd phi D\u01b0\u01a1ng Ng\u1ecdc Ho\u00e0n.`,
  `Khi\u1ebfn nh\u00e0 h\u1ecd D\u01b0\u01a1ng c\u00f3 th\u1ebf l\u1ef1c.`,
  `D\u01b0\u01a1ng Qu\u1ed1c Trung, anh h\u1ecd c\u1ee7a D\u01b0\u01a1ng Ng\u1ecdc Ho\u00e0n, gi\u1eef ch\u1ee9c t\u1ec3 t\u01b0\u1edbng.`,
  `H\u1eafn tham \u00f4 x\u00e3 h\u1ed9i,`,
  `b\u00e0i tr\u1eeb ng\u01b0\u1eddi ch\u1ed1ng \u0111\u1ed1i, l\u00e0m lo\u1ea1n tri\u1ec1u ch\u00ednh,`,
  `x\u00e3 h\u1ed9i d\u1ea7n d\u1ea7n xu\u1ea5t hi\u1ec7n xu h\u01b0\u1edbng suy b\u1ea1i.`,
  `D\u01b0\u01a1ng Qu\u00fd Phi c\u00f2n c\u00f3 m\u1ed9t ng\u01b0\u1eddi con nu\u00f4i l\u00e0 An L\u1ed9c S\u01a1n,`,
  `l\u00e0 m\u1ed9t ng\u01b0\u1eddi H\u1ed3 lai,`,
  `\u00f4ng ta l\u00e0 t\u1ed5ng qu\u1ea3n ki\u00eam th\u1ed1ng l\u0129nh ba t\u1ec9nh,`,
  `n\u1eafm gi\u1eef binh quy\u1ec1n. An L\u1ed9c S\u01a1n c\u00f3 th\u00f9 v\u1edbi D\u01b0\u01a1ng Qu\u1ed1c Trung,`,
  `khi th\u1ea5y D\u01b0\u01a1ng Qu\u1ed1c Trung l\u00e0m lo\u1ea1n tri\u1ec1u ch\u00ednh,`,
  `li\u1ec1n l\u1ea5y danh ngh\u0129a th\u1ea3o ph\u1ea1t D\u01b0\u01a1ng Qu\u1ed1c Trung m\u00e0 d\u1ea5y binh t\u1ea5n c\u00f4ng Tr\u01b0\u1eddng An.`,
  `L\u00fd Long C\u01a1 b\u00e8n v\u1ed9i v\u00e0ng \u0111\u01b0a D\u01b0\u01a1ng Qu\u00fd Phi ch\u1ea1y \u0111\u1ebfn M\u00e3 Ng\u00f4i Pha,`,
  `nay l\u00e0 T\u00e2n B\u00ecnh, Thi\u1ec3m T\u00e2y.`,
  `C\u00e1c t\u01b0\u1edbng s\u0129 qu\u00e2n T\u00f9y c\u1ea3m th\u1ea5y t\u1ea5t c\u1ea3 l\u00e0 l\u1ed7i c\u1ee7a D\u01b0\u01a1ng Ng\u1ecdc Ho\u00e0n,`,
  `th\u1ebf l\u00e0 b\u1ee9c b\u00e1ch L\u00fd Long C\u01a1 gi\u1ebft D\u01b0\u01a1ng Ng\u1ecdc Ho\u00e0n.`,
  `M\u1ed9t n\u0103m sau binh bi\u1ebfn,`,
  `An L\u1ed9c S\u01a1n g\u1eb7p h\u1ecda t\u1eeb n\u1ed9i b\u1ed9, b\u1ecb con trai An Kh\u00e1nh T\u1ef1 gi\u1ebft.`,
  `Nh\u01b0ng cu\u1ed9c binh bi\u1ebfn v\u1eabn ch\u01b0a k\u1ebft th\u00fac,`,
  `Sau khi An L\u1ed9c S\u01a1n ch\u1ebft, ph\u1ea3i m\u1ea5t th\u00eam b\u1ea3y n\u0103m,`,
  `nh\u00e0 \u0110\u01b0\u1eddng m\u1edbi d\u1eadp t\u1eaft ho\u00e0n to\u00e0n lo\u1ea1n An S\u1eed n\u1ed5i ti\u1ebfng.`,
  `Cu\u1ed9c n\u1ed5i lo\u1ea1n n\u00e0y \u0111\u00e3 l\u00e0m suy y\u1ebfu \u0111\u00e1ng k\u1ec3 s\u1ee9c m\u1ea1nh c\u1ee7a nh\u00e0 \u0110\u01b0\u1eddng,`,
  `khi\u1ebfn nh\u00e0 \u0110\u01b0\u1eddng t\u1eeb th\u1ecbnh v\u01b0\u1ee3ng suy tho\u00e1i,`,
  `v\u00e0 tr\u1ef1c ti\u1ebfp d\u1eabn \u0111\u1ebfn c\u1ee5c di\u1ec7n c\u00e1t c\u1ee9 phi\u00ean tr\u1ea5n sau n\u00e0y.`,
  `M\u1ed9t lo\u1ea1t c\u00e1c ho\u00e0ng \u0111\u1ebf nh\u00e0 \u0110\u01b0\u1eddng gi\u1eefa th\u1eddi L\u00fd Long C\u01a1 \u0111\u1ec1u s\u1ee7ng \u00e1i ho\u1ea1n quan,`,
  `xa l\u00e1nh hi\u1ec1n t\u00e0i. T\u1eeb sau th\u1eddi \u0110\u1ee9c T\u00f4ng,`,
  `nhi\u1ec1u ho\u00e0ng \u0111\u1ebf nh\u00e0 \u0110\u01b0\u1eddng sau n\u00e0y ho\u1eb7c do ho\u1ea1n quan l\u1eadp,`,
  `ho\u1eb7c b\u1ecb ho\u1ea1n quan ph\u1ebf, th\u1eadm ch\u00ed b\u1ecb ho\u1ea1n quan gi\u1ebft.`,
  `Ho\u1ea1n quan tr\u1edf th\u00e0nh ng\u01b0\u1eddi n\u1eafm quy\u1ec1n th\u1ef1c s\u1ef1 c\u1ee7a ho\u00e0ng th\u1ea5t nh\u00e0 \u0110\u01b0\u1eddng l\u00fac b\u1ea5y gi\u1edd,`,
  `\u0111i\u1ec1u n\u00e0y khi\u1ebfn s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a \u0111\u1ebf qu\u1ed1c nh\u00e0 \u0110\u01b0\u1eddng c\u00e0ng th\u00eam t\u1ed3i t\u1ec7,`,
  `c\u00e1c d\u00e2n t\u1ed9c ngo\u1ea1i bang nh\u01b0 Th\u1ed5 Ph\u1ed3n, H\u1ed3i H\u1ed9t li\u00ean t\u1ee5c \u0111e d\u1ecda nh\u00e0 \u0110\u01b0\u1eddng.`,
  `\u0110\u1ebfn cu\u1ed1i th\u1eddi, t\u1eeb th\u1eddi M\u1ee5c T\u00f4ng,`,
  `c\u00e1c ho\u00e0ng \u0111\u1ebf b\u1eaft \u0111\u1ea7u th\u1ecbnh h\u00e0nh vi\u1ec7c d\u00f9ng thu\u1ed1c tr\u01b0\u1eddng sinh.`,
  `Trong s\u1ed1 m\u01b0\u1eddi v\u1ecb ho\u00e0ng \u0111\u1ebf sau n\u00e0y,`,
  `c\u00f3 ba ng\u01b0\u1eddi ch\u1ebft v\u00ec u\u1ed1ng \u0111an d\u01b0\u1ee3c.`,
  `C\u00f9ng v\u1edbi t\u00ecnh tr\u1ea1ng c\u00e1t c\u1ee9 phi\u00ean tr\u1ea5n k\u00e9o d\u00e0i, khi\u1ebfn s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a nh\u00e0 \u0110\u01b0\u1eddng ch\u1ec9 c\u00f2n tr\u00ean danh ngh\u0129a.`,
  `C\u00e1c phi\u00ean tr\u1ea5n \u0111\u1ecba ph\u01b0\u01a1ng tr\u00ean c\u1ea3 n\u01b0\u1edbc t\u1ef1 n\u1eafm quy\u1ec1n,`,
  `h\u1ecd \u0111\u1ec1u c\u00f3 binh quy\u1ec1n ri\u00eang.`,
  `V\u00ec v\u1eady, ho\u00e0ng t\u1ed9c cu\u1ed1i nh\u00e0 \u0110\u01b0\u1eddng ch\u1ee7 y\u1ebfu t\u1eadp trung d\u1eb9p lo\u1ea1n,`,
  `kh\u00f4ng c\u00f2n th\u1eddi gian lo \u0111\u1ebfn ph\u00e1t tri\u1ec3n kinh t\u1ebf,`,
  `v\u0103n h\u00f3a v\u00e0 c\u00e1c m\u1eb7t kh\u00e1c.`,
  `S\u1ee9c m\u1ea1nh qu\u1ed1c gia c\u1ee7a nh\u00e0 \u0110\u01b0\u1eddng ng\u00e0y c\u00e0ng suy y\u1ebfu,`,
  `kh\u00f4ng th\u1ec3 g\u01b0\u1ee3ng d\u1eady n\u1ed5i. Qu\u1ed1c gia suy y\u1ebfu, d\u00e2n ch\u00fang kh\u1ed1n kh\u1ed5,`,
  `nh\u1eefng cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n quen thu\u1ed9c l\u1ea1i xu\u1ea5t hi\u1ec7n,`,
  `nh\u00e0 \u0110\u01b0\u1eddng c\u0169ng kh\u00f4ng ngo\u1ea1i l\u1ec7.`,
  `Cu\u1ed1i nh\u00e0 \u0110\u01b0\u1eddng x\u1ea3y ra c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n quy m\u00f4 l\u1edbn,`,
  `trong \u0111\u00f3 m\u1ea1nh nh\u1ea5t l\u00e0 kh\u1edfi ngh\u0129a Ho\u00e0ng S\u00e0o.`,
  `Ho\u00e0ng S\u00e0o xu\u1ea5t th\u00e2n t\u1eeb gia \u0111\u00ecnh bu\u00f4n mu\u1ed1i.`,
  `Th\u1eddi c\u1ed5 \u0111\u1ea1i, nh\u1eefng ng\u01b0\u1eddi b\u00e1n mu\u1ed1i \u0111\u1ec1u r\u1ea5t gi\u00e0u c\u00f3,`,
  `v\u00ec v\u1eady Ho\u00e0ng S\u00e0o \u0111\u00e3 \u0111\u01b0\u1ee3c gi\u00e1o d\u1ee5c t\u1ed1t,`,
  `r\u1ea5t c\u00f3 t\u00e0i. Thu\u1edf nh\u1ecf, Ho\u00e0ng S\u00e0o nhi\u1ec1u l\u1ea7n tham gia c\u00e1c k\u1ef3 thi khoa b\u1ea3ng,`,
  `nh\u01b0ng \u00f4ng \u0111\u1ec1u kh\u00f4ng \u0111\u1ed7,`,
  `v\u1eeba hay l\u00fac \u0111\u00f3 c\u00f3 ng\u01b0\u1eddi t\u00ean V\u01b0\u01a1ng Ti\u00ean Chi ph\u00e1t \u0111\u1ed9ng kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n,`,
  `c\u00f3 l\u1ebd v\u00ec lu\u00f4n thi tr\u01b0\u1ee3t, nh\u1ea5t th\u1eddi kh\u00f4ng cam l\u00f2ng,`,
  `Ho\u00e0ng S\u00e0o li\u1ec1n tham gia kh\u1edfi ngh\u0129a.`,
  `Sau khi V\u01b0\u01a1ng Ti\u00ean Chi ch\u1ebft,`,
  `Ho\u00e0ng S\u00e0o \u0111\u01b0\u1ee3c b\u1ea7u l\u00e0m th\u1ee7 l\u0129nh m\u1edbi c\u1ee7a qu\u00e2n kh\u1edfi ngh\u0129a.`,
  `Sau hai m\u01b0\u01a1i l\u0103m n\u0103m \u0111\u1ea5u tranh,`,
  `cu\u1ed9c kh\u1edfi ngh\u0129a c\u1ee7a Ho\u00e0ng S\u00e0o v\u1eabn k\u1ebft th\u00fac b\u1eb1ng th\u1ea5t b\u1ea1i,`,
  `nh\u01b0ng cu\u1ed9c kh\u1edfi ngh\u0129a quy m\u00f4 l\u1edbn v\u00e0 k\u00e9o d\u00e0i ch\u01b0a t\u1eebng c\u00f3 n\u00e0y,`,
  `\u0111\u00e3 gi\u00e1ng m\u1ed9t \u0111\u00f2n ch\u00ed m\u1ea1ng tr\u1ef1c ti\u1ebfp v\u00e0o ho\u00e0ng th\u1ea5t nh\u00e0 \u0110\u01b0\u1eddng v\u1ed1n \u0111\u00e3 lung lay.`,
  `N\u0103m 907 sau C\u00f4ng nguy\u00ean,`,
  `Chu \u00d4n, t\u01b0\u1edbc L\u01b0\u01a1ng V\u01b0\u01a1ng, t\u1eebng l\u00e0 b\u1ed9 t\u01b0\u1edbng c\u1ee7a Ho\u00e0ng S\u00e0o v\u00e0 sau n\u00e0y \u0111\u1ea7u h\u00e0ng nh\u00e0 \u0110\u01b0\u1eddng, \u0111\u00e3 \u00e9p \u0110\u01b0\u1eddng Ai \u0110\u1ebf tho\u00e1i v\u1ecb,`,
  `T\u1ef1 l\u1eadp x\u01b0ng \u0111\u1ebf, l\u1eadp ra tri\u1ec1u L\u01b0\u01a1ng.`,
  `\u0110\u1ebfn \u0111\u00e2y, nh\u00e0 L\u00fd \u0110\u01b0\u1eddng di\u1ec7t vong,`,
  `Trung Qu\u1ed1c b\u01b0\u1edbc v\u00e0o m\u1ed9t th\u1eddi k\u1ef3 chia c\u1eaft kh\u00e1c,`,
  `Ng\u0169 \u0110\u1ea1i Th\u1eadp Qu\u1ed1c. Ng\u0169 \u0110\u1ea1i Th\u1eadp Qu\u1ed1c nghe c\u00f3 v\u1ebb h\u01a1i ph\u1ee9c t\u1ea1p,`,
  `th\u1ef1c ra n\u00f3 th\u1ef1c s\u1ef1 h\u01a1i ph\u1ee9c t\u1ea1p, n\u00ean t\u00f4i s\u1ebd n\u00f3i m\u1ed9t c\u00e1ch \u0111\u01a1n gi\u1ea3n nh\u1ea5t.`,
  `Ng\u0169 \u0110\u1ea1i l\u00e0 n\u0103m tri\u1ec1u \u0111\u1ea1i l\u1ea7n l\u01b0\u1ee3t n\u1eafm quy\u1ec1n \u1edf v\u00f9ng Trung Nguy\u00ean sau khi nh\u00e0 \u0110\u01b0\u1eddng di\u1ec7t vong,`,
  `\u0111\u1ea7u ti\u00ean l\u00e0 H\u1eadu L\u01b0\u01a1ng, tri\u1ec1u \u0111\u1ea1i \u0111\u00e3 l\u1eadt \u0111\u1ed5 nh\u00e0 \u0110\u01b0\u1eddng.`,
  `Cu\u1ed1i th\u1eddi \u0110\u01b0\u1eddng kh\u00f4ng ph\u1ea3i t\u00ecnh tr\u1ea1ng c\u00e1t c\u1ee9 phi\u00ean tr\u1ea5n r\u1ea5t nghi\u00eam tr\u1ecdng sao?`,
  `C\u00e1c phi\u00ean v\u01b0\u01a1ng \u1edf kh\u1eafp n\u01a1i \u0111\u1ec1u r\u1ea5t c\u00f3 th\u1ef1c l\u1ef1c,`,
  `L\u00fd Kh\u1eafc D\u1ee5ng, chi\u1ebfn h\u1eefu n\u0103m x\u01b0a c\u1ee7a Chu \u00d4n, \u0111\u00e3 c\u00e1t c\u1ee9 ph\u01b0\u01a1ng B\u1eafc,`,
  `th\u1ef1c l\u1ef1c h\u00f9ng m\u1ea1nh. Sau khi L\u00fd Kh\u1eafc D\u1ee5ng qua \u0111\u1eddi, con trai \u00f4ng l\u00e0 L\u00fd T\u1ed3n \u00dac k\u1ebf v\u1ecb,`,
  `L\u00fd T\u1ed3n \u00dac t\u1ef1 x\u01b0ng \u0111\u1ebf, l\u1eadp ra H\u1eadu \u0110\u01b0\u1eddng.`,
  `Ngay trong n\u0103m L\u00fd T\u1ed3n \u00dac x\u01b0ng \u0111\u1ebf,`,
  `\u00f4ng \u0111\u00e3 di\u1ec7t H\u1eadu L\u01b0\u01a1ng,`,
  `tr\u1edf th\u00e0nh ch\u00ednh quy\u1ec1n th\u1ee9 hai c\u1ee7a Ng\u0169 \u0110\u1ea1i.`,
  `\u0110\u1ebfn \u0111\u1eddi L\u00fd T\u00f2ng Khoa, v\u1ecb vua cu\u1ed1i c\u00f9ng c\u1ee7a H\u1eadu \u0110\u01b0\u1eddng,`,
  `\u0111\u1ea1i t\u01b0\u1edbng Th\u1ea1ch K\u00ednh \u0110\u01b0\u1eddng trong tri\u1ec1u c\u00f3 quy\u1ec1n l\u1ef1c r\u1ea5t l\u1edbn.`,
  `\u0110\u1ec3 chi\u1ebfm ng\u00f4i, Th\u1ea1ch K\u00ednh \u0110\u01b0\u1eddng \u0111\u00e3 t\u00f4n Gia Lu\u1eadt \u0110\u1ee9c Quang, th\u1ee7 l\u0129nh ng\u01b0\u1eddi Khi\u1ebft \u0110an k\u00e9m \u00f4ng m\u01b0\u1eddi m\u1ea5y tu\u1ed5i, l\u00e0m cha nu\u00f4i,`,
  `v\u00e0 \u0111\u1ed5i l\u1ea5y s\u1ef1 \u1ee7ng h\u1ed9 c\u1ee7a ng\u01b0\u1eddi Khi\u1ebft \u0110an v\u1edbi c\u00e1i gi\u00e1 l\u00e0 16 ch\u00e2u Y\u00ean V\u00e2n.`,
  `Cu\u1ed1i c\u00f9ng, \u00f4ng di\u1ec7t H\u1eadu \u0110\u01b0\u1eddng v\u00e0 l\u1eadp ra H\u1eadu T\u1ea5n, nh\u01b0ng kh\u00f4ng l\u00e2u sau \u0111\u00f3,`,
  `ng\u01b0\u1eddi Khi\u1ebft \u0110an \u0111\u00e3 quay l\u1ea1i \u0111\u00e1nh con nu\u00f4i c\u1ee7a \u00f4ng,`,
  `di\u1ec7t H\u1eadu T\u1ea5n. Ng\u01b0\u1eddi Khi\u1ebft \u0110an kh\u00f4ng c\u00f3 h\u1ee9ng th\u00fa v\u1edbi tri\u1ec1u \u0111\u00ecnh Trung Nguy\u00ean,`,
  `sau khi c\u01b0\u1edbp s\u1ea1ch ti\u1ec1n th\u00ec b\u1ecf \u0111i.`,
  `V\u00ec v\u1eady, L\u01b0u Tri Vi\u1ec5n, m\u1ed9t \u0111\u1ea1i t\u01b0\u1edbng c\u0169 c\u1ee7a H\u1eadu T\u1ea5n, \u0111\u00e3 n\u1eafm b\u1eaft c\u01a1 h\u1ed9i n\u00e0y,`,
  `trong th\u1eddi k\u1ef3 tr\u1ed1ng tr\u1ea3i c\u1ee7a tri\u1ec1u \u0111\u00ecnh, \u0111\u00e3 l\u1eadp ra H\u1eadu H\u00e1n.`,
  `Sau khi \u00f4ng m\u1ea5t,`,
  `con trai \u00f4ng l\u00e0 L\u01b0u Th\u1eeba l\u1ea1i k\u1ebf v\u1ecb.`,
  `L\u01b0u Th\u1eeba l\u1ea1i mu\u1ed1n ra tay v\u1edbi \u0111\u1ea1i t\u01b0\u1edbng Qu\u00e1ch Uy trong tri\u1ec1u.`,
  `Qu\u00e1ch Uy \u0111\u00e3 ph\u1ea3n c\u00f4ng, tr\u1ef1c ti\u1ebfp kh\u1edfi binh di\u1ec7t H\u1eadu H\u00e1n,`,
  `v\u00e0 l\u1eadp ra H\u1eadu Chu.`,
  `Sau \u0111\u00f3, H\u1eadu Chu b\u1ecb nh\u00e0 T\u1ed1ng thay th\u1ebf.`,
  `Ng\u0169 \u0110\u1ea1i c\u1ee9 th\u1ebf k\u1ebft th\u00fac vui v\u1ebb,`,
  `C\u00f3 ph\u1ea3i b\u1ea1n c\u1ea3m th\u1ea5y v\u1eabn thi\u1ebfu g\u00ec \u0111\u00f3 kh\u00f4ng?`,
  `Kh\u00f4ng ph\u1ea3i c\u00f2n Th\u1eadp Qu\u1ed1c sao?`,
  `Th\u1eadp Qu\u1ed1c th\u1ef1c ra kh\u00f4ng ch\u1ec9 c\u00f3 m\u01b0\u1eddi qu\u1ed1c gia, n\u00f3 l\u00e0 t\u00ean g\u1ecdi chung c\u1ee7a h\u01a1n m\u01b0\u1eddi qu\u1ed1c gia \u0111\u01b0\u1ee3c th\u00e0nh l\u1eadp ngo\u00e0i khu v\u1ef1c trung nguy\u00ean trong th\u1eddi k\u1ef3 \u0111\u00f3.`,
  `Nh\u1eefng qu\u1ed1c gia n\u00e0y kh\u00f4ng n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c trung \u01b0\u01a1ng,`,
  `Cho n\u00ean, ch\u00fang t\u1ed3n t\u1ea1i \u0111\u1ed3ng th\u1eddi v\u1edbi Ng\u0169 \u0110\u1ea1i,`,
  `v\u00e0 ch\u1ec9 \u0111\u00f3ng vai tr\u00f2 th\u1ee9 y\u1ebfu \u1edf c\u00e1c v\u00f9ng xung quanh ngo\u00e0i trung nguy\u00ean.`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn v\u1ed1n l\u00e0 \u0111\u1ea1i t\u01b0\u1edbng c\u1ee7a nh\u00e0 H\u1eadu Chu,`,
  `n\u1eafm gi\u1eef binh quy\u1ec1n, vua cu\u1ed1i c\u00f9ng c\u1ee7a nh\u00e0 H\u1eadu Chu l\u00e0 S\u00e0i T\u00f4ng Hu\u1ea5n m\u1edbi b\u1ea3y tu\u1ed5i.`,
  `L\u00fac n\u00e0y, Tri\u1ec7u Khu\u00f4ng D\u1eadn th\u1ea5y \u0111i\u1ec1u ki\u1ec7n \u0111\u1ec3 \u0111o\u1ea1t l\u1ea5y H\u1eadu Chu \u0111\u00e3 ch\u00edn mu\u1ed3i,`,
  `n\u00ean \u00f4ng \u0111\u00e3 l\u00ean k\u1ebf ho\u1ea1ch t\u1ec9 m\u1ec9 cho m\u1ed9t cu\u1ed9c binh bi\u1ebfn tr\u1ee9 danh trong l\u1ecbch s\u1eed l\u00e0 binh bi\u1ebfn Tr\u1ea7n Ki\u1ec1u.`,
  `N\u0103m 960 sau C\u00f4ng nguy\u00ean,`,
  `c\u00f3 tin \u0111\u1ed3n r\u1eb1ng ng\u01b0\u1eddi Khi\u1ebft \u0110an s\u1ebd t\u1ea5n c\u00f4ng H\u1eadu Chu,`,
  `tri\u1ec1u \u0111\u00ecnh nghe tin li\u1ec1n lo l\u1eafng.`,
  `V\u1ed9i v\u00e0ng tri\u1ec7u Tri\u1ec7u Khu\u00f4ng D\u1eadn v\u1ec1 l\u00e3nh binh ph\u00eda B\u1eafc ch\u1ed1ng gi\u1eb7c.`,
  `\u0110o\u00e0n ng\u01b0\u1eddi \u0111\u1ebfn Tr\u1ea7n Ki\u1ec1u D\u1ecbch,`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn li\u1ec1n b\u00ed m\u1eadt ph\u00e1t \u0111\u1ed9ng binh bi\u1ebfn.`,
  `T\u01b0\u1edbng s\u0129 trong qu\u00e2n kho\u00e1c \u00e1o b\u00e0o v\u00e0ng l\u00ean ng\u01b0\u1eddi Tri\u1ec7u Khu\u00f4ng D\u1eadn,`,
  `\u1ee7ng h\u1ed9 \u00f4ng l\u00ean l\u00e0m ho\u00e0ng \u0111\u1ebf.`,
  `Sau \u0111\u00f3, ti\u1ec3u ho\u00e0ng \u0111\u1ebf nh\u00e0 H\u1eadu Chu nh\u01b0\u1eddng ng\u00f4i cho Tri\u1ec7u Khu\u00f4ng D\u1eadn,`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn l\u00ean ng\u00f4i,`,
  `th\u00e0nh l\u1eadp nh\u00e0 T\u1ed1ng,`,
  `\u0111\u00f3ng \u0111\u00f4 \u1edf \u0110\u00f4ng Kinh, t\u1ee9c Khai Phong, H\u00e0 Nam ng\u00e0y nay,`,
  `s\u1eed g\u1ecdi l\u00e0 B\u1eafc T\u1ed1ng. L\u00fac \u0111\u00f3, ngo\u00e0i nh\u00e0 T\u1ed1ng v\u1eeba th\u00e0nh l\u1eadp,`,
  `c\u00f2n t\u1ed3n t\u1ea1i nhi\u1ec1u th\u1ebf l\u1ef1c c\u00e1t c\u1ee9 kh\u00e1c.`,
  `V\u00ec v\u1eady, T\u1ed1ng Th\u00e1i T\u1ed5 Tri\u1ec7u Khu\u00f4ng D\u1eadn b\u1eaft \u0111\u1ea7u cu\u1ed9c \u0111\u1ea5u tranh th\u1ed1ng nh\u1ea5t \u0111\u1ea5t n\u01b0\u1edbc k\u00e9o d\u00e0i nhi\u1ec1u n\u0103m.`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn \u0111\u00e3 d\u00f9ng m\u01b0\u1eddi ba n\u0103m \u0111\u1ec3`,
  `th\u1ed1ng nh\u1ea5t t\u1ea5t c\u1ea3 c\u00e1c v\u00f9ng \u0111\u1ea5t ngo\u1ea1i tr\u1eeb B\u1eafc H\u00e1n,`,
  `kh\u00f4i ph\u1ee5c s\u1ef1 th\u1ed1ng nh\u1ea5t c\u1ee7a Trung Hoa.`,
  `Trong qu\u00e1 tr\u00ecnh th\u1ed1ng nh\u1ea5t \u0111\u1ea5t n\u01b0\u1edbc,`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn \u0111\u00e3 r\u00fat kinh nghi\u1ec7m t\u1eeb s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a nh\u00e0 \u0110\u01b0\u1eddng,`,
  `\u00e2n uy song song, l\u00e0m suy y\u1ebfu quy\u1ec1n l\u1ef1c c\u1ee7a c\u00e1c t\u01b0\u1edbng l\u0129nh v\u00e0 t\u1ec3 t\u01b0\u1edbng,`,
  `t\u0103ng c\u01b0\u1eddng t\u1eadp trung quy\u1ec1n l\u1ef1c v\u00e0o trung \u01b0\u01a1ng,`,
  `ng\u01b0\u1eddi d\u00e2n ph\u1ea3i ch\u1ecbu \u0111\u1ef1ng chi\u1ebfn tranh cu\u1ed1i c\u00f9ng \u0111\u00e3 c\u00f3 m\u1ed9t m\u00f4i tr\u01b0\u1eddng s\u1ed1ng v\u00e0 s\u1ea3n xu\u1ea5t h\u00f2a b\u00ecnh v\u00e0 \u1ed5n \u0111\u1ecbnh,`,
  `t\u1ea1o \u0111i\u1ec1u ki\u1ec7n thu\u1eadn l\u1ee3i cho s\u1ef1 ti\u1ebfn b\u1ed9 x\u00e3 h\u1ed9i v\u00e0 ph\u00e1t tri\u1ec3n kinh t\u1ebf.`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn c\u0169ng l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf xu\u1ea5t s\u1eafc,`,
  `\u00f4ng c\u1ea7n c\u00f9 ch\u00ednh s\u1ef1, y\u00eau d\u00e2n, nghi\u00eam kh\u1eafc v\u1edbi b\u1ea3n th\u00e2n,`,
  `\u0111\u01b0\u1ee3c d\u00e2n ch\u00fang y\u00eau m\u1ebfn s\u00e2u s\u1eafc.`,
  `Nh\u01b0ng sau m\u01b0\u1eddi s\u00e1u n\u0103m Tri\u1ec7u Khu\u00f4ng D\u1eadn l\u00ean ng\u00f4i, \u00f4ng \u0111\u1ed9t ng\u1ed9t qua \u0111\u1eddi.`,
  `\u0110\u00eam \u0111\u00f3, \u00f4ng \u0111\u00e3 u\u1ed1ng r\u01b0\u1ee3u v\u00e0 tr\u00f2 chuy\u1ec7n v\u1edbi em trai Tri\u1ec7u Quang Ngh\u0129a,`,
  `k\u1ebft qu\u1ea3 s\u00e1ng h\u00f4m sau,`,
  `Tri\u1ec7u Khu\u00f4ng D\u1eadn \u0111\u01b0\u1ee3c ph\u00e1t hi\u1ec7n \u0111\u00e3 ch\u1ebft trong cung c\u1ea5m,`,
  `v\u00ec v\u1eady r\u1ea5t c\u00f3 th\u1ec3 \u00f4ng \u0111\u00e3 b\u1ecb Tri\u1ec7u Quang Ngh\u0129a \u00e1m h\u1ea1i,`,
  `nh\u01b0ng c\u0169ng c\u00f3 th\u1ec3 l\u00e0 do u\u1ed1ng r\u01b0\u1ee3u qu\u00e1 nhi\u1ec1u m\u00e0 ch\u1ebft.`,
  `Kh\u00f4ng ai bi\u1ebft s\u1ef1 th\u1eadt.`,
  `T\u00f3m l\u1ea1i, em trai \u00f4ng l\u00e0 Tri\u1ec7u Quang Ngh\u0129a sau n\u00e0y \u0111\u00e3 l\u00ean ng\u00f4i.`,
  `Tr\u01b0\u1edbc \u0111\u00f3, Th\u1ea1ch K\u00ednh \u0110\u01b0\u1eddng c\u1ee7a H\u1eadu T\u1ea5n th\u1eddi Ng\u0169 \u0110\u1ea1i Th\u1eadp Qu\u1ed1c \u0111\u00e3 c\u1eaft m\u01b0\u1eddi s\u00e1u ch\u00e2u Y\u00ean V\u00e2n cho n\u01b0\u1edbc Li\u00eau.`,
  `\u0110\u1ec3 gi\u00e0nh l\u1ea1i m\u01b0\u1eddi s\u00e1u ch\u00e2u Y\u00ean V\u00e2n,`,
  `T\u1eeb Tri\u1ec7u Quang Ngh\u0129a tr\u1edf \u0111i,`,
  `B\u1eafc T\u1ed1ng \u0111\u00e3 nhi\u1ec1u l\u1ea7n giao tranh v\u1edbi nh\u00e0 Li\u00eau nh\u01b0ng \u0111\u1ec1u kh\u00f4ng th\u1ec3 thu h\u1ed3i \u0111\u01b0\u1ee3c l\u00e3nh th\u1ed5 \u0111\u00e3 m\u1ea5t.`,
  `M\u00e3i \u0111\u1ebfn n\u0103m 1004 sau C\u00f4ng nguy\u00ean,`,
  `B\u1eafc T\u1ed1ng m\u1edbi c\u00f9ng n\u01b0\u1edbc Li\u00eau k\u00fd hi\u1ec7p \u01b0\u1edbc \u0111\u00ecnh chi\u1ebfn t\u1ea1i Tr\u1ea5n Ch\u00e2u,`,
  `Quy \u0111\u1ecbnh T\u1ed1ng v\u00e0 Li\u00eau l\u00e0 anh em,`,
  `B\u1eafc T\u1ed1ng h\u00e0ng n\u0103m ph\u1ea3i c\u1ed1ng n\u1ea1p m\u1ed9t kho\u1ea3n chi ph\u00ed qu\u00e2n s\u1ef1 cho n\u01b0\u1edbc Li\u00eau,`,
  `Hai b\u00ean kh\u00f4ng x\u00e2m ph\u1ea1m l\u1eabn nhau.`,
  `T\u1eeb \u0111\u00f3, mi\u1ec1n b\u1eafc Trung Qu\u1ed1c m\u1edbi c\u00f3 \u0111\u01b0\u1ee3c ch\u00fat b\u00ecnh y\u00ean.`,
  `Li\u00ean minh n\u00e0y \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 Minh \u01b0\u1edbc Thi\u1ec1n Uy\u00ean trong l\u1ecbch s\u1eed,`,
  `Sau n\u00e0y, do s\u1ef1 x\u00e2m l\u01b0\u1ee3c c\u1ee7a c\u00e1c d\u00e2n t\u1ed9c ngo\u1ea1i bang v\u00e0 s\u1ef1 b\u1ea5t t\u00e0i c\u1ee7a nh\u1eefng ng\u01b0\u1eddi cai tr\u1ecb,`,
  `Khi\u1ebfn x\u00e3 h\u1ed9i b\u1ea5t \u1ed5n.`,
  `T\u1ed1ng Th\u1ea7n T\u00f4ng Tri\u1ec7u H\u00fac, v\u1ecb ho\u00e0ng \u0111\u1ebf th\u1ee9 s\u00e1u c\u1ee7a tri\u1ec1u T\u1ed1ng, \u0111\u1ec3 ph\u00e1t tri\u1ec3n x\u00e3 h\u1ed9i,`,
  `\u0111\u00e3 b\u1ed5 nhi\u1ec7m V\u01b0\u01a1ng An Th\u1ea1ch l\u00e0m t\u1ec3 t\u01b0\u1edbng v\u00e0 ti\u1ebfn h\u00e0nh t\u00e2n ph\u00e1p.`,
  `Tuy nhi\u00ean, do th\u1ebf l\u1ef1c b\u1ea3o th\u1ee7 qu\u00e1 m\u1ea1nh,`,
  `V\u01b0\u01a1ng An Th\u1ea1ch hai l\u1ea7n ti\u1ebfn h\u00e0nh t\u00e2n ph\u00e1p \u0111\u1ec1u th\u1ea5t b\u1ea1i.`,
  `\u0110\u1ebfn \u0111\u00e2y, B\u1eafc T\u1ed1ng b\u1eaft \u0111\u1ea7u suy t\u00e0n.`,
  `Do s\u1ef1 th\u1ed1i n\u00e1t c\u1ee7a quan l\u1ea1i B\u1eafc T\u1ed1ng \u0111\u00e3 khi\u1ebfn nh\u00e2n d\u00e2n n\u1ed5i d\u1eady ph\u1ea3n kh\u00e1ng.`,
  `C\u00f9ng l\u00fac \u0111\u00f3, n\u01b0\u1edbc Li\u00eau \u1edf ph\u00eda B\u1eafc b\u1ecb n\u01b0\u1edbc Kim do ng\u01b0\u1eddi N\u1eef Ch\u00e2n th\u00e0nh l\u1eadp ti\u00eau di\u1ec7t.`,
  `Sau khi Kim di\u1ec7t Li\u00eau,`,
  `m\u1ee5c ti\u00eau ti\u1ebfp theo l\u00e0 B\u1eafc T\u1ed1ng.`,
  `N\u01b0\u1edbc Kim l\u1ea5y c\u1edb tri\u1ec1u T\u1ed1ng ph\u00e1 v\u1ee1 th\u1ecfa thu\u1eadn c\u00f9ng \u0111\u1ed1i ph\u00f3 v\u1edbi Li\u00eau,`,
  `\u0111\u00e3 xu\u1ea5t binh x\u00e2m l\u01b0\u1ee3c T\u1ed1ng.`,
  `Ban \u0111\u1ea7u, qu\u00e2n \u0111\u1ed9i B\u1eafc T\u1ed1ng d\u01b0\u1edbi s\u1ef1 l\u00e3nh \u0111\u1ea1o c\u1ee7a T\u1ec3 t\u01b0\u1edbng L\u00fd C\u01b0\u01a1ng \u0111\u00e3 \u0111\u00e1nh b\u1ea1i qu\u00e2n Kim,`,
  `t\u1ea1m th\u1eddi ng\u0103n ch\u1eb7n cu\u1ed9c x\u00e2m l\u01b0\u1ee3c ph\u01b0\u01a1ng Nam c\u1ee7a n\u01b0\u1edbc Kim.`,
  `Nh\u01b0ng l\u00fac \u0111\u00f3, Th\u00e1i th\u01b0\u1ee3ng ho\u00e0ng T\u1ed1ng Huy T\u00f4ng v\u00e0 Ho\u00e0ng \u0111\u1ebf T\u1ed1ng Kh\u00e2m T\u00f4ng qu\u00e1 v\u00f4 n\u0103ng,`,
  `ch\u1ec9 mu\u1ed1n c\u1ea7u h\u00f2a,`,
  `kh\u00f4ng ch\u1ec9 b\u1ed3i th\u01b0\u1eddng cho nh\u00e0 Kim, m\u00e0 c\u00f2n b\u00e3i nhi\u1ec7m L\u00fd C\u01b0\u01a1ng v\u00e0 c\u00e1c trung th\u1ea7n kh\u00e1c,`,
  `khi\u1ebfn nh\u00e0 Kim c\u00e0ng tr\u1edf n\u00ean ngang ng\u01b0\u1ee3c.`,
  `N\u0103m 1127,`,
  `qu\u00e2n Kim m\u1ed9t l\u1ea7n n\u1eefa t\u1ea5n c\u00f4ng kinh th\u00e0nh Khai Phong,`,
  `b\u1eaft \u0111i hai v\u1ecb ho\u00e0ng \u0111\u1ebf T\u1ed1ng Huy T\u00f4ng, T\u1ed1ng Kh\u00e2m T\u00f4ng c\u00f9ng nhi\u1ec1u t\u00e0i s\u1ea3n.`,
  `T\u1eeb \u0111\u00f3, tri\u1ec1u \u0111\u1ea1i B\u1eafc T\u1ed1ng k\u00e9o d\u00e0i 167 n\u0103m cu\u1ed1i c\u00f9ng b\u1ecb nh\u00e0 Kim ti\u00eau di\u1ec7t,`,
  `m\u1edf ra th\u1eddi k\u1ef3 ngo\u1ea1i t\u1ed9c cai tr\u1ecb Trung Qu\u1ed1c.`,
  `Sau khi qu\u00e2n Kim chi\u1ebfm \u0111\u01b0\u1ee3c B\u1eafc T\u1ed1ng,`,
  `kh\u00f4ng bi\u1ebft c\u00e1ch tr\u1ecb v\u00ec \u0111\u1ea5t n\u01b0\u1edbc,`,
  `li\u1ec1n d\u1ef1ng m\u1ed9t \u0111\u1ea1i th\u1ea7n B\u1eafc T\u1ed1ng l\u00e0 Tr\u01b0\u01a1ng Bang X\u01b0\u01a1ng l\u00e0m ho\u00e0ng \u0111\u1ebf b\u00f9 nh\u00ecn.`,
  `Tuy nhi\u00ean, ph\u1ea7n l\u1edbn c\u00e1c quan l\u1ea1i c\u0169 c\u1ee7a nh\u00e0 T\u1ed1ng kh\u00f4ng ph\u1ee5c k\u1ebb ph\u1ea3n b\u1ed9i \u0111\u1ea7u h\u00e0ng gi\u1eb7c Kim n\u00e0y,`,
  `b\u1ea5t \u0111\u1eafc d\u0129, Tr\u01b0\u01a1ng Bang X\u01b0\u01a1ng \u0111\u00e0nh ph\u1ea3i tho\u00e1i v\u1ecb,`,
  `l\u1eadp Khang V\u01b0\u01a1ng Tri\u1ec7u C\u1ea5u l\u00e0m Ho\u00e0ng \u0111\u1ebf.`,
  `C\u00f9ng n\u0103m \u0111\u00f3, Tri\u1ec7u C\u1ea5u l\u00ean ng\u00f4i \u1edf Nam Kinh \u1ee8ng Thi\u00ean Ph\u1ee7, t\u1ee9c l\u00e0 Th\u01b0\u01a1ng Kh\u00e2u, H\u00e0 Nam ng\u00e0y nay,`,
  `th\u00e0nh l\u1eadp Nam T\u1ed1ng.`,
  `Sau khi nh\u00e0 Kim bi\u1ebft \u0111\u01b0\u1ee3c, l\u1ea5y l\u00fd do Tr\u01b0\u01a1ng Bang X\u01b0\u01a1ng b\u1ecb ph\u1ebf,`,
  `\u0111\u00e3 ti\u1ebfn h\u00e0nh cu\u1ed9c x\u00e2m l\u01b0\u1ee3c l\u1edbn xu\u1ed1ng ph\u00eda nam. Nh\u00e0 Kim l\u1ea1i l\u1eadp m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf b\u00f9 nh\u00ecn l\u00e0 L\u01b0u D\u1ee5,`,
  `qu\u1ed1c hi\u1ec7u m\u00e0 l\u1ecbch s\u1eed g\u1ecdi l\u00e0 T\u1ec1 Ng\u1ee5y.`,
  `Khi qu\u00e2n Kim x\u00e2m l\u01b0\u1ee3c ph\u00eda nam,`,
  `Nam T\u1ed1ng c\u0169ng ph\u00e1i qu\u00e2n b\u1eafc ph\u1ea1t,`,
  `do c\u00e1c t\u01b0\u1edbng kh\u00e1ng Kim nh\u01b0 Nh\u1ea1c Phi, H\u00e0n Th\u1ebf Trung ch\u1ec9 huy,`,
  `\u0111\u00e3 nhi\u1ec1u l\u1ea7n \u0111\u00e1nh tan li\u00ean qu\u00e2n Kim v\u00e0 Ng\u1ee5y T\u1ec1 \u1edf b\u1edd nam s\u00f4ng Ho\u00e0ng H\u00e0.`,
  `Nh\u01b0ng v\u00ec nhi\u1ec1u l\u00fd do ch\u00ednh tr\u1ecb,`,
  `T\u1ed1ng Cao T\u00f4ng Tri\u1ec7u C\u1ea5u m\u1ed9t l\u00f2ng mu\u1ed1n h\u00f2a, tr\u00e1i ng\u01b0\u1ee3c v\u1edbi \u00fd ch\u00ed ki\u00ean quy\u1ebft kh\u00e1ng chi\u1ebfn c\u1ee7a Nh\u1ea1c Phi,`,
  `\u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng cho vi\u1ec7c Nh\u1ea1c Phi sau n\u00e0y b\u1ecb gi\u1ebft.`,
  `Sau \u0111\u00f3, t\u1ec3 t\u01b0\u1edbng T\u1ea7n C\u1ed1i l\u1ea5y t\u1ed9i danh kh\u00f4ng c\u00f3 th\u1eadt b\u1ecf t\u00f9 Nh\u1ea1c Phi,`,
  `v\u00e0 n\u0103m sau gi\u1ebft h\u1ea1i cha con Nh\u1ea1c Phi.`,
  `T\u1ed1ng Cao T\u00f4ng \u0111\u00e3 ph\u1ea3i tr\u1ea3 gi\u00e1 b\u1eb1ng vi\u1ec7c c\u1ed1ng n\u1ea1p v\u00e0 x\u01b0ng th\u1ea7n,`,
  `\u0111\u1ec3 \u0111\u1ed5i l\u1ea5y quy\u1ec1n th\u1ed1ng tr\u1ecb n\u1eeda giang s\u01a1n ph\u00eda \u0111\u00f4ng nam.`,
  `V\u00e0i n\u0103m sau \u0111\u00f3, quan h\u1ec7 gi\u1eefa T\u1ed1ng v\u00e0 Kim t\u01b0\u01a1ng \u0111\u1ed1i \u1ed5n \u0111\u1ecbnh.`,
  `V\u00e0i th\u1eadp k\u1ef7 sau, th\u1ef1c l\u1ef1c c\u1ee7a nh\u00e0 Kim \u0111\u00e3 suy y\u1ebfu \u0111i r\u1ea5t nhi\u1ec1u,`,
  `v\u00e0 l\u00fac n\u00e0y, m\u1ed9t th\u1ebf l\u1ef1c m\u1ea1nh h\u01a1n xu\u1ea5t hi\u1ec7n \u1edf v\u00f9ng t\u00e2y b\u1eafc \u2013 M\u00f4ng C\u1ed5.`,
  `Ng\u01b0\u1eddi M\u00f4ng C\u1ed5 l\u00e0 m\u1ed9t d\u00e2n t\u1ed9c c\u1ed5 x\u01b0a,`,
  `h\u1ecd lu\u00f4n s\u1ed1ng d\u1ef1a v\u00e0o l\u1ed1i s\u1ed1ng du m\u1ee5c.`,
  `Kho\u1ea3ng th\u1ebf k\u1ef7 12 sau C\u00f4ng nguy\u00ean,`,
  `m\u1ed9t nh\u00e0 l\u00e3nh \u0111\u1ea1o xu\u1ea5t s\u1eafc c\u1ee7a ng\u01b0\u1eddi M\u00f4ng C\u1ed5 \u0111\u00e3 xu\u1ea5t hi\u1ec7n l\u00e0 Thi\u1ebft M\u1ed9c Ch\u00e2n,`,
  `\u00f4ng \u0111\u01b0\u1ee3c suy t\u00f4n l\u00e0m th\u1ee7 l\u0129nh c\u00e1c b\u1ed9 l\u1ea1c,`,
  `g\u1ecdi l\u00e0 Th\u00e0nh C\u00e1t T\u01b0 H\u00e3n.`,
  `D\u01b0\u1edbi s\u1ef1 l\u00e3nh \u0111\u1ea1o c\u1ee7a Thi\u1ebft M\u1ed9c Ch\u00e2n, ng\u01b0\u1eddi M\u00f4ng C\u1ed5 d\u1ea7n tr\u1edf n\u00ean m\u1ea1nh m\u1ebd,`,
  `tr\u1edf th\u00e0nh m\u1ed9t th\u1ebf l\u1ef1c kh\u00f4ng th\u1ec3 xem th\u01b0\u1eddng \u1edf mi\u1ec1n B\u1eafc Trung Qu\u1ed1c.`,
  `Sau n\u00e0y, Nam T\u1ed1ng v\u00e0 M\u00f4ng C\u1ed5 li\u00ean minh ch\u1ed1ng Kim,`,
  `n\u0103m 1234 sau C\u00f4ng nguy\u00ean,`,
  `nh\u00e0 Kim b\u1ecb M\u00f4ng C\u1ed5 ti\u00eau di\u1ec7t.`,
  `Sau khi nh\u00e0 Kim di\u1ec7t vong, n\u0103m sau M\u00f4ng C\u1ed5 \u0111\u00e3 ph\u00e1t \u0111\u1ed9ng cu\u1ed9c t\u1ea5n c\u00f4ng v\u00e0o Nam T\u1ed1ng.`,
  `Do qu\u00e2n T\u1ed1ng chi\u1ebfn \u0111\u1ea5u d\u0169ng c\u1ea3m,`,
  `M\u00f4ng C\u1ed5 \u0111\u00e3 kh\u00f4ng th\u1ec3 chi\u1ebfm \u0111\u01b0\u1ee3c Nam T\u1ed1ng.`,
  `\u0110\u00fang l\u00fac M\u00f4ng C\u1ed5 giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ed1ng,`,
  `\u0110\u1ea1i h\u00e3n M\u00f4ng C\u1ed5 M\u00f4ng Kha qua \u0111\u1eddi,`,
  `em trai \u00f4ng l\u00e0 H\u1ed1t T\u1ea5t Li\u1ec7t \u0111\u00e3 t\u1eeb b\u1ecf vi\u1ec7c giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ed1ng,`,
  `ngay l\u1eadp t\u1ee9c r\u00fat qu\u00e2n v\u1ec1 qu\u00ea nh\u00e0 \u0111\u1ec3 tranh gi\u00e0nh ngai v\u00e0ng.`,
  `C\u01a1 h\u1ed9i t\u1ed1t n\u00e0y,`,
  `qu\u00e2n T\u1ed1ng kh\u00f4ng nh\u1eefng kh\u00f4ng truy \u0111u\u1ed5i,`,
  `m\u00e0 c\u00f2n c\u1ea7u h\u00f2a v\u1edbi M\u00f4ng C\u1ed5.`,
  `Sau \u0111\u00f3, H\u1ed1t T\u1ea5t Li\u1ec7t l\u00ean ng\u00f4i \u0110\u1ea1i h\u00e3n v\u00e0 ti\u1ebfp t\u1ee5c t\u1ea5n c\u00f4ng Nam T\u1ed1ng.`,
  `N\u0103m 1271, H\u1ed1t T\u1ea5t Li\u1ec7t th\u00e0nh l\u1eadp nh\u00e0 Nguy\u00ean.`,
  `N\u0103m 1276,`,
  `M\u00f4ng C\u1ed5 chi\u1ebfm \u0111\u01b0\u1ee3c L\u00e2m An, kinh \u0111\u00f4 c\u1ee7a Nam tri\u1ec1u,`,
  `t\u1ee9c l\u00e0 H\u00e0ng Ch\u00e2u ng\u00e0y nay.`,
  `Nam T\u1ed1ng di\u1ec7t vong, M\u00f4ng C\u1ed5 th\u1ed1ng nh\u1ea5t to\u00e0n b\u1ed9 Trung Qu\u1ed1c,`,
  `Trung Qu\u1ed1c b\u01b0\u1edbc v\u00e0o th\u1eddi nh\u00e0 Nguy\u00ean.`,
  `N\u0103m 1206,`,
  `Tr\u00ean th\u1ea3o nguy\u00ean, Thi\u1ebft M\u1ed9c Ch\u00e2n, m\u1ed9t b\u1eadc th\u1ea7y chi\u1ebfn \u0111\u1ea5u c\u1ee7a d\u00f2ng h\u1ecd B\u1ed9t Nhi Ch\u1ec9 C\u00e1t \u0110\u1eb7c, \u0111\u00e3 th\u00e0nh l\u1eadp \u0110\u1ea1i M\u00f4ng C\u1ed5 Qu\u1ed1c.`,
  `\u00d4ng c\u00f2n c\u00f3 m\u1ed9t t\u00f4n hi\u1ec7u l\u00e0 Th\u00e0nh C\u00e1t T\u01b0 H\u00e3n.`,
  `V\u00e0o th\u1eddi \u0111i\u1ec3m \u0111\u00f3, l\u00e3nh th\u1ed5 c\u1ee7a gia t\u1ed9c \u00f4ng ch\u1ec9 r\u1ed9ng nh\u01b0 th\u1ebf n\u00e0y.`,
  `K\u1ec3 t\u1eeb n\u0103m \u0111\u00f3,`,
  `Ng\u01b0\u1eddi anh h\u00f9ng n\u00e0y \u0111\u00e3 b\u1eaft \u0111\u1ea7u m\u1ed9t cu\u1ed9c \u0111\u1eddi k\u1ef3 di\u1ec7u \u0111\u1ea7y chinh ph\u1ea1t.`,
  `Kh\u00f4ng ch\u1ec9 \u00f4ng \u1ea5y gi\u1ecfi \u0111\u00e1nh tr\u1eadn, m\u00e0 c\u1ea3 gia \u0111\u00ecnh \u00f4ng \u1ea5y \u0111\u1ec1u gi\u1ecfi chi\u1ebfn \u0111\u1ea5u.`,
  `H\u00e3n v\u01b0\u01a1ng sau Thi\u1ebft M\u1ed9c Ch\u00e2n l\u00e0 con trai th\u1ee9 ba c\u1ee7a \u00f4ng, Oa Kho\u00e1t \u0110\u00e0i.`,
  `Sau Oa Kho\u00e1t \u0110\u00e0i l\u00e0 M\u00f4ng Kha, con trai c\u1ee7a \u0110\u00e0 L\u00f4i, con trai \u00fat c\u1ee7a Thi\u1ebft M\u1ed9c Ch\u00e2n.`,
  `Sau M\u00f4ng Kha l\u00e0 em trai ru\u1ed9t c\u1ee7a \u00f4ng, H\u1ed1t T\u1ea5t Li\u1ec7t.`,
  `D\u01b0\u1edbi s\u1ef1 n\u1ed7 l\u1ef1c c\u1ee7a c\u00e1c H\u00e3n v\u01b0\u01a1ng thu\u1ed9c d\u00f2ng h\u1ecd B\u1ed9t Nhi Ch\u1ec9 C\u00e1t \u0110\u1eb7c n\u00e0y,`,
  `L\u00e3nh th\u1ed5 c\u1ee7a gia t\u1ed9c h\u1ecd \u0111\u00e3 tr\u1edf n\u00ean nh\u01b0 th\u1ebf n\u00e0y ch\u1ec9 trong v\u00e0i th\u1eadp k\u1ef7 ng\u1eafn ng\u1ee7i.`,
  `Trong th\u1eddi \u0111\u1ea1i v\u0169 kh\u00ed l\u1ea1nh, kh\u00f4ng m\u1ed9t qu\u1ed1c gia n\u00e0o c\u00f3 th\u1ec3 li\u00ean t\u1ee5c m\u1edf r\u1ed9ng ra b\u00ean ngo\u00e0i nh\u01b0 \u0110\u1ebf qu\u1ed1c M\u00f4ng C\u1ed5 trong v\u00e0i th\u1eadp k\u1ef7,`,
  `Li\u00ean ti\u1ebfp ti\u00eau di\u1ec7t h\u01a1n b\u1ed1n m\u01b0\u01a1i qu\u1ed1c gia,`,
  `Chinh ph\u1ee5c h\u01a1n b\u1ea3y tr\u0103m hai m\u01b0\u01a1i d\u00e2n t\u1ed9c,`,
  `L\u00e3nh th\u1ed5 tr\u1ea3i d\u00e0i t\u1eeb Vi\u1ec7t Nam \u0111\u1ebfn t\u1eadn Hungary,`,
  `thi\u1ebft l\u1eadp \u0111\u1ebf ch\u1ebf r\u1ed9ng l\u1edbn \u0111\u1ea7u ti\u00ean trong l\u1ecbch s\u1eed nh\u00e2n lo\u1ea1i v\u1edbi di\u1ec7n t\u00edch h\u01a1n 33 tri\u1ec7u km\u00b2,`,
  `tr\u1ea3i kh\u1eafp l\u1ee5c \u0111\u1ecba \u00c2u-\u00c1.`,
  `N\u0103m 1260,`,
  `sau c\u00e1i ch\u1ebft c\u1ee7a M\u00f4ng Kha, H\u00e3n v\u01b0\u01a1ng th\u1ee9 ba c\u1ee7a \u0110\u1ea1i M\u00f4ng C\u1ed5 qu\u1ed1c,`,
  `hai ng\u01b0\u1eddi em trai c\u1ee7a \u00f4ng l\u00e0 H\u1ed1t T\u1ea5t Li\u1ec7t v\u00e0 A L\u00fd B\u1ea5t Ca tranh gi\u00e0nh v\u1ecb tr\u00ed H\u00e3n v\u01b0\u01a1ng.`,
  `\u0110\u1ea1i M\u00f4ng C\u1ed5 qu\u1ed1c sau \u0111\u00f3 tan r\u00e3,`,
  `b\u1ed1n n\u0103m sau, H\u1ed1t T\u1ea5t Li\u1ec7t cu\u1ed1i c\u00f9ng \u0111\u00e3 \u0111\u00e1nh b\u1ea1i A L\u00fd B\u1ea5t Ca,`,
  `l\u00ean ng\u00f4i H\u00e3n v\u01b0\u01a1ng.`,
  `B\u1ed1n l\u00e3nh \u0111\u1ecba \u0111\u01b0\u1ee3c phong c\u1ee7a c\u00e1c h\u1eadu du\u1ec7 kh\u00e1c c\u1ee7a Th\u00e0nh C\u00e1t T\u01b0 H\u00e3n, v\u1ed1n thu\u1ed9c v\u1ec1 \u0110\u1ea1i M\u00f4ng C\u1ed5 qu\u1ed1c, \u0111\u00e3 gi\u00e0nh \u0111\u01b0\u1ee3c \u0111\u1ed9c l\u1eadp tr\u00ean th\u1ef1c t\u1ebf,`,
  `th\u00e0nh l\u1eadp l\u1ea7n l\u01b0\u1ee3t H\u00e3n qu\u1ed1c Kim Tr\u01b0\u1edbng,`,
  `H\u00e3n qu\u1ed1c S\u00e1t H\u1ee3p \u0110\u00e0i,`,
  `H\u00e3n qu\u1ed1c Oa Kho\u00e1t \u0110\u00e0i v\u00e0 H\u00e3n qu\u1ed1c Y Nhi.`,
  `Sau khi H\u1ed1t T\u1ea5t Li\u1ec7t \u1ed5n \u0111\u1ecbnh ngai v\u00e0ng,`,
  `n\u0103m 1271, \u00f4ng \u0111\u00e3 th\u00e0nh l\u1eadp tri\u1ec1u \u0111\u1ea1i nh\u00e0 Nguy\u00ean.`,
  `Nh\u00e0 Nguy\u00ean tr\u1edf th\u00e0nh n\u01b0\u1edbc ch\u1ee7 c\u1ee7a c\u00e1c h\u00e3n qu\u1ed1c kh\u00e1c,`,
  `Sau \u0111\u00f3 l\u1ea1i di\u1ec7t Nam T\u1ed1ng,`,
  `\u0110\u1eb7t \u0111\u00f4 th\u00e0nh \u1edf \u0110\u1ea1i \u0110\u00f4, t\u1ee9c l\u00e0 B\u1eafc Kinh ng\u00e0y nay.`,
  `Nh\u00e0 Nguy\u00ean b\u1eaft \u0111\u1ea7u cai tr\u1ecb Trung Qu\u1ed1c trong 97 n\u0103m.`,
  `\u0110\u1eebng th\u1ea5y H\u1ed1t T\u1ea5t Li\u1ec7t l\u00e0 ng\u01b0\u1eddi th\u1ea3o nguy\u00ean,`,
  `M\u00e0 ngh\u0129 r\u1eb1ng \u00f4ng ta ch\u1ec9 bi\u1ebft c\u01b0\u1ee1i ng\u1ef1a \u0111\u00e1nh tr\u1eadn,`,
  `Th\u1eadt ra \u00f4ng ta c\u00f2n kh\u00e1 t\u00e0i n\u0103ng trong qu\u1ea3n l\u00fd nh\u00e2n s\u1ef1.`,
  `H\u1ed1t T\u1ea5t Li\u1ec7t d\u00f9 sao c\u0169ng l\u00e0 con ch\u00e1u ho\u00e0ng t\u1ed9c, t\u1eeb nh\u1ecf \u0111\u00e3 hi\u1ec3u r\u1ea5t r\u00f5 v\u0103n h\u00f3a H\u00e1n t\u1ed9c.`,
  `Sau khi th\u00e0nh l\u1eadp nh\u00e0 Nguy\u00ean, \u00f4ng tr\u1ecdng d\u1ee5ng c\u00e1c qu\u1ea7n th\u1ea7n ng\u01b0\u1eddi H\u00e1n,`,
  `Ph\u1ea7n l\u1edbn \u0111\u00e3 dung h\u00f2a m\u00e2u thu\u1eabn d\u00e2n t\u1ed9c gi\u1eefa ng\u01b0\u1eddi H\u00e1n v\u00e0 ng\u01b0\u1eddi M\u00f4ng C\u1ed5,`,
  `V\u00ec v\u1eady, trong th\u1eddi gian \u00f4ng tr\u1ecb v\u00ec,`,
  `Ch\u00ednh quy\u1ec1n nh\u00e0 Nguy\u00ean v\u1eefng ch\u1eafc.`,
  `V\u00ec ng\u01b0\u1eddi M\u00f4ng C\u1ed5 ch\u1ee7 y\u1ebfu l\u00e0 du m\u1ee5c,`,
  `N\u0103ng su\u1ea5t th\u1ea5p, \u0111\u1ec3 thay \u0111\u1ed5i t\u00ecnh h\u00ecnh n\u00e0y,`,
  `T\u1eeb th\u1eddi H\u1ed1t T\u1ea5t Li\u1ec7t,`,
  `Nh\u1eefng ng\u01b0\u1eddi cai tr\u1ecb c\u1ee7a tri\u1ec1u \u0111\u1ea1i Nguy\u00ean sau n\u00e0y \u0111\u1ec1u r\u1ea5t coi tr\u1ecdng s\u1ef1 ph\u00e1t tri\u1ec3n c\u1ee7a n\u00f4ng nghi\u1ec7p,`,
  `Khi d\u00e2n ch\u00fang \u0111\u00e3 no \u0111\u1ee7, h\u1ecd s\u1ebd mua s\u1eafm qu\u1ea7n \u00e1o v\u00e0 nhi\u1ec1u th\u1ee9 kh\u00e1c.`,
  `Vi\u1ec7c tr\u1ed3ng b\u00f4ng \u1edf tri\u1ec1u Nguy\u00ean r\u1ea5t ph\u1ed5 bi\u1ebfn,`,
  `D\u00f9 ng\u00e0nh d\u1ec7t may ph\u00e1t tri\u1ec3n nhanh ch\u00f3ng,`,
  `\u0110\u1ed3ng th\u1eddi, l\u00e3nh th\u1ed5 c\u1ee7a tri\u1ec1u Nguy\u00ean l\u1ea1i \u0111\u1ee7 r\u1ed9ng l\u1edbn,`,
  `M\u1edf r\u1ed9ng \u0111\u1ebfn khu v\u1ef1c T\u00e2y \u00c1,`,
  `Khi\u1ebfn giao l\u01b0u gi\u1eefa ch\u00e2u \u00c2u v\u00e0 Trung Qu\u1ed1c c\u00e0ng tr\u1edf n\u00ean th\u01b0\u1eddng xuy\u00ean.`,
  `Th\u01b0\u01a1ng nghi\u1ec7p \u1edf tri\u1ec1u Nguy\u00ean nhanh ch\u00f3ng th\u1ecbnh v\u01b0\u1ee3ng,`,
  `Tr\u1edf th\u00e0nh m\u1ed9t trong nh\u1eefng qu\u1ed1c gia gi\u00e0u c\u00f3 nh\u1ea5t th\u1ebf gi\u1edbi l\u00fac b\u1ea5y gi\u1edd.`,
  `V\u1ed1n s\u1ed1ng cu\u1ed9c s\u1ed1ng du m\u1ee5c nay \u0111\u00e2y mai \u0111\u00f3, b\u1eefa \u0111\u00f3i b\u1eefa no,`,
  `\u0110\u1ed9t nhi\u00ean m\u1ed9t \u0111\u00eam tr\u1edf n\u00ean gi\u00e0u c\u00f3, ti\u1ec1n nhi\u1ec1u \u0111\u1ebfn n\u1ed7i ti\u00eau kh\u00f4ng h\u1ebft,`,
  `Th\u00ec s\u1ebd th\u1ebf n\u00e0o?`,
  `Th\u00ec s\u1ebd t\u1eadn h\u01b0\u1edfng v\u00e0 phung ph\u00ed h\u1ebft s\u1ee9c m\u00ecnh th\u00f4i.`,
  `S\u1ef1 d\u1ed3i d\u00e0o v\u1ec1 v\u1eadt ch\u1ea5t \u0111\u00e3 khi\u1ebfn cu\u1ed9c s\u1ed1ng c\u1ee7a giai c\u1ea5p th\u1ed1ng tr\u1ecb tri\u1ec1u Nguy\u00ean d\u1ea7n tr\u1edf n\u00ean xa hoa.`,
  `K\u1ec3 t\u1eeb sau c\u00e1i ch\u1ebft c\u1ee7a H\u1ed1t T\u1ea5t Li\u1ec7t,`,
  `N\u0103m 1965, n\u1ed9i b\u1ed9 ch\u00ednh tr\u1ecb b\u1eaft \u0111\u1ea7u th\u1ed1i n\u00e1t,`,
  `v\u00e0 ch\u1ebf \u0111\u1ed9 th\u1eeba k\u1ebf c\u1ee7a ng\u01b0\u1eddi M\u00f4ng C\u1ed5 kh\u00e1c v\u1edbi ng\u01b0\u1eddi H\u00e1n,`,
  `h\u1ecd kh\u00f4ng ph\u1ea3i cha truy\u1ec1n con n\u1ed1i,`,
  `m\u00e0 l\u00e0 ch\u1ecdn m\u1ed9t ng\u01b0\u1eddi t\u00e0i n\u0103ng v\u00e0 c\u00f3 n\u0103ng l\u1ef1c trong s\u1ed1 nh\u1eefng ng\u01b0\u1eddi th\u00e2n c\u1ee7a ho\u00e0ng \u0111\u1ebf \u0111\u1ec3 k\u1ebf v\u1ecb.`,
  `N\u00f3i c\u00e1ch kh\u00e1c, n\u1ebfu b\u1ea1n c\u00f3 ch\u00fat quan h\u1ec7 huy\u1ebft th\u1ed1ng v\u1edbi ho\u00e0ng \u0111\u1ebf,`,
  `v\u1eady th\u00ec b\u1ea1n c\u00f3 c\u01a1 h\u1ed9i l\u00e0m ho\u00e0ng \u0111\u1ebf.`,
  `V\u00ec v\u1eady \u0111\u1ebfn th\u1ebf h\u1ec7 th\u1ee9 ba,`,
  `cu\u1ed9c tranh gi\u00e0nh ngai v\u00e0ng tr\u1edf n\u00ean v\u00f4 c\u00f9ng kh\u1ed1c li\u1ec7t,`,
  `trong 25 n\u0103m \u0111\u00e3 thay \u0111\u1ed5i 8 v\u1ecb ho\u00e0ng \u0111\u1ebf,`,
  `m\u1ed7i l\u1ea7n thay \u0111\u1ed5i ho\u00e0ng \u0111\u1ebf \u0111\u1ec1u x\u1ea3y ra m\u1ed9t cu\u1ed9c th\u1ea3m s\u00e1t l\u1edbn trong ho\u00e0ng t\u1ed9c,`,
  `khi\u1ebfn t\u1eadp \u0111o\u00e0n th\u1ed1ng tr\u1ecb chia r\u1ebd, g\u00e2y ra th\u1ea3m h\u1ecda l\u1edbn cho nh\u00e2n d\u00e2n.`,
  `H\u01a1n n\u1eefa, trong th\u1eddi k\u1ef3 cai tr\u1ecb c\u1ee7a nh\u00e0 Nguy\u00ean, ng\u01b0\u1eddi d\u00e2n \u0111\u01b0\u1ee3c chia th\u00e0nh b\u1ed1n \u0111\u1eb3ng c\u1ea5p:`,
  `Ng\u01b0\u1eddi M\u00f4ng C\u1ed5, ng\u01b0\u1eddi H\u1ed3i gi\u00e1o (ng\u01b0\u1eddi T\u00e2y H\u1ea1),`,
  `ng\u01b0\u1eddi Duy Ng\u00f4 Nh\u0129, ng\u01b0\u1eddi T\u00e2y V\u1ef1c, v.v.,`,
  `ng\u01b0\u1eddi H\u00e1n ph\u01b0\u01a1ng B\u1eafc v\u00e0 ng\u01b0\u1eddi H\u00e1n ph\u01b0\u01a1ng Nam.`,
  `D\u01b0\u1edbi ch\u1ebf \u0111\u1ed9 nh\u01b0 v\u1eady,`,
  `\u0110\u1ecba v\u1ecb c\u1ee7a ng\u01b0\u1eddi H\u00e1n r\u1ea5t th\u1ea5p,`,
  `V\u00ec v\u1eady ng\u01b0\u1eddi H\u00e1n b\u1ecb \u00e1p b\u1ee9c \u0111\u1eb7c bi\u1ec7t nghi\u00eam tr\u1ecdng,`,
  `Kh\u00f4ng s\u1ed1ng n\u1ed5i th\u00ec ph\u1ea3i ph\u1ea3n kh\u00e1ng th\u00f4i.`,
  `Cu\u1ed1i th\u1eddi Nguy\u00ean, nh\u00e2n d\u00e2n t\u1ed9c H\u00e1n \u0111\u00e3 ti\u1ebfn h\u00e0nh v\u00f4 s\u1ed1 cu\u1ed9c ph\u1ea3n kh\u00e1ng d\u01b0\u1edbi nhi\u1ec1u h\u00ecnh th\u1ee9c kh\u00e1c nhau.`,
  `Cu\u1ed9c kh\u1edfi ngh\u0129a Kh\u0103n \u0110\u1ecf do m\u1ed9t ng\u01b0\u1eddi t\u00ean L\u01b0u Ph\u00fac l\u00e3nh \u0111\u1ea1o \u0111\u00e3 c\u00e0n qu\u00e9t c\u1ea3 n\u01b0\u1edbc,`,
  `Trong qu\u00e2n kh\u1edfi ngh\u0129a xu\u1ea5t hi\u1ec7n m\u1ed9t nh\u00f3m t\u01b0\u1edbng l\u0129nh xu\u1ea5t s\u1eafc.`,
  `B\u1ea1n h\u1ecdc c\u1ee7a ch\u00fang ta Chu Nguy\u00ean Ch\u01b0\u01a1ng \u0111\u00e3 xu\u1ea5t hi\u1ec7n v\u00e0o th\u1eddi \u0111i\u1ec3m n\u00e0y.`,
  `N\u0103m 1368 sau C\u00f4ng nguy\u00ean,`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u00f4ng h\u00e3m Nguy\u00ean \u0110\u1ea1i \u0110\u00f4, ch\u1ea5m d\u1ee9t s\u1ef1 th\u1ed1ng tr\u1ecb c\u1ee7a nh\u00e0 Nguy\u00ean.`,
  `C\u00f9ng n\u0103m \u0111\u00f3, Chu Nguy\u00ean Ch\u01b0\u01a1ng x\u01b0ng \u0111\u1ebf \u1edf Nam Kinh, th\u00e0nh l\u1eadp nh\u00e0 Minh.`,
  `Sau khi nh\u00e0 Nguy\u00ean b\u1ecb nh\u00e0 Minh ti\u00eau di\u1ec7t, v\u1ecb ho\u00e0ng \u0111\u1ebf cu\u1ed1i c\u00f9ng l\u00e0 Nguy\u00ean Hu\u1ec7 T\u00f4ng \u0111\u00e3 ch\u1ea1y tr\u1ed1n \u0111\u1ebfn v\u00f9ng M\u00f4ng C\u1ed5,`,
  `Th\u00e0nh l\u1eadp B\u1eafc Nguy\u00ean,`,
  `V\u1eabn ki\u00eam nhi\u1ec7m \u0110\u1ea1i h\u00e3n M\u00f4ng C\u1ed5 v\u1edbi th\u00e2n ph\u1eadn ho\u00e0ng \u0111\u1ebf B\u1eafc Nguy\u00ean.`,
  `N\u00f3i l\u00e0 \u0110\u1ea1i h\u00e3n, nh\u01b0ng th\u1ef1c ch\u1ea5t \u00f4ng ta \u0111\u00e3 kh\u00f4ng c\u00f2n th\u1ef1c l\u1ef1c g\u00ec n\u1eefa,`,
  `Ch\u1eb3ng m\u1ea5y ch\u1ed1c, \u00f4ng ta b\u1ecb m\u1ed9t th\u1ebf l\u1ef1c M\u00f4ng C\u1ed5 kh\u00e1c l\u1eadt \u0111\u1ed5 v\u00e0 s\u00e1t h\u1ea1i.`,
  `B\u1eafc Nguy\u00ean s\u1ee5p \u0111\u1ed5. C\u00e1c b\u1ed9 t\u1ed9c M\u00f4ng C\u1ed5 l\u1ea1i quay v\u1ec1 cu\u1ed9c h\u1ed7n chi\u1ebfn tranh gi\u00e0nh ngai v\u00e0ng h\u00e3n M\u00f4ng C\u1ed5.`,
  `C\u00f2n v\u1ec1 ph\u00eda nh\u00e0 Minh,`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng \u0111\u00e3 t\u1eeb m\u1ed9t \u0111\u1ee9a tr\u1ebb ch\u0103n tr\u00e2u tr\u1edf th\u00e0nh ho\u00e0ng \u0111\u1ebf nh\u01b0 th\u1ebf n\u00e0o?`,
  `Trong t\u1ea5t c\u1ea3 c\u00e1c ho\u00e0ng \u0111\u1ebf khai qu\u1ed1c, Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u00f3 l\u1ebd l\u00e0 ng\u01b0\u1eddi c\u00f3 th\u00e2n th\u1ebf bi th\u1ea3m nh\u1ea5t.`,
  `Cha \u00f4ng l\u00e0 m\u1ed9t n\u00f4ng d\u00e2n ch\u00ednh hi\u1ec7u,`,
  `Khi c\u00f2n nh\u1ecf, \u00f4ng t\u1eebng ch\u0103n tr\u00e2u cho nh\u00e0 \u0111\u1ecba ch\u1ee7.`,
  `D\u00f9 cu\u1ed9c s\u1ed1ng gian kh\u1ed5, nh\u01b0ng \u00edt nh\u1ea5t c\u0169ng c\u00f3 c\u00e1i \u0103n,`,
  `Ng\u00e0y th\u00e1ng c\u1ee9 th\u1ebf tr\u00f4i \u0111i b\u00ecnh l\u1eb7ng.`,
  `Ch\u1eb3ng bao l\u00e2u, cu\u1ed9c s\u1ed1ng b\u00ecnh y\u00ean n\u00e0y b\u1ecb ph\u00e1 v\u1ee1.`,
  `M\u1ed9t n\u0103m n\u1ecd, qu\u00ea h\u01b0\u01a1ng h\u1ea1n h\u00e1n n\u1eb7ng,`,
  `Th\u00eam v\u00e0o n\u1ea1n ch\u00e2u ch\u1ea5u, h\u01a1n n\u1eeda gia \u0111\u00ecnh h\u1ecd Chu ch\u1ebft \u0111\u00f3i.`,
  `Th\u1ef1c s\u1ef1 kh\u00f4ng c\u00f2n \u0111\u01b0\u1eddng n\u00e0o kh\u00e1c, Chu Nguy\u00ean Ch\u01b0\u01a1ng \u0111\u00e0nh ph\u1ea3i \u0111\u1ebfn Ho\u00e0ng Gi\u00e1c T\u1ef1 l\u00e0m h\u00f2a th\u01b0\u1ee3ng,`,
  `Nh\u01b0ng trong ch\u00f9a c\u0169ng r\u1ea5t ngh\u00e8o,`,
  `C\u00e1c h\u00f2a th\u01b0\u1ee3ng ph\u1ea3i \u0111i kh\u1ea5t th\u1ef1c \u0111\u1ec3 t\u1ef1 nu\u00f4i s\u1ed1ng b\u1ea3n th\u00e2n.`,
  `Th\u1ef1c ra l\u00e0 \u0111i \u0103n xin.`,
  `L\u00fac n\u00e0y, c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n cu\u1ed1i th\u1eddi Nguy\u00ean \u0111ang di\u1ec5n ra \u00e1c li\u1ec7t,`,
  `\u0110\u1eb7c bi\u1ec7t l\u00e0 qu\u00e2n Kh\u0103n \u0110\u1ecf.`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng \u0111\u00e3 \u0103n xin nhi\u1ec1u n\u0103m, n\u1ebfm tr\u1ea3i m\u1ecdi s\u1ef1 \u1ea5m l\u1ea1nh c\u1ee7a \u0111\u1eddi ng\u01b0\u1eddi,`,
  `C\u0169ng lo l\u1eafng b\u1ea5t c\u1ee9 l\u00fac n\u00e0o c\u0169ng c\u00f3 th\u1ec3 b\u1ecb qu\u00e2n Nguy\u00ean b\u1eaft \u0111i,`,
  `T\u00ednh m\u1ea1ng kh\u00f3 gi\u1eef, l\u1ea1i nh\u1eadn \u0111\u01b0\u1ee3c th\u01b0 c\u1ee7a ng\u01b0\u1eddi b\u1ea1n thu\u1edf nh\u1ecf Thang H\u00f2a m\u1eddi \u00f4ng tham gia ngh\u0129a qu\u00e2n.`,
  `Do nhi\u1ec1u nguy\u00ean nh\u00e2n kh\u00e1c nhau,`,
  `Th\u00fac \u0111\u1ea9y Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u1edfi b\u1ecf c\u00e0 sa, ki\u00ean quy\u1ebft gia nh\u1eadp qu\u00e2n Kh\u0103n \u0110\u1ecf c\u1ee7a Qu\u00e1ch T\u1eed H\u01b0ng.`,
  `Do Chu l\u00e3o gia t\u00e1c chi\u1ebfn d\u0169ng m\u00e3nh, \u0111\u1ea7u \u00f3c l\u1ea1i r\u1ea5t linh ho\u1ea1t,`,
  `R\u1ea5t nhanh \u0111\u00e3 \u0111\u01b0\u1ee3c Qu\u00e1ch T\u1eed H\u01b0ng\u8cde\u8bc6,`,
  `Th\u1eadm ch\u00ed c\u00f2n g\u1ea3 con g\u00e1i nu\u00f4i M\u00e3 th\u1ecb cho Chu Nguy\u00ean Ch\u01b0\u01a1ng,`,
  `Ch\u00ednh l\u00e0 M\u00e3 Ho\u00e0ng h\u1eadu sau n\u00e0y.`,
  `C\u00e1nh c\u1ee7a Chu Nguy\u00ean Ch\u01b0\u01a1ng d\u1ea7n d\u1ea7n c\u1ee9ng c\u00e1p,`,
  `Quy\u1ebft \u0111\u1ecbnh t\u1ef1 m\u00ecnh l\u1eadp nghi\u1ec7p ri\u00eang,`,
  `D\u00e1m l\u00e0m. Cha v\u1ee3 Qu\u00e1ch T\u1eed H\u01b0ng c\u0169ng \u1ee7ng h\u1ed9 \u00f4ng.`,
  `Sau khi t\u1ef1 l\u1eadp, Chu Nguy\u00ean Ch\u01b0\u01a1ng nh\u01b0 \u201chack\u201d v\u1eady,`,
  `chi\u00eau m\u1ed9 r\u1ea5t nhi\u1ec1u binh l\u00ednh, k\u1ebft giao r\u1ea5t nhi\u1ec1u b\u1ea1n b\u00e8,`,
  `c\u0169ng \u0111\u00e1nh th\u1eafng r\u1ea5t nhi\u1ec1u tr\u1eadn.`,
  `Sau n\u00e0y, Qu\u00e1ch T\u1eed H\u01b0ng l\u00e2m b\u1ec7nh qua \u0111\u1eddi, nh\u1edd n\u1ed7 l\u1ef1c c\u1ee7a b\u1ea3n th\u00e2n v\u00e0 t\u00e0i nguy\u00ean t\u1eeb cha v\u1ee3 \u0111\u1ec3 l\u1ea1i,`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng nhanh ch\u00f3ng x\u00e2y d\u1ef1ng \u0111\u01b0\u1ee3c m\u1ed9t \u0111\u1ed9i qu\u00e2n h\u00f9ng m\u1ea1nh.`,
  `L\u00fac n\u00e0y, Chu Nguy\u00ean Ch\u01b0\u01a1ng kh\u00f4ng v\u1ed9i b\u00e0nh tr\u01b0\u1edbng,`,
  `d\u01b0\u1edbi s\u1ef1 ch\u1ec9 d\u1eabn c\u1ee7a m\u01b0u s\u0129 Chu Th\u0103ng, ki\u00ean \u0111\u1ecbnh v\u1edbi ph\u01b0\u01a1ng ch\u00e2m \u201ccao tr\u00fac t\u01b0\u1eddng\u201d,`,
  `ngh\u0129a l\u00e0 t\u0103ng c\u01b0\u1eddng ph\u00f2ng b\u1ecb qu\u00e2n s\u1ef1;`,
  `\u201cqu\u1ea3ng t\u00edch l\u01b0\u01a1ng\u201d, ngh\u0129a l\u00e0 ph\u00e1t tri\u1ec3n s\u1ea3n xu\u1ea5t, t\u00edch tr\u1eef l\u01b0\u01a1ng th\u1ef1c;`,
  `\u201cho\u00e3n x\u01b0ng v\u01b0\u01a1ng\u201d, ngh\u0129a l\u00e0 kh\u00f4ng v\u1ed9i x\u01b0ng \u0111\u1ebf s\u1edbm,`,
  `tr\u00e1nh g\u00e2y qu\u00e1 nhi\u1ec1u k\u1ebb th\u00f9.`,
  `V\u1edbi c\u01b0\u01a1ng l\u0129nh c\u00e1ch m\u1ea1ng t\u1ef1 r\u0103n m\u00ecnh n\u00e0y, l\u00e3o Chu ti\u1ebfp t\u1ee5c \u00e2m th\u1ea7m ph\u00e1t tri\u1ec3n l\u1ef1c l\u01b0\u1ee3ng c\u1ee7a m\u00ecnh.`,
  `L\u00fac n\u00e0y, ngo\u00e0i Chu Nguy\u00ean Ch\u01b0\u01a1ng ra,`,
  `qu\u00e2n kh\u1edfi ngh\u0129a c\u00f2n c\u00f3 hai th\u1ebf l\u1ef1c c\u1ef1c k\u1ef3 l\u1edbn m\u1ea1nh kh\u00e1c,`,
  `l\u00e0 Tr\u01b0\u01a1ng S\u0129 Th\u00e0nh chi\u1ebfm gi\u1eef m\u1ed9t v\u00f9ng ph\u00eda \u0110\u00f4ng v\u00e0 Tr\u1ea7n H\u1eefu L\u01b0\u1ee3ng n\u1eafm gi\u1eef b\u00e1 quy\u1ec1n ph\u00eda T\u00e2y.`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng \u1edf gi\u1eefa hai ng\u01b0\u1eddi h\u1ecd.`,
  `Tr\u01b0\u01a1ng Th\u00e0nh v\u00e0 qu\u00e2n c\u1ee7a \u00f4ng th\u1ea5y Chu Nguy\u00ean Ch\u01b0\u01a1ng th\u1eadt ng\u1ee9a m\u1eaft,`,
  `t\u00ednh to\u00e1n tr\u01b0\u1edbc h\u1ebft l\u00e0 ph\u1ea3i h\u1ea1 g\u1ee5c \u00f4ng, nh\u01b0ng h\u1ecd \u0111\u00e3 t\u00ednh to\u00e1n sai.`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng ti\u00ean di\u1ec7t Tr\u1ea7n H\u1eefu L\u01b0\u1ee3ng, k\u1ebb m\u1ea1nh nh\u1ea5t,`,
  `sau \u0111\u00f3 \u0111\u00e1nh Tr\u01b0\u01a1ng S\u0129 Th\u00e0nh.`,
  `C\u1ee9 nh\u01b0 v\u1eady, sau v\u00e0i n\u0103m chinh chi\u1ebfn, Chu Nguy\u00ean Ch\u01b0\u01a1ng \u0111\u00e3 ki\u1ec3m so\u00e1t m\u1ed9t v\u00f9ng \u0111\u1ea5t r\u1ed9ng l\u1edbn, gi\u00e0u c\u00f3 nh\u1ea5t \u1edf trung v\u00e0 h\u1ea1 l\u01b0u s\u00f4ng Tr\u01b0\u1eddng Giang,`,
  `c\u00f3 m\u1ed9t \u0111\u1ed9i qu\u00e2n h\u00f9ng m\u1ea1nh,`,
  `\u0111\u00e3 c\u00f3 \u0111\u1ee7 s\u1ee9c m\u1ea1nh \u0111\u1ec3 l\u1eadt \u0111\u1ed5 nh\u00e0 Nguy\u00ean, th\u1ed1ng nh\u1ea5t \u0111\u1ea5t n\u01b0\u1edbc.`,
  `N\u0103m 1368 sau C\u00f4ng nguy\u00ean,`,
  `qu\u00e2n Chu l\u1ea1i c\u00f4ng chi\u1ebfm \u0110\u1ea1i \u0110\u00f4 nh\u00e0 Nguy\u00ean,`,
  `\u0111\u00e1nh cho v\u1ecb ho\u00e0ng \u0111\u1ebf cu\u1ed1i c\u00f9ng c\u1ee7a nh\u00e0 Nguy\u00ean ph\u1ea3i ch\u1ea1y v\u1ec1 th\u1ea3o nguy\u00ean.`,
  `Nh\u00e0 Nguy\u00ean tuy\u00ean b\u1ed1 di\u1ec7t vong,`,
  `L\u00e3o Chu \u0111\u0103ng c\u01a1, l\u1eadp ra nh\u00e0 Minh.`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng l\u00e0 m\u1ed9t s\u1ef1 qu\u1eadt kh\u1edfi th\u1ef1c s\u1ef1 c\u1ee7a k\u1ebb xu\u1ea5t th\u00e2n th\u1ea5p k\u00e9m, nh\u01b0ng s\u1ef1 tr\u1ed7i d\u1eady c\u1ee7a \u00f4ng kh\u00f4ng ch\u1ec9 d\u1ef1a v\u00e0o may m\u1eafn.`,
  `Tr\u01b0\u1edbc h\u1ebft, \u00f4ng hi\u1ec3u \u0111\u01b0\u1ee3c c\u00e1ch m\u01b0\u1ee3n th\u1ebf,`,
  `M\u01b0\u1ee3n danh ngh\u0129a qu\u00e2n Kh\u0103n \u0110\u1ecf \u0111\u1ec3 ph\u00e1t tri\u1ec3n b\u1ea3n th\u00e2n;`,
  `Th\u1ee9 hai, \u00f4ng k\u1ebft giao r\u1ed9ng r\u00e3i v\u1edbi nh\u1eefng ng\u01b0\u1eddi t\u00e0i gi\u1ecfi, bi\u1ebft c\u00e1ch d\u00f9ng ng\u01b0\u1eddi.`,
  `L\u01b0u B\u00e1 \u00d4n, Thang H\u00f2a, T\u1eeb \u0110\u1ea1t v\u00e0 nh\u1eefng c\u00f4ng th\u1ea7n khai qu\u1ed1c kh\u00e1c \u0111\u00e3 c\u00f3 \u1ea3nh h\u01b0\u1edfng quan tr\u1ecdng \u0111\u1ebfn th\u00e0nh c\u00f4ng c\u1ee7a \u00f4ng;`,
  `Ngo\u00e0i ra, qu\u00e2n \u0111\u1ed9i c\u1ee7a \u00f4ng c\u00f3 k\u1ef7 lu\u1eadt nghi\u00eam minh,`,
  `V\u1eeba \u0111\u01b0\u1ee3c d\u00e2n ch\u00fang \u1ee7ng h\u1ed9, v\u1eeba \u0111\u01b0\u1ee3c \u0111\u1ecba ch\u1ee7, h\u00e0o ph\u00fa \u1ee7ng h\u1ed9.`,
  `Thi\u00ean th\u1eddi, \u0111\u1ecba l\u1ee3i, nh\u00e2n h\u00f2a \u0111\u00e3 t\u1ea1o n\u00ean th\u00e0nh c\u00f4ng c\u1ee7a Chu Nguy\u00ean Ch\u01b0\u01a1ng.`,
  `Gi\u00e0nh \u0111\u01b0\u1ee3c giang s\u01a1n ch\u1ec9 l\u00e0 kh\u1edfi \u0111\u1ea7u,`,
  `L\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 cai tr\u1ecb l\u1ea1i l\u00e0 m\u1ed9t th\u1eed th\u00e1ch m\u1edbi \u0111\u1ed1i v\u1edbi Chu Nguy\u00ean Ch\u01b0\u01a1ng.`,
  `L\u00e0 m\u1ed9t ho\u00e0ng \u0111\u1ebf xu\u1ea5t th\u00e2n t\u1eeb n\u00f4ng d\u00e2n, Chu Nguy\u00ean Ch\u01b0\u01a1ng kh\u00f4ng qu\u00ean g\u1ed1c g\u00e1c,`,
  `Sau khi l\u00ean ng\u00f4i, \u00f4ng khuy\u1ebfn kh\u00edch khai hoang, th\u1ef1c hi\u1ec7n ch\u00ednh s\u00e1ch \u0111\u1ed3n \u0111i\u1ec1n,`,
  `X\u00e2y d\u1ef1ng th\u1ee7y l\u1ee3i, gi\u1ea3m thu\u1ebf v\u00e0 lao d\u1ecbch.`,
  `Nh\u1eefng ch\u00ednh s\u00e1ch c\u00f3 l\u1ee3i cho d\u00e2n n\u00e0y \u0111\u00e3 khi\u1ebfn nh\u1eefng ng\u01b0\u1eddi n\u00f4ng d\u00e2n b\u1ecb \u00e1p b\u1ee9c tr\u00e0n \u0111\u1ea7y hy v\u1ecdng v\u00e0o cu\u1ed9c s\u1ed1ng.`,
  `Nh\u00e0 Minh d\u1ea7n d\u1ea7n h\u1ed3i sinh t\u1eeb n\u1ed7i s\u1ee3 h\u00e3i c\u1ee7a s\u1ef1 cai tr\u1ecb c\u1ee7a ngo\u1ea1i t\u1ed9c nh\u00e0 Nguy\u00ean,`,
  `V\u00e0 vi\u1ec7c Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u0103m gh\u00e9t quan l\u1ea1i tham nh\u0169ng c\u0169ng l\u00e0 \u0111i\u1ec1u ai c\u0169ng bi\u1ebft,`,
  `V\u1eabn c\u00f2n li\u00ean quan \u0111\u1ebfn nh\u1eefng tr\u1ea3i nghi\u1ec7m th\u1eddi tr\u1ebb c\u1ee7a \u00f4ng.`,
  `B\u1ecb b\u00f3c l\u1ed9t \u0111\u1ebfn s\u1ee3 h\u00e3i, \u0111\u1ec3 tr\u1eebng tr\u1ecb tham quan, \u00f4ng \u0111\u00e3 ph\u00e1t minh ra \u0111\u1ee7 lo\u1ea1i h\u00ecnh ph\u1ea1t kinh ho\u00e0ng.`,
  `M\u1ed7i l\u1ea7n \u0111i\u1ec1u tra quan l\u1ea1i b\u1ea9n th\u1ec9u \u0111\u1ec1u ph\u1ea3i gi\u1ebft ch\u1ebft h\u00e0ng v\u1ea1n ng\u01b0\u1eddi,`,
  `V\u00ec v\u1eady \u00f4ng c\u0169ng \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 b\u1ea1o ch\u00faa.`,
  `M\u01b0\u1ee3n c\u1edb tr\u1ea5n \u00e1p tham nh\u0169ng, l\u00e3o Chu \u0111\u00e3 gi\u1ebft s\u1ea1ch m\u1ed9t lo\u1ea1t c\u00e1c anh em khai qu\u1ed1c \u0111\u00e3 c\u00f9ng m\u00ecnh g\u00e2y d\u1ef1ng thi\u00ean h\u1ea1.`,
  `\u0110\u01b0\u01a1ng nhi\u00ean, kh\u00f4ng ch\u1ec9 v\u00ec h\u1ecd tham lam,`,
  `Quan tr\u1ecdng h\u01a1n l\u00e0 l\u00e3o Chu s\u1ee3 m\u00ecnh b\u1ecb \u0111o\u1ea1t quy\u1ec1n.`,
  `N\u1ebfu kh\u00f4ng x\u1eed l\u00fd nh\u1eefng ng\u01b0\u1eddi n\u00e0y, nh\u00e0 h\u1ecd Chu c\u00f3 th\u1ec3 kh\u00f4ng gi\u1eef v\u1eefng \u0111\u01b0\u1ee3c giang s\u01a1n.`,
  `Ngo\u00e0i ra, Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u00f2n b\u00e3i b\u1ecf ch\u1ee9c t\u1ec3 t\u01b0\u1edbng,`,
  `Phong c\u00e1c con trai c\u1ee7a m\u00ecnh l\u00e0m phi\u00ean v\u01b0\u01a1ng,`,
  `M\u1ed7i ng\u01b0\u1eddi \u0111\u1ec1u n\u1eafm gi\u1eef tr\u1ecdng binh,`,
  `N\u1eafm ch\u1eafc quy\u1ec1n l\u1ef1c qu\u1ed1c gia trong tay nh\u00e0 h\u1ecd Chu c\u1ee7a h\u1ecd.`,
  `\u0110i\u1ec3m n\u00e0y c\u0169ng \u0111\u1eb7t n\u1ec1n m\u00f3ng cho vi\u1ec7c Chu \u0110\u1ec7 sau n\u00e0y thu\u1eadn l\u1ee3i so\u00e1n ng\u00f4i.`,
  `Tuy nhi\u00ean, \u0111\u00f3 l\u00e0 chuy\u1ec7n sau n\u00e0y.`,
  `\u0110\u1ebfn cu\u1ed1i \u0111\u1eddi, Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u00f3 l\u1ebd \u0111\u00e3 l\u1ea9n th\u1ea9n,`,
  `Ch\u1ee9ng hoang t\u01b0\u1edfng b\u1ecb h\u1ea1i th\u01b0\u1eddng xuy\u00ean t\u00e1i ph\u00e1t.`,
  `\u00d4ng ta th\u00e0nh l\u1eadp C\u1ea9m y v\u1ec7, m\u1ed9t c\u01a1 quan m\u1eadt v\u1ee5,`,
  `gi\u00fap ho\u00e0ng \u0111\u1ebf theo d\u00f5i v\u00e0 t\u1ed1 gi\u00e1c.`,
  `D\u01b0\u1edbi s\u1ef1 gi\u00e1m s\u00e1t c\u1ee7a Chu Nguy\u00ean Ch\u01b0\u01a1ng,`,
  `nhi\u1ec1u \u0111\u1ea1i th\u1ea7n khai qu\u1ed1c ho\u1eb7c l\u00e0 ch\u1ebft kh\u00f4ng to\u00e0n th\u00e2y,`,
  `ho\u1eb7c l\u00e0 cu\u1ed1i \u0111\u1eddi th\u00ea th\u1ea3m.`,
  `Cu\u1ed1i c\u00f9ng, c\u00e1c c\u00f4ng th\u1ea7n trung l\u01b0\u01a1ng \u0111\u1ec1u b\u1ecb gi\u1ebft g\u1ea7n h\u1ebft,`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng c\u0169ng \u0111i \u0111\u1ebfn cu\u1ed1i cu\u1ed9c \u0111\u1eddi.`,
  `N\u0103m 1398 sau C\u00f4ng nguy\u00ean,`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng l\u00e2m b\u1ec7nh qua \u0111\u1eddi,`,
  `h\u01b0\u1edfng th\u1ecd b\u1ea3y m\u01b0\u01a1i tu\u1ed5i.`,
  `Sau khi Chu Nguy\u00ean Ch\u01b0\u01a1ng m\u1ea5t,`,
  `ch\u00e1u c\u1ee7a \u00f4ng l\u00e0 Chu Do\u00e3n V\u0103n k\u1ebf v\u1ecb.`,
  `C\u00f3 nhi\u1ec1u con nh\u01b0 v\u1eady, v\u00ec sao l\u1ea1i ch\u1ecdn ch\u00e1u?`,
  `B\u1edfi v\u00ec Chu Do\u00e3n V\u0103n l\u00e0 con trai c\u1ee7a Chu Ti\u00eau, tr\u01b0\u1edfng t\u1eed c\u1ee7a Chu Nguy\u00ean Ch\u01b0\u01a1ng.`,
  `Chu Ti\u00eau v\u1ed1n l\u00e0 th\u00e1i t\u1eed, nh\u01b0ng \u00f4ng \u1ea5y m\u1ea5t s\u1edbm,`,
  `Tu\u00e2n theo nguy\u00ean t\u1eafc l\u1eadp \u0111\u00edch l\u1eadp tr\u01b0\u1edfng (ch\u1ecdn con n\u1ed1i d\u00f5i l\u00e0 con d\u00f2ng ch\u00ednh, l\u1edbn nh\u1ea5t),`,
  `ng\u00f4i b\u00e1u r\u01a1i v\u00e0o tay ch\u00e1u tr\u01b0\u1edfng c\u1ee7a ho\u00e0ng \u0111\u1ebf.`,
  `Sau khi Chu Do\u00e3n V\u0103n l\u00ean ng\u00f4i, \u00f4ng c\u1ea3m th\u1ea5y quy\u1ec1n l\u1ef1c c\u1ee7a c\u00e1c phi\u00ean v\u01b0\u01a1ng th\u00fac th\u00fac qu\u00e1 l\u1edbn,`,
  `\u0111e d\u1ecda \u0111\u1ebfn m\u00ecnh,`,
  `n\u00ean \u00f4ng nhanh ch\u00f3ng b\u1eaft \u0111\u1ea7u c\u1eaft gi\u1ea3m phi\u00ean v\u01b0\u01a1ng.`,
  `Y\u00ean V\u01b0\u01a1ng Chu \u0110\u1ec7 kh\u00f4ng th\u1ec3 ng\u1ed3i y\u00ean.`,
  `Chu \u0110\u1ec7 l\u00e0 con trai th\u1ee9 t\u01b0 c\u1ee7a Chu Nguy\u00ean Ch\u01b0\u01a1ng,`,
  `l\u1edbn l\u00ean trong qu\u00e2n doanh c\u00f9ng Chu Nguy\u00ean Ch\u01b0\u01a1ng t\u1eeb nh\u1ecf,`,
  `c\u00f3 n\u0103ng l\u1ef1c phi th\u01b0\u1eddng. M\u1eb7c d\u00f9 \u00f4ng r\u1ea5t t\u00e0i gi\u1ecfi, nh\u01b0ng m\u1eb9 ru\u1ed9t c\u1ee7a \u00f4ng c\u00f3 th\u00e2n ph\u1eadn r\u1ea5t th\u1ea5p,`,
  `b\u1ea3n th\u00e2n l\u1ea1i kh\u00f4ng ph\u1ea3i con tr\u01b0\u1edfng,`,
  `n\u00ean ng\u00f4i b\u00e1u th\u1ebf n\u00e0o c\u0169ng kh\u00f4ng \u0111\u1ebfn l\u01b0\u1ee3t \u00f4ng.`,
  `Chu Nguy\u00ean Ch\u01b0\u01a1ng phong \u00f4ng l\u00e0m Y\u00ean V\u01b0\u01a1ng.`,
  `V\u1ec1 \u0111i\u1ec1u n\u00e0y, Chu \u0110\u1ec7 c\u1ef1c k\u1ef3 b\u1ea5t m\u00e3n,`,
  `nh\u01b0ng c\u0169ng kh\u00f4ng c\u00f3 c\u00e1ch n\u00e0o kh\u00e1c,`,
  `v\u00ec quy t\u1eafc c\u1ee7a t\u1ed5 ti\u00ean \u0111\u00e3 \u1edf \u0111\u00f3 r\u1ed3i.`,
  `V\u00e0 vi\u1ec7c Chu Do\u00e3n V\u0103n c\u1eaft gi\u1ea3m phi\u00ean v\u01b0\u01a1ng \u0111\u00e3 t\u1ea1o c\u1edb cho Chu \u0110\u1ec7,`,
  `\u00d4ng ta li\u1ec1n d\u1eabn binh ph\u1ea3n c\u00f4ng Chu Do\u00e3n V\u0103n.`,
  `\u0110\u00e2y ch\u00ednh l\u00e0 Chi\u1ebfn d\u1ecbch T\u0129nh Nan n\u1ed5i ti\u1ebfng trong l\u1ecbch s\u1eed.`,
  `Chu Do\u00e3n V\u0103n ch\u1ec9 l\u00e0 m\u1ed9t c\u1eadu b\u00e9 t\u00f3c b\u1ea1c,`,
  `Ho\u00e0ng \u0111\u1ebf th\u01b0 sinh y\u1ebfu \u1edbt sao c\u00f3 th\u1ec3 \u0111\u1ea5u l\u1ea1i Chu \u0110\u1ec7?`,
  `Sau khi Chu \u0110\u1ec7 c\u00f4ng ph\u00e1 kinh th\u00e0nh,`,
  `Chu Do\u00e3n V\u0103n \u0111\u00e3 b\u1ed1c h\u01a1i kh\u1ecfi th\u1ebf gian.`,
  `C\u00f3 ng\u01b0\u1eddi n\u00f3i \u00f4ng ta \u0111\u1ebfn Ph\u00fac Ki\u1ebfn l\u00e0m h\u00f2a th\u01b0\u1ee3ng, c\u0169ng c\u00f3 ng\u01b0\u1eddi n\u00f3i \u00f4ng ta ch\u1ea1y tr\u1ed1n \u0111\u1ebfn \u0110\u00f4ng Nam \u00c1.`,
  `T\u00f3m l\u1ea1i, Chu \u0110\u1ec7 c\u01b0\u1edbp ng\u00f4i th\u00e0nh c\u00f4ng,`,
  `Ni\u00ean hi\u1ec7u V\u0129nh L\u1ea1c. Sau khi Chu \u0110\u1ec7 l\u00ean ng\u00f4i, \u0111\u1ed1i v\u1edbi c\u00e1c c\u1ef1u th\u1ea7n c\u1ee7a Chu Do\u00e3n V\u0103n ch\u1ec9 c\u00f3 m\u1ed9t ch\u1eef,`,
  `Gi\u1ebft, h\u1ec5 \u0111\u1ed9ng m\u1ed9t ch\u00fat l\u00e0 tru di c\u1eedu t\u1ed9c, tru di th\u1eadp t\u1ed9c.`,
  `M\u1eb7c d\u00f9 th\u1ee7 \u0111o\u1ea1n c\u1ee7a Chu \u0110\u1ec7 r\u1ea5t t\u00e0n nh\u1eabn, nh\u01b0ng qu\u1ea3 th\u1ef1c \u0111\u00e3 ph\u1ea7n n\u00e0o l\u00e0m cho nh\u1eefng ng\u01b0\u1eddi xem ph\u1ea3i khi\u1ebfp s\u1ee3.`,
  `Ch\u00ednh quy\u1ec1n trong n\u01b0\u1edbc nhanh ch\u00f3ng \u1ed5n \u0111\u1ecbnh.`,
  `Chu \u0110\u1ec7 tr\u1ecb qu\u1ed1c c\u0169ng c\u00f3 m\u1ed9t b\u1ed9, m\u1ed9t b\u1ed9 ph\u1eadn,`,
  `D\u01b0\u1edbi s\u1ef1 cai tr\u1ecb c\u1ee7a \u00f4ng, x\u00e3 h\u1ed9i th\u1eddi \u0111\u00f3 n\u00f4ng nghi\u1ec7p ph\u1ed3n th\u1ecbnh,`,
  `Th\u01b0\u01a1ng nghi\u1ec7p v\u00e0 ti\u1ec3u th\u1ee7 c\u00f4ng nghi\u1ec7p ph\u00e1t tri\u1ec3n v\u01b0\u1ee3t b\u1eadc,`,
  `ng\u00e0nh \u0111\u00f3ng t\u00e0u ph\u00e1t tri\u1ec3n nh\u1ea5t,`,
  `v\u0103n h\u00f3a l\u1ea1i c\u00e0ng r\u1ef1c r\u1ee1.`,
  `Chu \u0110\u1ec7 \u0111\u00e3 t\u1ed5 ch\u1ee9c h\u00e0ng ngh\u00ecn ng\u01b0\u1eddi, m\u1ea5t 4 n\u0103m \u0111\u1ec3 bi\u00ean so\u1ea1n "V\u0129nh L\u1ea1c \u0110\u1ea1i \u0110i\u1ec3n",`,
  `\u0111\u00e2y l\u00e0 b\u1ed9 b\u00e1ch khoa to\u00e0n th\u01b0 l\u1edbn nh\u1ea5t th\u1ebf gi\u1edbi l\u00fac b\u1ea5y gi\u1edd.`,
  `\u0110\u1ec3 ch\u1ed1ng l\u1ea1i k\u1ebb th\u00f9 b\u00ean ngo\u00e0i,`,
  `Chu \u0110\u1ec7 c\u00f2n quy\u1ebft \u0111\u1ecbnh d\u1eddi \u0111\u00f4 v\u1ec1 B\u1eafc Kinh,`,
  `v\u00e0 th\u1ebf l\u00e0 C\u1ed1 Cung, cung \u0111i\u1ec7n l\u1edbn nh\u1ea5t th\u1ebf gi\u1edbi, \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng \u1edf B\u1eafc Kinh.`,
  `C\u00f3 th\u1ec3 n\u00f3i, v\u00e0o th\u1eddi V\u0129nh L\u1ea1c,`,
  `nh\u00e0 Minh v\u1ec1 c\u01a1 b\u1ea3n \u0111\u00e3 \u0111\u1ea1t \u0111\u01b0\u1ee3c ti\u1ebfn b\u1ed9 to\u00e0n di\u1ec7n,`,
  `v\u1eeba c\u00f3 ti\u1ec1n, v\u1eeba c\u00f3 v\u0103n h\u00f3a, l\u1ea1i c\u00f2n bi\u1ebft \u0111\u00f3ng t\u00e0u,`,
  `th\u1ebf th\u00ec ra ngo\u00e0i khoe khoang m\u1ed9t ch\u00fat th\u00f4i.`,
  `Th\u1ebf l\u00e0, Chu \u0110\u1ec7 ph\u00e1i Tr\u1ecbnh H\u00f2a \u0111i xu\u1ed1ng T\u00e2y D\u01b0\u01a1ng.`,
  `Th\u1ef1c ra c\u00f2n c\u00f3 m\u1ed9t c\u00e1ch n\u00f3i kh\u00e1c,`,
  `\u00f4ng ph\u00e1i Tr\u1ecbnh H\u00f2a l\u00e0 \u0111\u1ec3 t\u00ecm ki\u1ebfm Chu Do\u00e3n V\u0103n m\u1ea5t t\u00edch.`,
  `B\u1ea5t k\u1ec3 v\u00ec l\u00fd do g\u00ec, Tr\u1ecbnh H\u00f2a \u0111\u00e3 b\u1ea3y l\u1ea7n du ngo\u1ea1n T\u00e2y D\u01b0\u01a1ng,`,
  `kh\u00e1m ph\u00e1 h\u01a1n ba m\u01b0\u01a1i qu\u1ed1c gia v\u00e0 khu v\u1ef1c.`,
  `Kh\u00f4ng ch\u1ec9 m\u1edf ra c\u00e1nh c\u1eeda th\u01b0\u01a1ng m\u1ea1i v\u1edbi c\u00e1c n\u01b0\u1edbc ngo\u00e0i, m\u00e0 c\u00f2n`,
  `cho th\u1ebf gi\u1edbi th\u1ea5y s\u1ee9c m\u1ea1nh t\u1ed5ng h\u1ee3p c\u1ee7a nh\u00e0 Minh.`,
  `Sau khi \u0111\u1ea1t \u0111\u01b0\u1ee3c th\u00e0nh c\u00f4ng trong quan h\u1ec7 ngo\u1ea1i giao v\u1edbi n\u01b0\u1edbc ngo\u00e0i,`,
  `Chu \u0110\u1ec7 l\u1ea1i b\u1eaft \u0111\u1ea7u ch\u00fa \u00fd \u0111\u1ebfn c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 xung quanh.`,
  `Th\u1ef1c ra, ph\u01b0\u01a1ng ph\u00e1p c\u1ee7a \u00f4ng r\u1ea5t \u0111\u01a1n gi\u1ea3n:`,
  `ai v\u00e2ng l\u1eddi th\u00ec chi\u00eau m\u1ed9, ai kh\u00f4ng v\u00e2ng l\u1eddi th\u00ec ra tay ngay.`,
  `\u0110\u1ec3 \u1ed5n \u0111\u1ecbnh bi\u00ean gi\u1edbi ph\u00eda B\u1eafc, Chu \u0110\u1ec7 \u0111\u00e3 n\u0103m l\u1ea7n vi\u1ec5n chinh M\u00f4ng C\u1ed5 trong \u0111\u1eddi.`,
  `Trong l\u1ea7n xu\u1ea5t chinh cu\u1ed1i c\u00f9ng, Chu \u0110\u1ec7 qua \u0111\u1eddi v\u00ec b\u1ec7nh.`,
  `\u00d4ng tr\u1ecb v\u00ec 22 n\u0103m,`,
  `d\u1ed1c l\u00f2ng cai tr\u1ecb, t\u1ea1o n\u00ean th\u1eddi k\u1ef3 th\u1ecbnh v\u01b0\u1ee3ng V\u0129nh L\u1ea1c, c\u00f3 \u1ea3nh h\u01b0\u1edfng s\u00e2u r\u1ed9ng \u0111\u1ebfn c\u00e1c th\u1ebf h\u1ec7 sau.`,
  `Sau \u0111\u00f3, Chu Cao S\u00ed, con trai c\u1ea3 c\u1ee7a Chu \u0110\u1ec7, l\u00ean ng\u00f4i.`,
  `V\u00ec b\u00e9o v\u00e0 ham \u0103n, \u00f4ng \u0111\u01b0\u1ee3c h\u1eadu th\u1ebf g\u1ecdi l\u00e0 ho\u00e0ng \u0111\u1ebf ham \u0103n.`,
  `Nh\u01b0ng b\u00e9o kh\u00f4ng \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn vi\u1ec7c \u00f4ng l\u00e0 m\u1ed9t minh qu\u00e2n.`,
  `Trong th\u1eddi gian tr\u1ecb v\u00ec, \u00f4ng ra s\u1ee9c truy\u1ec1n b\u00e1 t\u01b0 t\u01b0\u1edfng Nho gi\u00e1o,`,
  `tr\u1ecdng d\u1ee5ng hi\u1ec1n t\u00e0i, \u0111\u1eb7c bi\u1ec7t khuy\u1ebfn kh\u00edch c\u00e1c quan l\u1ea1i th\u1eb3ng th\u1eafn can gi\u00e1n.`,
  `\u0110i\u1ec1u n\u00e0y \u0111\u00e3 l\u00e0m cho tri\u1ec1u \u0111\u00ecnh nh\u00e0 Minh th\u1eddi \u0111\u00f3 c\u1edfi m\u1edf v\u00e0 trong s\u1ea1ch.`,
  `\u00d4ng c\u00f2n b\u00e3i b\u1ecf m\u1ed9t s\u1ed1 ch\u00ednh s\u00e1ch h\u00e0 kh\u1eafc th\u1eddi V\u0129nh L\u1ea1c,`,
  `minh oan cho c\u00e1c c\u1ef1u th\u1ea7n.`,
  `Chu Cao S\u00ed c\u0169ng ng\u1eebng c\u00e1c cu\u1ed9c chi\u1ebfn tranh quy m\u00f4 l\u1edbn,`,
  `gi\u00fap d\u00e2n ch\u00fang c\u00f3 cu\u1ed9c s\u1ed1ng \u1ea5m no.`,
  `\u0110\u00e1ng ti\u1ebfc thay, Chu Cao S\u00ed ch\u1ec9 \u1edf ng\u00f4i \u0111\u01b0\u1ee3c ch\u00edn th\u00e1ng th\u00ec qua \u0111\u1eddi.`,
  `Tuy th\u1eddi gian tr\u1ecb v\u00ec c\u1ee7a \u00f4ng r\u1ea5t ng\u1eafn,`,
  `nh\u01b0ng \u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng cho th\u1eddi k\u1ef3 Nh\u00e2n Tuy\u00ean Chi Tr\u1ecb.`,
  `Sau khi Chu Cao S\u00ed m\u1ea5t, con trai c\u1ea3 Chu Chi\u00eam C\u01a1 k\u1ebf v\u1ecb.`,
  `Chu Chi\u00eam C\u01a1 \u0111\u01b0\u1ee3c m\u1ec7nh danh l\u00e0 Ho\u00e0ng \u0111\u1ebf d\u1ebf, \u00f4ng r\u1ea5t th\u00edch ch\u01a1i d\u1ebf,`,
  `nh\u01b0ng kh\u00f4ng v\u00ec th\u1ebf m\u00e0 b\u1ecf b\u00ea vi\u1ec7c n\u01b0\u1edbc,`,
  `l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf \u01b0u t\u00fa hi\u1ebfm c\u00f3 trong l\u1ecbch s\u1eed nh\u00e0 Minh.`,
  `Trong th\u1eddi gian ch\u1ea5p ch\u00ednh, \u00f4ng gi\u1ecfi d\u00f9ng ng\u01b0\u1eddi, nghi\u00eam tr\u1ecb tham quan \u00f4 l\u1ea1i,`,
  `Th\u01b0\u01a1ng x\u00f3t b\u00e1 t\u00e1nh. Th\u1eddi \u0111\u1ea1i c\u1ee7a \u00f4ng l\u00e0 th\u1eddi k\u1ef3 ho\u00e0ng kim c\u1ee7a to\u00e0n b\u1ed9 tri\u1ec1u Minh.`,
  `\u0110\u1ea1i Minh d\u01b0\u1edbi s\u1ef1 cai tr\u1ecb c\u1ee7a \u00f4ng,`,
  `ch\u00ednh tr\u1ecb trong s\u1ea1ch, b\u00e1 t\u00e1nh an c\u01b0 l\u1ea1c nghi\u1ec7p, x\u00e3 h\u1ed9i ph\u00e1t tri\u1ec3n v\u1eefng ch\u1eafc.`,
  `Th\u1ebf nh\u01b0ng, th\u1ebf nh\u01b0ng, \u00f4ng c\u0169ng kh\u00f4ng s\u1ed1ng \u0111\u01b0\u1ee3c bao l\u00e2u,`,
  `ba m\u01b0\u01a1i t\u00e1m tu\u1ed5i \u0111ang \u1edf \u0111\u1ed9 tu\u1ed5i tr\u00e1ng ni\u00ean th\u00ec \u0111\u00e3 s\u1edbm b\u0103ng h\u00e0 v\u00ec b\u1ec7nh t\u1eadt.`,
  `Con trai c\u1ea3 c\u1ee7a \u00f4ng l\u00e0 Chu K\u1ef3 Tr\u1ea5n k\u1ebf v\u1ecb, v\u00ec cha m\u1ea5t s\u1edbm,`,
  `Chu K\u1ef3 Tr\u1ea5n khi k\u1ebf v\u1ecb m\u1edbi ch\u00edn tu\u1ed5i,`,
  `cho n\u00ean m\u1ecdi vi\u1ec7c l\u1edbn nh\u1ecf trong qu\u1ed1c gia \u0111\u1ec1u do th\u00e1i h\u1eadu v\u00e0 c\u00e1c l\u00e3o th\u1ea7n quy\u1ebft \u0111\u1ecbnh.`,
  `May m\u1eafn l\u00e0 c\u00e1c l\u00e3o th\u1ea7n n\u00e0y \u0111\u1ec1u kh\u00f4ng c\u00f3 \u00fd \u0111\u1ecbnh so\u00e1n ng\u00f4i,`,
  `cho n\u00ean tri\u1ec1u Minh th\u1eddi k\u1ef3 \u0111\u1ea7u c\u1ee7a Chu K\u1ef3 Tr\u1ea5n v\u1eabn r\u1ea5t h\u00e0i h\u00f2a.`,
  `Do kh\u00f4ng c\u00f3 vi\u1ec7c g\u00ec \u0111\u00e1ng \u0111\u1ec3 Chu K\u1ef3 Tr\u1ea5n lo l\u1eafng,`,
  `nhi\u1ec7m v\u1ee5 h\u00e0ng ng\u00e0y c\u1ee7a \u00f4ng l\u00e0 ch\u01a1i \u0111\u00f9a.`,
  `Nh\u1eefng ng\u01b0\u1eddi b\u1ea1n nh\u1ecf c\u1ee7a \u00f4ng l\u00e0 m\u1ed9t \u0111\u00e1m th\u00e1i gi\u00e1m nh\u1ecf,`,
  `c\u00f3 m\u1ed9t th\u00e1i gi\u00e1m t\u00ean V\u01b0\u01a1ng Ch\u1ea5n \u0111\u01b0\u1ee3c Chu K\u1ef3 Tr\u1ea5n y\u00eau m\u1ebfn nh\u1ea5t.`,
  `L\u00fac n\u00e0y, M\u00f4ng C\u1ed5 b\u00ean c\u1ea1nh b\u1eaft \u0111\u1ea7u r\u1ee5c r\u1ecbch.`,
  `Kh\u00f4ng l\u00e2u sau \u0111\u00f3, qu\u00e2n M\u00f4ng C\u1ed5 ti\u1ebfn v\u1ec1 ph\u00eda nam,`,
  `Th\u01b0\u1eddng th\u00ec qu\u00e2n \u0111\u1ed3n tr\u00fa c\u1ee7a nh\u00e0 Minh \u0111\u01b0\u1ee3c nu\u00f4ng chi\u1ec1u,`,
  `Kh\u00f4ng c\u00f3 kh\u1ea3 n\u0103ng chi\u1ebfn \u0111\u1ea5u, k\u1ebft qu\u1ea3 l\u00e0 b\u1ecb qu\u00e2n M\u00f4ng C\u1ed5 \u0111\u00e1nh t\u01a1i b\u1eddi,`,
  `Tin t\u1ee9c th\u1ea5t b\u1ea1i truy\u1ec1n \u0111\u1ebfn tri\u1ec1u \u0111\u00ecnh.`,
  `Chu K\u1ef3 Tr\u1ea5n r\u1ea5t lo l\u1eafng,`,
  `H\u1eafn ch\u01b0a t\u1eebng \u0111\u00e1nh tr\u1eadn v\u00e0 kh\u00f4ng bi\u1ebft ph\u1ea3i l\u00e0m g\u00ec.`,
  `V\u01b0\u01a1ng Ch\u1ea5n li\u1ec1n nh\u1ea3y ra n\u00f3i r\u1eb1ng s\u1ebd c\u00f9ng Chu K\u1ef3 Tr\u1ea5n ng\u1ef1 gi\u00e1 th\u00e2n chinh \u0111\u1ec3 \u0111\u1ed1i ph\u00f3 v\u1edbi b\u1ecdn ng\u01b0\u1eddi M\u00f4ng C\u1ed5 H\u1ed3 nh\u00e2n.`,
  `Chu K\u1ef3 Tr\u1ea5n nghe v\u1eady th\u00ec v\u1ecb huynh \u0111\u1ec7 t\u1ed1t n\u00e0y \u0111\u00e3 n\u00f3i th\u1ebf r\u1ed3i,`,
  `Th\u00ec c\u1ee9 \u0111i th\u00f4i. Th\u1ebf l\u00e0, b\u1ea5t ch\u1ea5p s\u1ef1 ph\u1ea3n \u0111\u1ed1i c\u1ee7a qu\u1ea7n th\u1ea7n,`,
  `H\u1eafn ki\u00ean quy\u1ebft d\u1eabn n\u0103m m\u01b0\u01a1i v\u1ea1n \u0111\u1ea1i qu\u00e2n th\u00e2n chinh Ng\u00f5a L\u1ea1t,`,
  `Nhi\u1ec7m v\u1ee5 qu\u00e2n s\u1ef1 \u0111\u1ec1u giao cho V\u01b0\u01a1ng Ch\u1ea5n chuy\u00ean quy\u1ec1n.`,
  `V\u01b0\u01a1ng Ch\u1ea5n l\u00e0 m\u1ed9t k\u1ebb ng\u1ed1c, h\u1eafn ch\u1ec9 gi\u1ecfi kho\u00e1c l\u00e1c,`,
  `H\u1eafn ch\u01b0a t\u1eebng \u0111\u00e1nh tr\u1eadn, h\u1eafn hi\u1ec3u g\u00ec v\u1ec1 t\u00e2n qu\u00e2n,`,
  `C\u0169ng b\u1ecb t\u00ean kh\u1ed1n n\u00e0y l\u00e0m cho ph\u1ee5c.`,
  `Qu\u00e2n Minh b\u1ecb l\u00e0m cho ng\u01b0\u1eddi ng\u1ef1a m\u1ec7t m\u1ecfi r\u00e3 r\u1eddi,`,
  `Khi \u0111\u1ebfn T\u00f4m M\u1ed9c B\u1ea3o,`,
  `qu\u00e2n M\u00f4ng C\u1ed5 nh\u00e2n c\u01a1 h\u1ed9i t\u1ea5n c\u00f4ng.`,
  `Qu\u00e2n Minh b\u1ecb \u0111\u00e1nh b\u1ea5t ng\u1edd,`,
  `th\u1ea3m b\u1ea1i, trong s\u1eed g\u1ecdi l\u00e0 S\u1ef1 bi\u1ebfn T\u00f4m M\u1ed9c B\u1ea3o.`,
  `Th\u1ea3m kh\u1ed1c \u0111\u1ebfn m\u1ee9c n\u00e0o \u01b0? Tr\u1eadn chi\u1ebfn n\u00e0y,`,
  `Minh tri\u1ec1u c\u00f3 s\u00e1u m\u01b0\u01a1i s\u00e1u v\u1ecb \u0111\u1ea1i th\u1ea7n t\u1eed tr\u1eadn,`,
  `binh l\u00ednh tinh nhu\u1ec7 to\u00e0n b\u1ed9 b\u1ecb ti\u00eau di\u1ec7t, ch\u1ec9 c\u00f2n l\u1ea1i ch\u01b0a \u0111\u1ebfn m\u01b0\u1eddi v\u1ea1n l\u00e3o binh v\u00e0 t\u00e0n binh,`,
  `h\u01a1n n\u1eefa Chu K\u1ef3 Tr\u1ea5n c\u00f2n b\u1ecb b\u1eaft l\u00e0m t\u00f9 binh.`,
  `V\u01b0\u01a1ng Ch\u1ea5n c\u0169ng kh\u00f4ng c\u00f3 k\u1ebft c\u1ee5c t\u1ed1t \u0111\u1eb9p, b\u1ecb thu\u1ed9c h\u1ea1 \u0111\u00e1nh ch\u1ebft.`,
  `Tin t\u1ee9c ho\u00e0ng \u0111\u1ebf b\u1ecb b\u1eaft l\u00e0m t\u00f9 binh truy\u1ec1n \u0111\u1ebfn,`,
  `tri\u1ec1u \u0111\u00ecnh ngay l\u1eadp t\u1ee9c n\u00e1o lo\u1ea1n.`,
  `Tuy nhi\u00ean may m\u1eafn thay, Chu K\u1ef3 Tr\u1ea5n c\u00f3 m\u1ed9t ng\u01b0\u1eddi m\u1eb9 \u0111\u00e3 \u0111\u1ea1i ngh\u0129a di\u1ec7t th\u00e2n,`,
  `ch\u01b0a \u0111\u1ee3i \u0111\u1ed1i ph\u01b0\u01a1ng \u0111\u1ebfn uy hi\u1ebfp, \u0111\u00e3 thay th\u1ebf ho\u00e0ng \u0111\u1ebf.`,
  `Kh\u00f4ng bao l\u00e2u sau khi Chu K\u1ef3 Tr\u1ea5n b\u1ecb b\u1eaft, em trai \u00f4ng l\u00e0 Chu K\u1ef3 Ng\u1ecdc \u0111\u00e3 \u0111\u01b0\u1ee3c l\u1eadp l\u00e0m ho\u00e0ng \u0111\u1ebf m\u1edbi.`,
  `Sau khi Chu K\u1ef3 Ng\u1ecdc nhanh ch\u00f3ng l\u00ean ng\u00f4i,`,
  `Quay l\u1ea1i v\u1edbi qu\u00e2n M\u00f4ng C\u1ed5.`,
  `Bi\u1ebft m\u00ecnh v\u1eeba b\u1eaft \u0111\u01b0\u1ee3c m\u1ed9t ho\u00e0ng \u0111\u1ebf,`,
  `qu\u00e2n M\u00f4ng C\u1ed5 c\u1ee9 ng\u1ee1 nh\u01b0 m\u00ecnh nh\u1eb7t \u0111\u01b0\u1ee3c b\u00e1u v\u1eadt.`,
  `N\u00e0o ng\u1edd, th\u01b0 t\u1ed1ng ti\u1ec1n c\u00f2n ch\u01b0a k\u1ecbp vi\u1ebft,`,
  `th\u00ec \u0111\u00e3 c\u00f3 tin b\u00e1o,`,
  `ngai v\u00e0ng nh\u00e0 Minh \u0111\u00e3 \u0111\u1ed5i ch\u1ee7.`,
  `Chu K\u1ef3 Tr\u1ea5n \u0111\u01b0\u1ee3c t\u00f4n l\u00e0m Th\u00e1i th\u01b0\u1ee3ng ho\u00e0ng,`,
  `\u00fd l\u00e0 Th\u00e1i th\u01b0\u1ee3ng ho\u00e0ng n\u00e0y \u0111\u00e3 v\u00f4 d\u1ee5ng r\u1ed3i,`,
  `c\u00e1c ng\u01b0\u01a1i mu\u1ed1n l\u00e0m g\u00ec th\u00ec l\u00e0m.`,
  `Qu\u00e2n M\u00f4ng C\u1ed5 su\u00fdt n\u1eefa t\u1ee9c ch\u1ebft.`,
  `Kh\u00f4ng t\u1ed1ng ti\u1ec1n \u0111\u01b0\u1ee3c th\u00ec g\u00e2y chuy\u1ec7n.`,
  `N\u1ebfu trong tri\u1ec1u \u0111\u00ecnh nh\u00e0 Minh c\u00f3 c\u1ea3 Chu K\u1ef3 Tr\u1ea5n v\u00e0 Chu K\u1ef3 D\u1ee5c c\u00f9ng l\u00e0m ho\u00e0ng \u0111\u1ebf,`,
  `th\u00ec s\u1ebd th\u1ebf n\u00e0o \u0111\u00e2y?`,
  `Ch\u1eafc l\u00e0 v\u1edbi t\u00e2m l\u00fd mu\u1ed1n xem k\u1ecbch hay ho\u1eb7c t\u00e1i s\u1eed d\u1ee5ng ng\u01b0\u1eddi v\u00f4 d\u1ee5ng.`,
  `M\u1ed9t n\u0103m sau, qu\u00e2n M\u00f4ng C\u1ed5 th\u1ea3 Chu K\u1ef3 Tr\u1ea5n v\u1ec1.`,
  `C\u00f9ng l\u00fac \u0111\u00f3,`,
  `Chu K\u1ef3 V\u0169 v\u1eeba l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf \u0111\u00e3 nghi\u1ec7n l\u00e0m vua,`,
  `Quy\u1ec1n l\u1ef1c trong tay, li\u1ec7u c\u00f3 th\u1ec3 d\u1ec5 d\u00e0ng t\u1eeb b\u1ecf?`,
  `Th\u1ebf l\u00e0, \u00f4ng ta giam l\u1ecfng Chu K\u1ef3 Tr\u1ea5n, ng\u01b0\u1eddi \u0111\u00e3 tr\u1edf v\u1ec1 B\u1eafc Kinh, trong Nam Cung.`,
  `Cu\u1ed9c giam c\u1ea7m k\u00e9o d\u00e0i b\u1ea3y n\u0103m.`,
  `\u0110\u1ec3 c\u1ee7ng c\u1ed1 ngai v\u00e0ng c\u1ee7a m\u00ecnh,`,
  `Chu K\u1ef3 V\u0169 \u0111\u00e3 l\u1eadp con trai m\u00ecnh l\u00e0m th\u00e1i t\u1eed.`,
  `Ai ng\u1edd con trai \u00f4ng ta l\u1ea1i kh\u00f4ng \u0111\u01b0\u1ee3c nh\u01b0 \u00fd, ch\u1ec9 v\u00e0i ng\u00e0y sau \u0111\u00e3 qua \u0111\u1eddi.`,
  `Kh\u00f4ng l\u00e2u sau \u0111\u00f3, Chu K\u1ef3 V\u0169 c\u0169ng l\u00e2m b\u1ec7nh.`,
  `V\u1ec1 ph\u1ea7n Chu K\u1ef3 Tr\u1ea5n, m\u1eb7c d\u00f9 b\u1ecb giam l\u1ecfng,`,
  `Nh\u1edb l\u1ea1i nh\u1eefng ng\u00e0y th\u00e1ng phong l\u01b0u khi c\u00f2n l\u00e0m ho\u00e0ng \u0111\u1ebf,`,
  `Gi\u1edd \u0111\u00e2y l\u1ea1i b\u1ecb ch\u00ednh em trai m\u00ecnh nh\u1ed1t trong c\u0103n ph\u00f2ng \u0111\u1ed5 n\u00e1t n\u00e0y,`,
  `Li\u1ec7u \u00f4ng ta c\u00f3 cam l\u00f2ng?`,
  `Th\u00eam v\u00e0o \u0111\u00f3, m\u1ed9t v\u00e0i \u0111\u1ea1i th\u1ea7n trong tri\u1ec1u \u0111\u00ecnh v\u00ec l\u1ee3i \u00edch ri\u00eang t\u01b0,`,
  `\u0110\u00e3 nh\u00e2n l\u00fac Chu K\u1ef3 V\u0169 l\u00e2m b\u1ec7nh m\u00e0 li\u00ean k\u1ebft v\u1edbi Chu K\u1ef3 Tr\u1ea5n,`,
  `l\u00e9n l\u00fat ti\u1ebfp c\u1eadn Chu K\u1ef3 Tr\u1ea5n \u1edf Nam Cung,`,
  `\u0111\u01b0a \u00f4ng ta v\u00e0o cung \u0111i\u1ec7n,`,
  `tuy\u00ean b\u1ed1 ph\u1ee5c v\u1ecb, gi\u00e1ng Chu K\u1ef3 D\u1ee5c \u0111ang b\u1ec7nh n\u1eb7ng l\u00e0m th\u00e2n v\u01b0\u01a1ng,`,
  `giam l\u1ecfng.`,
  `Kh\u00f4ng l\u00e2u sau, Chu K\u1ef3 D\u1ee5c qua \u0111\u1eddi.`,
  `Kh\u00f4ng r\u00f5 \u00f4ng ta ch\u1ebft v\u00ec b\u1ec7nh hay b\u1ecb \u00e1m s\u00e1t.`,
  `S\u1ef1 ki\u1ec7n n\u00e0y \u0111\u01b0\u1ee3c l\u1ecbch s\u1eed g\u1ecdi l\u00e0 s\u1ef1 bi\u1ebfn \u0110o\u1ea1t M\u00f4n, c\u00f2n \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 Nam Cung ph\u1ee5c v\u1ecb.`,
  `Chu K\u1ef3 D\u1ee5c tr\u1ecb v\u00ec t\u00e1m n\u0103m, khi l\u00ean ng\u00f4i, \u00f4ng ti\u1ebfp qu\u1ea3n m\u1edb h\u1ed7n \u0111\u1ed9n c\u1ee7a anh trai Chu K\u1ef3 Tr\u1ea5n,`,
  `nh\u1eadn l\u1ec7nh trong l\u00fac nguy c\u1ea5p. \u00d4ng \u0111\u00e3 ch\u1ed1ng l\u1ea1i m\u1ed9t \u0111\u1ee3t t\u1ea5n c\u00f4ng n\u1eefa c\u1ee7a Oa L\u1ea1t,`,
  `gi\u1eef v\u1eefng B\u1eafc Kinh.`,
  `Trong th\u1eddi gian\u6267\u653f, \u00f4ng tr\u1ecdng d\u1ee5ng hi\u1ec1n th\u1ea7n, duy tr\u00ec s\u1ef1 \u1ed5n \u0111\u1ecbnh ch\u00ednh tr\u1ecb c\u1ee7a nh\u00e0 Minh.`,
  `T\u1ea5t c\u1ea3 nh\u1eefng \u0111i\u1ec1u n\u00e0y \u0111\u1ec1u l\u00e0 c\u00f4ng lao kh\u00f4ng th\u1ec3 ph\u1ee7 nh\u1eadn.`,
  `Sau khi Chu K\u1ef3 Tr\u1ea5n m\u1ed9t l\u1ea7n n\u1eefa l\u00ean ng\u00f4i ho\u00e0ng \u0111\u1ebf, \u00f4ng c\u00f2n gi\u1ebft \u0111\u1ea1i trung th\u1ea7n Vu Khi\u00eam,`,
  `v\u00ec Vu Khi\u00eam l\u00e0 th\u1ee7 h\u1ea1 \u0111\u1eafc l\u1ef1c nh\u1ea5t c\u1ee7a Chu K\u1ef3 D\u1ee5c.`,
  `Tuy nhi\u00ean, vi\u1ec7c gi\u1ebft Vu Khi\u00eam qu\u1ea3 th\u1ef1c l\u00e0 v\u1ebft nh\u01a1 trong cu\u1ed9c \u0111\u1eddi Chu K\u1ef3 Tr\u1ea5n.`,
  `Chu K\u1ef3 Tr\u1ea5n \u1edf ng\u00f4i t\u1ed5ng c\u1ed9ng 22 n\u0103m.`,
  `C\u00f3 l\u1ebd \u0111\u00e3 tr\u1ea3i qua qu\u00e1 nhi\u1ec1u gian nan, c\u1ea3nh gi\u1edbi th\u0103ng hoa,`,
  `Tr\u01b0\u1edbc khi l\u00e2m chung, \u00f4ng \u0111\u00e3 l\u00e0m m\u1ed9t vi\u1ec7c t\u1ed1t,`,
  `B\u00e3i b\u1ecf ch\u1ebf \u0111\u1ed9 tu\u1eabn t\u00e1ng phi t\u1ea7n c\u00f3 t\u1eeb th\u1eddi Chu Nguy\u00ean Ch\u01b0\u01a1ng trong tri\u1ec1u Minh.`,
  `Sau \u0111\u00f3, Anh T\u00f4ng Chu K\u1ef3 Tr\u1ea5n, 38 tu\u1ed5i, t\u1eeb gi\u00e3 c\u00f5i \u0111\u1eddi.`,
  `Sau khi Chu K\u1ef3 Tr\u1ea5n qua \u0111\u1eddi v\u00ec b\u1ec7nh, con trai \u00f4ng l\u00e0 Chu Ki\u1ebfn Sinh k\u1ebf v\u1ecb.`,
  `Chu Ki\u1ebfn Sinh tr\u1ecb v\u00ec khoan dung nh\u00e2n h\u1eadu, \u0111\u00e3 minh oan cho Vu Khi\u00eam.`,
  `\u00d4ng gi\u1ea3m thu\u1ebf, x\u00e3 h\u1ed9i \u1ed5n \u0111\u1ecbnh, nh\u01b0ng \u0111\u1ed3ng th\u1eddi \u00f4ng c\u0169ng tr\u1ecdng d\u1ee5ng k\u1ebb gian t\u00e0,`,
  `Tri\u1ec1u ch\u00ednh c\u00f3 d\u1ea5u hi\u1ec7u tham nh\u0169ng.`,
  `N\u00f3i chung, c\u0169ng b\u00ecnh th\u01b0\u1eddng th\u00f4i.`,
  `Qua \u0111\u1eddi v\u00ec b\u1ec7nh n\u0103m 41 tu\u1ed5i,`,
  `Con trai \u00f4ng l\u00e0 Hi\u1ebfu Trung Chu Nh\u1ee5c \u0110\u01b0\u1eddng k\u1ebf v\u1ecb.`,
  `Chu Nh\u1ee5c \u0110\u01b0\u1eddng r\u1ea5t t\u1ed1t, th\u1ef1c s\u1ef1 r\u1ea5t t\u1ed1t,`,
  `V\u00e0o th\u1eddi \u0111i\u1ec3m nh\u00e0 Minh s\u1eafp suy t\u00e0n, \u00f4ng \u0111\u00e3 xoay chuy\u1ec3n c\u1ee5c di\u1ec7n,`,
  `C\u1ed1 g\u1eafng thay \u0111\u1ed5i t\u00ecnh tr\u1ea1ng tham nh\u0169ng trong tri\u1ec1u ch\u00ednh th\u1eddi cha \u00f4ng l\u00e0 Hi\u1ebfn Trung.`,
  `Xua \u0111u\u1ed5i gian th\u1ea7n, chuy\u00ean t\u00e2m ch\u00ednh s\u1ef1, d\u1ed1c l\u00f2ng cai tr\u1ecb,`,
  `khi\u1ebfn nh\u00e0 Minh m\u1ed9t l\u1ea7n n\u1eefa ph\u00e1t tri\u1ec3n th\u00e0nh th\u1eddi th\u1ecbnh tr\u1ecb.`,
  `H\u01a1n n\u1eefa, \u0111i\u1ec1u \u0111\u00e1ng qu\u00fd h\u01a1n l\u00e0,`,
  `c\u1ea3 \u0111\u1eddi \u00f4ng ch\u1ec9 c\u01b0\u1edbi duy nh\u1ea5t m\u1ed9t Tr\u01b0\u01a1ng ho\u00e0ng h\u1eadu,`,
  `hai ng\u01b0\u1eddi t\u00ecnh ngh\u0129a phu th\u00ea s\u00e2u n\u1eb7ng, tr\u1edf th\u00e0nh v\u1ecb ho\u00e0ng \u0111\u1ebf duy nh\u1ea5t trong l\u1ecbch s\u1eed Trung Qu\u1ed1c c\u1ea3 \u0111\u1eddi ch\u1ec9 l\u1ea5y m\u1ed9t v\u1ee3.`,
  `V\u00ec Chu Nh\u1ee5c \u0110\u01b0\u1eddng ch\u1ec9 c\u00f3 duy nh\u1ea5t Tr\u01b0\u01a1ng ho\u00e0ng h\u1eadu l\u00e0 v\u1ee3,`,
  `Tr\u01b0\u01a1ng ho\u00e0ng h\u1eadu sinh hai ng\u01b0\u1eddi con trai,`,
  `ng\u01b0\u1eddi con trai \u00fat m\u1ea5t t\u1eeb khi c\u00f2n r\u1ea5t nh\u1ecf.`,
  `V\u00ec v\u1eady, sau n\u00e0y Chu Nh\u1ee5c \u0110\u01b0\u1eddng truy\u1ec1n ng\u00f4i cho con trai \u0111\u1ed9c nh\u1ea5t c\u1ee7a m\u00ecnh l\u00e0 Chu H\u1eadu T\u00e1o.`,
  `V\u00ec l\u00e0 con m\u1ed9t,`,
  `Chu H\u1eadu T\u00e1o t\u1eeb nh\u1ecf \u0111\u00e3 \u0111\u01b0\u1ee3c nu\u00f4ng chi\u1ec1u, n\u00ean t\u00ednh c\u00e1ch kh\u00e1 \u0111\u1ed9c \u0111\u00e1o,`,
  `kh\u00f4ng l\u00e0m theo l\u1ebd th\u01b0\u1eddng.`,
  `Sau khi l\u00ean ng\u00f4i, d\u01b0\u1edbi s\u1ef1 d\u1eabn d\u1eaft c\u1ee7a th\u00e1i gi\u00e1m L\u01b0u C\u1ea9n, \u0111\u00e3 l\u00e0m r\u1ea5t nhi\u1ec1u chuy\u1ec7n hoang \u0111\u01b0\u1eddng.`,
  `\u00d4ng th\u00edch cosplay, b\u1eaft ch\u01b0\u1edbc ch\u1ee3 b\u00faa trong cung, x\u00e2y d\u1ef1ng nhi\u1ec1u c\u1eeda h\u00e0ng,`,
  `nh\u00e0 th\u1ed5, b\u1eaft th\u00e1i gi\u00e1m cung n\u1eef \u0111\u00f3ng gi\u1ea3 g\u00e1i l\u1ea7u xanh v\u00e0 ch\u1ee7 qu\u00e1n.`,
  `khi\u1ebfn tri\u1ec1u \u0111\u00ecnh h\u1ed7n lo\u1ea1n.`,
  `C\u00f2n L\u01b0u C\u1ea9n x\u00e2y m\u1ed9t B\u00e1o Ph\u00f2ng \u0111\u1ec3 nu\u00f4i th\u00fa v\u1eadt,`,
  `nu\u00f4i m\u1ef9 n\u1eef, t\u1ea5t c\u1ea3 ti\u1ec1n b\u1ea1c t\u1ecbch thu \u0111\u01b0\u1ee3c trong c\u1ea3 n\u01b0\u1edbc \u0111\u1ec1u c\u1ea5t gi\u1eef trong B\u00e1o Ph\u00f2ng.`,
  `\u0110i\u1ec1u n\u00e0y gi\u1ed1ng nh\u01b0 m\u1ed9t kho b\u1ea1c nh\u1ecf c\u1ee7a Chu H\u1eadu Chi\u1ebfu.`,
  `Khi trong cung \u0111i\u1ec7n \u0111\u00e3 h\u1ed7n lo\u1ea1n nh\u01b0 v\u1eady r\u1ed3i,`,
  `Chu H\u1eadu Chi\u1ebfu v\u1eabn kh\u00f4ng th\u1ec3 ng\u1ed3i y\u00ean,`,
  `l\u1ea1i b\u1eaft \u0111\u1ea7u n\u00f3ng l\u00f2ng mu\u1ed1n ra ngo\u00e0i \u0111\u00e1nh tr\u1eadn.`,
  `C\u00f3 m\u1ed9t n\u0103m, Giang Nam c\u00f3 ng\u01b0\u1eddi l\u00e0m lo\u1ea1n, \u00f4ng ta c\u1ee9 \u0111\u00f2i \u0111\u00edch th\u00e2n \u0111i tr\u1ea5n \u00e1p.`,
  `Kh\u00f4ng ng\u1edd qu\u00e2n \u0111\u1ed9i v\u1eeba \u0111i \u0111\u01b0\u1ee3c n\u1eeda \u0111\u01b0\u1eddng, ti\u1ec1n tuy\u1ebfn \u0111\u00e3 b\u00e1o v\u1ec1,`,
  `lo\u1ea1n \u0111\u00e3 d\u1eb9p y\u00ean.`,
  `Chu H\u1eadu Chi\u1ebfu th\u1eadm ch\u00ed th\u1ea3 t\u00ean ph\u1ea3n th\u1ea7n \u0111\u00f3,`,
  `r\u1ed3i \u0111\u00edch th\u00e2n b\u1eaft l\u1ea1i h\u1eafn,`,
  `sau \u0111\u00f3 t\u1ed5 ch\u1ee9c y\u1ebfn ti\u1ec7c \u0103n m\u1eebng chi\u1ebfn th\u1eafng c\u1ee7a m\u00ecnh.`,
  `B\u1ea1n n\u00f3i h\u1eafn c\u00f3 l\u1eadp d\u1ecb kh\u00f4ng?`,
  `Chu H\u1eadu Chi\u1ebfu \u0111\u00e3 l\u00e0m ho\u00e0ng \u0111\u1ebf m\u01b0\u1eddi s\u00e1u n\u0103m v\u1edbi tinh th\u1ea7n th\u00edch \u0111\u00f9a gi\u1ee1n nh\u01b0 v\u1eady.`,
  `N\u0103m 31 tu\u1ed5i, \u00f4ng l\u00e2m b\u1ec7nh m\u1ea5t t\u1ea1i B\u00e1o Ph\u00f2ng.`,
  `D\u00f9 h\u01b0\u1edfng l\u1ea1c c\u1ea3 \u0111\u1eddi, khi ch\u1ebft l\u1ea1i kh\u00f4ng c\u00f3 con trai.`,
  `V\u00ec v\u1eady, ch\u1ec9 c\u00f3 th\u1ec3 ch\u1ecdn \u0111\u01b0\u1eddng \u0111\u1ec7 Chu H\u1eadu Th\u00f4ng, con trai c\u1ee7a ch\u00fa \u00f4ng, phi\u00ean v\u01b0\u01a1ng Chu Nguy\u00ean H\u1eefu, l\u00ean k\u1ebf v\u1ecb.`,
  `Th\u1eddi k\u1ef3 \u0111\u1ea7u, Chu H\u1eadu Th\u00f4ng kh\u00e1 n\u0103ng n\u1ed5, qu\u1ea3n l\u00fd \u0111\u1ea5t n\u01b0\u1edbc m\u1ed9t c\u00e1ch quy c\u1ee7.`,
  `Nh\u01b0ng sau \u0111\u00f3 \u0111\u00e3 n\u1ea3y sinh tranh ch\u1ea5p v\u1edbi c\u00e1c \u0111\u1ea1i th\u1ea7n trong tri\u1ec1u.`,
  `Nguy\u00ean nh\u00e2n c\u1ee5 th\u1ec3 l\u00e0 Chu H\u1eadu Th\u00f4ng mu\u1ed1n truy t\u00f4n cha m\u00ecnh l\u00e0m Ho\u00e0ng \u0111\u1ebf.`,
  `Tuy nhi\u00ean, cha \u00f4ng l\u00e0 phi\u00ean v\u01b0\u01a1ng, n\u00ean c\u00e1c \u0111\u1ea1i th\u1ea7n \u0111\u1ee9ng \u0111\u1ea7u l\u00e0 V\u01b0\u01a1ng \u0110\u00ecnh H\u00f2a kh\u00f4ng \u0111\u1ed3ng \u00fd.`,
  `\u0110i\u1ec1u n\u00e0y tho\u1ea1t nh\u00ecn c\u00f3 v\u1ebb l\u00e0 m\u1ed9t v\u1ee5 truy t\u00f4n \u0111\u01a1n gi\u1ea3n,`,
  `nh\u01b0ng th\u1ef1c ch\u1ea5t l\u00e0 xung \u0111\u1ed9t l\u1ee3i \u00edch gi\u1eefa ph\u00e1i c\u1ea3i c\u00e1ch v\u00e0 ph\u00e1i b\u1ea3o th\u1ee7.`,
  `V\u00ec v\u1eady, s\u1ef1 vi\u1ec7c n\u00e0y k\u00e9o d\u00e0i su\u1ed1t 20 n\u0103m,`,
  `s\u1eed g\u1ecdi l\u00e0 \u0110\u1ea1i l\u1ec5 nghi.`,
  `Sau khi \u0110\u1ea1i l\u1ec5 nghi k\u1ebft th\u00fac,`,
  `nhi\u1ec7t huy\u1ebft mu\u1ed1n l\u00e0m m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf t\u1ed1t c\u1ee7a Chu H\u1eadu Th\u00f4ng khi m\u1edbi l\u00ean ng\u00f4i \u0111\u00e3 ho\u00e0n to\u00e0n ti\u00eau tan.`,
  `\u00d4ng b\u1eaft \u0111\u1ea7u tin v\u00e0o \u0110\u1ea1o gi\u00e1o,`,
  `v\u00ec mu\u1ed1n tr\u01b0\u1eddng sinh b\u1ea5t t\u1eed, \u0111\u00e3 nghe theo m\u1ed9t \u0111\u1ea1o s\u0129 v\u1ec1 m\u1ed9t ph\u01b0\u01a1ng thu\u1ed1c b\u00ed truy\u1ec1n.`,
  `C\u1ea7n l\u1ea5y m\u00e1u trinh n\u1eef l\u00e0m thu\u1ed1c.`,
  `\u0110\u1ec3 gi\u1eef cho nh\u1eefng cung n\u1eef d\u00f9ng l\u00e0m thu\u1ed1c n\u00e0y \u0111\u01b0\u1ee3c trong s\u1ea1ch,`,
  `h\u1ecd kh\u00f4ng \u0111\u01b0\u1ee3c \u0103n c\u01a1m, ch\u1ec9 \u0111\u01b0\u1ee3c \u0103n m\u1ed9t \u00edt l\u00e1 d\u00e2u t\u1eb1m,`,
  `u\u1ed1ng m\u1ed9t \u00edt n\u01b0\u1edbc, v\u00e0 th\u01b0\u1eddng xuy\u00ean b\u1ecb b\u1ea1o h\u00e0nh.`,
  `S\u1ed1 cung n\u1eef b\u1ecb gi\u00e0y v\u00f2 \u0111\u1ebfn ch\u1ebft kh\u00f4ng ph\u1ea3i \u00edt.`,
  `\u0110i\u1ec1u n\u00e0y c\u00f2n g\u1ecdi l\u00e0 g\u00ec n\u1eefa?`,
  `Cu\u1ed1i c\u00f9ng \u0111\u00e3 d\u1eabn \u0111\u1ebfn m\u1ed9t cu\u1ed9c binh bi\u1ebfn cung \u0111\u00ecnh hi\u1ebfm th\u1ea5y trong l\u1ecbch s\u1eed.`,
  `M\u01b0\u1eddi s\u00e1u cung n\u1eef l\u1ee3i d\u1ee5ng l\u00fac Chu H\u1eadu Chi\u1ebfu ng\u1ee7 say,`,
  `d\u00f9ng d\u00e2y th\u1eebng mu\u1ed1n si\u1ebft ch\u1ebft \u00f4ng ta.`,
  `C\u00f3 th\u1ec3 do qu\u00e1 c\u0103ng th\u1eb3ng,`,
  `Chu H\u1eadu Chi\u1ebfu b\u1ecb si\u1ebft ng\u1ea5t \u0111i, nh\u01b0ng kh\u00f4ng ch\u1ebft.`,
  `Ho\u00e0ng h\u1eadu Ph\u01b0\u01a1ng sau khi bi\u1ebft tin, li\u1ec1n nhanh ch\u00f3ng ch\u1ea1y \u0111\u1ebfn,`,
  `c\u1ee9u Chu H\u1eadu Chi\u1ebfu m\u1ed9t m\u1ea1ng, t\u1ea5t c\u1ea3 cung n\u1eef l\u00e0m lo\u1ea1n \u0111\u1ec1u b\u1ecb x\u1eed t\u1eed.`,
  `N\u0103m \u0111\u00f3 tr\u00f9ng v\u1edbi n\u0103m Nh\u00e2m D\u1ea7n c\u1ee7a Gia T\u0129nh,`,
  `s\u1eed g\u1ecdi l\u00e0 Nh\u00e2m D\u1ea7n cung bi\u1ebfn.`,
  `Chu H\u1eadu Chi\u00eau c\u00f3 l\u1ebd b\u1ecb d\u1ecda s\u1ee3, t\u1eeb \u0111\u00f3 v\u1ec1 sau kh\u00f4ng c\u00f2n \u1edf tri\u1ec1u L\u00fd n\u1eefa,`,
  `qua \u0111\u1eddi \u1edf tu\u1ed5i s\u00e1u m\u01b0\u01a1i.`,
  `M\u1eb7c d\u00f9 Gia T\u0129nh \u0110\u1ebf Chu H\u1eadu Chi\u00eau d\u00e0nh ph\u1ea7n l\u1edbn cu\u1ed9c \u0111\u1eddi \u0111\u1ec3 tu ti\u00ean,`,
  `nh\u01b0ng th\u1ef1c ra \u00f4ng c\u0169ng kh\u00e1 t\u00e0i gi\u1ecfi.`,
  `Th\u1eddi k\u1ef3 \u0111\u1ea7u, \u00f4ng \u0111\u00e3 l\u00e0m nhi\u1ec1u vi\u1ec7c l\u1edbn c\u00f3 \u00edch cho \u0111\u1ea5t n\u01b0\u1edbc,`,
  `th\u00fac \u0111\u1ea9y t\u00e2n ch\u00ednh, t\u0103ng c\u01b0\u1eddng quy\u1ec1n l\u1ef1c t\u1eadp trung c\u1ee7a tri\u1ec1u \u0111\u00ecnh.`,
  `Hai m\u01b0\u01a1i n\u0103m cu\u1ed1i \u0111\u1eddi kh\u00f4ng l\u00ean tri\u1ec1u, v\u1eady m\u00e0 v\u1eabn n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c l\u1edbn trong tri\u1ec1u \u0111\u00ecnh.`,
  `Nh\u01b0ng \u0111\u1ed3ng th\u1eddi, hai m\u01b0\u01a1i n\u0103m n\u00e0y c\u0169ng l\u00e0 th\u1eddi k\u1ef3 bi\u00ean gi\u1edbi nh\u00e0 Minh g\u1eb7p nguy hi\u1ec3m nh\u1ea5t,`,
  `tri\u1ec1u \u0111\u1ea1i nh\u00e0 Minh \u0111\u00e3 ng\u00e0y c\u00e0ng suy y\u1ebfu.`,
  `Sau khi Chu H\u1eadu Chi\u00eau qua \u0111\u1eddi, con trai \u00f4ng l\u00e0 Chu T\u00e1i H\u1eadu k\u1ebf v\u1ecb.`,
  `Chu T\u00e1i H\u1eadu n\u0103ng l\u1ef1c trung b\u00ecnh, nh\u01b0ng \u00f4ng l\u1ea1i g\u1eb7p may m\u1eafn \u0111\u1eb7c bi\u1ec7t.`,
  `Th\u1eddi \u0111\u1ea1i c\u1ee7a \u00f4ng c\u00f3 r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi t\u00e0i gi\u1ecfi v\u00e0 hi\u1ec1n th\u1ea7n,`,
  `v\u00e0 \u00f4ng c\u0169ng r\u1ea5t bi\u1ebft d\u00f9ng ng\u01b0\u1eddi,`,
  `tr\u1ecdng d\u1ee5ng c\u00e1c danh th\u1ea7n nh\u01b0 Tr\u01b0\u01a1ng C\u01b0 Ch\u00ednh, Cao C\u1ee7ng,...`,
  `c\u1ea3i c\u00e1ch tri\u1ec1u ch\u00ednh, b\u00e3i b\u1ecf l\u1ec7nh c\u1ea5m bi\u1ec3n,`,
  `cho ph\u00e9p bu\u00f4n b\u00e1n v\u1edbi n\u01b0\u1edbc ngo\u00e0i,`,
  `ngo\u1ea1i th\u01b0\u01a1ng ph\u00e1t tri\u1ec3n nhanh ch\u00f3ng,`,
  `t\u1ea1o n\u00ean c\u1ee5c di\u1ec7n m\u1edf c\u1eeda to\u00e0n di\u1ec7n.`,
  `V\u00ec v\u1eady, trong th\u1eddi gian \u00f4ng t\u1ea1i v\u1ecb, Trung Qu\u1ed1c \u0111\u00e3 ki\u1ebfm \u0111\u01b0\u1ee3c r\u1ea5t nhi\u1ec1u b\u1ea1c tr\u1eafng.`,
  `Nh\u01b0ng \u00f4ng c\u00f3 m\u1ed9t nh\u01b0\u1ee3c \u0111i\u1ec3m ch\u00ed m\u1ea1ng,`,
  `\u0111\u00f3 l\u00e0 ham m\u00ea n\u1eef s\u1eafc. T\u1ea1i sao l\u1ea1i n\u00f3i l\u00e0 ch\u00ed m\u1ea1ng?`,
  `B\u1edfi v\u00ec \u00f4ng h\u00e0ng ng\u00e0y ch\u00ecm \u0111\u1eafm trong d\u1ee5c v\u1ecdng,`,
  `s\u1ee9c kh\u1ecfe ng\u00e0y c\u00e0ng xu\u1ed1ng d\u1ed1c,`,
  `ch\u1ec9 t\u1ea1i v\u1ecb s\u00e1u n\u0103m r\u1ed3i qua \u0111\u1eddi.`,
  `Con trai Chu D\u1ef1c Qu\u00e2n k\u1ebf v\u1ecb, t\u1ee9c l\u00e0 V\u1ea1n L\u1ecbch \u0111\u1ebf.`,
  `B\u1edfi v\u00ec cha m\u1ea5t s\u1edbm, l\u00fac \u00f4ng k\u1ebf v\u1ecb m\u1edbi m\u01b0\u1eddi tu\u1ed5i,`,
  `vi\u1ec7c tri\u1ec1u ch\u00ednh c\u01a1 b\u1ea3n do Tr\u01b0\u01a1ng C\u01b0 Ch\u00ednh thay quy\u1ec1n.`,
  `Tr\u01b0\u01a1ng C\u01b0 Ch\u00ednh \u0111\u01b0\u1ee3c m\u1ec7nh danh l\u00e0 m\u1ed9t trong nh\u1eefng N\u1ed9i c\u00e1c Th\u1ee7 ph\u1ee5 xu\u1ea5t s\u1eafc nh\u1ea5t l\u1ecbch s\u1eed Trung Qu\u1ed1c,`,
  `l\u00e0 nh\u00e0 c\u1ea3i c\u00e1ch v\u0129 \u0111\u1ea1i nh\u1ea5t tri\u1ec1u Minh.`,
  `Ch\u1ec9 c\u1ea7n nghe nh\u1eefng danh hi\u1ec7u n\u00e0y c\u0169ng bi\u1ebft Tr\u01b0\u01a1ng C\u01b0 Ch\u00ednh r\u1ea5t l\u1ee3i h\u1ea1i.`,
  `D\u01b0\u1edbi s\u1ef1 ph\u00f2 t\u00e1 c\u1ee7a \u00f4ng \u1ea5y,`,
  `m\u01b0\u1eddi n\u0103m \u0111\u1ea7u th\u1eddi V\u1ea1n L\u1ecbch nh\u01b0 \u0111\u01b0\u1ee3c ti\u00eam m\u1ed9t li\u1ec1u thu\u1ed1c h\u1ed3i sinh,`,
  `gi\u00fap tri\u1ec1u Minh \u0111ang suy t\u00e0n c\u00f3 c\u01a1 h\u1ed9i th\u1edf ph\u00e0o nh\u1eb9 nh\u00f5m.`,
  `Tuy nhi\u00ean, \u0111\u00e2y c\u0169ng l\u00e0 l\u1ea7n h\u1ed3i quang ph\u1ea3n chi\u1ebfu cu\u1ed1i c\u00f9ng.`,
  `Sau khi Tr\u01b0\u01a1ng C\u01b0 Ch\u00ednh m\u1ea5t,`,
  `Chu D\u1ef1c Qu\u00e2n b\u1eaft \u0111\u1ea7u t\u1ef1 sa \u0111\u1ecda,`,
  `th\u00f4ng th\u1ea1o t\u1eedu s\u1eafc t\u00e0i kh\u00ed (r\u01b0\u1ee3u ch\u00e8, g\u00e1i g\u00fa, ti\u1ec1n b\u1ea1c, n\u00f3ng n\u1ea3y),`,
  `tri\u1ec1u ch\u00ednh ho\u00e0n to\u00e0n b\u1ecb hoang ph\u1ebf.`,
  `Su\u1ed1t hai m\u01b0\u01a1i t\u00e1m n\u0103m kh\u00f4ng l\u00e2m tri\u1ec1u,`,
  `c\u00f3 v\u1ecb ho\u00e0ng \u0111\u1ebf nh\u01b0 v\u1eady, \u0111\u1ea5t n\u01b0\u1edbc l\u00e0m sao c\u00f3 th\u1ec3 t\u1ed1t \u0111\u1eb9p \u0111\u01b0\u1ee3c?`,
  `D\u00e2n ch\u00fang ph\u1ea3i ch\u1ecbu s\u1ef1 \u00e1p b\u1ee9c c\u1ee7a quan l\u1ea1i, l\u1ea1i th\u00eam h\u1ebft l\u0169 l\u1ee5t \u0111\u1ebfn h\u1ea1n h\u00e1n,`,
  `h\u1ebft h\u1ea1n h\u00e1n l\u1ea1i \u0111\u1ebfn n\u1ea1n ch\u00e2u ch\u1ea5u.`,
  `Gi\u1eefa l\u00fac trong n\u01b0\u1edbc lo\u1ea1n th\u00e0nh m\u1ed9t n\u1ed3i ch\u00e1o,`,
  `N\u1ed7 Nh\u0129 C\u00e1p X\u00edch \u0111\u00e3 th\u1ed1ng nh\u1ea5t c\u00e1c b\u1ed9 n\u1eef ch\u00e2n,`,
  `th\u00e0nh l\u1eadp ch\u00ednh quy\u1ec1n H\u1eadu Kim.`,
  `Kh\u00f4ng l\u00e2u sau \u0111\u00f3, qu\u00e2n Kim \u0111\u00e3 nam h\u1ea1 \u0111\u00e1nh Minh.`,
  `L\u00fac n\u00e0y, qu\u1ed1c kh\u1ed1 \u0111\u00e3 b\u1ecb Chu D\u1ef1c Qu\u00e2n v\u00e9t s\u1ea1ch,`,
  `l\u1ea5y \u0111\u00e2u ra ti\u1ec1n \u0111\u1ec3 \u0111\u00e1nh gi\u1eb7c?`,
  `\u0110\u01b0\u01a1ng nhi\u00ean, ng\u00e2n kh\u1ed1 ri\u00eang c\u1ee7a Chu D\u1ef1c Qu\u00e2n th\u00ec kh\u00f4ng thi\u1ebfu ti\u1ec1n,`,
  `nh\u01b0ng \u00f4ng ta kh\u00f4ng n\u1ee1 b\u1ecf ti\u1ec1n t\u00fai.`,
  `N\u00e0y, ch\u1eb3ng l\u1ebd qu\u1ed1c gia kh\u00f4ng ph\u1ea3i c\u1ee7a \u00f4ng ta sao?`,
  `Th\u1ebf l\u00e0 \u00f4ng ta ngh\u0129 ra m\u1ed9t chi\u00eau t\u00e0n \u0111\u1ed9c,`,
  `t\u0103ng thu\u1ebf, b\u1eaft d\u00e2n ch\u00fang ph\u1ea3i g\u00e1nh ch\u1ecbu.`,
  `\u0110\u00e2y c\u00f2n ch\u01b0a ph\u1ea3i l\u00e0 t\u1ed3i t\u1ec7 nh\u1ea5t,`,
  `m\u1ed9t n\u1eeda s\u1ed1 thu\u1ebf thu \u0111\u01b0\u1ee3c l\u1ea1i ch\u1ea3y v\u00e0o ng\u00e2n kh\u1ed1 ri\u00eang c\u1ee7a Chu D\u1ef1c Qu\u00e2n.`,
  `Trong t\u00ecnh hu\u1ed1ng n\u00e0y,`,
  `\u0111\u1ed9i qu\u00e2n ch\u1eafp v\u00e1 \u0111i \u0111\u1ed1i \u0111\u1ea7u v\u1edbi qu\u00e2n Kim c\u1ee7a N\u1ed7 Nh\u0129 C\u00e1p X\u00edch,`,
  `ch\u1eb3ng ph\u1ea3i l\u00e0 t\u00ecm ch\u1ebft sao?`,
  `Qu\u1ea3 nhi\u00ean, qu\u00e2n Minh \u0111\u1ea1i b\u1ea1i,`,
  `sau \u0111\u00f3 th\u1ef1c l\u1ef1c c\u1ee7a qu\u00e2n Minh gi\u1ea3m s\u00fat nghi\u00eam tr\u1ecdng,`,
  `Bi k\u1ecbch m\u1ea5t n\u01b0\u1edbc c\u1ee7a nh\u00e0 Minh \u0111\u00e3 b\u1eaft \u0111\u1ea7u.`,
  `Chu D\u1ef1c Qu\u00e2n t\u1ea1i v\u1ecb 48 n\u0103m, sau khi l\u00e0m c\u1ea1n ki\u1ec7t c\u1ea3 b\u1ea3n th\u00e2n v\u00e0 qu\u1ed1c gia th\u00ec \u0111i g\u1eb7p t\u1ed5 ti\u00ean,`,
  `Con tr\u01b0\u1edfng Chu Th\u01b0\u1eddng L\u1ea1c k\u1ebf v\u1ecb.`,
  `Chu Th\u01b0\u1eddng L\u1ea1c mu\u1ed1n ra s\u1ee9c ph\u00e1t huy t\u00e0i n\u0103ng,`,
  `\u0110\u01b0a nh\u00e0 Minh tr\u1edf l\u1ea1i \u0111\u00fang qu\u1ef9 \u0111\u1ea1o, nh\u01b0ng \u00f4ng ta m\u1edbi k\u1ebf v\u1ecb m\u01b0\u1eddi ng\u00e0y \u0111\u00e3 l\u00e2m b\u1ec7nh,`,
  `V\u00e0 m\u1ed9t th\u00e1ng sau th\u00ec b\u1ec7nh ch\u1ebft.`,
  `Con trai \u00f4ng l\u00e0 Chu Do Ki\u1ec3m k\u1ebf v\u1ecb,`,
  `Chu Do Ki\u1ec3m th\u00edch l\u00e0m m\u1ed9c, t\u01b0\u01a1ng truy\u1ec1n t\u00e0i ngh\u1ec7 l\u00e0m m\u1ed9c c\u1ee7a \u00f4ng \u0111\u00e3 \u0111\u1ea1t \u0111\u1ebfn tr\u00ecnh \u0111\u1ed9 c\u1ee7a b\u1eadc \u0111\u1ea1i th\u1ea7n.`,
  `V\u00ec \u0111am m\u00ea l\u00e0m m\u1ed9c m\u00e0 b\u1ecf b\u00ea tri\u1ec1u ch\u00ednh,`,
  `\u0110\u1ea1i quy\u1ec1n trong tri\u1ec1u b\u1ecb v\u00fa nu\u00f4i c\u1ee7a Chu Do Ki\u1ec3m l\u00e0 Kh\u1eafc th\u1ecb v\u00e0 \u0111\u1ea1i th\u00e1i gi\u00e1m Ng\u1ee5y Trung Hi\u1ec1n n\u1eafm gi\u1eef.`,
  `Hai ng\u01b0\u1eddi n\u00e0y c\u1ea5u k\u1ebft v\u1edbi nhau, ra s\u1ee9c \u0111\u00e0n \u00e1p nh\u1eefng ng\u01b0\u1eddi \u0111\u1ed1i l\u1eadp,`,
  `H\u00e3m h\u1ea1i trung l\u01b0\u01a1ng. Sau khi Ng\u1ee5y Trung Hi\u1ec1n v\u00e0 phe ho\u1ea1n quan chuy\u00ean quy\u1ec1n,`,
  `Cu\u1ed9c s\u1ed1ng c\u1ee7a tr\u0103m h\u1ecd c\u00e0ng th\u00eam l\u1ea7m than,`,
  `C\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a ng\u00e0y c\u00e0ng nhi\u1ec1u.`,
  `Sau b\u1ea3y n\u0103m tr\u1ecb v\u00ec c\u1ee7a Chu Do Ki\u1ec3m,`,
  `M\u1ed9t l\u1ea7n kh\u00f4ng may r\u01a1i xu\u1ed1ng n\u01b0\u1edbc, \u00f4ng ng\u00e3 b\u1ec7nh.`,
  `\u0110\u1ec3 ch\u1eefa b\u1ec7nh, \u00f4ng c\u00f2n u\u1ed1ng m\u1ed9t lo\u1ea1i ti\u00ean \u0111an.`,
  `Ti\u00ean \u0111an th\u1eddi x\u01b0a \u1ea5y m\u00e0, u\u1ed1ng v\u00e0i th\u00e1ng sau th\u00ec ch\u1ebft.`,
  `M\u1edbi hai m\u01b0\u01a1i ba tu\u1ed5i, kh\u00f4ng c\u00f3 con n\u1ed1i d\u00f5i.`,
  `Em trai \u00f4ng l\u00e0 Chu Do Ki\u1ec3m l\u00ean ng\u00f4i, t\u1ee9c l\u00e0 vua S\u00f9ng Trinh.`,
  `Khi S\u00f9ng Trinh \u0110\u1ebf l\u00ean ng\u00f4i, giang s\u01a1n \u0110\u1ea1i Minh \u0111\u00e3 tan hoang.`,
  `M\u1eb7c d\u00f9 sau khi k\u1ebf v\u1ecb, \u00f4ng \u0111\u00e3 n\u1eafm b\u1eaft c\u01a1 h\u1ed9i nhanh ch\u00f3ng ti\u00eau di\u1ec7t b\u00e8 \u0111\u1ea3ng Ng\u1ee5y Trung Hi\u1ec1n,`,
  `Tr\u1eeb b\u1ecf c\u00e1c th\u00e1i gi\u00e1m chuy\u00ean quy\u1ec1n,`,
  `Nh\u01b0ng sau \u0111\u00f3 \u00f4ng l\u1ea1i ph\u1ea1m m\u1ed9t lo\u1ea1t sai l\u1ea7m.`,
  `K\u1ebb th\u00f9 l\u1edbn nh\u1ea5t c\u1ee7a nh\u00e0 Minh l\u00fac b\u1ea5y gi\u1edd l\u00e0 H\u1eadu Kim \u1edf ph\u00eda \u0111\u00f4ng b\u1eafc.`,
  `S\u00f9ng Trinh \u0110\u1ebf \u0111\u00e3 tr\u1ecdng d\u1ee5ng l\u1ea1i Vi\u00ean S\u00f9ng Ho\u00e1n, Vi\u00ean S\u00f9ng Ho\u00e1n v\u1eeba nh\u1eadm ch\u1ee9c,`,
  `\u0110\u00e3 s\u1eafp x\u1ebfp c\u00f4ng vi\u1ec7c ph\u00f2ng th\u1ee7 \u0111\u00f4ng b\u1eafc \u0111\u00e2u v\u00e0o \u0111\u1ea5y,`,
  `Kh\u00f4ng cho H\u1eadu Kim b\u1ea5t c\u1ee9 c\u01a1 h\u1ed9i x\u00e2m l\u01b0\u1ee3c n\u00e0o.`,
  `Nh\u01b0ng S\u00f9ng Trinh \u0111a nghi n\u00f4n n\u00f3ng,`,
  `M\u1ed9t k\u1ebf ph\u1ea3n gi\u00e1n nh\u1ecf c\u1ee7a Ho\u00e0ng Th\u00e1i C\u1ef1c b\u00ean ph\u00eda H\u1eadu Kim,`,
  `\u0111\u1ec3 Ho\u00e0ng \u0111\u1ebf S\u00f9ng Trinh ngh\u0129 r\u1eb1ng Vi\u00ean S\u00f9ng Ho\u00e1n \u0111\u00e3 th\u00f4ng \u0111\u1ed3ng v\u1edbi qu\u00e2n Kim,`,
  `Ho\u00e0ng \u0111\u1ebf S\u00f9ng Trinh tin v\u00e0o tin \u0111\u1ed3n,`,
  `l\u1eadp t\u1ee9c x\u1eed t\u1eed Vi\u00ean S\u00f9ng Ho\u00e1n b\u1eb1ng c\u00e1ch l\u0103ng tr\u00ec.`,
  `T\u1eeb \u0111\u00f3, nh\u00e0 Minh m\u1ea5t \u0111i l\u00e1 ch\u1eafn duy nh\u1ea5t \u1edf \u0110\u00f4ng B\u1eafc,`,
  `qu\u00e2n Kim c\u00f3 th\u1ec3 t\u1ef1 do tung ho\u00e0nh kh\u1eafp v\u00f9ng \u0110\u00f4ng B\u1eafc, nh\u01b0 th\u1ec3 v\u00e0o khu v\u01b0\u1eddn sau nh\u00e0 c\u1ee7a m\u00ecnh.`,
  `Trong khi \u0111\u00f3, \u1edf trong n\u01b0\u1edbc,`,
  `c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n ng\u00e0y c\u00e0ng l\u1edbn m\u1ea1nh,`,
  `qu\u00e2n \u0111\u1ed9i n\u00f4ng d\u00e2n do L\u00fd T\u1ef1 Th\u00e0nh \u0111\u1ee9ng \u0111\u1ea7u nhanh ch\u00f3ng ph\u00e1t tri\u1ec3n l\u00ean \u0111\u1ebfn h\u00e0ng tri\u1ec7u ng\u01b0\u1eddi.`,
  `Nh\u00e0 Minh \u0111\u00e3 t\u1eeb suy t\u00e0n c\u00e0ng th\u00eam suy s\u1ee5p.`,
  `M\u1eb7c d\u00f9 Ho\u00e0ng \u0111\u1ebf S\u00f9ng Trinh \u0111\u00e3 r\u1ea5t c\u1ed1 g\u1eafng \u0111\u1ec3 tr\u1edf th\u00e0nh m\u1ed9t v\u1ecb vua t\u1ed1t,`,
  `nh\u01b0ng v\u1eabn b\u1ecb l\u1ecbch s\u1eed an b\u00e0i m\u1ed9t k\u1ebft c\u1ee5c bi th\u1ea3m.`,
  `N\u0103m 1644,`,
  `sau khi qu\u00e2n L\u00fd T\u1ef1 Th\u00e0nh chi\u1ebfm \u0111\u01b0\u1ee3c B\u1eafc Kinh,`,
  `Ho\u00e0ng \u0111\u1ebf S\u00f9ng Trinh \u0111\u00e3 t\u1ef1 v\u1eabn tr\u00ean m\u1ed9t c\u00e1i c\u00e2y \u1edf C\u1ea9m S\u01a1n,`,
  `h\u01b0\u1edfng d\u01b0\u01a1ng 35 tu\u1ed5i.`,
  `nh\u00e0 Minh c\u0169ng \u0111\u1eb7t d\u1ea5u ch\u1ea5m h\u1ebft.`,
  `N\u1ed7 Nh\u0129 C\u00e1p X\u00edch c\u1ee7a H\u1eadu Kim, gia \u0111\u00ecnh \u00f4ng l\u00e0 qu\u00fd t\u1ed9c N\u1eef Ch\u00e2n,`,
  `b\u1ea3n th\u00e2n \u00f4ng ta v\u1ed1n l\u00e0 m\u1ed9t quan nh\u1ecf \u1edf bi\u00ean gi\u1edbi nh\u00e0 Minh.`,
  `Sau n\u00e0y, v\u00ec nh\u00e0 Minh \u0111\u00e3 \u00e1p d\u1ee5ng c\u00e1c bi\u1ec7n ph\u00e1p c\u1ee9ng r\u1eafn \u0111\u1ed1i v\u1edbi c\u00e1c d\u00e2n t\u1ed9c thi\u1ec3u s\u1ed1 \u1edf bi\u00ean gi\u1edbi ph\u00eda \u0111\u00f4ng b\u1eafc,`,
  `\u00f4ng ta bu\u1ed9c ph\u1ea3i n\u1ed5i d\u1eady t\u1ef1 b\u1ea3o v\u1ec7 m\u00ecnh, v\u00e0 nhanh ch\u00f3ng th\u1ed1ng nh\u1ea5t Ki\u1ebfn Ch\u00e2u N\u1eef Ch\u00e2n,`,
  `th\u00e0nh l\u1eadp H\u1eadu Kim.`,
  `L\u00fac n\u00e0y, H\u1eadu Kim ch\u1ec9 l\u00e0 m\u1ed9t ch\u00ednh quy\u1ec1n \u0111\u1ecba ph\u01b0\u01a1ng,`,
  `ch\u01b0a \u0111\u1ee7 m\u1ea1nh,`,
  `h\u1ea7u h\u1ebft th\u1eddi gian h\u1ecd ch\u1ec9 \u0111\u00e1nh nhau nh\u1ecf l\u1ebb \u1edf \u0111\u00f4ng b\u1eafc v\u1edbi nh\u00e0 Minh.`,
  `Sau khi N\u1ed7 Nh\u0129 C\u00e1p X\u00edch ch\u1ebft, con trai \u00f4ng l\u00e0 Ho\u00e0ng Th\u00e1i C\u1ef1c \u0111\u1ed5i t\u00ean H\u1eadu Kim th\u00e0nh Thanh,`,
  `\u00e1p d\u1ee5ng ch\u00ednh s\u00e1ch h\u1ee3p l\u00fd v\u00e0 t\u00edch c\u1ef1c h\u01a1n,`,
  `ti\u00eau hao \u0111\u00e1ng k\u1ec3 qu\u1ed1c l\u1ef1c c\u1ee7a nh\u00e0 Minh,`,
  `gi\u00fap nh\u00e0 Thanh c\u00f3 \u0111\u1ee7 s\u1ee9c m\u1ea1nh \u0111\u1ec3 th\u1ed1ng nh\u1ea5t thi\u00ean h\u1ea1.`,
  `Ngay tr\u01b0\u1edbc \u0111\u00eam quy\u1ebft chi\u1ebfn v\u1edbi nh\u00e0 Minh,`,
  `Ho\u00e0ng Th\u00e1i C\u1ef1c l\u1ea1i \u0111\u1ed9t ng\u1ed9t qua \u0111\u1eddi.`,
  `Th\u1eadm ch\u00ed c\u00f2n kh\u00f4ng c\u00f3 ng\u01b0\u1eddi th\u1eeba k\u1ebf.`,
  `L\u00fac n\u00e0y, con trai tr\u01b0\u1edfng c\u1ee7a \u00f4ng l\u00e0 H\u00e0o C\u00e1ch v\u00e0 em trai \u00f4ng l\u00e0 \u0110a Nh\u0129 C\u1ed5n mu\u1ed1n tranh gi\u00e0nh ngai v\u00e0ng,`,
  `Th\u1ebf l\u1ef1c ngang nhau, kh\u00f4ng ai c\u00f3 th\u1ec3 l\u00e0m g\u00ec \u0111\u01b0\u1ee3c ai.`,
  `Cu\u1ed1i c\u00f9ng ch\u1ec9 c\u00f3 th\u1ec3 ch\u1ecdn m\u1ed9t ph\u01b0\u01a1ng ph\u00e1p th\u1ecfa hi\u1ec7p,`,
  `\u0110\u00f3 l\u00e0 \u0111\u1ec3 con trai s\u00e1u tu\u1ed5i c\u1ee7a Ho\u00e0ng Th\u00e1i C\u1ef1c l\u00e0 Ph\u00fac L\u00e2m k\u1ebf v\u1ecb,`,
  `Ch\u00ednh l\u00e0 vua Thu\u1eadn Tr\u1ecb.`,
  `C\u00f9ng n\u0103m \u0111\u00f3, qu\u00e2n Thanh d\u01b0\u1edbi s\u1ef1 d\u1eabn d\u1eaft c\u1ee7a t\u1ed5ng binh S\u01a1n H\u1ea3i Quan nh\u00e0 Minh Ng\u00f4 Tam Qu\u1ebf,`,
  `\u0110\u00e3 \u0111\u00e1nh \u0111u\u1ed5i L\u00fd T\u1ef1 Th\u00e0nh, ng\u01b0\u1eddi v\u1eeba m\u1edbi t\u1ea5n c\u00f4ng B\u1eafc Kinh v\u00e0 ti\u00eau di\u1ec7t tri\u1ec1u Minh.`,
  `Nh\u00e0 Thanh ti\u1ebfp qu\u1ea3n to\u00e0n b\u1ed9 Trung Qu\u1ed1c.`,
  `Thu\u1eadn Tr\u1ecb l\u00e0 v\u1ecb ho\u00e0ng \u0111\u1ebf \u0111\u1ea7u ti\u00ean c\u1ee7a nh\u00e0 Thanh nh\u1eadp quan,`,
  `Th\u1eddi gian t\u1ea1i v\u1ecb c\u1ee7a \u00f4ng kh\u00f4ng d\u00e0i, nh\u01b0ng \u00f4ng \u0111\u00e3 t\u00edch c\u1ef1c ti\u1ebfp thu v\u0103n h\u00f3a H\u00e1n,`,
  `Tr\u1ecdng d\u1ee5ng m\u1ed9t lo\u1ea1t c\u00e1c h\u1ecdc gi\u1ea3 H\u00e1n,`,
  `Khi\u1ebfn nh\u00e0 Thanh c\u00f3 th\u1ec3 \u0111\u1ee9ng v\u1eefng m\u1ed9t c\u00e1ch \u1ed5n \u0111\u1ecbnh tr\u00ean l\u00e3nh th\u1ed5 c\u1ee7a ng\u01b0\u1eddi H\u00e1n.`,
  `Sau \u0111\u00f3, s\u1ee7ng phi \u0110\u1ed5ng Ng\u1ea1c th\u1ecb c\u1ee7a \u00f4ng qua \u0111\u1eddi, \u00f4ng ch\u00e1n n\u1ea3n c\u00f5i tr\u1ea7n,`,
  `Nh\u1ea5t quy\u1ebft mu\u1ed1n xu\u1ea5t gia. M\u1eb7c d\u00f9 sau n\u00e0y c\u0169ng kh\u00f4ng th\u1ef1c s\u1ef1 tr\u1edf th\u00e0nh h\u00f2a th\u01b0\u1ee3ng,`,
  `Th\u1ebf nh\u01b0ng kh\u00f4ng l\u00e2u sau \u0111\u00f3, \u00f4ng ta m\u1eafc b\u1ec7nh \u0111\u1eadu m\u00f9a m\u00e0 ch\u1ebft.`,
  `Khang Hy l\u00ean ng\u00f4i n\u0103m 8 tu\u1ed5i,`,
  `v\u00ec c\u00f2n nh\u1ecf n\u00ean \u0111\u00e3 t\u00ecm 4 v\u1ecb \u0111\u1ea1i th\u1ea7n nhi\u1ebfp ch\u00ednh \u0111\u1ec3 ph\u00f2 t\u00e1,`,
  `trong \u0111\u00f3 c\u00f3 Ngao B\u00e1i.`,
  `Ngao B\u00e1i l\u00e0 l\u00e3o th\u1ea7n ba tri\u1ec1u, theo Ho\u00e0ng Th\u00e1i C\u1ef1c \u0111\u00e1nh tr\u1eadn t\u1eeb khi c\u00f2n tr\u1ebb,`,
  `d\u1ef1a v\u00e0o c\u00f4ng lao hi\u1ec3n h\u00e1ch, b\u00e8 ph\u00e1i \u0111\u00f4ng \u0111\u1ea3o,`,
  `ho\u00e0n to\u00e0n kh\u00f4ng xem Khang Hy ra g\u00ec.`,
  `\u0110\u1ee3i \u0111\u1ebfn khi Khang Hy t\u1ef1 m\u00ecnh ch\u1ea5p ch\u00ednh, \u0111\u00e3 d\u00f9ng v\u00e0i ti\u1ec3u th\u00e1i gi\u00e1m \u0111\u1ec3 x\u1eed l\u00fd Ngao B\u00e1i,`,
  `ti\u00eau di\u1ec7t t\u1eadp \u0111o\u00e0n Ngao B\u00e1i.`,
  `L\u00fac \u0111\u00f3, \u00f4ng \u1ea5y m\u1edbi 16 tu\u1ed5i,`,
  `Khang Hy th\u1eadt s\u1ef1 \u0111\u00e3 n\u1eafm gi\u1eef tri\u1ec1u ch\u00ednh.`,
  `Sau khi tr\u01b0\u1edfng th\u00e0nh, \u00f4ng \u1ea5y l\u1ea1i b\u00ecnh \u0111\u1ecbnh Ng\u00f4 Tam Qu\u1ebf \u1edf V\u00e2n Nam,`,
  `Th\u01b0\u1ee3ng Kh\u1ea3 H\u1ef7 \u1edf Qu\u1ea3ng \u0110\u00f4ng v\u00e0 C\u1ea3nh Tinh M\u1eadu \u1edf Ph\u00fac Ki\u1ebfn, ba th\u1ebf l\u1ef1c c\u00e1t c\u1ee9,`,
  `ti\u00eau di\u1ec7t t\u1eadp \u0111o\u00e0n Tr\u1ecbnh th\u1ecb c\u1ee7a gia t\u1ed9c Tr\u1ecbnh Th\u00e0nh C\u00f4ng \u1edf \u0110\u00e0i Loan,`,
  `ba l\u1ea7n th\u00e2n chinh M\u00f4ng C\u1ed5 Chu\u1ea9n C\u00e1t Nh\u0129,`,
  `d\u1eb9p y\u00ean c\u00e1c cu\u1ed9c n\u1ed5i lo\u1ea1n c\u1ee7a ng\u01b0\u1eddi M\u00f4ng C\u1ed5,`,
  `b\u1ea3o v\u1ec7 s\u1ef1 th\u1ed1ng nh\u1ea5t c\u1ee7a Trung Qu\u1ed1c.`,
  `V\u1ec1 m\u1eb7t n\u1ed9i tr\u1ecb,`,
  `Khang Hy c\u0169ng r\u1ea5t xu\u1ea5t s\u1eafc,`,
  `ch\u0103m ch\u1ec9 vi\u1ec7c n\u01b0\u1edbc, y\u00eau th\u01b0\u01a1ng d\u00e2n ch\u00fang, t\u00f4n tr\u1ecdng v\u0103n h\u00f3a H\u00e1n.`,
  `D\u01b0\u1edbi s\u1ef1 cai tr\u1ecb c\u1ee7a \u00f4ng,`,
  `nh\u00e0 Thanh ng\u00e0y c\u00e0ng th\u1ecbnh v\u01b0\u1ee3ng,`,
  `nh\u01b0ng \u00f4ng c\u0169ng kh\u00f4ng ph\u1ea3i kh\u00f4ng c\u00f3 khuy\u1ebft \u0111i\u1ec3m.`,
  `S\u1ef1 do d\u1ef1 trong v\u1ea5n \u0111\u1ec1 truy\u1ec1n ng\u00f4i \u0111\u00e3 d\u1eabn \u0111\u1ebfn bi k\u1ecbch C\u1eedu t\u1eed \u0111o\u1ea1t \u0111\u00edch,`,
  `h\u01a1n n\u1eefa, ch\u00ednh s\u00e1ch qu\u00e1 khoan dung \u0111\u00e3 khi\u1ebfn tri\u1ec1u \u0111\u00ecnh h\u1ee7 b\u1ea1i,`,
  `qu\u1ed1c kh\u1ed1 tr\u1ed1ng r\u1ed7ng. Khang Hy tr\u1ecb v\u00ec s\u00e1u m\u01b0\u01a1i m\u1ed1t n\u0103m,`,
  `\u0111\u00e1nh gi\u00e1 v\u1ec1 \u00f4ng v\u1eabn l\u00e0 c\u00f4ng l\u1edbn h\u01a1n t\u1ed9i,`,
  `l\u00e0 m\u1ed9t trong nh\u1eefng v\u1ecb ho\u00e0ng \u0111\u1ebf t\u00e0i n\u0103ng nh\u1ea5t c\u1ee7a nh\u00e0 Thanh.`,
  `Sau n\u00e0y, T\u1ee9 ho\u00e0ng t\u1eed Ung Ch\u00ednh c\u1ee7a \u00f4ng, sau nhi\u1ec1u n\u0103m \u0111\u1ea5u tr\u00ed \u0111\u1ea5u d\u0169ng,`,
  `cu\u1ed1i c\u00f9ng \u0111\u00e3 n\u1ed5i b\u1eadt h\u01a1n t\u1ea5t c\u1ea3 c\u00e1c em v\u00e0 anh c\u1ee7a m\u00ecnh.`,
  `Sau khi l\u00ean ng\u00f4i, Ung Ch\u00ednh \u0111\u00e3 thanh tr\u1eebng t\u1ea5t c\u1ea3 c\u00e1c ho\u00e0ng t\u1eed t\u1eebng tranh gi\u00e0nh ngai v\u00e0ng v\u1edbi \u00f4ng tr\u01b0\u1edbc \u0111\u00f3,`,
  `\u0110i\u1ec1u n\u00e0y khi\u1ebfn \u00f4ng mang ti\u1ebfng l\u00e0 m\u1ed9t b\u1ea1o ch\u00faa t\u00e0n b\u1ea1o, v\u00f4 t\u00ecnh.`,
  `Trong vi\u1ec7c cai tr\u1ecb \u0111\u1ea5t n\u01b0\u1edbc,`,
  `Ung Ch\u00ednh l\u00e0 m\u1ed9t ng\u01b0\u1eddi lao \u0111\u1ed9ng ki\u1ec3u m\u1eabu,`,
  `k\u1ec3 t\u1eeb khi \u00f4ng l\u00ean ng\u00f4i,`,
  `\u00f4ng \u0111\u00e3 thay \u0111\u1ed5i nh\u1eefng t\u1ec7 n\u1ea1n v\u00e0o cu\u1ed1i th\u1eddi Khang Hy,`,
  `ch\u00fa tr\u1ecdng th\u1ef1c t\u1ebf, gi\u00fap \u0111\u1ea5t n\u01b0\u1edbc l\u00e0m \u0103n ph\u00e1t \u0111\u1ea1t.`,
  `\u0110\u1ea1i Thanh c\u0169ng m\u1ed9t l\u1ea7n n\u1eefa h\u1ed3i sinh m\u1ea1nh m\u1ebd,`,
  `\u0111\u1ec3 l\u1ea1i cho con trai C\u00e0n Long m\u1ed9t giang s\u01a1n th\u1ecbnh v\u01b0\u1ee3ng.`,
  `Ung Ch\u00ednh qua \u0111\u1eddi v\u00ec b\u1ec7nh t\u1eadt sau 13 n\u0103m t\u1ea1i v\u1ecb,`,
  `C\u00e0n Long l\u00e0 v\u1ecb ho\u00e0ng \u0111\u1ebf s\u1ed1ng th\u1ecd nh\u1ea5t trong l\u1ecbch s\u1eed Trung Qu\u1ed1c.`,
  `Ti\u1ebfp n\u1ed1i s\u1ee9c m\u1ea1nh qu\u1ed1c gia h\u00f9ng c\u01b0\u1eddng,`,
  `C\u00e0n Long \u0111\u00e3 th\u1ed1ng nh\u1ea5t T\u00e2n C\u01b0\u01a1ng,`,
  `d\u01b0\u1edbi th\u1eddi \u00f4ng,`,
  `tri\u1ec1u \u0111\u1ea1i nh\u00e0 Thanh \u0111\u00e3 ph\u00e1t tri\u1ec3n \u0111\u1ebfn \u0111\u1ec9nh cao.`,
  `C\u00e0n Long r\u1ea5t th\u00edch ch\u01a1i b\u1eddi, nh\u01b0 m\u1ed9t th\u1ed5 h\u00e0o v\u1eady,`,
  `\u0111i \u0111\u1ebfn \u0111\u00e2u c\u0169ng ti\u00eau ti\u1ec1n nh\u01b0 n\u01b0\u1edbc.`,
  `Khi v\u1ec1 gi\u00e0, \u00f4ng c\u00e0ng th\u00eam m\u00ea mu\u1ed9i v\u1edbi c\u1ee7a c\u1ea3i.`,
  `D\u01b0\u1edbi \u1ea3nh h\u01b0\u1edfng c\u1ee7a \u00f4ng,`,
  `tri\u1ec1u \u0111\u1ea1i nh\u00e0 Thanh ho\u00e0n to\u00e0n r\u01a1i v\u00e0o v\u00f2ng xo\u00e1y tham nh\u0169ng,`,
  `t\u1eeb tr\u00ean xu\u1ed1ng d\u01b0\u1edbi trong quan tr\u01b0\u1eddng tr\u00e0n ng\u1eadp tham quan \u00f4 l\u1ea1i,`,
  `t\u01b0 ph\u00e1p suy \u0111\u1ed3i, d\u00e2n ch\u00fang l\u1ea7m than.`,
  `H\u00f2a Th\u00e2n, \u0111\u1ea1i tham quan n\u1ed5i ti\u1ebfng trong l\u1ecbch s\u1eed, \u0111\u00e3 nh\u00e2n c\u01a1 h\u1ed9i n\u00e0y m\u00e0 n\u1ecbnh b\u1ee3 C\u00e0n Long,`,
  `m\u1ed9t b\u01b0\u1edbc l\u00ean m\u00e2y, th\u0103ng quan ph\u00e1t t\u00e0i,`,
  `tha h\u1ed3 tham \u00f4 nh\u1eadn h\u1ed1i l\u1ed9.`,
  `Trong khi \u0111\u00f3, ph\u01b0\u01a1ng T\u00e2y \u0111\u00e3 tr\u1ea3i qua nh\u1eefng thay \u0111\u1ed5i long tr\u1eddi l\u1edf \u0111\u1ea5t,`,
  `Anh b\u1eaft \u0111\u1ea7u c\u00e1ch m\u1ea1ng c\u00f4ng nghi\u1ec7p,`,
  `M\u1ef9 \u0111\u00e3 th\u00e0nh l\u1eadp,`,
  `C\u00e1ch m\u1ea1ng Ph\u00e1p b\u00f9ng n\u1ed5.`,
  `Ba s\u1ef1 ki\u1ec7n n\u00e0y \u0111\u00e3 thay \u0111\u1ed5i ho\u00e0n to\u00e0n ti\u1ebfn tr\u00ecnh v\u00e0 c\u1ee5c di\u1ec7n v\u0103n minh th\u1ebf gi\u1edbi,`,
  `Trong khi \u0111\u00f3, tri\u1ec1u \u0111\u1ea1i nh\u00e0 Thanh c\u1ee7a C\u00e0n Long v\u1eabn t\u1ef1 \u0111\u00f3ng c\u1eeda,`,
  `\u0111\u00e1nh m\u1ea5t c\u01a1 h\u1ed9i cu\u1ed1i c\u00f9ng \u0111\u1ec3 t\u00ecm hi\u1ec3u th\u1ebf gi\u1edbi ph\u01b0\u01a1ng T\u00e2y.`,
  `Trong l\u00fac C\u00e0n Long \u0111ang t\u1ef1 m\u00e3n,`,
  `th\u1ebf gi\u1edbi ph\u01b0\u01a1ng T\u00e2y \u0111ang nhanh ch\u00f3ng v\u01b0\u1ee3t qua Trung Qu\u1ed1c.`,
  `C\u00e0n Long tho\u00e1i v\u1ecb sau 60 n\u0103m tr\u1ecb v\u00ec,`,
  `truy\u1ec1n ng\u00f4i cho Gia Kh\u00e1nh,`,
  `b\u1ed1n n\u0103m sau th\u00ec b\u0103ng h\u00e0,`,
  `th\u1ecd 89 tu\u1ed5i.`,
  `Tri\u1ec1u Thanh m\u00e0 C\u00e0n Long \u0111\u1ec3 l\u1ea1i \u0111\u00e3 suy y\u1ebfu kh\u00f3 l\u00f2ng c\u1ee9u v\u00e3n,`,
  `Gia Kh\u00e1nh nh\u00ecn th\u1ea5y s\u1ef1 m\u1ee5c n\u00e1t c\u1ee7a x\u00e3 h\u1ed9i,`,
  `l\u00ean ng\u00f4i li\u1ec1n gi\u1ebft H\u00f2a Th\u00e2n, \u0111i\u1ec1u tra quan tham.`,
  `Nh\u01b0ng s\u1ef1 suy vong c\u1ee7a \u0110\u1ea1i Thanh \u0111\u00e3 th\u1ec3 hi\u1ec7n r\u00f5 tr\u00ean ph\u01b0\u01a1ng di\u1ec7n qu\u00e2n s\u1ef1 v\u00e0 qu\u1ed1c l\u1ef1c.`,
  `D\u01b0\u1edbi th\u1eddi Gia Kh\u00e1nh,`,
  `nh\u00e0 Thanh v\u1eabn ti\u1ebfp t\u1ee5c suy t\u00e0n.`,
  `Sau \u0111\u00f3 \u0110\u1ea1o Quang k\u1ebf v\u1ecb, \u00f4ng l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf v\u1eeba ti\u1ebft ki\u1ec7m v\u1eeba c\u00f3 tr\u00e1ch nhi\u1ec7m.`,
  `Trong th\u1eddi gian t\u1ea1i v\u1ecb, thu\u1ed1c phi\u1ec7n lu\u00f4n l\u00e0 v\u1ea5n \u0111\u1ec1 l\u1edbn nh\u1ea5t.`,
  `L\u01b0\u1ee3ng thu\u1ed1c phi\u1ec7n nh\u1eadp kh\u1ea9u l\u1edbn kh\u00f4ng ch\u1ec9 khi\u1ebfn c\u1ea3 Trung Qu\u1ed1c tr\u1edf n\u00ean b\u1ec7nh t\u1eadt, suy y\u1ebfu,`,
  `m\u00e0 c\u00f2n d\u1eabn \u0111\u1ebfn vi\u1ec7c m\u1ed9t l\u01b0\u1ee3ng l\u1edbn b\u1ea1c b\u1ecb ch\u1ea3y ra ngo\u00e0i.`,
  `Th\u1ebf l\u00e0 m\u1ed9t phong tr\u00e0o c\u1ea5m thu\u1ed1c phi\u1ec7n r\u1ea7m r\u1ed9 \u0111\u00e3 di\u1ec5n ra.`,
  `D\u01b0\u1edbi s\u1ef1 \u1ee7ng h\u1ed9 c\u1ee7a \u0110\u1ea1o Quang \u0110\u1ebf,`,
  `L\u00e2m T\u1eafc T\u1eeb ki\u00ean quy\u1ebft c\u1ea5m thu\u1ed1c phi\u1ec7n,`,
  `\u0111\u00e3 ti\u00eau h\u1ee7y s\u1ed1 thu\u1ed1c phi\u1ec7n thu gi\u1eef \u0111\u01b0\u1ee3c t\u1ea1i b\u00e3i bi\u1ec3n H\u1ed5 M\u00f4n.`,
  `\u0110\u00e2y ch\u00ednh l\u00e0 s\u1ef1 ki\u1ec7n H\u1ed5 M\u00f4n Ti\u00eau Y\u00ean n\u1ed5i ti\u1ebfng.`,
  `V\u00e0 c\u00e1ch l\u00e0m n\u00e0y c\u0169ng \u0111\u00e3 x\u00e2m ph\u1ea1m l\u1ee3i \u00edch c\u1ee7a ng\u01b0\u1eddi Anh.`,
  `N\u0103m 1840,`,
  `ng\u01b0\u1eddi Anh x\u00e2m l\u01b0\u1ee3c Trung Qu\u1ed1c, ph\u00e1t \u0111\u1ed9ng Chi\u1ebfn tranh Nha phi\u1ebfn l\u1ea7n th\u1ee9 nh\u1ea5t.`,
  `\u0110\u1ed1i m\u1eb7t v\u1edbi t\u00e0u chi\u1ebfn v\u00e0 s\u00fang \u1ed1ng uy l\u1ef1c c\u1ee7a Anh, tri\u1ec1u \u0111\u00ecnh nh\u00e0 Thanh b\u1ecb \u0111\u00e1nh b\u1ea1i ho\u00e0n to\u00e0n,`,
  `bu\u1ed9c ph\u1ea3i c\u1ea7u h\u00f2a,`,
  `k\u00fd v\u1edbi Anh hi\u1ec7p \u01b0\u1edbc b\u1ea5t b\u00ecnh \u0111\u1eb3ng \u0111\u1ea7u ti\u00ean trong l\u1ecbch s\u1eed Trung Qu\u1ed1c \u2013 Hi\u1ec7p \u01b0\u1edbc Nam Kinh.`,
  `Trung Qu\u1ed1c tr\u1edf th\u00e0nh m\u1ed9t x\u00e3 h\u1ed9i n\u1eeda thu\u1ed9c \u0111\u1ecba, n\u1eeda phong ki\u1ebfn.`,
  `Ch\u00ednh ph\u1ee7 nh\u00e0 Thanh v\u1ed1n kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ea1i ph\u1ea3i b\u1ed3i th\u01b0\u1eddng chi\u1ebfn ph\u00ed,`,
  `ch\u1ec9 c\u00f3 th\u1ec3 ra s\u1ee9c v\u01a1 v\u00e9t c\u1ee7a c\u1ea3i c\u1ee7a d\u00e2n ch\u00fang.`,
  `K\u1ebft qu\u1ea3 l\u00e0 quan b\u1ee9c d\u00e2n ph\u1ea3n,`,
  `c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a li\u00ean ti\u1ebfp n\u1ed5 ra.`,
  `Trong b\u1ed1i c\u1ea3nh v\u1eeba c\u00f3 gi\u1eb7c trong v\u1eeba c\u00f3 gi\u1eb7c ngo\u00e0i nh\u01b0 v\u1eady,`,
  `\u0110\u1ea1o Quang qua \u0111\u1eddi v\u1edbi s\u1ef1 c\u0103m ph\u1eabn v\u00e0 ti\u1ebfc nu\u1ed1i.`,
  `H\u00e0m Phong l\u00ean ng\u00f4i. \u0110\u1ed1i m\u1eb7t v\u1edbi m\u1ed9t \u0111\u1ed1ng h\u1ed7n \u0111\u1ed9n m\u00e0 c\u00e1c \u0111\u1eddi tr\u01b0\u1edbc \u0111\u1ec3 l\u1ea1i,`,
  `b\u00ean trong c\u00f3 Th\u00e1i B\u00ecnh Thi\u00ean Qu\u1ed1c chi\u1ebfm n\u1eeda giang s\u01a1n,`,
  `b\u00ean ngo\u00e0i c\u00f3 li\u00ean qu\u00e2n Anh - Ph\u00e1p ph\u00e1t \u0111\u1ed9ng Chi\u1ebfn tranh nha phi\u1ebfn l\u1ea7n th\u1ee9 hai.`,
  `Qu\u00e2n Thanh kh\u00f4ng th\u1ec3 \u0111\u00e1nh b\u1ea1i b\u1ea5t k\u1ef3 b\u00ean n\u00e0o trong s\u1ed1 h\u1ecd,`,
  `kh\u00f4ng \u0111\u00e1nh l\u1ea1i \u0111\u01b0\u1ee3c th\u00ec ch\u1ec9 c\u00f3 th\u1ec3 ch\u1ea1y tr\u1ed1n.`,
  `Sau khi ch\u1ea1y \u0111\u1ebfn Nhi\u1ec7t H\u00e0,`,
  `H\u00e0m Phong b\u1eaft \u0111\u1ea7u m\u1eb7c k\u1ec7 t\u1ea5t c\u1ea3,`,
  `s\u1ed1ng trong men say v\u00e0 \u1ea3o m\u1ed9ng,`,
  `r\u1ed3i qua \u0111\u1eddi \u1edf tu\u1ed5i ba m\u01b0\u01a1i m\u1ed1t.`,
  `\u00d4ng c\u0169ng l\u00e0 ho\u00e0ng \u0111\u1ebf cu\u1ed1i c\u00f9ng c\u1ee7a tri\u1ec1u Thanh n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c th\u1ef1c s\u1ef1.`,
  `C\u00e1c \u0111\u1eddi \u0110\u1ed3ng Tr\u1ecb, Quang T\u1ef1,`,
  `Tuy\u00ean Th\u1ed1ng sau n\u00e0y, ho\u1eb7c l\u00e0 b\u00f9 nh\u00ecn c\u1ee7a ng\u01b0\u1eddi c\u1ee7a m\u00ecnh,`,
  `ho\u1eb7c l\u00e0 b\u00f9 nh\u00ecn c\u1ee7a ng\u01b0\u1eddi n\u01b0\u1edbc ngo\u00e0i.`,
  `T\u1eeb Hy l\u00e0 phi t\u1ea7n c\u1ee7a H\u00e0m Phong, l\u00e0 m\u1eb9 ru\u1ed9t c\u1ee7a \u0110\u1ed3ng Tr\u1ecb.`,
  `\u0110\u1ed3ng Tr\u1ecb l\u00ean ng\u00f4i khi c\u00f2n r\u1ea5t nh\u1ecf,`,
  `n\u00ean T\u1eeb Hy v\u00e0 T\u1eeb An, ho\u00e0ng h\u1eadu c\u1ee7a H\u00e0m Phong, c\u00f9ng nhau bu\u00f4ng r\u00e8m nhi\u1ebfp ch\u00ednh.`,
  `Kh\u00f4ng l\u00e2u sau, T\u1eeb An qua \u0111\u1eddi,`,
  `tri\u1ec1u ch\u00ednh c\u01a1 b\u1ea3n do T\u1eeb Hy m\u1ed9t m\u00ecnh n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c.`,
  `N\u0103m 19 tu\u1ed5i, \u0110\u1ed3ng Tr\u1ecb qua \u0111\u1eddi v\u00ec b\u1ec7nh \u0111\u1eadu m\u00f9a,`,
  `\u00f4ng kh\u00f4ng c\u00f3 con trai,`,
  `ng\u01b0\u1eddi em h\u1ecd b\u1ed1n tu\u1ed5i Quang T\u1ef1 l\u00ean ng\u00f4i.`,
  `Quang T\u1ef1 t\u1eeb nh\u1ecf \u0111\u00e3 l\u1edbn l\u00ean d\u01b0\u1edbi s\u1ef1 gi\u00e1m s\u00e1t c\u1ee7a T\u1eeb Hy,`,
  `n\u00ean t\u00ednh c\u00e1ch \u00f4ng \u0111\u1eb7c bi\u1ec7t y\u1ebfu \u0111u\u1ed1i.`,
  `Sau khi tr\u01b0\u1edfng th\u00e0nh, \u00f4ng c\u0169ng mu\u1ed1n thay \u0111\u1ed5i \u0111\u1ea5t n\u01b0\u1edbc b\u1eb1ng c\u00e1ch c\u1ea3i c\u00e1ch,`,
  `Nh\u01b0ng g\u1eb7p ph\u1ea3i s\u1ef1 ph\u1ea3n \u0111\u1ed1i gay g\u1eaft t\u1eeb phe b\u1ea3o th\u1ee7 c\u1ee7a T\u1eeb Hy,`,
  `cu\u1ed9c c\u1ea3i c\u00e1ch th\u1ea5t b\u1ea1i ch\u1ec9 sau m\u1ed9t tr\u0103m l\u1ebb ba ng\u00e0y,`,
  `s\u1eed g\u1ecdi l\u00e0 B\u00e1ch nh\u1eadt duy t\u00e2n.`,
  `Sau \u0111\u00f3, Quang T\u1ef1 b\u1ecb T\u1eeb Hy giam l\u1ecfng,`,
  `r\u1ed3i sau \u0111\u00f3, Li\u00ean qu\u00e2n T\u00e1m n\u01b0\u1edbc t\u1ea5n c\u00f4ng v\u00e0o B\u1eafc Kinh,`,
  `T\u1eeb Hy v\u00e0 Quang T\u1ef1 b\u1ecf ch\u1ea1y,`,
  `Li\u00ean qu\u00e2n \u0111\u1ed1t ph\u00e1, gi\u1ebft ch\u00f3c, c\u01b0\u1edbp b\u00f3c \u1edf B\u1eafc Kinh, l\u00e0m \u0111\u1ee7 m\u1ecdi \u0111i\u1ec1u \u00e1c,`,
  `sau khi c\u01b0\u1edbp xong, gi\u1ebft \u0111\u1ee7, l\u1ea1i k\u00fd v\u1edbi ch\u00ednh ph\u1ee7 nh\u00e0 Thanh m\u1ed9t hi\u1ec7p \u01b0\u1edbc nh\u1ee5c nh\u00e3, m\u1ea5t ch\u1ee7 quy\u1ec1n,`,
  `Hi\u1ec7p \u01b0\u1edbc T\u00e2n S\u1eedu v\u1edbi kho\u1ea3n b\u1ed3i th\u01b0\u1eddng kh\u1ed5ng l\u1ed3.`,
  `Li\u00ean qu\u00e2n T\u00e1m n\u01b0\u1edbc l\u00fac \u0111\u00f3 m\u1edbi no say r\u1eddi \u0111i,`,
  `T\u1eeb Hy v\u1ec1 kinh ti\u1ebfp t\u1ee5c l\u00e0m L\u00e3o Ph\u1eadt gia c\u1ee7a m\u00ecnh.`,
  `Cu\u1ed1i c\u00f9ng \u0111\u1ee3i \u0111\u1ebfn khi T\u1eeb Hy s\u1eafp b\u0103ng h\u00e0,`,
  `b\u00e0 ta c\u00f2n kh\u00f4ng qu\u00ean \u0111\u1ea7u \u0111\u1ed9c ch\u1ebft Quang T\u1ef1 tr\u01b0\u1edbc.`,
  `Quang T\u1ef1 c\u0169ng kh\u00f4ng c\u00f3 con trai,`,
  `tr\u01b0\u1edbc khi ch\u1ebft T\u1eeb Hy \u0111\u00e3 t\u1ea1m th\u1eddi tuy\u00ean b\u1ed1 Ph\u1ed5 Nghi, t\u1ee9c Ho\u00e0ng \u0111\u1ebf Tuy\u00ean Th\u1ed1ng, k\u1ebf v\u1ecb.`,
  `L\u00fac \u0111\u00f3, Ph\u1ed5 Nghi m\u1edbi 3 tu\u1ed5i,`,
  `\u0110\u1ea1i Thanh l\u00fac n\u00e0y c\u0169ng \u0111\u00e3 g\u1ea7n suy t\u00e0n r\u1ed3i.`,
  `\u0110i\u1ec1u duy nh\u1ea5t Ph\u1ed5 Nghi c\u00f3 th\u1ec3 l\u00e0m l\u00e0 h\u1ed3 \u0111\u1ed3 l\u00ean ng\u00f4i r\u1ed3i tho\u00e1i v\u1ecb.`,
  `Ba n\u0103m sau, C\u00e1ch m\u1ea1ng T\u00e2n H\u1ee3i b\u00f9ng n\u1ed5 v\u00e0o n\u0103m 1911,`,
  `C\u00e1c t\u1ec9nh \u0111\u1ec1u li\u00ean ti\u1ebfp tuy\u00ean b\u1ed1 \u0111\u1ed9c l\u1eadp.`,
  `N\u0103m 1912,`,
  `Trung Hoa D\u00e2n Qu\u1ed1c tuy\u00ean b\u1ed1 th\u00e0nh l\u1eadp,`,
  `Ph\u1ed5 Nghi ch\u00ednh th\u1ee9c ban chi\u1ebfu tho\u00e1i v\u1ecb,`,
  `Tri\u1ec1u \u0111\u1ea1i phong ki\u1ebfn cu\u1ed1i c\u00f9ng c\u1ee7a Trung Qu\u1ed1c l\u00e0 nh\u00e0 Thanh di\u1ec7t vong.`,
  `\u0110\u01b0\u1ee3c r\u1ed3i, l\u1ecbch s\u1eed c\u1ed5 \u0111\u1ea1i Trung Qu\u1ed1c \u0111\u00e3 n\u00f3i xong.`,
  `N\u1ebfu b\u1ea1n th\u00edch video c\u1ee7a t\u00f4i, hoan ngh\u00eanh nh\u1ea5n \u0111\u0103ng k\u00fd,`,
  `M\u1edf chu\u00f4ng nh\u1ecf, video m\u1edbi s\u1ebd th\u00f4ng b\u00e1o cho b\u1ea1n ngay l\u1eadp t\u1ee9c,`,
  `H\u1eb9n g\u1eb7p l\u1ea1i l\u1ea7n sau.`,
];

