const CHINA_HISTORY_CH03_NH_T_N_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `N\u00f3i v\u1ec1 nh\u00e0 T\u1ea7n, ch\u1ee7 y\u1ebfu l\u00e0 n\u00f3i v\u1ec1 T\u1ea7n Th\u1ee7y Ho\u00e0ng, v\u00ec nh\u00e0 T\u1ea7n qu\u00e1 ng\u1eafn ng\u1ee7i,`,
  `ch\u1ec9 c\u00f3 m\u01b0\u1eddi l\u0103m n\u0103m.`,
  `N\u0103m 221 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `T\u1ea7n di\u1ec7t s\u00e1u n\u01b0\u1edbc, ch\u1ea5m d\u1ee9t th\u1eddi k\u1ef3 ch\u01b0 h\u1ea7u tranh gi\u00e0nh k\u00e9o d\u00e0i h\u01a1n 500 n\u0103m th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c,`,
  `th\u1ed1ng nh\u1ea5t Trung Hoa. \u0110\u1ea5t n\u01b0\u1edbc \u0111\u00e3 th\u1ed1ng nh\u1ea5t, nh\u01b0ng tr\u01b0\u1edbc l\u1ecbch s\u1eed \u0111\u1eabm m\u00e1u c\u1ee7a nh\u00e0 Chu, tri\u1ec1u \u0111\u1ea1i tr\u01b0\u1edbc \u0111\u00f3,`,
  `nh\u00e0 T\u1ea7n suy ngh\u0129 l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 kh\u00f4ng \u0111i v\u00e0o v\u1ebft xe \u0111\u1ed5.`,
  `Th\u1ec3 ch\u1ebf c\u1ee7a nh\u00e0 Chu khi \u0111\u00f3 ch\u1ee7 y\u1ebfu l\u00e0 ch\u1ebf \u0111\u1ed9 phong ki\u1ebfn,`,
  `Thi\u00ean t\u1eed nh\u00e0 Chu phong \u0111\u1ea5t \u0111ai c\u1ee7a m\u00ecnh cho ng\u01b0\u1eddi th\u00e2n ho\u1eb7c th\u1ea7n t\u1eed,`,
  `m\u1ed7i phong \u0111\u1ecba l\u00e0 m\u1ed9t n\u01b0\u1edbc ch\u01b0 h\u1ea7u.`,
  `N\u00f3i c\u00e1ch kh\u00e1c, \u0111\u1ea5t \u0111ai kh\u00f4ng ho\u00e0n to\u00e0n thu\u1ed9c v\u1ec1 ho\u00e0ng th\u1ea5t,`,
  `c\u00e1c v\u01b0\u01a1ng ch\u01b0 h\u1ea7u c\u00f3 quy\u1ec1n l\u1ef1c tuy\u1ec7t \u0111\u1ed1i tr\u00ean \u0111\u1ea5t phong c\u1ee7a m\u00ecnh,`,
  `c\u00f3 th\u1ec3 th\u1ebf t\u1eadp, c\u00f3 th\u1ec3 c\u00f3 qu\u00e2n \u0111\u1ed9i ri\u00eang,`,
  `v\u00e0 c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u ph\u1ea3i n\u1ed9p thu\u1ebf c\u1ed1ng cho ho\u00e0ng th\u1ea5t.`,
  `Ch\u1ebf \u0111\u1ed9 n\u00e0y ban \u0111\u1ea7u th\u00ec v\u1eabn \u1ed5n,`,
  `v\u00ec Thi\u00ean t\u1eed nh\u00e0 Chu v\u00e0 c\u00e1c ch\u01b0 h\u1ea7u \u0111\u1ec1u l\u00e0 ng\u01b0\u1eddi th\u00e2n, quen bi\u1ebft,`,
  `nh\u01b0ng l\u00e2u d\u1ea7n, c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u s\u1ebd c\u00f3 th\u1ebf l\u1ef1c v\u01b0\u1ee3t qua ho\u00e0ng th\u1ea5t,`,
  `d\u1eabn \u0111\u1ebfn c\u1ee5c di\u1ec7n c\u00e1c ch\u01b0 h\u1ea7u l\u1edbn h\u00f9ng c\u1ee9 nhi\u1ec1u n\u01a1i.`,
  `Th\u1eddi Xu\u00e2n Thu Chi\u1ebfn Qu\u1ed1c l\u00e0 v\u00ec th\u1ebf m\u00e0 c\u00f3.`,
  `nh\u00e0 T\u1ea7n r\u00fat kinh nghi\u1ec7m t\u1eeb s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a nh\u00e0 Chu,`,
  `l\u1ea7n \u0111\u1ea7u ti\u00ean t\u1ea1o ra ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n.`,
  `ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n l\u1ea5y Ho\u00e0ng \u0111\u1ebf l\u00e0m ng\u01b0\u1eddi \u0111\u1ee9ng \u0111\u1ea7u,`,
  `Tam C\u00f4ng C\u1eedu Khanh l\u00e0m \u0111\u1ea1i di\u1ec7n c\u1ee7a ch\u1ebf \u0111\u1ed9 t\u1eadp quy\u1ec1n c\u1ee7a ch\u00ednh ph\u1ee7 trung \u01b0\u01a1ng,`,
  `chia \u0111\u1ea5t n\u01b0\u1edbc th\u00e0nh ba m\u01b0\u01a1i s\u00e1u qu\u1eadn,`,
  `d\u01b0\u1edbi qu\u1eadn l\u1ea1i chia th\u00e0nh h\u01a1n m\u1ed9t ngh\u00ecn huy\u1ec7n,`,
  `quan l\u1ea1i \u0111\u1ee9ng \u0111\u1ea7u m\u1ed7i qu\u1eadn huy\u1ec7n \u0111\u1ec1u do trung \u01b0\u01a1ng b\u1ed5 nhi\u1ec7m,`,
  `kh\u00f4ng c\u00f3 b\u1ea5t k\u1ef3 m\u1ed1i quan h\u1ec7 huy\u1ebft th\u1ed1ng n\u00e0o v\u1edbi nhau.`,
  `kh\u00e1c v\u1edbi vi\u1ec7c c\u00e1c ch\u01b0 h\u1ea7u nh\u00e0 Chu n\u1ed9p c\u1ed1ng n\u1ea1p cho nh\u00e0 n\u01b0\u1edbc,`,
  `ch\u1ebf \u0111\u1ed9 qu\u1eadn huy\u1ec7n c\u1ee7a Ho\u00e0ng \u0111\u1ebf tr\u1ea3 b\u1ed5ng l\u1ed9c cho ho\u1ea1n quan.`,
  `m\u00f4 h\u00ecnh ph\u00e2n c\u1ea5p n\u00e0y l\u00e0m cho quy\u1ec1n l\u1ef1c trung \u01b0\u01a1ng t\u1eadp trung cao \u0111\u1ed9,`,
  `ng\u01b0\u1eddi cai tr\u1ecb c\u00f3 quy\u1ec1n l\u1ef1c tuy\u1ec7t \u0111\u1ed1i,`,
  `c\u00f3 l\u1ee3i cho vi\u1ec7c t\u0103ng c\u01b0\u1eddng t\u1eadp quy\u1ec1n trung \u01b0\u01a1ng v\u00e0 th\u1ed1ng nh\u1ea5t \u0111\u1ea5t n\u01b0\u1edbc.`,
  `c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u hi\u1ec7n nay c\u00f3 th\u1ec3 ch\u1ebf ri\u00eang \u1edf nhi\u1ec1u m\u1eb7t,`,
  `nh\u01b0ng sau khi th\u1ed1ng nh\u1ea5t c\u1ea3 n\u01b0\u1edbc, c\u00e1c th\u1ec3 ch\u1ebf n\u00e0y s\u1ebd g\u00e2y ra nhi\u1ec1u r\u1eafc r\u1ed1i,`,
  `V\u00ed d\u1ee5, Ti\u1ec1n t\u1ec7 kh\u00f4ng \u0111\u1ed3ng nh\u1ea5t,`,
  `Th\u01b0\u01a1ng m\u1ea1i v\u00e0 c\u00f4ng nghi\u1ec7p kh\u00f4ng th\u1ec3 ph\u00e1t tri\u1ec3n,`,
  `Khi \u0111\u01a1n v\u1ecb \u0111o l\u01b0\u1eddng kh\u00f4ng th\u1ed1ng nh\u1ea5t, vi\u1ec7c mua b\u00e1n r\u1ea5t b\u1ea5t ti\u1ec7n,`,
  `Ng\u00f4n ng\u1eef b\u1ea5t \u0111\u1ed3ng th\u00ec kh\u00f4ng th\u1ec3 giao ti\u1ebfp.`,
  `V\u00ec v\u1eady, T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 th\u1ed1ng nh\u1ea5t ti\u1ec1n t\u1ec7 v\u00e0 \u0111o l\u01b0\u1eddng tr\u00ean to\u00e0n qu\u1ed1c,`,
  `\u0110\u1eb7t n\u1ec1n m\u00f3ng cho giao th\u01b0\u01a1ng kinh t\u1ebf c\u1ee7a nh\u00e0 T\u1ea7n,`,
  `L\u1ea5y ch\u1eef Ti\u1ec3u tri\u1ec7n l\u00e0m v\u0103n t\u1ef1 chung tr\u00ean to\u00e0n qu\u1ed1c,`,
  `C\u00f3 l\u1ee3i cho vi\u1ec7c ph\u1ed5 c\u1eadp v\u0103n h\u00f3a v\u00e0 th\u1ed1ng nh\u1ea5t t\u01b0 t\u01b0\u1edfng c\u1ee7a ng\u01b0\u1eddi d\u00e2n.`,
  `N\u00f3i \u0111\u1ebfn th\u1ed1ng nh\u1ea5t t\u01b0 t\u01b0\u1edfng, ti\u1ec7n th\u1ec3 nh\u1eafc \u0111\u1ebfn vi\u1ec7c \u0111\u1ed1t s\u00e1ch ch\u00f4n Nho lu\u00f4n.`,
  `Tr\u01b0\u1edbc \u0111\u00e2y, c\u00e1c n\u01b0\u1edbc ch\u01b0 h\u1ea7u c\u00f3 c\u00e1c quan ni\u1ec7m v\u0103n h\u00f3a kh\u00e1c nhau,`,
  `M\u1edbi c\u00f3`,
  `\u0110\u1ebfn khi T\u1ea7n th\u1ed1ng nh\u1ea5t,`,
  `Hai tr\u00e0o l\u01b0u t\u01b0 t\u01b0\u1edfng l\u1edbn nh\u1ea5t l\u00fac b\u1ea5y gi\u1edd l\u00e0 v\u0103n h\u00f3a Nho gia v\u00e0 v\u0103n h\u00f3a Ph\u00e1p gia.`,
  `Nho gia nh\u1ea5n m\u1ea1nh tr\u1ecb n\u01b0\u1edbc b\u1eb1ng l\u00f2ng nh\u00e2n, ph\u1ee5c ng\u01b0\u1eddi b\u1eb1ng l\u1ec5 ngh\u0129a;`,
  `Ph\u00e1p gia nh\u1ea5n m\u1ea1nh tr\u1ecb n\u01b0\u1edbc b\u1eb1ng v\u0169 l\u1ef1c, cai tr\u1ecb con ng\u01b0\u1eddi b\u1eb1ng quy\u1ec1n l\u1ef1c.`,
  `Th\u1ec3 ch\u1ebf Ph\u00e1p gia \u0111\u01b0\u1ee3c nh\u00e0 T\u1ea7n \u0111\u1ec1 cao \u0111\u00e3 v\u1ea5p ph\u1ea3i s\u1ef1 ph\u1ea3n \u0111\u1ed1i c\u1ee7a c\u00e1c nh\u00e0 nho s\u0129,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u00e3 h\u1ee7y ho\u1ea1i s\u00e1ch s\u1eed,`,
  `ch\u00f4n s\u1ed1ng c\u00e1c nh\u00e0 nho \u0111\u1ec3 \u0111\u00e0n \u00e1p c\u00e1c n\u1ec1n v\u0103n h\u00f3a kh\u00e1c,`,
  `nh\u1eb1m duy tr\u00ec s\u1ef1 th\u1ed1ng nh\u1ea5t v\u0129 \u0111\u1ea1i.`,
  `Ch\u00ednh t\u01b0 t\u01b0\u1edfng l\u1ea5y v\u00f5 tr\u1ecb qu\u1ed1c c\u1ee7a T\u1ea7n Th\u1ee7y Ho\u00e0ng n\u00e0y,`,
  `c\u0169ng \u0111\u00e3 \u0111\u1eb7t n\u1ec1n m\u00f3ng cho s\u1ef1 s\u1ee5p \u0111\u1ed5 c\u1ee7a nh\u00e0 T\u1ea7n sau n\u00e0y.`,
  `\u0110\u1ec3 ch\u1ed1ng l\u1ea1i s\u1ef1 x\u00e2m l\u01b0\u1ee3c c\u1ee7a ngo\u1ea1i t\u1ed9c,`,
  `nh\u00e0 T\u1ea7n \u0111\u00e3 huy \u0111\u1ed9ng h\u00e0ng ch\u1ee5c v\u1ea1n lao c\u00f4ng x\u00e2y d\u1ef1ng V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh.`,
  `Th\u1ef1c ra, V\u1ea1n L\u00fd Tr\u01b0\u1eddng Th\u00e0nh \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng s\u1edbm nh\u1ea5t v\u00e0o th\u1eddi Xu\u00e2n Thu,`,
  `sau khi nh\u00e0 T\u1ea7n th\u1ed1ng nh\u1ea5t \u0111\u00e3 c\u1ee7ng c\u1ed1 v\u00e0 s\u1eeda ch\u1eefa n\u00f3,`,
  `v\u00e0 k\u1ebft n\u1ed1i ho\u00e0n ch\u1ec9nh.`,
  `Ngo\u00e0i ra, nh\u00e0 T\u1ea7n c\u00f2n x\u00e2y d\u1ef1ng cung A Ph\u00f2ng, s\u1eeda sang l\u0103ng m\u1ed9 ho\u00e0ng gia,`,
  `huy \u0111\u1ed9ng h\u00e0ng tri\u1ec7u lao \u0111\u1ed9ng,`,
  `lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n h\u00e0 kh\u1eafc, lao d\u1ecbch n\u1eb7ng n\u1ec1 v\u00e0 \u00e1p b\u1ee9c khi\u1ebfn d\u00e2n ch\u00fang l\u1ea7m than,`,
  `m\u00e2u thu\u1eabn x\u00e3 h\u1ed9i ng\u00e0y c\u00e0ng gia t\u0103ng.`,
  `N\u0103m 210 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean,`,
  `T\u1ea7n Th\u1ee7y Ho\u00e0ng th\u1ef1c hi\u1ec7n chuy\u1ebfn tu\u1ea7n du cu\u1ed1i c\u00f9ng,`,
  `v\u00e0 \u0111\u1ed9t ng\u1ed9t b\u0103ng h\u00e0 t\u1ea1i h\u00e0nh cung Sa Kh\u00e2u.`,
  `\u0110\u00fang v\u1eady, ghi ch\u00e9p ch\u00ednh s\u1eed ch\u1ec9 c\u00f3 hai ch\u1eef:`,
  `\u0111\u1ed9t t\u1eed. D\u00e2n gian c\u00f3 hai gi\u1ea3 thuy\u1ebft v\u1ec1 nguy\u00ean nh\u00e2n c\u00e1i ch\u1ebft c\u1ee7a \u00f4ng,`,
  `m\u1ed9t l\u00e0 \u00f4ng ch\u1ebft v\u00ec b\u1ec7nh, hai l\u00e0 \u00f4ng b\u1ecb Tri\u1ec7u Cao m\u01b0u h\u1ea1i,`,
  `b\u1edfi v\u00ec c\u00e1i ch\u1ebft qu\u00e1 \u0111\u1ed9t ng\u1ed9t.`,
  `Nguy\u00ean do di chi\u1ebfu c\u1ee7a \u00f4ng l\u00e0 mu\u1ed1n ho\u00e0ng t\u1eed tr\u01b0\u1edfng Ph\u00f9 T\u00f4 k\u1ebf v\u1ecb,`,
  `nh\u01b0ng khi T\u1ea7n Th\u1ee7y Ho\u00e0ng \u0111\u1ec3 l\u1ea1i di chi\u1ebfu,`,
  `b\u00ean c\u1ea1nh \u00f4ng ch\u1ec9 c\u00f3 ho\u00e0ng t\u1eed \u00fat H\u1ed3 H\u1ee3i,`,
  `th\u00e1i gi\u00e1m Tri\u1ec7u Cao v\u00e0 th\u1eeba t\u01b0\u1edbng L\u00fd T\u01b0.`,
  `Tri\u1ec7u Cao c\u00f3 m\u00e2u thu\u1eabn v\u1edbi Ph\u00f9 T\u00f4,`,
  `n\u00ean h\u1eafn s\u1ee3 Ph\u00f9 T\u00f4 k\u1ebf v\u1ecb s\u1ebd tr\u1ea3 th\u00f9 m\u00ecnh,`,
  `v\u00ec v\u1eady Tri\u1ec7u Cao \u0111\u00e3 thuy\u1ebft ph\u1ee5c H\u1ed3 H\u1ee3i,`,
  `\u0111e d\u1ecda L\u00fd T\u01b0 s\u1eeda \u0111\u1ed5i di chi\u1ebfu c\u1ee7a T\u1ea7n Th\u1ee7y Ho\u00e0ng,`,
  `ra l\u1ec7nh cho Ph\u00f9 T\u00f4 t\u1ef1 s\u00e1t,`,
  `do H\u1ed3 H\u1ee3i k\u1ebf v\u1ecb.`,
  `Sau \u0111\u00f3, L\u00fd T\u01b0 c\u0169ng b\u1ecb H\u1ed3 H\u1ee3i ch\u00e9m ngang l\u01b0ng,`,
  `Tri\u1ec7u Cao \u0111\u1ed9c chi\u1ebfm quy\u1ec1n h\u00e0nh.`,
  `Sau \u0111\u00f3, chuy\u1ec7n g\u00ec \u0111\u00e3 x\u1ea3y ra?`,
  `Nh\u00e0 T\u1ea7n \u0111\u00e3 s\u1ee5p \u0111\u1ed5 nh\u01b0 th\u1ebf n\u00e0o?`,
  `T\u1ea7n Nh\u1ecb Th\u1ebf H\u1ed3 H\u1ee3i sau khi l\u00ean ng\u00f4i, ch\u1ec9 lo h\u01b0\u1edfng l\u1ea1c,`,
  `kh\u00f4ng m\u00e0ng tri\u1ec1u ch\u00ednh, l\u1ea1i c\u00f2n tin l\u1eddi gi\u00e8m pha c\u1ee7a Tri\u1ec7u Cao,`,
  `s\u00e1t h\u1ea1i trung l\u01b0\u01a1ng. Tri\u1ec7u Cao trong tri\u1ec1u \u0111\u00ecnh nh\u00e0 T\u1ea7n h\u00f4 m\u01b0a g\u1ecdi gi\u00f3,`,
  `l\u00e0m \u0111\u1ee7 \u0111i\u1ec1u x\u1eb1ng b\u1eady, l\u00e0m t\u0103ng th\u00eam s\u1ef1 t\u00e0n b\u1ea1o trong cai tr\u1ecb c\u1ee7a ho\u00e0ng th\u1ea5t,`,
  `th\u1eadm ch\u00ed c\u00f2n t\u00e0n kh\u1ed1c h\u01a1n th\u1eddi T\u1ea7n Th\u1ee7y Ho\u00e0ng.`,
  `C\u1ea3 n\u01b0\u1edbc l\u1ea7m than, d\u00e2n ch\u00fang k\u00eau than kh\u1eafp n\u01a1i,`,
  `d\u01b0\u1edbi b\u1ea1o ch\u00ednh \u1eaft s\u1ebd c\u00f3 ph\u1ea3n kh\u00e1ng.`,
  `Trong c\u00e1c cu\u1ed9c ph\u1ea3n kh\u00e1ng l\u1edbn nh\u1ecf,`,
  `\u0111\u00e1ng k\u1ec3 nh\u1ea5t l\u00e0 cu\u1ed9c kh\u1edfi ngh\u0129a \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng.`,
  `\u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng c\u00f3 th\u1ec3 b\u1ea1n kh\u00f4ng bi\u1ebft, nh\u01b0ng Tr\u1ea7n Th\u1eafng,`,
  `Ng\u00f4 Qu\u1ea3ng ch\u1eafc ch\u1eafn b\u1ea1n \u0111\u00e3 t\u1eebng nghe qua.`,
  `V\u00e0o n\u0103m 209 tr\u01b0\u1edbc C\u00f4ng nguy\u00ean, hai v\u1ecb t\u01b0\u1edbng \u1edf H\u00e0 Nam \u0111\u00e3 \u00e1p gi\u1ea3i m\u1ed9t nh\u00f3m 900 lao \u0111\u1ed9ng \u0111\u1ebfn B\u1eafc Kinh.`,
  `Vi\u00ean quan \u0111\u00e3 ch\u1ecdn hai lao \u0111\u1ed9ng trong s\u1ed1 \u0111\u00f3 \u0111\u1ec3 qu\u1ea3n l\u00fd nh\u1eefng ng\u01b0\u1eddi c\u00f2n l\u1ea1i,`,
  `\u0111\u00f3 ch\u00ednh l\u00e0 Tr\u1ea7n Th\u1eafng v\u00e0 Ng\u00f4 Qu\u1ea3ng.`,
  `Khi \u0111o\u00e0n ng\u01b0\u1eddi c\u1ee7a h\u1ecd \u0111\u1ebfn \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng,`,
  `tr\u1eddi \u0111\u1ed5 m\u01b0a l\u1edbn,`,
  `to\u00e0n b\u1ed9 \u0111\u01b0\u1eddng s\u00e1 b\u1ecb ng\u1eadp n\u01b0\u1edbc, m\u1ecdi ng\u01b0\u1eddi kh\u00f4ng th\u1ec3 \u0111\u1ebfn B\u1eafc Kinh \u0111\u00fang th\u1eddi h\u1ea1n quy \u0111\u1ecbnh.`,
  `Lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n th\u1eddi b\u1ea5y gi\u1edd v\u00f4 c\u00f9ng h\u00e0 kh\u1eafc,`,
  `n\u1ebfu qu\u00e1 th\u1eddi h\u1ea1n \u0111\u1ebfn n\u01a1i s\u1ebd b\u1ecb ch\u00e9m \u0111\u1ea7u.`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng ngh\u0129,`,
  `ki\u1ec3u g\u00ec c\u0169ng ch\u1ebft, chi b\u1eb1ng c\u1ee9 li\u1ec1u m\u1ed9t phen.`,
  `Trong t\u00ecnh th\u1ebf c\u1ea5p b\u00e1ch,`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng \u0111\u00e3 l\u00e3nh \u0111\u1ea1o c\u00e1c lao c\u00f4ng kh\u00e1c gi\u1ebft ch\u1ebft vi\u00ean t\u01b0\u1edbng \u00e1p b\u1ee9c h\u1ecd,`,
  `ph\u00e1t \u0111\u1ed9ng binh bi\u1ebfn,`,
  `V\u00e0 li\u00ean t\u1ee5c gi\u00e0nh th\u1eafng l\u1ee3i nh\u01b0 ch\u1ebb tre.`,
  `Qu\u00e2n kh\u1edfi ngh\u0129a d\u1ea7n l\u1edbn m\u1ea1nh, chi\u1ebfm \u0111\u01b0\u1ee3c v\u00e0i huy\u1ec7n l\u00e2n c\u1eadn.`,
  `Ch\u01b0a \u0111\u1ea7y ba th\u00e1ng sau kh\u1edfi ngh\u0129a, nh\u1eefng ng\u01b0\u1eddi ch\u1ed1ng T\u1ea7n c\u0169ng nhao nhao n\u1ed5i d\u1eady,`,
  `T\u1ea1i Tri\u1ec7u, T\u1ec1, Y\u00ean, Ng\u1ee5y v\u00e0 c\u00e1c n\u01a1i kh\u00e1c \u0111\u1ec1u c\u00f3 ng\u01b0\u1eddi l\u1ea5y danh ngh\u0129a kh\u00f4i ph\u1ee5c s\u00e1u n\u01b0\u1edbc m\u00e0 t\u1ef1 x\u01b0ng v\u01b0\u01a1ng.`,
  `Sau \u0111\u00f3, qu\u00e2n c\u1ee7a Tr\u1ea7n Th\u1eafng t\u1ea5n c\u00f4ng v\u1ec1 ph\u00eda t\u00e2y,`,
  `Ti\u1ebfn s\u00e1t kinh \u0111\u00f4 H\u00e0m D\u01b0\u01a1ng c\u1ee7a n\u01b0\u1edbc T\u1ea7n.`,
  `H\u1ed3 H\u1ee3i li\u1ec1n ph\u00e1i qu\u00e2n tr\u1ea5n \u00e1p,`,
  `B\u1edfi v\u00ec ph\u1ea7n l\u1edbn qu\u00e2n kh\u1edfi ngh\u0129a l\u00e0 n\u00f4ng d\u00e2n,`,
  `C\u0169ng kh\u00f4ng ph\u1ea3i qu\u00e2n ch\u00ednh quy.`,
  `V\u00ec v\u1eady cu\u1ed1i c\u00f9ng, qu\u00e2n kh\u1edfi ngh\u0129a \u0111\u00e3 th\u1ea5t b\u1ea1i,`,
  `Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng b\u1ecb gi\u1ebft.`,
  `M\u1eb7c d\u00f9 h\u1ecd th\u1ea5t b\u1ea1i, nh\u01b0ng cu\u1ed9c kh\u1edfi ngh\u0129a n\u00f4ng d\u00e2n quy m\u00f4 l\u1edbn n\u00e0y \u0111\u00e3 l\u00e0m lung lay n\u1ec1n th\u1ed1ng tr\u1ecb c\u0103n b\u1ea3n c\u1ee7a nh\u00e0 T\u1ea7n,`,
  `T\u1ea1o \u0111i\u1ec1u ki\u1ec7n thu\u1eadn l\u1ee3i cho L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169 di\u1ec7t T\u1ea7n sau n\u00e0y.`,
  `L\u00fac n\u00e0y n\u00f3i v\u1ec1 tri\u1ec1u \u0111\u00ecnh nh\u00e0 T\u1ea7n,`,
  `Hai n\u0103m sau cu\u1ed9c kh\u1edfi ngh\u0129a \u0110\u1ea1i Tr\u1ea1ch H\u01b0\u01a1ng,`,
  `H\u1ed3 H\u1ee3i b\u1ecb Tri\u1ec7u Cao \u00e9p t\u1ef1 s\u00e1t.`,
  `Tri\u1ec7u Cao th\u1ef1c ra mu\u1ed1n t\u1ef1 m\u00ecnh x\u01b0ng \u0111\u1ebf, nh\u01b0ng b\u1ecb tri\u1ec1u th\u1ea7n k\u1ecbch li\u1ec7t ph\u1ea3n \u0111\u1ed1i.`,
  `Kh\u00f4ng c\u00f2n c\u00e1ch n\u00e0o, Tri\u1ec7u Cao b\u00e8n t\u00ecm con c\u1ee7a Ph\u00f9 T\u00f4 l\u00e0 T\u1eed Anh,`,
  `mu\u1ed1n \u0111\u01b0a h\u1eafn l\u00ean ng\u00f4i l\u00e0m b\u00f9 nh\u00ecn.`,
  `Nh\u01b0ng \u0111i\u1ec1u Tri\u1ec7u Cao kh\u00f4ng ng\u1edd l\u00e0,`,
  `T\u1eed Anh kh\u00f4ng h\u1ec1 ngu ng\u1ed1c.`,
  `V\u00e0o ng\u00e0y th\u1ee9 n\u0103m sau khi T\u1eed Anh \u0111\u0103ng c\u01a1,`,
  `\u00f4ng \u0111\u00e3 l\u1eadp k\u1ebf ho\u1ea1ch lo\u1ea1i b\u1ecf Tri\u1ec7u Cao.`,
  `\u0110\u00e1ng ti\u1ebfc, nh\u00e0 T\u1ea7n l\u00fac b\u1ea5y gi\u1edd \u0111\u00e3 lung lay s\u1eafp \u0111\u1ed5,`,
  `d\u00f9 T\u1eed Anh c\u00f3 t\u00e0i gi\u1ecfi \u0111\u1ebfn m\u1ea5y c\u0169ng kh\u00f4ng th\u1ec3 c\u1ee9u v\u00e3n \u0111\u01b0\u1ee3c n\u1eefa.`,
  `Kh\u1eafp n\u01a1i tr\u00ean \u0111\u1ea5t n\u01b0\u1edbc, c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a n\u1ed5i d\u1eady,`,
  `trong \u0111\u00f3 c\u00f3 L\u01b0u Bang \u1edf B\u00e1i huy\u1ec7n v\u00e0 H\u1ea1ng V\u0169, qu\u00fd t\u1ed9c c\u1ee7a n\u01b0\u1edbc S\u1edf c\u0169.`,
  `T\u1eed Anh t\u1ea1i v\u1ecb ch\u1ec9 v\u1ecfn v\u1eb9n 46 ng\u00e0y th\u00ec b\u1ecb L\u01b0u Bang, ng\u01b0\u1eddi \u0111\u00e3 t\u1ea5n c\u00f4ng H\u00e0m D\u01b0\u01a1ng, b\u1eaft gi\u1eef.`,
  `T\u1eed Anh \u0111\u1ea7u h\u00e0ng, nh\u00e0 T\u1ea7n di\u1ec7t vong.`,
  `Sau \u0111\u00f3, H\u1ea1ng V\u0169 c\u0169ng d\u1eabn qu\u00e2n t\u1ea5n c\u00f4ng H\u00e0m D\u01b0\u01a1ng,`,
  `T\u1eed Anh b\u1ecb H\u1ea1ng V\u0169 gi\u1ebft ch\u1ebft,`,
  `Cung \u0111i\u1ec7n nh\u00e0 T\u1ea7n c\u0169ng b\u1ecb H\u1ea1ng V\u0169 san b\u1eb1ng.`,
  `\u0110\u1ebfn \u0111\u00e2y, nh\u00e0 T\u1ea7n v\u0129nh vi\u1ec5n r\u00fat kh\u1ecfi v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed.`,
];

