const CHINA_HISTORY_CH04_S_H_N_TRANH_H_NG_P1_C9QIE0RFSLQ_TRANSLATIONS = [
  `Sau khi nh\u00e0 T\u1ea7n s\u1ee5p \u0111\u1ed5 l\u00e0 cu\u1ed9c chi\u1ebfn S\u1edf H\u00e1n.`,
  `Tr\u01b0\u1edbc ti\u00ean h\u00e3y n\u00f3i v\u1ec1 hai nh\u00e2n v\u1eadt ch\u00ednh l\u00e0 L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169.`,
  `L\u01b0u Bang thu\u1ed9c tu\u00fdp ng\u01b0\u1eddi th\u00e0nh c\u00f4ng mu\u1ed9n,`,
  `Th\u1eddi nh\u00e0 T\u1ea7n, \u00f4ng ch\u1ec9 l\u00e0 m\u1ed9t th\u01b0\u1eddng d\u00e2n nh\u1ecf \u1edf huy\u1ec7n B\u00e1i,`,
  `L\u00e0m m\u1ed9t ch\u1ee9c quan nh\u1ecf, T\u1ef7 Th\u1ee7y \u0110\u00ecnh Tr\u01b0\u1edfng,`,
  `C\u00f4ng vi\u1ec7c l\u00e0 ch\u1ea1y vi\u1ec7c v\u1eb7t, \u00e1p gi\u1ea3i phu t\u00f9, v.v.`,
  `C\u00f3 l\u1ea7n, L\u01b0u Bang ph\u1ea3i \u00e1p gi\u1ea3i m\u1ed9t t\u1ed1p phu t\u00f9 \u0111\u1ebfn L\u1ec7 S\u01a1n \u0111\u1ec3 x\u00e2y l\u0103ng m\u1ed9 ho\u00e0ng gia,`,
  `M\u1edbi kh\u1edfi h\u00e0nh kh\u00f4ng l\u00e2u, m\u1ea5y ng\u01b0\u1eddi phu t\u00f9 \u0111\u00e3 nh\u00e2n l\u00fac \u00f4ng kh\u00f4ng ch\u00fa \u00fd m\u00e0 b\u1ecf tr\u1ed1n.`,
  `Vi\u1ec7c n\u00e0y c\u00f2n t\u1ec7 h\u01a1n, lu\u1eadt ph\u00e1p nh\u00e0 T\u1ea7n th\u1eddi \u0111\u00f3 r\u1ea5t nghi\u00eam kh\u1eafc,`,
  `L\u01b0u Bang ch\u1eafc ch\u1eafn s\u1ebd b\u1ecb tr\u1ecb t\u1ed9i,`,
  `Th\u1ebf l\u00e0 \u00f4ng ta d\u1ee9t kho\u00e1t th\u1ea3 nh\u1eefng phu t\u00f9 c\u00f2n l\u1ea1i,`,
  `B\u1ea3n th\u00e2n c\u0169ng chu\u1ea9n b\u1ecb b\u1ecf tr\u1ed1n.`,
  `Nh\u1eefng lao \u0111\u1ed9ng n\u00e0y c\u0169ng kh\u00f4ng c\u00f3 n\u01a1i n\u00e0o kh\u00e1c \u0111\u1ec3 \u0111i,`,
  `\u0111\u00e0nh theo L\u01b0u Bang l\u00e0m gi\u1eb7c c\u01b0\u1edbp.`,
  `Sau khi Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng kh\u1edfi ngh\u0129a, n\u00f4ng d\u00e2n c\u00e1c n\u01a1i c\u1ee7a nh\u00e0 T\u1ea7n c\u0169ng n\u1ed5i d\u1eady h\u01b0\u1edfng \u1ee9ng,`,
  `gi\u01b0\u01a1ng cao ng\u1ecdn c\u1edd ph\u1ea3n T\u1ea7n.`,
  `\u0110\u1ed9i c\u1ee7a L\u01b0u Bang nh\u00e2n c\u01a1 h\u1ed9i n\u00e0y \u0111\u00e3 gi\u1ebft ch\u1ebft huy\u1ec7n l\u1ec7nh huy\u1ec7n B\u00e1i,`,
  `L\u01b0u Bang \u0111\u01b0\u1ee3c b\u1ea7u l\u00e0m huy\u1ec7n l\u1ec7nh m\u1edbi,`,
  `x\u01b0ng l\u00e0 B\u00e1i C\u00f4ng. C\u1ee9 nh\u01b0 v\u1eady, B\u00e1i C\u00f4ng L\u01b0u Bang b\u1eaft \u0111\u1ea7u b\u01b0\u1edbc l\u00ean v\u0169 \u0111\u00e0i l\u1ecbch s\u1eed.`,
  `N\u0103m \u0111\u00f3, \u00f4ng \u0111\u00e3 48 tu\u1ed5i.`,
  `C\u00f2n v\u1ec1 ph\u00eda H\u1ea1ng V\u0169 th\u00ec t\u00ecnh h\u00ecnh ho\u00e0n to\u00e0n kh\u00e1c,`,
  `H\u1ea1ng V\u0169 l\u00e0 h\u1eadu du\u1ec7 c\u1ee7a \u0111\u1ea1i t\u01b0\u1edbng H\u1ea1ng Y\u00ean n\u01b0\u1edbc S\u1edf ng\u00e0y tr\u01b0\u1edbc,`,
  `\u0111\u01b0\u1ee3c coi l\u00e0 con ch\u00e1u danh gia v\u1ecdng t\u1ed9c.`,
  `Sau khi Tr\u1ea7n Th\u1eafng, Ng\u00f4 Qu\u1ea3ng kh\u1edfi ngh\u0129a,`,
  `m\u1ed9t ng\u01b0\u1eddi ch\u00fa c\u1ee7a H\u1ea1ng V\u0169 l\u00e0 H\u1ea1ng L\u01b0\u01a1ng c\u0169ng d\u1eabn H\u1ea1ng V\u0169, l\u00fac \u0111\u00f3 v\u1eabn c\u00f2n l\u00e0 m\u1ed9t thanh ni\u00ean, gia nh\u1eadp qu\u00e2n \u0111\u1ed9i ph\u1ea3n T\u1ea7n.`,
  `H\u1ea1ng V\u0169 gi\u1ebft ch\u1ebft qu\u1eadn tr\u01b0\u1edfng qu\u1eadn C\u1ed1i K\u00ea, H\u1ea1ng L\u01b0\u01a1ng nh\u1eadm ch\u1ee9c qu\u1eadn tr\u01b0\u1edfng m\u1edbi,`,
  `H\u1ea1ng V\u0169 l\u00e0m ph\u00f3 t\u01b0\u1edbng.`,
  `D\u00f9 sao th\u00ec nh\u00e0 h\u1ecd H\u1ea1ng t\u1eebng l\u00e0 m\u1ed9t d\u00f2ng d\u00f5i danh gi\u00e1 m\u00e0.`,
  `B\u1ea1n b\u00e8 th\u00ec nhi\u1ec1u, quan h\u1ec7 r\u1ed9ng r\u00e3i.`,
  `H\u1ea1ng L\u01b0\u01a1ng \u0111\u00e3 hi\u1ec7u tri\u1ec7u t\u1ea5t c\u1ea3 nh\u00e2n t\u00e0i t\u1eeb kh\u1eafp v\u00f9ng T\u00f4 Ch\u00e2u,`,
  `c\u00f9ng nhau ch\u1ed1ng T\u1ea7n, v\u00e0 l\u1eadp ch\u00e1u c\u1ee7a S\u1edf Ho\u00e0i V\u01b0\u01a1ng n\u0103m x\u01b0a, H\u00f9ng T\u00e2m l\u00e0m S\u1edf Ho\u00e0i V\u01b0\u01a1ng m\u1edbi.`,
  `L\u00fac n\u00e0y, L\u01b0u Bang c\u0169ng \u0111\u1ebfn \u0111\u1ea7u qu\u00e2n cho H\u1ea1ng L\u01b0\u01a1ng.`,
  `Sau \u0111\u00f3, L\u01b0u Bang theo H\u1ea1ng V\u0169, H\u1ea1ng L\u01b0\u01a1ng chinh chi\u1ebfn kh\u1eafp n\u01a1i,`,
  `giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ea7n.`,
  `Qu\u00e2n T\u1ea7n l\u00fac b\u1ea5y gi\u1edd v\u1eabn c\u00f2n kh\u00e1 m\u1ea1nh,`,
  `trong m\u1ed9t tr\u1eadn giao chi\u1ebfn,`,
  `H\u1ea1ng L\u01b0\u01a1ng b\u1ecb danh t\u01b0\u1edbng Tr\u01b0\u01a1ng H\u00e0n c\u1ee7a nh\u00e0 T\u1ea7n gi\u1ebft ch\u1ebft.`,
  `Khi H\u1ea1ng V\u0169 v\u00e0 L\u01b0u Bang\u8d76 \u0111\u1ebfn th\u00ec \u0111\u00e3 mu\u1ed9n r\u1ed3i.`,
  `L\u00fac n\u00e0y, S\u1edf Ho\u00e0i V\u01b0\u01a1ng tri\u1ec7u h\u1ed3i t\u1ea5t c\u1ea3 c\u00e1c \u0111\u1ea1i t\u01b0\u1edbng,`,
  `h\u1ee9a v\u1edbi h\u1ecd, ai c\u00f4ng ph\u00e1 \u0111\u01b0\u1ee3c kinh \u0111\u00f4 H\u00e0m D\u01b0\u01a1ng c\u1ee7a nh\u00e0 T\u1ea7n tr\u01b0\u1edbc,`,
  `ng\u01b0\u1eddi \u0111\u00f3 c\u00f3 th\u1ec3 x\u01b0ng v\u01b0\u01a1ng.`,
  `Tuy n\u00f3i l\u00e0 v\u1eady,`,
  `Tr\u01b0\u1edbc \u0111\u1ea1o qu\u00e2n T\u1ea7n nh\u01b0 h\u1ed5 \u0111\u00f3i, ai d\u00e1m ch\u1ed1ng l\u1ea1i?`,
  `R\u1ea5t c\u00f3 th\u1ec3 s\u1ebd u\u1ed5ng c\u00f4ng v\u00f4 \u00edch.`,
  `L\u00fac n\u00e0y, trong s\u1ed1 t\u1ea5t c\u1ea3 c\u00e1c t\u01b0\u1edbng l\u0129nh, ch\u1ec9 c\u00f3 L\u01b0u Bang v\u00e0 H\u1ea1ng V\u0169 s\u1eb5n s\u00e0ng giao chi\u1ebfn v\u1edbi qu\u00e2n T\u1ea7n.`,
  `H\u1ecd chia qu\u00e2n th\u00e0nh hai \u0111\u01b0\u1eddng, m\u1ed7i ng\u01b0\u1eddi \u0111i m\u1ed9t ng\u1ea3, ai c\u00f3 th\u1ec3 \u0111\u1ebfn H\u00e0m D\u01b0\u01a1ng tr\u01b0\u1edbc th\u00ec ph\u1ea3i xem \u00fd tr\u1eddi.`,
  `Tr\u00ean \u0111\u01b0\u1eddng \u0111i, c\u1ea3 hai b\u00ean \u0111\u1ec1u ch\u1ea1m tr\u00e1n qu\u00e2n T\u1ea7n.`,
  `Ph\u00eda L\u01b0u Bang th\u00ec thu\u1eadn l\u1ee3i h\u01a1n, m\u1ed9t m\u1ea1ch v\u01b0\u1ee3t qua m\u1ecdi c\u1eeda \u1ea3i.`,
  `Khi \u00f4ng ta \u0111\u1ebfn ngo\u1ea1i \u00f4 H\u00e0m D\u01b0\u01a1ng,`,
  `H\u1ea1ng V\u0169 v\u1eabn c\u00f2n \u0111ang giao tranh v\u1edbi qu\u00e2n c\u1ee7a Ch\u01b0\u01a1ng H\u00e0m.`,
  `\u0110\u00fang, ch\u00ednh l\u00e0 Ch\u01b0\u01a1ng H\u00e0m, k\u1ebb \u0111\u00e3 gi\u1ebft ch\u1ebft H\u1ea1ng L\u01b0\u01a1ng.`,
  `Cu\u1ed1i c\u00f9ng, H\u1ea1ng V\u0169 \u0111\u00e3 gi\u00e0nh chi\u1ebfn th\u1eafng,`,
  `nh\u01b0ng tr\u1eadn chi\u1ebfn n\u00e0y \u0111\u00e3 l\u00e3ng ph\u00ed r\u1ea5t nhi\u1ec1u th\u1eddi gian.`,
  `Khi H\u1ea1ng V\u0169 \u0111\u1ebfn b\u00ean ngo\u00e0i H\u00e0m D\u01b0\u01a1ng,`,
  `qu\u00e2n \u0111\u1ed9i c\u1ee7a L\u01b0u Bang \u0111\u00e3 ch\u1edd s\u1eb5n \u1edf \u0111\u00f3 r\u1ed3i.`,
  `H\u1ea1ng V\u0169 r\u1ea5t t\u1ee9c gi\u1eadn, h\u1eafn ngh\u0129: "Ta l\u00e0 ai ch\u1ee9?`,
  `Ng\u01b0\u01a1i ch\u1ec9 l\u00e0 m\u1ed9t k\u1ebb v\u00f4 danh ti\u1ec3u t\u1ed1t, v\u1eady m\u00e0 l\u1ea1i \u0111\u1ebfn tr\u01b0\u1edbc ta, ng\u01b0\u01a1i mu\u1ed1n x\u01b0ng v\u01b0\u01a1ng sao?`,
  `\u0110\u1ecbnh gi\u1eabm l\u00ean \u0111\u1ea7u t\u00f4i sao?`,
  `Th\u1ebf l\u00e0 theo l\u1eddi khuy\u00ean c\u1ee7a m\u01b0u s\u0129 Ph\u1ea1m T\u0103ng,`,
  `M\u1ed9t \u00e2m m\u01b0u \u0111\u00e3 ra \u0111\u1eddi, \u0111\u00f3 ch\u00ednh l\u00e0 b\u1eefa ti\u1ec7c \u1edf H\u1ed3ng M\u00f4n.`,
  `H\u1ea1ng V\u0169 chu\u1ea9n b\u1ecb m\u1edf ti\u1ec7c chi\u00eau \u0111\u00e3i L\u01b0u Bang t\u1ea1i H\u1ed3ng M\u00f4n,`,
  `Th\u1ef1c ch\u1ea5t l\u00e0 \u0111\u1ec3 lo\u1ea1i b\u1ecf L\u01b0u Bang, nh\u01b0ng kh\u00f4ng hi\u1ec3u sao tin t\u1ee9c n\u00e0y l\u1ea1i b\u1ecb l\u1ed9 ra,`,
  `B\u1ecb H\u1ea1ng B\u00e1 bi\u1ebft \u0111\u01b0\u1ee3c.`,
  `H\u1ea1ng B\u00e1 l\u00e0 m\u1ed9t ng\u01b0\u1eddi ch\u00fa kh\u00e1c c\u1ee7a H\u1ea1ng V\u0169,`,
  `\u0110\u00e3 l\u00e0 ng\u01b0\u1eddi nh\u00e0 bi\u1ebft th\u00ec ch\u1eafc c\u0169ng kh\u00f4ng c\u00f3 v\u1ea5n \u0111\u1ec1 l\u1edbn g\u00ec \u0111\u00e2u nh\u1ec9.`,
  `V\u1ea5n \u0111\u1ec1 l\u00e0 H\u1ea1ng B\u00e1 quen Tr\u01b0\u01a1ng L\u01b0\u01a1ng, m\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng n\u00e0y l\u00e0 ai?`,
  `Tr\u01b0\u01a1ng L\u01b0\u01a1ng l\u00e0 m\u1ed9t \u0111\u1ea1i t\u01b0\u1edbng trong qu\u00e2n c\u1ee7a L\u01b0u Bang.`,
  `M\u1ed1i quan h\u1ec7 gi\u1eefa H\u1ea1ng B\u00e1 v\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng kh\u00f4ng h\u1ec1 b\u00ecnh th\u01b0\u1eddng,`,
  `Tr\u01b0\u01a1ng L\u01b0\u01a1ng t\u1eebng c\u1ee9u m\u1ea1ng H\u1ea1ng B\u00e1.`,
  `Th\u1ef1c ra L\u01b0u Bang ch\u1ebft hay kh\u00f4ng kh\u00f4ng li\u00ean quan g\u00ec \u0111\u1ebfn H\u1ea1ng B\u00e1,`,
  `Nh\u01b0ng n\u1ebfu L\u01b0u Bang ch\u1ebft,`,
  `Li\u1ec7u c\u00f3 li\u00ean l\u1ee5y \u0111\u1ebfn \u00e2n nh\u00e2n c\u1ee9u m\u1ea1ng c\u1ee7a m\u00ecnh l\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng kh\u00f4ng?`,
  `Th\u1eadt kh\u00f3 n\u00f3i.`,
  `Th\u1ebf n\u00ean H\u1ea1ng B\u00e1 \u0111\u00e3 b\u00e1o tin n\u00e0y cho Tr\u01b0\u01a1ng L\u01b0\u01a1ng,`,
  `V\u00e0 Tr\u01b0\u01a1ng L\u01b0\u01a1ng l\u1ea1i b\u00e1o cho L\u01b0u Bang.`,
  `M\u1ea1ng l\u01b0\u1edbi quan h\u1ec7 th\u1eadt k\u1ef3 di\u1ec7u.`,
  `L\u01b0u Bang b\u00ean n\u00e0y \u0111\u00e3 bi\u1ebft H\u1ea1ng V\u0169 mu\u1ed1n gi\u1ebft m\u00ecnh,`,
  `Kh\u00f4ng \u0111i ch\u1eb3ng ph\u1ea3i l\u00e0 \u0111\u01b0\u1ee3c r\u1ed3i sao?`,
  `Kh\u00f4ng \u0111\u01b0\u1ee3c, l\u00fac b\u1ea5y gi\u1edd qu\u00e2n H\u1ea1ng V\u0169 v\u1eabn m\u1ea1nh h\u01a1n qu\u00e2n L\u01b0u Bang r\u1ea5t nhi\u1ec1u,`,
  `N\u00ean kh\u00f4ng c\u00f3 c\u00e1ch n\u00e0o kh\u00e1c \u0111\u00e0nh ph\u1ea3i c\u1ee9ng \u0111\u1ea7u m\u00e0 \u0111i th\u00f4i.`,
  `C\u0169ng may L\u01b0u Bang \u0111\u00e3 l\u00e0 m\u1ed9t l\u00e3o l\u00e0ng r\u1ed3i,`,
  `V\u1eeba \u0111\u1ebfn ti\u1ec7c \u0111\u00e3 b\u1eaft \u0111\u1ea7u t\u00ecm c\u00e1ch l\u1ea5y l\u00f2ng H\u1ea1ng V\u0169,`,
  `Kh\u00fam n\u00fam, \u0111\u1ea1i v\u01b0\u01a1ng d\u00e0i \u0111\u1ea1i v\u01b0\u01a1ng ng\u1eafn, n\u00f3i r\u1eb1ng nh\u1eefng tin \u0111\u1ed3n m\u00ecnh mu\u1ed1n x\u01b0ng \u0111\u1ebf \u0111\u1ec1u l\u00e0 tin \u0111\u1ed3n nh\u1ea3m,`,
  `Ai \u0111\u00f3 mu\u1ed1n chia r\u1ebd ch\u00fang ta, ng\u00e0i \u0111\u1eebng tin nh\u1eefng l\u1eddi nh\u01b0 v\u1eady.`,
  `H\u1ea1ng V\u0169 tuy d\u0169ng m\u00e3nh, nh\u01b0ng t\u00e2m t\u01b0 t\u01b0\u01a1ng \u0111\u1ed1i \u0111\u01a1n gi\u1ea3n,`,
  `B\u1ecb chi\u00eau tr\u00f2 n\u00e0y c\u1ee7a L\u01b0u Bang l\u00e0m cho ng\u1edb ng\u01b0\u1eddi ra,`,
  `Ng\u01b0\u1ee3c l\u1ea1i c\u00f2n c\u1ea3m th\u1ea5y m\u00ecnh \u0111\u00e3 hi\u1ec3u l\u1ea7m L\u01b0u Bang.`,
  `V\u1ed1n d\u0129, K\u1ebf ho\u1ea1ch ban \u0111\u1ea7u l\u00e0 \u0111\u1ec3 H\u1ea1ng Trang gi\u1ebft L\u01b0u Bang khi m\u00faa ki\u1ebfm,`,
  `Nh\u01b0ng l\u00fac n\u00e0y H\u1ea1ng V\u0169 \u0111\u00e3 \u0111\u1ed9ng l\u00f2ng tr\u1eafc \u1ea9n,`,
  `Ph\u1ea1m T\u0103ng \u0111\u00e3 nhi\u1ec1u l\u1ea7n ra hi\u1ec7u th\u00fac gi\u1ee5c nh\u01b0ng \u00f4ng \u0111\u1ec1u l\u00e0m ng\u01a1.`,
  `L\u01b0u Bang vi\u1ec7n c\u1edb \u0111i v\u1ec7 sinh trong b\u1eefati\u1ec7c,`,
  `R\u1ed3i tr\u1ed1n v\u1ec1 \u0111\u1ea1i b\u1ea3n doanh c\u1ee7a m\u00ecnh.`,
  `Sau b\u1eefa ti\u1ec7c H\u1ed3ng K\u00f4ng, L\u01b0u Bang b\u1eaft \u0111\u1ea7u \u0111\u1ec1 ph\u00f2ng H\u1ea1ng V\u0169 kh\u1eafp m\u1ecdi n\u01a1i,`,
  `V\u1ed1n d\u0129 \u00f4ng l\u00e0 ng\u01b0\u1eddi \u0111\u1ea7u ti\u00ean \u0111\u1ebfn H\u00e0m D\u01b0\u01a1ng, l\u1ebd ra \u00f4ng ph\u1ea3i x\u01b0ng v\u01b0\u01a1ng,`,
  `Nh\u01b0ng \u0111\u1ed1i m\u1eb7t v\u1edbi H\u1ea1ng V\u0169 h\u00f9ng m\u1ea1nh, L\u01b0u Bang bi\u1ebft th\u1eddi c\u01a1 ch\u01b0a \u0111\u1ebfn,`,
  `V\u00ec v\u1eady, \u00f4ng \u0111\u00e3 \u0111\u1ec3 H\u1ea1ng V\u0169 d\u1eabn qu\u00e2n ti\u1ebfn v\u00e0o H\u00e0m D\u01b0\u01a1ng tr\u01b0\u1edbc.`,
  `Sau \u0111\u00f3, H\u1ea1ng V\u0169 gi\u1ebft T\u1eed Anh, \u0111\u1ed1t cung T\u1ea7n,`,
  `T\u1ef1 l\u1eadp l\u00e0m T\u00e2y S\u1edf B\u00e1 V\u01b0\u01a1ng, phong L\u01b0u Bang l\u00e0m H\u00e1n V\u01b0\u01a1ng.`,
  `Cu\u1ed9c chi\u1ebfn H\u00e1n S\u1edf ch\u00ednh th\u1ee9c b\u1eaft \u0111\u1ea7u t\u1eeb \u0111\u00e2y.`,
  `Sau khi H\u1ea1ng V\u0169 tr\u1edf th\u00e0nh T\u00e2y S\u1edf B\u00e1 V\u01b0\u01a1ng, \u00f4ng b\u1eaft \u0111\u1ea7u noi theo Chu Thi\u00ean t\u1eed ph\u00e2n phong ch\u01b0 h\u1ea7u,`,
  `Nh\u01b0ng H\u1ea1ng V\u0169 kh\u00f4ng theo l\u1ebd th\u01b0\u1eddng, vi\u1ec7c ph\u00e2n phong c\u1ee7a \u00f4ng kh\u00f4ng x\u00e9t c\u00f4ng lao,`,
  `M\u00e0 ho\u00e0n to\u00e0n d\u1ef1a v\u00e0o s\u1edf th\u00edch c\u1ee7a b\u1ea3n th\u00e2n,`,
  `Ng\u01b0\u1eddi c\u00f3 c\u00f4ng th\u00ec kh\u00f4ng \u0111\u01b0\u1ee3c phong, ng\u01b0\u1eddi kh\u00f4ng c\u00f4ng l\u1ea1i chi\u1ebfm kh\u00f4ng \u00edt l\u1ee3i l\u1ed9c.`,
  `\u00d4ng ta \u0111\u00e3 c\u1eed L\u01b0u Bang \u0111\u1ebfn v\u00f9ng H\u00e1n Trung Ba Th\u1ee5c xa x\u00f4i h\u1ebbo l\u00e1nh,`,
  `Chuy\u1ec7n n\u00e0y khi\u1ebfn m\u1ed9t s\u1ed1 t\u01b0\u1edbng l\u0129nh trong qu\u00e2n \u0111\u1ed9i th\u1ef1c s\u1ef1 kh\u00f4ng th\u1ec3 ch\u1ea5p nh\u1eadn \u0111\u01b0\u1ee3c,`,
  `H\u1ecd c\u1ea3m th\u1ea5y H\u1ea1ng V\u0169 kh\u00f4ng ph\u1ea3i l\u00e0 ng\u01b0\u1eddi \u0111\u00e1ng tin c\u1eady,`,
  `Ng\u01b0\u1ee3c l\u1ea1i, L\u01b0u Bang gi\u00e0 d\u1eb7n, v\u1eefng v\u00e0ng, l\u00e0 ng\u01b0\u1eddi c\u00f3 th\u1ec3 l\u00e0m n\u00ean vi\u1ec7c l\u1edbn.`,
  `V\u00ec v\u1eady, h\u1ecd \u0111\u00e3 \u00e2m th\u1ea7m b\u1ecf sang theo L\u01b0u Bang,`,
  `Trong s\u1ed1 \u0111\u00f3 c\u00f3 H\u00e0n T\u00edn,`,
  `H\u00e3y nh\u1edb k\u1ef9 ng\u01b0\u1eddi n\u00e0y.`,
  `Sau \u0111\u00f3, L\u01b0u Bang d\u1eabn qu\u00e2n \u0111\u1ed9i c\u1ee7a m\u00ecnh \u0111\u1ebfn nh\u1eadm ch\u1ee9c t\u1ea1i v\u00f9ng H\u00e1n Trung Ba Th\u1ee5c.`,
  `Ba Th\u1ee5c m\u1ecdi ng\u01b0\u1eddi \u0111\u1ec1u bi\u1ebft m\u00e0,`,
  `Nam c\u1ee7a Th\u1ee5c l\u00e0 T\u1ee9 Xuy\u00ean v\u1edbi n\u00fai non tr\u00f9ng \u0111i\u1ec7p, \u0111\u01b0\u1eddng l\u00ean tr\u1eddi xanh.`,
  `N\u0103m x\u01b0a, n\u01b0\u1edbc T\u1ea7n \u0111\u1ec3 qu\u1ea3n l\u00fd \u0111\u1ea5t Th\u1ee5c, \u0111\u00e3 s\u1eeda ch\u1eefa \u0111\u01b0\u1eddng s\u1ea1n \u0111\u1ea1o,`,
  `\u0110\u00f3 l\u00e0 nh\u1eefng con \u0111\u01b0\u1eddng nh\u1ecf \u0111\u01b0\u1ee3c x\u00e2y d\u1ef1ng d\u1ecdc theo v\u00e1ch n\u00fai,`,
  `v\u00e0 c\u00e1c \u0111\u00ecnh tr\u1ea1m,`,
  `\u0111\u1ec3 thu\u1eadn ti\u1ec7n cho m\u1ecdi ng\u01b0\u1eddi ra v\u00e0o \u0111\u1ea5t Th\u1ee5c.`,
];

