const CHINA_HISTORY_CH12_NH_THANH_P2_C9QIE0RFSLQ_TRANSLATIONS = [
  `Trong khi \u0111\u00f3, ph\u01b0\u01a1ng T\u00e2y \u0111\u00e3 tr\u1ea3i qua nh\u1eefng thay \u0111\u1ed5i long tr\u1eddi l\u1edf \u0111\u1ea5t,`,
  `Anh b\u1eaft \u0111\u1ea7u c\u00e1ch m\u1ea1ng c\u00f4ng nghi\u1ec7p,`,
  `M\u1ef9 \u0111\u00e3 th\u00e0nh l\u1eadp,`,
  `C\u00e1ch m\u1ea1ng Ph\u00e1p b\u00f9ng n\u1ed5.`,
  `Ba s\u1ef1 ki\u1ec7n n\u00e0y \u0111\u00e3 thay \u0111\u1ed5i ho\u00e0n to\u00e0n ti\u1ebfn tr\u00ecnh v\u00e0 c\u1ee5c di\u1ec7n v\u0103n minh th\u1ebf gi\u1edbi,`,
  `Trong khi \u0111\u00f3, tri\u1ec1u \u0111\u1ea1i nh\u00e0 Thanh c\u1ee7a C\u00e0n Long v\u1eabn t\u1ef1 \u0111\u00f3ng c\u1eeda,`,
  `\u0111\u00e1nh m\u1ea5t c\u01a1 h\u1ed9i cu\u1ed1i c\u00f9ng \u0111\u1ec3 t\u00ecm hi\u1ec3u th\u1ebf gi\u1edbi ph\u01b0\u01a1ng T\u00e2y.`,
  `Trong l\u00fac C\u00e0n Long \u0111ang t\u1ef1 m\u00e3n,`,
  `th\u1ebf gi\u1edbi ph\u01b0\u01a1ng T\u00e2y \u0111ang nhanh ch\u00f3ng v\u01b0\u1ee3t qua Trung Qu\u1ed1c.`,
  `C\u00e0n Long tho\u00e1i v\u1ecb sau 60 n\u0103m tr\u1ecb v\u00ec,`,
  `truy\u1ec1n ng\u00f4i cho Gia Kh\u00e1nh,`,
  `b\u1ed1n n\u0103m sau th\u00ec b\u0103ng h\u00e0,`,
  `th\u1ecd 89 tu\u1ed5i.`,
  `Tri\u1ec1u Thanh m\u00e0 C\u00e0n Long \u0111\u1ec3 l\u1ea1i \u0111\u00e3 suy y\u1ebfu kh\u00f3 l\u00f2ng c\u1ee9u v\u00e3n,`,
  `Gia Kh\u00e1nh nh\u00ecn th\u1ea5y s\u1ef1 m\u1ee5c n\u00e1t c\u1ee7a x\u00e3 h\u1ed9i,`,
  `l\u00ean ng\u00f4i li\u1ec1n gi\u1ebft H\u00f2a Th\u00e2n, \u0111i\u1ec1u tra quan tham.`,
  `Nh\u01b0ng s\u1ef1 suy vong c\u1ee7a \u0110\u1ea1i Thanh \u0111\u00e3 th\u1ec3 hi\u1ec7n r\u00f5 tr\u00ean ph\u01b0\u01a1ng di\u1ec7n qu\u00e2n s\u1ef1 v\u00e0 qu\u1ed1c l\u1ef1c.`,
  `D\u01b0\u1edbi th\u1eddi Gia Kh\u00e1nh,`,
  `nh\u00e0 Thanh v\u1eabn ti\u1ebfp t\u1ee5c suy t\u00e0n.`,
  `Sau \u0111\u00f3 \u0110\u1ea1o Quang k\u1ebf v\u1ecb, \u00f4ng l\u00e0 m\u1ed9t v\u1ecb ho\u00e0ng \u0111\u1ebf v\u1eeba ti\u1ebft ki\u1ec7m v\u1eeba c\u00f3 tr\u00e1ch nhi\u1ec7m.`,
  `Trong th\u1eddi gian t\u1ea1i v\u1ecb, thu\u1ed1c phi\u1ec7n lu\u00f4n l\u00e0 v\u1ea5n \u0111\u1ec1 l\u1edbn nh\u1ea5t.`,
  `L\u01b0\u1ee3ng thu\u1ed1c phi\u1ec7n nh\u1eadp kh\u1ea9u l\u1edbn kh\u00f4ng ch\u1ec9 khi\u1ebfn c\u1ea3 Trung Qu\u1ed1c tr\u1edf n\u00ean b\u1ec7nh t\u1eadt, suy y\u1ebfu,`,
  `m\u00e0 c\u00f2n d\u1eabn \u0111\u1ebfn vi\u1ec7c m\u1ed9t l\u01b0\u1ee3ng l\u1edbn b\u1ea1c b\u1ecb ch\u1ea3y ra ngo\u00e0i.`,
  `Th\u1ebf l\u00e0 m\u1ed9t phong tr\u00e0o c\u1ea5m thu\u1ed1c phi\u1ec7n r\u1ea7m r\u1ed9 \u0111\u00e3 di\u1ec5n ra.`,
  `D\u01b0\u1edbi s\u1ef1 \u1ee7ng h\u1ed9 c\u1ee7a \u0110\u1ea1o Quang \u0110\u1ebf,`,
  `L\u00e2m T\u1eafc T\u1eeb ki\u00ean quy\u1ebft c\u1ea5m thu\u1ed1c phi\u1ec7n,`,
  `\u0111\u00e3 ti\u00eau h\u1ee7y s\u1ed1 thu\u1ed1c phi\u1ec7n thu gi\u1eef \u0111\u01b0\u1ee3c t\u1ea1i b\u00e3i bi\u1ec3n H\u1ed5 M\u00f4n.`,
  `\u0110\u00e2y ch\u00ednh l\u00e0 s\u1ef1 ki\u1ec7n H\u1ed5 M\u00f4n Ti\u00eau Y\u00ean n\u1ed5i ti\u1ebfng.`,
  `V\u00e0 c\u00e1ch l\u00e0m n\u00e0y c\u0169ng \u0111\u00e3 x\u00e2m ph\u1ea1m l\u1ee3i \u00edch c\u1ee7a ng\u01b0\u1eddi Anh.`,
  `N\u0103m 1840,`,
  `ng\u01b0\u1eddi Anh x\u00e2m l\u01b0\u1ee3c Trung Qu\u1ed1c, ph\u00e1t \u0111\u1ed9ng Chi\u1ebfn tranh Nha phi\u1ebfn l\u1ea7n th\u1ee9 nh\u1ea5t.`,
  `\u0110\u1ed1i m\u1eb7t v\u1edbi t\u00e0u chi\u1ebfn v\u00e0 s\u00fang \u1ed1ng uy l\u1ef1c c\u1ee7a Anh, tri\u1ec1u \u0111\u00ecnh nh\u00e0 Thanh b\u1ecb \u0111\u00e1nh b\u1ea1i ho\u00e0n to\u00e0n,`,
  `bu\u1ed9c ph\u1ea3i c\u1ea7u h\u00f2a,`,
  `k\u00fd v\u1edbi Anh hi\u1ec7p \u01b0\u1edbc b\u1ea5t b\u00ecnh \u0111\u1eb3ng \u0111\u1ea7u ti\u00ean trong l\u1ecbch s\u1eed Trung Qu\u1ed1c \u2013 Hi\u1ec7p \u01b0\u1edbc Nam Kinh.`,
  `Trung Qu\u1ed1c tr\u1edf th\u00e0nh m\u1ed9t x\u00e3 h\u1ed9i n\u1eeda thu\u1ed9c \u0111\u1ecba, n\u1eeda phong ki\u1ebfn.`,
  `Ch\u00ednh ph\u1ee7 nh\u00e0 Thanh v\u1ed1n kh\u00f4ng c\u00f3 ti\u1ec1n l\u1ea1i ph\u1ea3i b\u1ed3i th\u01b0\u1eddng chi\u1ebfn ph\u00ed,`,
  `ch\u1ec9 c\u00f3 th\u1ec3 ra s\u1ee9c v\u01a1 v\u00e9t c\u1ee7a c\u1ea3i c\u1ee7a d\u00e2n ch\u00fang.`,
  `K\u1ebft qu\u1ea3 l\u00e0 quan b\u1ee9c d\u00e2n ph\u1ea3n,`,
  `c\u00e1c cu\u1ed9c kh\u1edfi ngh\u0129a li\u00ean ti\u1ebfp n\u1ed5 ra.`,
  `Trong b\u1ed1i c\u1ea3nh v\u1eeba c\u00f3 gi\u1eb7c trong v\u1eeba c\u00f3 gi\u1eb7c ngo\u00e0i nh\u01b0 v\u1eady,`,
  `\u0110\u1ea1o Quang qua \u0111\u1eddi v\u1edbi s\u1ef1 c\u0103m ph\u1eabn v\u00e0 ti\u1ebfc nu\u1ed1i.`,
  `H\u00e0m Phong l\u00ean ng\u00f4i. \u0110\u1ed1i m\u1eb7t v\u1edbi m\u1ed9t \u0111\u1ed1ng h\u1ed7n \u0111\u1ed9n m\u00e0 c\u00e1c \u0111\u1eddi tr\u01b0\u1edbc \u0111\u1ec3 l\u1ea1i,`,
  `b\u00ean trong c\u00f3 Th\u00e1i B\u00ecnh Thi\u00ean Qu\u1ed1c chi\u1ebfm n\u1eeda giang s\u01a1n,`,
  `b\u00ean ngo\u00e0i c\u00f3 li\u00ean qu\u00e2n Anh - Ph\u00e1p ph\u00e1t \u0111\u1ed9ng Chi\u1ebfn tranh nha phi\u1ebfn l\u1ea7n th\u1ee9 hai.`,
  `Qu\u00e2n Thanh kh\u00f4ng th\u1ec3 \u0111\u00e1nh b\u1ea1i b\u1ea5t k\u1ef3 b\u00ean n\u00e0o trong s\u1ed1 h\u1ecd,`,
  `kh\u00f4ng \u0111\u00e1nh l\u1ea1i \u0111\u01b0\u1ee3c th\u00ec ch\u1ec9 c\u00f3 th\u1ec3 ch\u1ea1y tr\u1ed1n.`,
  `Sau khi ch\u1ea1y \u0111\u1ebfn Nhi\u1ec7t H\u00e0,`,
  `H\u00e0m Phong b\u1eaft \u0111\u1ea7u m\u1eb7c k\u1ec7 t\u1ea5t c\u1ea3,`,
  `s\u1ed1ng trong men say v\u00e0 \u1ea3o m\u1ed9ng,`,
  `r\u1ed3i qua \u0111\u1eddi \u1edf tu\u1ed5i ba m\u01b0\u01a1i m\u1ed1t.`,
  `\u00d4ng c\u0169ng l\u00e0 ho\u00e0ng \u0111\u1ebf cu\u1ed1i c\u00f9ng c\u1ee7a tri\u1ec1u Thanh n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c th\u1ef1c s\u1ef1.`,
  `C\u00e1c \u0111\u1eddi \u0110\u1ed3ng Tr\u1ecb, Quang T\u1ef1,`,
  `Tuy\u00ean Th\u1ed1ng sau n\u00e0y, ho\u1eb7c l\u00e0 b\u00f9 nh\u00ecn c\u1ee7a ng\u01b0\u1eddi c\u1ee7a m\u00ecnh,`,
  `ho\u1eb7c l\u00e0 b\u00f9 nh\u00ecn c\u1ee7a ng\u01b0\u1eddi n\u01b0\u1edbc ngo\u00e0i.`,
  `T\u1eeb Hy l\u00e0 phi t\u1ea7n c\u1ee7a H\u00e0m Phong, l\u00e0 m\u1eb9 ru\u1ed9t c\u1ee7a \u0110\u1ed3ng Tr\u1ecb.`,
  `\u0110\u1ed3ng Tr\u1ecb l\u00ean ng\u00f4i khi c\u00f2n r\u1ea5t nh\u1ecf,`,
  `n\u00ean T\u1eeb Hy v\u00e0 T\u1eeb An, ho\u00e0ng h\u1eadu c\u1ee7a H\u00e0m Phong, c\u00f9ng nhau bu\u00f4ng r\u00e8m nhi\u1ebfp ch\u00ednh.`,
  `Kh\u00f4ng l\u00e2u sau, T\u1eeb An qua \u0111\u1eddi,`,
  `tri\u1ec1u ch\u00ednh c\u01a1 b\u1ea3n do T\u1eeb Hy m\u1ed9t m\u00ecnh n\u1eafm gi\u1eef quy\u1ec1n l\u1ef1c.`,
  `N\u0103m 19 tu\u1ed5i, \u0110\u1ed3ng Tr\u1ecb qua \u0111\u1eddi v\u00ec b\u1ec7nh \u0111\u1eadu m\u00f9a,`,
  `\u00f4ng kh\u00f4ng c\u00f3 con trai,`,
  `ng\u01b0\u1eddi em h\u1ecd b\u1ed1n tu\u1ed5i Quang T\u1ef1 l\u00ean ng\u00f4i.`,
  `Quang T\u1ef1 t\u1eeb nh\u1ecf \u0111\u00e3 l\u1edbn l\u00ean d\u01b0\u1edbi s\u1ef1 gi\u00e1m s\u00e1t c\u1ee7a T\u1eeb Hy,`,
  `n\u00ean t\u00ednh c\u00e1ch \u00f4ng \u0111\u1eb7c bi\u1ec7t y\u1ebfu \u0111u\u1ed1i.`,
  `Sau khi tr\u01b0\u1edfng th\u00e0nh, \u00f4ng c\u0169ng mu\u1ed1n thay \u0111\u1ed5i \u0111\u1ea5t n\u01b0\u1edbc b\u1eb1ng c\u00e1ch c\u1ea3i c\u00e1ch,`,
  `Nh\u01b0ng g\u1eb7p ph\u1ea3i s\u1ef1 ph\u1ea3n \u0111\u1ed1i gay g\u1eaft t\u1eeb phe b\u1ea3o th\u1ee7 c\u1ee7a T\u1eeb Hy,`,
  `cu\u1ed9c c\u1ea3i c\u00e1ch th\u1ea5t b\u1ea1i ch\u1ec9 sau m\u1ed9t tr\u0103m l\u1ebb ba ng\u00e0y,`,
  `s\u1eed g\u1ecdi l\u00e0 B\u00e1ch nh\u1eadt duy t\u00e2n.`,
  `Sau \u0111\u00f3, Quang T\u1ef1 b\u1ecb T\u1eeb Hy giam l\u1ecfng,`,
  `r\u1ed3i sau \u0111\u00f3, Li\u00ean qu\u00e2n T\u00e1m n\u01b0\u1edbc t\u1ea5n c\u00f4ng v\u00e0o B\u1eafc Kinh,`,
  `T\u1eeb Hy v\u00e0 Quang T\u1ef1 b\u1ecf ch\u1ea1y,`,
  `Li\u00ean qu\u00e2n \u0111\u1ed1t ph\u00e1, gi\u1ebft ch\u00f3c, c\u01b0\u1edbp b\u00f3c \u1edf B\u1eafc Kinh, l\u00e0m \u0111\u1ee7 m\u1ecdi \u0111i\u1ec1u \u00e1c,`,
  `sau khi c\u01b0\u1edbp xong, gi\u1ebft \u0111\u1ee7, l\u1ea1i k\u00fd v\u1edbi ch\u00ednh ph\u1ee7 nh\u00e0 Thanh m\u1ed9t hi\u1ec7p \u01b0\u1edbc nh\u1ee5c nh\u00e3, m\u1ea5t ch\u1ee7 quy\u1ec1n,`,
  `Hi\u1ec7p \u01b0\u1edbc T\u00e2n S\u1eedu v\u1edbi kho\u1ea3n b\u1ed3i th\u01b0\u1eddng kh\u1ed5ng l\u1ed3.`,
  `Li\u00ean qu\u00e2n T\u00e1m n\u01b0\u1edbc l\u00fac \u0111\u00f3 m\u1edbi no say r\u1eddi \u0111i,`,
  `T\u1eeb Hy v\u1ec1 kinh ti\u1ebfp t\u1ee5c l\u00e0m L\u00e3o Ph\u1eadt gia c\u1ee7a m\u00ecnh.`,
  `Cu\u1ed1i c\u00f9ng \u0111\u1ee3i \u0111\u1ebfn khi T\u1eeb Hy s\u1eafp b\u0103ng h\u00e0,`,
  `b\u00e0 ta c\u00f2n kh\u00f4ng qu\u00ean \u0111\u1ea7u \u0111\u1ed9c ch\u1ebft Quang T\u1ef1 tr\u01b0\u1edbc.`,
  `Quang T\u1ef1 c\u0169ng kh\u00f4ng c\u00f3 con trai,`,
  `tr\u01b0\u1edbc khi ch\u1ebft T\u1eeb Hy \u0111\u00e3 t\u1ea1m th\u1eddi tuy\u00ean b\u1ed1 Ph\u1ed5 Nghi, t\u1ee9c Ho\u00e0ng \u0111\u1ebf Tuy\u00ean Th\u1ed1ng, k\u1ebf v\u1ecb.`,
  `L\u00fac \u0111\u00f3, Ph\u1ed5 Nghi m\u1edbi 3 tu\u1ed5i,`,
  `\u0110\u1ea1i Thanh l\u00fac n\u00e0y c\u0169ng \u0111\u00e3 g\u1ea7n suy t\u00e0n r\u1ed3i.`,
  `\u0110i\u1ec1u duy nh\u1ea5t Ph\u1ed5 Nghi c\u00f3 th\u1ec3 l\u00e0m l\u00e0 h\u1ed3 \u0111\u1ed3 l\u00ean ng\u00f4i r\u1ed3i tho\u00e1i v\u1ecb.`,
  `Ba n\u0103m sau, C\u00e1ch m\u1ea1ng T\u00e2n H\u1ee3i b\u00f9ng n\u1ed5 v\u00e0o n\u0103m 1911,`,
  `C\u00e1c t\u1ec9nh \u0111\u1ec1u li\u00ean ti\u1ebfp tuy\u00ean b\u1ed1 \u0111\u1ed9c l\u1eadp.`,
  `N\u0103m 1912,`,
  `Trung Hoa D\u00e2n Qu\u1ed1c tuy\u00ean b\u1ed1 th\u00e0nh l\u1eadp,`,
  `Ph\u1ed5 Nghi ch\u00ednh th\u1ee9c ban chi\u1ebfu tho\u00e1i v\u1ecb,`,
  `Tri\u1ec1u \u0111\u1ea1i phong ki\u1ebfn cu\u1ed1i c\u00f9ng c\u1ee7a Trung Qu\u1ed1c l\u00e0 nh\u00e0 Thanh di\u1ec7t vong.`,
  `\u0110\u01b0\u1ee3c r\u1ed3i, l\u1ecbch s\u1eed c\u1ed5 \u0111\u1ea1i Trung Qu\u1ed1c \u0111\u00e3 n\u00f3i xong.`,
  `N\u1ebfu b\u1ea1n th\u00edch video c\u1ee7a t\u00f4i, hoan ngh\u00eanh nh\u1ea5n \u0111\u0103ng k\u00fd,`,
  `M\u1edf chu\u00f4ng nh\u1ecf, video m\u1edbi s\u1ebd th\u00f4ng b\u00e1o cho b\u1ea1n ngay l\u1eadp t\u1ee9c,`,
  `H\u1eb9n g\u1eb7p l\u1ea1i l\u1ea7n sau.`,
];

